import { withAuth, type AuthenticatedNextApiRequest } from './middleware';
import { log } from '@/lib/logger';

export interface CompanyApiRequest extends AuthenticatedNextApiRequest {
  companyId: string;
  companyRole: string;
}

// Accept handlers that declare a more specific req type (e.g. CompanyApiRequest,
// AuthenticatedNextApiRequest) — the cast inside withCompany is safe because
// by the time handler is called, the request has been enriched with those fields.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CompanyHandler = (req: any, res: NextApiResponse<any>) => any;

/**
 * Middleware that requires authentication AND resolves the active company.
 *
 * Company resolution order:
 * 1. X-Company-Id request header (set by frontend CompanyContext)
 * 2. User's default company (is_default = true in company_users)
 * 3. First company the user belongs to
 *
 * Attaches companyId and companyRole to the request object.
 */
export function withCompany(handler: CompanyHandler): NextApiHandler {
  return withAuth(async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const authReq = req as AuthenticatedNextApiRequest;
      const userId = authReq.user.id;

      // 1. Try X-Company-Id header
      const companyId = req.headers['x-company-id'] as string | undefined;

      if (companyId) {
        // Validate user has access to this specific company
        const access = await sql`
          SELECT role FROM company_users
          WHERE user_id = ${userId} AND company_id = ${companyId}::UUID
          LIMIT 1
        `;

        if (access.length === 0) {
          return res.status(403).json({
            success: false,
            error: { code: 'FORBIDDEN', message: 'You do not have access to this company' },
          });
        }

        (req as CompanyApiRequest).companyId = companyId;
        (req as CompanyApiRequest).companyRole = access[0]!.role as string;
        return handler(req, res);
      }

      // 2. Fall back to user's default or first company
      const companies = await sql`
        SELECT company_id, role, is_default
        FROM company_users
        WHERE user_id = ${userId}
        ORDER BY is_default DESC, created_at ASC
        LIMIT 1
      `;

      if (companies.length === 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'NO_COMPANY', message: 'No company assigned. Please contact an administrator.' },
        });
      }

      (req as CompanyApiRequest).companyId = companies[0]!.company_id as string;
      (req as CompanyApiRequest).companyRole = companies[0]!.role as string;
      return handler(req, res);
    } catch (error) {
      log.error('Company middleware error', error instanceof Error ? { message: error.message } : { error }, 'CompanyMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'COMPANY_ERROR', message: 'Failed to resolve company context' },
      });
    }
  });
}

/**
 * Admin Billing Subscriptions API
 * GET  /api/admin/billing/subscriptions — List subscriptions with filters
 * POST /api/admin/billing/subscriptions — Create a subscription
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listSubscriptions, createSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { status, plan_id, search, page, limit } = req.query;

      const result = await listSubscriptions({
        status: status as string | undefined,
        plan_id: plan_id as string | undefined,
        search: search as string | undefined,
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to list subscriptions', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list subscriptions');
    }
  }

  if (req.method === 'POST') {
    try {
      const { company_id, plan_id, billing_cycle, discount_percent, notes } = req.body as {
        company_id: string;
        plan_id: string;
        billing_cycle: string;
        discount_percent?: number;
        notes?: string;
      };

      if (!company_id || !plan_id || !billing_cycle) {
        return apiResponse.badRequest(res, 'company_id, plan_id, and billing_cycle are required');
      }

      const subscriptionId = await createSubscription({
        company_id,
        plan_id,
        billing_cycle,
        discount_percent,
        notes,
      });

      await logAdminAction(
        req.user.id,
        'subscription.create',
        'subscription',
        subscriptionId,
        { company_id, plan_id, billing_cycle },
        getIp(req)
      );

      return apiResponse.success(res, { id: subscriptionId });
    } catch (err) {
      log.error('Failed to create subscription', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAdmin(handler);

/**
 * Admin Billing Subscription Detail API
 * GET   /api/admin/billing/subscriptions/[id] — Get a single subscription
 * PATCH /api/admin/billing/subscriptions/[id] — Update a subscription
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getSubscription, updateSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const subscription = await getSubscription(id);
      if (!subscription) return apiResponse.notFound(res, 'Subscription not found');
      return apiResponse.success(res, subscription);
    } catch (err) {
      log.error('Failed to get subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get subscription');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as {
        plan_id?: string;
        billing_cycle?: string;
        discount_percent?: number;
        status?: string;
        notes?: string;
      };
      await updateSubscription(id, body);

      await logAdminAction(
        req.user.id,
        'subscription.update',
        'subscription',
        id,
        body as Record<string, unknown>,
        getIp(req)
      );

      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH']);
}

export default withAdmin(handler);

/**
 * Admin Billing Subscription Cancel API
 * POST /api/admin/billing/subscriptions/[id]/cancel — Cancel a subscription
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { cancelSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'POST') {
    try {
      const { at_period_end } = req.body as { at_period_end?: boolean };

      const atPeriodEnd = at_period_end === true;
      await cancelSubscription(id, atPeriodEnd);

      await logAdminAction(
        req.user.id,
        'subscription.cancel',
        'subscription',
        id,
        { at_period_end: atPeriodEnd },
        getIp(req)
      );

      return apiResponse.success(res, { cancelled: true, at_period_end: atPeriodEnd });
    } catch (err) {
      log.error('Failed to cancel subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to cancel subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

export default withAdmin(handler);

/**
 * Admin Billing Plans API
 * GET  /api/admin/billing/plans — List all plans
 * POST /api/admin/billing/plans — Create a new plan
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listPlans, createPlan } from '@/modules/admin/services/planService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const includeArchived = req.query.include_archived === 'true';
      const plans = await listPlans(includeArchived);
      return apiResponse.success(res, plans);
    } catch (err) {
      log.error('Failed to list plans', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list plans');
    }
  }

  if (req.method === 'POST') {
    try {
      const {
        code,
        name,
        description,
        monthly_price_cents,
        annual_price_cents,
        currency,
        features,
        limits,
        display_order,
      } = req.body as {
        code: string;
        name: string;
        description?: string;
        monthly_price_cents: number;
        annual_price_cents: number | undefined;
        currency?: string;
        features?: Record<string, unknown>;
        limits?: Record<string, unknown>;
        display_order?: number;
      };

      if (!code || !name || monthly_price_cents == null) {
        return apiResponse.badRequest(res, 'code, name, and monthly_price_cents are required');
      }

      const plan = await createPlan({
        code,
        name,
        description,
        monthly_price_cents,
        annual_price_cents: annual_price_cents ?? monthly_price_cents,
        currency,
        features,
        limits,
        display_order,
      });

      await logAdminAction(
        req.user.id,
        'plan.create',
        'plan',
        plan.id,
        { code, name, monthly_price_cents },
        getIp(req)
      );

      return apiResponse.success(res, plan);
    } catch (err) {
      log.error('Failed to create plan', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create plan');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAdmin(handler);

/**
 * Admin Billing Plan Detail API
 * GET    /api/admin/billing/plans/[id] — Get a single plan
 * PATCH  /api/admin/billing/plans/[id] — Update a plan
 * DELETE /api/admin/billing/plans/[id] — Archive a plan
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getPlan, updatePlan, archivePlan } from '@/modules/admin/services/planService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const plan = await getPlan(id);
      if (!plan) return apiResponse.notFound(res, 'Plan not found');
      return apiResponse.success(res, plan);
    } catch (err) {
      log.error('Failed to get plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get plan');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as Record<string, unknown>;
      await updatePlan(id, body);

      await logAdminAction(
        req.user.id,
        'plan.update',
        'plan',
        id,
        body,
        getIp(req)
      );

      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update plan');
    }
  }

  if (req.method === 'DELETE') {
    try {
      await archivePlan(id);

      await logAdminAction(
        req.user.id,
        'plan.archive',
        'plan',
        id,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { archived: true });
    } catch (err) {
      log.error('Failed to archive plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to archive plan');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH', 'DELETE']);
