/**
 * AES-256-GCM encryption utilities for sensitive data at rest.
 * Requires ENCRYPTION_KEY env var (min 32 chars).
 */

import crypto from 'crypto';
import { log } from '@/lib/logger';

const ALGORITHM = 'aes-256-gcm';

function getEncryptionKey(): Buffer {
  const key = process.env.ENCRYPTION_KEY;
  if (!key || key.length < 32) {
    throw new Error('ENCRYPTION_KEY must be set (min 32 chars)');
  }
  return Buffer.from(key.slice(0, 32), 'utf-8');
}

export function isEncryptionAvailable(): boolean {
  const key = process.env.ENCRYPTION_KEY;
  return !!(key && key.length >= 32);
}

export function encrypt(plaintext: string): string {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return `${iv.toString('hex')}:${tag}:${encrypted}`;
}

export function decrypt(ciphertext: string): string {
  const key = getEncryptionKey();
  const [ivHex, tagHex, encryptedHex] = ciphertext.split(':');
  if (!ivHex || !tagHex || !encryptedHex) {
    throw new Error('Invalid encrypted format');
  }
  const iv = Buffer.from(ivHex, 'hex');
  const tag = Buffer.from(tagHex, 'hex');
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

/** Encrypt token if key is available, otherwise warn and return plaintext. */
export function encryptToken(plaintext: string): string {
  if (!isEncryptionAvailable()) {
    log.warn('ENCRYPTION_KEY not set — storing token as plaintext', {}, 'encryption');
    return plaintext;
  }
  return encrypt(plaintext);
}

/** Decrypt token if it looks encrypted, otherwise return as-is (plaintext fallback). */
export function decryptToken(value: string): string {
  if (!value) return value;
  // Encrypted format: hex:hex:hex (iv:tag:ciphertext)
  const parts = value.split(':');
  if (parts.length !== 3) {
    // Stored as plaintext — likely pre-encryption-key migration
    return value;
  }
  try {
    return decrypt(value);
  } catch {
    log.warn('Failed to decrypt token — returning as-is', {}, 'encryption');
    return value;
  }
}

/**
 * In-memory rate limiter using LRU cache with TTL
 */

import { LRUCache } from 'lru-cache';
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

interface RateLimitOptions {
  windowMs?: number;    // time window in ms (default 15 min)
  maxRequests?: number; // max requests per window (default 5)
}

// Each cache entry tracks hit count within the TTL window
const caches = new Map<string, LRUCache<string, number>>();

function getCache(windowMs: number): LRUCache<string, number> {
  const key = String(windowMs);
  if (!caches.has(key)) {
    caches.set(key, new LRUCache<string, number>({
      max: 10_000,
      ttl: windowMs,
    }));
  }
  return caches.get(key)!;
}

/**
 * Returns true if the key is rate limited, false if the request is allowed.
 */
export function checkRateLimit(key: string, opts?: RateLimitOptions): boolean {
  const windowMs = opts?.windowMs ?? 15 * 60 * 1000;
  const maxRequests = opts?.maxRequests ?? 5;

  const cache = getCache(windowMs);
  const current = cache.get(key) ?? 0;

  if (current >= maxRequests) {
    return true; // rate limited
  }

  cache.set(key, current + 1);
  return false;
}

function getClientIp(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (Array.isArray(forwarded)) return forwarded[0] ?? 'unknown';
  if (typeof forwarded === 'string') return forwarded.split(',')[0]?.trim() ?? 'unknown';
  return req.socket.remoteAddress ?? 'unknown';
}

/**
 * Middleware wrapper that applies rate limiting per IP before the handler runs.
 */
export function withRateLimit(
  handler: (req: NextApiRequest, res: NextApiResponse) => Promise<void> | void,
  opts?: RateLimitOptions
) {
  return async (req: NextApiRequest, res: NextApiResponse): Promise<void> => {
    const ip = getClientIp(req);
    const limited = checkRateLimit(ip, opts);

    if (limited) {
      log.warn('Rate limit exceeded', { ip }, 'rateLimit');
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
      });
      return;
    }

    return handler(req, res);
  };
}

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getCompanyDetail(
  companyId: string
): Promise<AdminCompanyDetail | null> {
  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')    AS status,
      p.name                          AS plan_name,
      p.code                          AS plan_code,
      c.registration_number,
      c.vat_number,
      c.tax_number,
      c.address_line1,
      c.city,
      c.province,
      c.postal_code,
      c.phone,
      c.email,
      c.website,
      c.billing_email,
      c.billing_contact,
      c.stripe_customer_id,
      c.trial_ends_at,
      c.suspended_at,
      c.suspended_reason,
      c.metadata,
      c.created_at,
      c.updated_at                    AS last_active,
      (SELECT COUNT(*)
         FROM company_users cu
        WHERE cu.company_id = c.id)::int AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int AS mrr_cents
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.id = ${companyId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    name: r.name as string,
    trading_name: r.trading_name as string | null,
    status: r.status as string,
    plan_name: r.plan_name as string | null,
    plan_code: r.plan_code as string | null,
    user_count: r.user_count as number,
    mrr_cents: r.mrr_cents as number,
    created_at: toIso(r.created_at) ?? '',
    last_active: toIso(r.last_active),
    registration_number: r.registration_number as string | null,
    vat_number: r.vat_number as string | null,
    tax_number: r.tax_number as string | null,
    address_line1: r.address_line1 as string | null,
    city: r.city as string | null,
    province: r.province as string | null,
    postal_code: r.postal_code as string | null,
    phone: r.phone as string | null,
    email: r.email as string | null,
    website: r.website as string | null,
    billing_email: r.billing_email as string | null,
    billing_contact: r.billing_contact as string | null,
    stripe_customer_id: r.stripe_customer_id as string | null,
    trial_ends_at: toIso(r.trial_ends_at),
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    metadata: (r.metadata ?? {}) as Record<string, unknown>,
  };
}

export async function updateCompany(
  companyId: string,
  data: Partial<AdminCompanyDetail>
): Promise<void> {
  // Only update safe, explicitly listed fields
  const {
    name, trading_name, phone, email, website,
    billing_email, billing_contact,
    address_line1, city, province, postal_code,
  } = data;

  await sql`
    UPDATE companies SET
      name             = COALESCE(${name ?? null}, name),
      trading_name     = COALESCE(${trading_name ?? null}, trading_name),
      phone            = COALESCE(${phone ?? null}, phone),
      email            = COALESCE(${email ?? null}, email),
      website          = COALESCE(${website ?? null}, website),
      billing_email    = COALESCE(${billing_email ?? null}, billing_email),
      billing_contact  = COALESCE(${billing_contact ?? null}, billing_contact),
      address_line1    = COALESCE(${address_line1 ?? null}, address_line1),
      city             = COALESCE(${city ?? null}, city),
      province         = COALESCE(${province ?? null}, province),
      postal_code      = COALESCE(${postal_code ?? null}, postal_code),
      updated_at       = NOW()
    WHERE id = ${companyId}
  `;

  log.info('updateCompany', { companyId }, 'AdminCompanyService');
}

export async function suspendCompany(
  companyId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'suspended',
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('suspendCompany', { companyId, reason }, 'AdminCompanyService');
}

export async function activateCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'active',
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('activateCompany', { companyId }, 'AdminCompanyService');
}

/** Soft delete — sets status='deleted', preserves data for audit trail. */
export async function deleteCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status     = 'deleted',
        updated_at = NOW()
    WHERE id = ${companyId}
  `;
  log.info('deleteCompany (soft)', { companyId }, 'AdminCompanyService');
}

export async function getCompanyUsers(
  companyId: string
): Promise<{ id: string; name: string; email: string; role: string; last_login: string | null }[]> {
  const rows = await sql`
    SELECT
      u.id,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS name,
      u.email,
      cu.role,
      u.last_login
    FROM company_users cu
    JOIN users u ON u.id = cu.user_id
    WHERE cu.company_id = ${companyId}
    ORDER BY cu.role, u.email
  `;

  return (rows as Row[]).map((r) => ({
    id: r.id as string,
    name: (r.name as string).trim(),
    email: r.email as string,
    role: r.role as string,
    last_login: toIso(r.last_login),
  }));
}

/**
 * Admin Middleware
 * Convenience wrapper: withAuth + withRole('super_admin') + withErrorHandler
 * All admin API routes must be wrapped with this.
 */

import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { checkRateLimit } from '@/lib/rateLimit';
import type { NextApiHandler, NextApiRequest, NextApiResponse } from 'next';

/**
 * Wraps a handler with:
 * 1. JWT authentication (withAuth)
 * 2. super_admin role enforcement (withRole)
 * 3. Structured error handling (withErrorHandler)
 *
 * Usage:
 *   export default withAdmin(async (req, res) => { ... });
 */
export function withAdmin(
  handler: (req: AuthenticatedNextApiRequest, res: NextApiResponse) => Promise<void>
): NextApiHandler {
  const rateLimitedHandler = async (req: NextApiRequest, res: NextApiResponse) => {
    const ip =
      (req.headers['x-forwarded-for'] as string | undefined)?.split(',')[0]?.trim() ??
      req.socket.remoteAddress ??
      'unknown';
    const limited = checkRateLimit(`admin:${ip}`, { windowMs: 60000, maxRequests: 30 });
    if (limited) {
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many requests. Please try again later.' },
      });
      return;
    }
    return handler(req as AuthenticatedNextApiRequest, res);
  };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const errorWrapped = withErrorHandler(rateLimitedHandler as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const roleWrapped = withRole('super_admin')(errorWrapped as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return withAuth(roleWrapped as any) as NextApiHandler;
}

/**
 * Admin Billing Invoices API
 * GET  /api/admin/billing/invoices — List invoices with filters
 * POST /api/admin/billing/invoices — Create an invoice
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listInvoices, createInvoice } from '@/modules/admin/services/invoiceService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { company_id, status, from_date, to_date, search, page, limit } = req.query;

      const result = await listInvoices({
        company_id: company_id as string | undefined,
        status: status as string | undefined,
        from_date: from_date as string | undefined,
        to_date: to_date as string | undefined,
        search: search as string | undefined,
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to list invoices', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list invoices');
    }
  }

  if (req.method === 'POST') {
    try {
      const {
        company_id,
        subscription_id,
        subtotal_cents,
        tax_cents,
        total_cents,
        due_date,
        line_items,
        notes,
      } = req.body as {
        company_id: string;
        subscription_id?: string;
        subtotal_cents: number;
        tax_cents: number;
        total_cents: number;
        due_date?: string;
        line_items?: Record<string, unknown>[];
        notes?: string;
      };

      if (!company_id || subtotal_cents == null || total_cents == null) {
        return apiResponse.badRequest(res, 'company_id, subtotal_cents, and total_cents are required');
      }

      const invoiceId = await createInvoice({
        company_id,
        subscription_id,
        subtotal_cents,
        tax_cents: tax_cents ?? 0,
        total_cents,
        due_date,
        line_items,
        notes,
      });

      await logAdminAction(
        req.user.id,
        'invoice.create',
        'invoice',
        invoiceId,
        { company_id, subscription_id, total_cents },
        getIp(req)
      );

      return apiResponse.success(res, { id: invoiceId });
    } catch (err) {
      log.error('Failed to create invoice', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create invoice');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAdmin(handler);

/**
 * AI Cash Flow Forecast API
 * POST: generate scenario-based forecast with AI narrative
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  buildForecastScenario, calculateWeeklyForecast,
  buildForecastNarrativePrompt, parseForecastNarrative,
} from '@/modules/accounting/services/cashFlowAIService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { baseRevenue = 0, baseExpenses = 0, cashBalance = 0, months = 6, weeklyMode = false } = req.body;

  // Generate scenarios
  const scenarios = {
    optimistic: buildForecastScenario('optimistic', { baseRevenue, baseExpenses, cashBalance, months }),
    base: buildForecastScenario('base', { baseRevenue, baseExpenses, cashBalance, months }),
    pessimistic: buildForecastScenario('pessimistic', { baseRevenue, baseExpenses, cashBalance, months }),
  };

  // 13-week rolling if requested
  const weekly = weeklyMode ? calculateWeeklyForecast({
    openingBalance: cashBalance,
    weeklyInflow: baseRevenue / 4.33,
    weeklyOutflow: baseExpenses / 4.33,
    weeks: 13,
    minimumBalance: cashBalance * 0.1,
  }) : null;

  // AI narrative
  const lastBase = scenarios.base.points[scenarios.base.points.length - 1];
  let narrative = null;
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (apiKey && lastBase) {
    try {
      const prompt = buildForecastNarrativePrompt({
        currentBalance: cashBalance, projectedBalance: lastBase.closingBalance,
        months, lowestPoint: Math.min(...scenarios.pessimistic.points.map(p => p.closingBalance)),
        lowestMonth: `Month ${scenarios.pessimistic.points.findIndex(p => p.closingBalance === Math.min(...scenarios.pessimistic.points.map(pp => pp.closingBalance))) + 1}`,
      });
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 512, messages: [{ role: 'user', content: prompt }] }),
      });
      if (response.ok) {
        const data = await response.json() as any;
        narrative = parseForecastNarrative(data.content?.[0]?.text || '');
      }
    } catch (err) { log.error('Forecast narrative failed', { error: err }, 'ai'); }
  }

  const allAlerts = [...scenarios.optimistic.alerts, ...scenarios.base.alerts, ...scenarios.pessimistic.alerts];

  log.info('AI forecast generated', { months, hasNarrative: !!narrative }, 'ai');

  return apiResponse.success(res, { scenarios, weekly, narrative, alerts: allAlerts, aiGenerated: !!narrative });
}
export default withCompany(withErrorHandler(handler));

