/**
 * Dunning Communications API
 * GET: List dunning communications (optionally filter by client_id)
 * POST: Create a new dunning communication
 * PUT: Update status (e.g. mark as sent)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withCompany(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  const { companyId } = req as CompanyApiRequest;

  switch (req.method) {
    case 'GET': {
      const { client_id, status: filterStatus, limit: limitStr } = req.query;
      const rowLimit = Math.min(parseInt(limitStr as string, 10) || 100, 500);

      if (client_id) {
        const rows = (await sql`
          SELECT dc.*, c.name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN customers c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.client_id = ${client_id as string}
            AND c.company_id = ${companyId}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      if (filterStatus) {
        const rows = (await sql`
          SELECT dc.*, c.name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN customers c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.status = ${filterStatus as string}
            AND c.company_id = ${companyId}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      const rows = (await sql`
        SELECT dc.*, c.name as client_name,
               u.first_name || ' ' || u.last_name as created_by_name
        FROM dunning_communications dc
        JOIN customers c ON c.id = dc.client_id
        LEFT JOIN users u ON u.id = dc.created_by
        WHERE c.company_id = ${companyId}
        ORDER BY dc.created_at DESC
        LIMIT ${rowLimit}
      `) as Row[];
      return apiResponse.success(res, rows);
    }

    case 'POST': {
      const {
        client_id, type = 'reminder', level = 1,
        subject, body, total_overdue = 0,
        invoices_included = [], sent_via = 'email', sent_to
      } = req.body;

      if (!client_id || !subject || !body) {
        return apiResponse.badRequest(res, 'client_id, subject, and body are required');
      }

      const userId = (req as NextApiRequest & { user?: { id: string } }).user?.id || null;

      const rows = (await sql`
        INSERT INTO dunning_communications (
          client_id, type, level, subject, body, total_overdue,
          invoices_included, sent_via, sent_to, status, created_by
        ) VALUES (
          ${client_id}, ${type}, ${level}, ${subject}, ${body},
          ${total_overdue}, ${invoices_included}, ${sent_via},
          ${sent_to || null}, 'draft', ${userId}
        )
        RETURNING *
      `) as Row[];

      log.info('Dunning communication created', { client_id, type, level }, 'accounting');
      return apiResponse.success(res, rows[0], 'Communication created', 201);
    }

    case 'PUT': {
      const { id, status: newStatus, sent_at } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');

      const rows = (await sql`
        UPDATE dunning_communications
        SET status = COALESCE(${newStatus || null}, status),
            sent_at = COALESCE(${sent_at || null}, sent_at)
        WHERE id = ${id}
        RETURNING *
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Communication', id);
      return apiResponse.success(res, rows[0]);
    }

    default:
      return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
  }
}));

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

