/**
 * Client Portal — Invoices API
 * GET — list invoices for the authenticated portal user's client
 * Requires signed portal session cookie (JWT)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { getClientInvoices } from '@/modules/accounting/services/portalService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    return { clientId: payload.clientId as string };
  } catch {
    return null;
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const session = await getPortalSession(req);
  if (!session) {
    return apiResponse.unauthorized(res, 'Portal authentication required');
  }

  const clientId = req.query.clientId as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'clientId is required');
  }

  // Enforce tenant isolation — user can only access their own client data
  if (session.clientId !== clientId) {
    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
  }

  const invoices = await getClientInvoices(clientId);
  return apiResponse.success(res, { items: invoices });
}

export default withErrorHandler(handler);

/**
 * GET /api/accounting/description-suggest
 * Auto-suggest descriptions from templates + GL history.
 * WS-6.5
 *
 * Query params:
 *   q           — search term (required)
 *   entity_type — optional filter (e.g. 'journal_entry')
 *   limit       — max results (default 10)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withCompany } from '@/lib/auth/withCompany';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { suggestDescriptions } from '@/modules/accounting/services/descriptionTemplateService';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  const companyReq = req as CompanyApiRequest;
  const companyId = companyReq.companyId;

  const q = (req.query.q as string | undefined) ?? '';
  const entityType = req.query.entity_type as string | undefined;
  const limit = Math.min(Number(req.query.limit ?? 10), 20);

  if (!q.trim()) {
    return apiResponse.success(res, { suggestions: [] });
  }

  const suggestions = await suggestDescriptions(companyId, q, entityType, limit);
  return apiResponse.success(res, { suggestions });
}

export default withCompany(withErrorHandler(handler) as any);

/**
 * Archived Data API (read-only)
 * GET /api/accounting/archived-data?date_from=YYYY-MM-DD&date_to=YYYY-MM-DD&limit=50&offset=0
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getArchivedEntries } from '@/modules/accounting/services/dataArchivingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { date_from, date_to, limit, offset } = req.query;

  try {
    const result = await getArchivedEntries(companyId, {
      dateFrom: typeof date_from === 'string' ? date_from : undefined,
      dateTo: typeof date_to === 'string' ? date_to : undefined,
      limit: limit ? Number(limit) : 50,
      offset: offset ? Number(offset) : 0,
    });
    return apiResponse.success(res, result);
  } catch (err) {
    log.error('Failed to get archived data', { companyId, error: err }, 'archived-data-api');
    return apiResponse.internalError(res, err, 'Failed to retrieve archived data');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Approval Requests API
 * GET  — list requests (optional ?status=pending)
 * POST — create request or decide on request
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listRequests, requestApproval, decideRequest, checkApproval, getPendingCount,
  type ApprovalStatus,
} from '@/modules/accounting/services/approvalService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const status = req.query.status as ApprovalStatus | undefined;

    if (req.query.action === 'check') {
      const { documentType, documentId, amount } = req.query;
      if (!documentType || !documentId) {
        return apiResponse.badRequest(res, 'documentType and documentId are required');
      }
      const result = await checkApproval(
        companyId,
        documentType as any,
        documentId as string,
        Number(amount) || 0
      );
      return apiResponse.success(res, result);
    }

    if (req.query.action === 'count') {
      const count = await getPendingCount(companyId);
      return apiResponse.success(res, { count });
    }

    const requests = await listRequests(companyId, status);
    return apiResponse.success(res, { items: requests });
  }

  if (req.method === 'POST') {
    const { action } = req.body;

    if (action === 'request') {
      const { ruleId, documentType, documentId, documentReference, amount } = req.body;
      if (!ruleId || !documentType || !documentId) {
        return apiResponse.badRequest(res, 'ruleId, documentType, and documentId are required');
      }
      const request = await requestApproval(companyId, {
        ruleId, documentType, documentId, documentReference, amount, requestedBy: userId,
      });
      return apiResponse.success(res, request);
    }

    if (action === 'approve' || action === 'reject') {
      const { requestId, notes } = req.body;
      if (!requestId) return apiResponse.badRequest(res, 'requestId is required');
      const decision = action === 'approve' ? 'approved' : 'rejected';
      const result = await decideRequest(companyId, requestId, decision, userId, notes);
      return apiResponse.success(res, result);
    }

    return apiResponse.badRequest(res, 'Invalid action. Use: request, approve, reject');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Data Export Service
 * Exports all major accounting data for a company as structured JSON.
 * Future enhancement: ZIP/CSV generation.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface CompanyExportResult {
  filename: string;
  data: Record<string, unknown[]>;
}

type Row = Record<string, unknown>;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function normalizeRows(rows: Row[]): Record<string, unknown>[] {
  return rows.map((r) => {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(r)) {
      out[k] = v instanceof Date ? toIso(v) : v;
    }
    return out;
  });
}

export async function exportCompanyData(
  companyId: string
): Promise<CompanyExportResult> {
  try {
    const [companyRows, accountRows, customerRows, supplierRows, invoiceRows, journalRows, bankRows] =
      await Promise.all([
        sql`SELECT * FROM companies WHERE id = ${companyId}`,

        sql`SELECT * FROM gl_accounts
            WHERE company_id = ${companyId}
            ORDER BY code`,

        sql`SELECT * FROM customers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM suppliers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM invoices
            WHERE company_id = ${companyId}
            ORDER BY invoice_date DESC`,

        sql`SELECT * FROM gl_journal_entries
            WHERE company_id = ${companyId}
            ORDER BY entry_date DESC`,

        sql`SELECT * FROM bank_transactions
            WHERE company_id = ${companyId}
            ORDER BY transaction_date DESC`,
      ]);

    const companyName =
      (companyRows[0]?.name as string | undefined) ?? companyId;

    const dateStr = new Date().toISOString().split('T')[0];
    const safeName = companyName.replace(/[^a-zA-Z0-9-_]/g, '-').toLowerCase();
    const filename = `export-${safeName}-${dateStr}.json`;

    return {
      filename,
      data: {
        company:         normalizeRows(companyRows),
        accounts:        normalizeRows(accountRows),
        customers:       normalizeRows(customerRows),
        suppliers:       normalizeRows(supplierRows),
        invoices:        normalizeRows(invoiceRows),
        journal_entries: normalizeRows(journalRows),
        bank_transactions: normalizeRows(bankRows),
      },
    };
  } catch (err) {
    log.error('exportCompanyData failed', { companyId, error: err }, 'dataExportService');
    throw err;
  }
}

/**
 * Admin Announcements API
 * GET  /api/admin/announcements — list all (optional ?active_only=true)
 * POST /api/admin/announcements — create announcement
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  listAnnouncements,
  createAnnouncement,
} from '@/modules/admin/services/announcementService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { active_only, page, limit } = req.query;
      const result = await listAnnouncements({
        active_only: active_only === 'true',
        page:  page  ? Number(page)  : undefined,
        limit: limit ? Number(limit) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to list announcements', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list announcements');
    }
  }

  if (req.method === 'POST') {
    try {
      const { title, message, type, target, target_ids, starts_at, ends_at, is_dismissible } =
        req.body as Record<string, unknown>;

      if (!title || !message || !starts_at) {
        return apiResponse.badRequest(res, 'title, message, and starts_at are required');
      }

      const id = await createAnnouncement({
        title:          String(title),
        message:        String(message),
        type:           type          ? String(type)    : undefined,
        target:         target        ? String(target)  : undefined,
        target_ids:     Array.isArray(target_ids) ? (target_ids as string[]) : undefined,
        starts_at:      String(starts_at),
        ends_at:        ends_at       ? String(ends_at) : undefined,
        is_dismissible: typeof is_dismissible === 'boolean' ? is_dismissible : undefined,
        created_by:     req.user.id,
      });

      await logAdminAction(
        req.user.id,
        'announcement.create',
        'announcement',
        id,
        { title: String(title) },
        getIp(req)
      );

      return apiResponse.success(res, { id });
    } catch (err) {
      log.error('Failed to create announcement', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create announcement');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

