import { NextApiRequest, NextApiResponse } from 'next';
import { apiLogger } from '@/lib/logger';

const SENSITIVE_KEYS = new Set(['password', 'confirmPassword', 'password_hash', 'token', 'secret', 'apiKey', 'api_key']);

function sanitizeBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body;
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
    sanitized[key] = SENSITIVE_KEYS.has(key) ? '[REDACTED]' : value;
  }
  return sanitized;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  success: false;
  data: null;
  message: string;
  code?: string;
  details?: Record<string, unknown>;
}

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  message?: string;
}

export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Wraps an API handler with error handling.
 *
 * Generic R extends NextApiRequest to support AuthenticatedNextApiRequest,
 * CompanyApiRequest, or plain NextApiRequest without requiring `as any` casts.
 * The handler's res parameter is typed as NextApiResponse<any> so callers that
 * declare `res: NextApiResponse` (without a type argument) are assignable.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function withErrorHandler<R extends NextApiRequest = NextApiRequest>(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  handler: (req: R, res: NextApiResponse<any>) => unknown
// eslint-disable-next-line @typescript-eslint/no-explicit-any
): (req: R, res: NextApiResponse<any>) => Promise<void | NextApiResponse<any>> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return async (req: R, res: NextApiResponse<any>) => {
    const startTime = Date.now();

    try {
      // Set CORS headers - restrict to known origins
      const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS ?? 'http://localhost:3101').split(',');
      const origin = req.headers.origin;
      if (origin && ALLOWED_ORIGINS.includes(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      }

      // Handle OPTIONS request for CORS
      if (req.method === 'OPTIONS') {
        return res.status(200).end();
      }

      // Log incoming request
      apiLogger.info({
        type: 'request',
        method: req.method,
        url: req.url,
        query: req.query,
        body: req.method !== 'GET' ? sanitizeBody(req.body) : undefined,
      }, `API Request: ${req.method} ${req.url}`);

      // Execute the actual handler
      await handler(req, res);

      // Log successful response
      const duration = Date.now() - startTime;
      apiLogger.info({
        type: 'response',
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
      }, `API Response: ${req.method} ${req.url} - ${res.statusCode} (${duration}ms)`);

    } catch (error) {
      const duration = Date.now() - startTime;

      // Log error with context
      apiLogger.error({
        type: 'error',
        method: req.method,
        url: req.url,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
        duration: `${duration}ms`,
      });

      // Check if headers were already sent
      if (res.headersSent) {
        apiLogger.warn({ method: req.method, url: req.url }, 'Headers already sent, cannot send error response');
        return;
      }

      // Send error response — mask internal details in production
      const errorMessage =
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : error instanceof Error ? error.message : 'An unexpected error occurred';

      res.status(500).json({
        success: false,
        data: null,
        message: errorMessage,
        code: 'INTERNAL_SERVER_ERROR',
        ...(process.env.NODE_ENV === 'development' && {
          details: error instanceof Error ? {
            message: error.message,
            stack: error.stack,
          } as Record<string, unknown> : { error: String(error) },
        }),
      });
    }
  };
}

/**
 * Creates a standard success response
 */
export function successResponse<T>(data: T, message?: string): ApiSuccessResponse<T> {
  return {
    success: true,
    data,
    ...(message && { message }),
  };
}

/**
 * Creates a standard error response
 */
export function errorResponse(
  message: string,
  code?: string,
  details?: Record<string, unknown>
): ApiErrorResponse {
  return {
    success: false,
    data: null,
    message,
    ...(code && { code }),
    ...(details && process.env.NODE_ENV === 'development' && { details }),
  };
}

/**
 * Common HTTP error responses
 */
export const HttpErrors = {
  BadRequest: (message = 'Bad Request') =>
    errorResponse(message, 'BAD_REQUEST'),

  Unauthorized: (message = 'Unauthorized') =>
    errorResponse(message, 'UNAUTHORIZED'),

  Forbidden: (message = 'Forbidden') =>
    errorResponse(message, 'FORBIDDEN'),

  NotFound: (message = 'Not Found') =>
    errorResponse(message, 'NOT_FOUND'),

  MethodNotAllowed: (method: string) =>
    errorResponse(`Method ${method} not allowed`, 'METHOD_NOT_ALLOWED'),

  InternalServerError: (message = 'Internal Server Error') =>
    errorResponse(message, 'INTERNAL_SERVER_ERROR'),

  DatabaseError: (message = 'Database operation failed') =>
    errorResponse(message, 'DATABASE_ERROR'),

  ValidationError: (message = 'Validation failed', details?: Record<string, unknown>) =>
    errorResponse(message, 'VALIDATION_ERROR', details),
};

/**
 * GET  /api/invite/[token] — Validate an invitation token (public)
 * POST /api/invite/[token] — Accept an invitation (requires auth)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { serialize } from 'cookie';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!local || !domain) return '***@***';
  return `${local[0]}***@${domain}`;
}

// ── GET: public token validation ──────────────────────────────────────────────

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  const rows = (await sql`
    SELECT
      ci.email,
      ci.role,
      c.name AS company_name,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS invited_by_name
    FROM company_invitations ci
    JOIN companies c ON c.id = ci.company_id
    LEFT JOIN users u ON u.id = ci.invited_by
    WHERE ci.token = ${token}
      AND ci.accepted_at IS NULL
      AND ci.expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const row = rows[0];

  return apiResponse.success(res, {
    email: maskEmail(row.email as string),
    companyName: row.company_name as string,
    role: row.role as string,
    invitedBy: (row.invited_by_name as string) || 'Someone',
  });
}

// ── POST: accept invitation (auth required) ───────────────────────────────────

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  // Look up the invitation
  const rows = (await sql`
    SELECT id, company_id, email, role
    FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const inv = rows[0];
  const userId = authReq.user.id;

  // Verify invited email matches the logged-in user's email
  if ((inv.email as string).toLowerCase() !== authReq.user.email.toLowerCase()) {
    return apiResponse.forbidden(res, 'This invitation was sent to a different email address');
  }

  // Insert into company_users
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  // Mark invitation accepted
  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  // Mark onboarding completed for this user (they're joining an existing company)
  await sql`
    UPDATE users SET onboarding_completed = true WHERE id = ${userId}
  `;

  log.info('Invitation accepted via token page', { token, userId, companyId: inv.company_id }, 'invite');

  // Set the onboarding-done cookie so middleware stops redirecting
  const cookieStr = serialize('ff_onboarding_done', '1', {
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 30 * 24 * 60 * 60,
  });
  res.setHeader('Set-Cookie', cookieStr);

  return apiResponse.success(res, { companyId: inv.company_id as string }, 'Invitation accepted');
}

// ── Router ────────────────────────────────────────────────────────────────────

const postHandler = withAuth(handlePost);

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    if (req.method === 'GET') {
      return await handleGet(req, res);
    }
    if (req.method === 'POST') {
      return await postHandler(req, res);
    }
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'POST']);
  } catch (err) {
    log.error('Invite token handler error', err instanceof Error ? { message: err.message } : { err }, 'invite');
    return apiResponse.internalError(res, err);
  }
}

/**
 * POST /api/auth/2fa-verify
 * Verify TOTP code during login using a short-lived temp token.
 * Returns full auth token on success (mirrors login response).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken, signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { verifyTOTPCode, addTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';
import type { AuthRole } from '@/lib/auth/types';
import { createHash } from 'crypto';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const {
    tempToken,
    code,
    trustDevice,
    deviceFingerprint,
    deviceName,
  } = req.body as {
    tempToken?: string;
    code?: string;
    trustDevice?: boolean;
    deviceFingerprint?: string;
    deviceName?: string;
  };

  if (!tempToken || !code) {
    return apiResponse.badRequest(res, 'tempToken and code are required');
  }

  try {
    // Verify the temp token
    const payload = await verifyToken(tempToken);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired temp token' },
      });
    }

    // Temp tokens use sessionId = '2fa-pending'
    if (payload.sessionId !== '2fa-pending') {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Token is not a 2FA temp token' },
      });
    }

    const userId = payload.sub;

    // Look up the user
    const rows = (await sql`
      SELECT id, email, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed
      FROM users
      WHERE id = ${userId} AND is_active = true
      LIMIT 1
    `) as Row[];

    const user = rows[0];
    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'USER_NOT_FOUND', message: 'User not found' },
      });
    }

    // Verify TOTP code
    const codeValid = await verifyTOTPCode(userId, code.trim());
    if (!codeValid) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_2FA_CODE', message: 'Invalid authentication code' },
      });
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Create full session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const pendingToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, pendingToken, ipAddress, userAgent);

    const finalToken = await signToken(authUser, session.id);
    const finalHash = createHash('sha256').update(finalToken).digest('hex');

    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Optionally trust device
    if (trustDevice && deviceFingerprint) {
      await addTrustedDevice(userId, deviceFingerprint, deviceName ?? 'Unknown Device');
    }

    const onboardingCompleted = !!user.onboarding_completed;

    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('2FA verified — full session created', { userId }, 'api/auth/2fa-verify');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
    }, 'Two-factor authentication verified');
  } catch (err) {
    log.error('2fa-verify error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-verify');
    return apiResponse.internalError(res, err);
  }
}

