  const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    const resp = await fetch(endpoint.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Event': 'webhook.test',
        ...(signature ? { 'X-Webhook-Signature': signature } : {}),
      },
      body,
      signal: controller.signal,
    });
    clearTimeout(timeout);
    const respBody = await resp.text().catch(() => '');
    log.info('Webhook test sent', { id, status: resp.status }, 'webhook');
    return { success: resp.ok, status: resp.status, body: respBody };
  } catch (err) {
    log.warn('Webhook test failed', { id, error: err }, 'webhook');
    return { success: false, status: 0, body: err instanceof Error ? err.message : 'Request failed' };
  }
}

/**
 * Accounting Documents API
 * GET  /api/accounting/documents?entity_type=...&entity_id=...  — List documents (direct + cross-linked)
 * POST /api/accounting/documents  (multipart form-data)          — Upload document
 * DELETE /api/accounting/documents?id=...                        — Soft-delete document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import path from 'path';
import { sql } from '@/lib/neon';
import formidable from 'formidable';
import fs from 'fs';
import { vfStorage } from '@/services/vfStorageAdapter';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';
import type {
  ProcurementDocument,
  LinkedDocument,
  AccountingEntityType,
  AccountingDocumentType,
} from '@/types/procurement/document.types';
import { extractFromPdf, extractFromImage } from '@/modules/accounting/services/ocrService';
import { isVlmAvailable } from '@/modules/accounting/services/vlmService';

export const config = {
  api: { bodyParser: false },
};

const VALID_ENTITY_TYPES: AccountingEntityType[] = [
  'supplier_invoice',
  'supplier_payment',
  'customer_invoice',
  'customer_payment',
  'credit_note',
];

const VALID_DOCUMENT_TYPES: AccountingDocumentType[] = [
  'proof_of_payment',
  'bank_statement',
  'remittance_advice',
  'credit_note_doc',
  'invoice',
  'receipt',
  'other',
];

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB

function validateMagicBytes(buffer: Buffer): boolean {
  if (buffer.length < 4) return false;
  const hex = buffer.subarray(0, 8).toString('hex').toUpperCase();
  if (hex.startsWith('FFD8FF')) return true;   // JPEG
  if (hex.startsWith('89504E47')) return true;  // PNG
  if (hex.startsWith('25504446')) return true;  // PDF
  if (hex.startsWith('504B0304')) return true;  // ZIP (docx/xlsx)
  return false;
}

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({ maxFileSize: MAX_FILE_SIZE, keepExtensions: true });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>, source: 'direct' | 'linked' = 'direct', linkReason?: string): LinkedDocument {
  return {
    id: row.id as string,
    entityType: row.entity_type as string,
    entityId: row.entity_id as string,
    documentType: row.document_type as AccountingDocumentType,
    documentName: row.document_name as string,
    fileUrl: row.file_url as string,
    filePath: (row.file_path as string) || undefined,
    fileSize: (row.file_size as number) || undefined,
    mimeType: (row.mime_type as string) || undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedByName: (row.uploaded_by_name as string) || undefined,
    uploadedAt: new Date(row.uploaded_at as string).toISOString(),
    notes: (row.notes as string) || undefined,
    isActive: row.is_active as boolean,
    source,
    linkReason,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string; name: string; email: string } }).user;

  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res, user);
  if (req.method === 'DELETE') return handleDelete(req, res);

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** GET — List direct + cross-linked documents for an accounting entity */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const entityType = req.query.entity_type as string;
  const entityId = req.query.entity_id as string;

  if (!entityType || !entityId) {
    return apiResponse.badRequest(res, 'Missing required query params: entity_type, entity_id');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
    return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  // Direct documents
  const directRows = await sql`
    SELECT * FROM procurement_documents
    WHERE entity_type = ${entityType}
      AND entity_id = ${entityId}::uuid
      AND is_active = true
    ORDER BY uploaded_at DESC
  `;

  // Cross-linked documents (via document_links)
  const linkedRows = await sql`
    SELECT pd.*, dl.link_reason
    FROM document_links dl
    JOIN procurement_documents pd ON pd.id = dl.document_id
    WHERE dl.linked_entity_type = ${entityType}
      AND dl.linked_entity_id = ${entityId}::uuid
      AND pd.is_active = true
    ORDER BY pd.uploaded_at DESC
  `;

  const results: LinkedDocument[] = [
    ...directRows.map(r => mapRow(r as Record<string, unknown>, 'direct')),
    ...linkedRows.map(r => mapRow(r as Record<string, unknown>, 'linked', (r as Record<string, unknown>).link_reason as string)),
  ];

  return apiResponse.success(res, results);
}

/** POST — Upload a document to an accounting entity */
async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  user: { id: string; name: string; email: string }
) {
  let tempFilePath: string | null = null;

  try {
    const { fields, files } = await parseForm(req);

    const entityType = (Array.isArray(fields.entity_type) ? fields.entity_type[0] : fields.entity_type) as string;
    const entityId = (Array.isArray(fields.entity_id) ? fields.entity_id[0] : fields.entity_id) as string;
    const documentType = ((Array.isArray(fields.document_type) ? fields.document_type[0] : fields.document_type) || 'other') as string;
    const notes = (Array.isArray(fields.notes) ? fields.notes[0] : fields.notes) as string | undefined;

    if (!entityType || !entityId) {
      return apiResponse.badRequest(res, 'Missing required fields: entity_type, entity_id');
    }
    if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
      return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
    }
    if (!VALID_DOCUMENT_TYPES.includes(documentType as AccountingDocumentType)) {
      return apiResponse.badRequest(res, `Invalid document_type. Allowed: ${VALID_DOCUMENT_TYPES.join(', ')}`);
    }

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;
    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    tempFilePath = file.filepath;

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype || '')) {
      return apiResponse.badRequest(res, `File type not allowed: ${file.mimetype}. Allowed: PDF, JPEG, PNG, DOCX, XLSX`);
    }
    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, 'File too large. Maximum size: 20MB');
    }

    const buffer = await fs.promises.readFile(file.filepath);
    if (!validateMagicBytes(buffer)) {
      return apiResponse.badRequest(res, 'File content does not match declared type');
    }

    // Upload to VF Storage: accounting/{entity_type}/{entityId}_{filename}
    const rawName = file.originalFilename || `document_${Date.now()}`;
    const fileName = path.basename(rawName).replace(/[^a-zA-Z0-9._-]/g, '_');
    const storageName = `${entityId}_${fileName}`;
    const result = await vfStorage.uploadFile(buffer, 'accounting', entityType, storageName);

    // Insert DB record
    const [row] = await sql`
      INSERT INTO procurement_documents (
        entity_type, entity_id, document_type, document_name,
        file_url, file_path, file_size, mime_type,
        uploaded_by, uploaded_by_name, notes
      ) VALUES (
        ${entityType}, ${entityId}::uuid, ${documentType}, ${fileName},
        ${result.url}, ${result.path}, ${file.size}, ${file.mimetype || ''},
        ${user.email}, ${user.name}, ${notes || null}
      )
      RETURNING *
    `;

    const docId = (row as Record<string, unknown>).id as string;

    // Auto-link: if supplier_invoice, create cross-links to PO/GRN
    if (entityType === 'supplier_invoice') {
      await autoLinkSupplierInvoice(docId, entityId);
    }

    // Fire-and-forget VLM extraction (non-blocking)
    if (isVlmAvailable()) {
      extractAndStoreDocMetadata(buffer, file.mimetype || '', docId).catch(err =>
        log.warn('Background VLM extraction failed', { error: err instanceof Error ? err.message : String(err) }, 'accounting-docs')
      );
    }

    log.info('Accounting document uploaded', {
      data: { entityType, entityId, documentType, fileName },
    }, 'accounting-docs');

    return apiResponse.created(res, mapRow(row as Record<string, unknown>, 'direct'));
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error('Accounting document upload error', { error }, 'accounting-docs');
    return apiResponse.internalError(res, error, `Failed to upload document: ${errMsg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) =>
        log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'accounting')
      );
    }
  }
}

/**
 * Auto-link a newly uploaded supplier_invoice doc to related PO/GRN,
 * and create reverse links so existing PO/GRN docs appear on the invoice.
 */
async function autoLinkSupplierInvoice(docId: string, invoiceId: string) {
  try {
    // Look up FK references on the invoice
    const [invoice] = await sql`
      SELECT purchase_order_id, grn_id
      FROM sage_supplier_invoices
      WHERE id = ${invoiceId}::uuid
    `;

    if (!invoice) return;

    const poId = invoice.purchase_order_id as string | null;
    const grnId = invoice.grn_id as string | null;

    // Forward links: this doc -> PO/GRN
    if (poId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'purchase_order', ${poId}::uuid, 'po_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }
    if (grnId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'goods_receipt_note', ${grnId}::uuid, 'grn_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }

    // Reverse links: existing PO/GRN docs -> this invoice
    if (poId) {
      const poDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'purchase_order' AND entity_id = ${poId}::uuid AND is_active = true
      `;
      for (const doc of poDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'po_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
    if (grnId) {
      const grnDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'goods_receipt_note' AND entity_id = ${grnId}::uuid AND is_active = true
      `;
      for (const doc of grnDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'grn_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
  } catch (err) {
    log.warn('Auto-link supplier invoice docs failed (non-fatal)', { error: err }, 'accounting-docs');
  }
}

/** Background VLM extraction — stores result in extracted_data JSONB column */
async function extractAndStoreDocMetadata(buffer: Buffer, mimeType: string, docId: string) {
  const isPdf = mimeType === 'application/pdf';
  const isImage = mimeType.startsWith('image/');

  if (!isPdf && !isImage) return;

  const extracted = isPdf
    ? await extractFromPdf(buffer)
    : await extractFromImage(buffer, mimeType);

  if (extracted && extracted.confidence > 0) {
    await sql`
      UPDATE procurement_documents
      SET extracted_data = ${JSON.stringify(extracted)}::jsonb
      WHERE id = ${docId}::uuid
    `;
    log.info('VLM extraction stored for document', { docId, confidence: extracted.confidence }, 'accounting-docs');
  }
}

/** DELETE — Soft-delete a document */
async function handleDelete(req: NextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;
  if (!id) {
    return apiResponse.badRequest(res, 'Missing required query param: id');
  }

  const [row] = await sql`
    UPDATE procurement_documents
    SET is_active = false
    WHERE id = ${id}::uuid AND is_active = true
    RETURNING id
  `;

  if (!row) {
    return apiResponse.notFound(res, 'Document', id);
  }

  log.info('Accounting document soft-deleted', { data: { id } }, 'accounting-docs');
  return apiResponse.success(res, { id: row.id, deleted: true });
}

export default withCompany(withErrorHandler(handler));

/**
 * Two-Factor Authentication Service
 * Handles TOTP setup, verification, backup codes, and trusted devices.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import * as OTPAuth from 'otpauth';
import QRCode from 'qrcode';
import { createHash, randomBytes } from 'crypto';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface TrustedDevice {
  id: string;
  deviceName: string | null;
  deviceFingerprint: string;
  trustedUntil: string;
  lastUsedAt: string;
  createdAt: string;
}

export interface TwoFactorStatus {
  enabled: boolean;
  method: string | null;
  verifiedAt: string | null;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function hashBackupCode(code: string): string {
  return createHash('sha256').update(code).digest('hex');
}

function generateBackupCodes(): string[] {
  return Array.from({ length: 10 }, () =>
    randomBytes(4).toString('hex').toUpperCase()
  );
}

// ── TOTP Setup ────────────────────────────────────────────────────────────────

export async function generateTOTPSecret(
  userId: string,
  userEmail: string
): Promise<{ secret: string; uri: string; qrCodeDataUrl: string }> {
  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: `ISAFlow:${userEmail}`,
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromUTF8(randomBytes(20).toString('hex').slice(0, 32)),
  });

  const secret = totp.secret.base32;
  const uri = totp.toString();

  // Upsert — replace any unverified pending setup
  await sql`
    INSERT INTO user_2fa (user_id, method, secret_encrypted, is_enabled, is_verified, updated_at)
    VALUES (${userId}, 'totp', ${secret}, false, false, NOW())
    ON CONFLICT (user_id, method)
    DO UPDATE SET
      secret_encrypted = EXCLUDED.secret_encrypted,
      is_enabled = false,
      is_verified = false,
      updated_at = NOW()
  `;

  const qrCodeDataUrl = await QRCode.toDataURL(uri, {
    errorCorrectionLevel: 'M',
    margin: 1,
    width: 280,
    color: { dark: '#000000', light: '#ffffff' },
  });

  log.info('TOTP secret generated', { userId }, 'twoFactorService');

  return { secret, uri, qrCodeDataUrl };
}

// ── TOTP Verify Setup ─────────────────────────────────────────────────────────

export async function verifyTOTPSetup(
  userId: string,
  code: string
): Promise<{ success: boolean; backupCodes?: string[] }> {
  const rows = await sql`
    SELECT secret_encrypted FROM user_2fa
    WHERE user_id = ${userId} AND method = 'totp'
    LIMIT 1
  `;

  const row = rows[0];
  if (!row?.secret_encrypted) {
    log.warn('TOTP setup verify: no pending setup found', { userId }, 'twoFactorService');
    return { success: false };
  }

  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: `ISAFlow`,
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromBase32(row.secret_encrypted as string),
  });

  const delta = totp.validate({ token: code, window: 1 });
  if (delta === null) {
    log.warn('TOTP setup verify: invalid code', { userId }, 'twoFactorService');
    return { success: false };
  }

  const plainCodes = generateBackupCodes();
  const hashedCodes = plainCodes.map(hashBackupCode);

  await sql`
    UPDATE user_2fa
    SET is_enabled = true,
        is_verified = true,
        backup_codes = ${hashedCodes},
        updated_at = NOW()
    WHERE user_id = ${userId} AND method = 'totp'
  `;

  log.info('TOTP setup verified and enabled', { userId }, 'twoFactorService');

  return { success: true, backupCodes: plainCodes };
}

// ── TOTP Verify (during login) ────────────────────────────────────────────────

export async function verifyTOTPCode(userId: string, code: string): Promise<boolean> {
  const rows = await sql`
    SELECT secret_encrypted, backup_codes FROM user_2fa
    WHERE user_id = ${userId} AND method = 'totp' AND is_enabled = true AND is_verified = true
    LIMIT 1
  `;

  const row = rows[0];
  if (!row?.secret_encrypted) return false;

  // Check TOTP
  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: 'ISAFlow',
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromBase32(row.secret_encrypted as string),
  });

  const delta = totp.validate({ token: code, window: 1 });
  if (delta !== null) {
    log.info('TOTP code verified', { userId }, 'twoFactorService');
    return true;
  }

  // Check backup codes (one-time use)
  const storedCodes = (row.backup_codes as string[]) || [];
  const codeHash = hashBackupCode(code.toUpperCase().trim());
  const matchIndex = storedCodes.indexOf(codeHash);

  if (matchIndex !== -1) {
    // Remove used backup code
    const updatedCodes = storedCodes.filter((_, i) => i !== matchIndex);
    await sql`
      UPDATE user_2fa SET backup_codes = ${updatedCodes}, updated_at = NOW()
      WHERE user_id = ${userId} AND method = 'totp'
    `;
    log.info('Backup code used', { userId, remaining: updatedCodes.length }, 'twoFactorService');
    return true;
  }

  log.warn('TOTP code invalid', { userId }, 'twoFactorService');
  return false;
}

// ── Disable 2FA ───────────────────────────────────────────────────────────────

export async function disable2FA(userId: string, code: string): Promise<boolean> {
  const valid = await verifyTOTPCode(userId, code);
  if (!valid) return false;

  await sql`
    DELETE FROM user_2fa WHERE user_id = ${userId} AND method = 'totp'
  `;

  log.info('2FA disabled', { userId }, 'twoFactorService');
  return true;
}

// ── Status ────────────────────────────────────────────────────────────────────

export async function get2FAStatus(userId: string): Promise<TwoFactorStatus> {
  const rows = await sql`
    SELECT method, is_enabled, updated_at FROM user_2fa
    WHERE user_id = ${userId} AND is_enabled = true AND is_verified = true
    LIMIT 1
  `;

  const row = rows[0];
  if (!row) return { enabled: false, method: null, verifiedAt: null };

  const updatedAt = row.updated_at;
  const verifiedAt =
    updatedAt instanceof Date
      ? updatedAt.toISOString()
      : typeof updatedAt === 'string'
        ? updatedAt
        : null;

  return {
    enabled: true,
    method: row.method as string,
    verifiedAt,
  };
}

// ── Trusted Devices ───────────────────────────────────────────────────────────

export async function addTrustedDevice(
  userId: string,
  fingerprint: string,
  deviceName: string
): Promise<void> {
  const trustedUntil = new Date();
  trustedUntil.setDate(trustedUntil.getDate() + 30);

  await sql`
    INSERT INTO user_trusted_devices (user_id, device_fingerprint, device_name, trusted_until, last_used_at)
    VALUES (${userId}, ${fingerprint}, ${deviceName}, ${trustedUntil.toISOString()}, NOW())
    ON CONFLICT (user_id, device_fingerprint)
    DO UPDATE SET
      trusted_until = EXCLUDED.trusted_until,
      device_name = EXCLUDED.device_name,
      last_used_at = NOW()
  `;

  log.info('Device trusted', { userId, deviceName }, 'twoFactorService');
}

export async function isTrustedDevice(
  userId: string,
  fingerprint: string
): Promise<boolean> {
  const rows = await sql`
    SELECT id FROM user_trusted_devices
    WHERE user_id = ${userId}
      AND device_fingerprint = ${fingerprint}
      AND trusted_until > NOW()
    LIMIT 1
  `;

  return rows.length > 0;
}

export async function getTrustedDevices(userId: string): Promise<TrustedDevice[]> {
  const rows = await sql`
    SELECT id, device_name, device_fingerprint, trusted_until, last_used_at, created_at
    FROM user_trusted_devices
    WHERE user_id = ${userId} AND trusted_until > NOW()
    ORDER BY last_used_at DESC
  `;

  return rows.map(r => {
    const trustedUntil = r.trusted_until instanceof Date
      ? r.trusted_until.toISOString() : r.trusted_until as string;
    const lastUsedAt = r.last_used_at instanceof Date
      ? r.last_used_at.toISOString() : r.last_used_at as string;
    const createdAt = r.created_at instanceof Date
      ? r.created_at.toISOString() : r.created_at as string;

    return {
      id: r.id as string,
      deviceName: (r.device_name as string | null),
      deviceFingerprint: r.device_fingerprint as string,
      trustedUntil,
      lastUsedAt,
      createdAt,
    };
  });
}

export async function removeTrustedDevice(
  userId: string,
  deviceId: string
): Promise<void> {
  await sql`
    DELETE FROM user_trusted_devices
    WHERE id = ${deviceId}::UUID AND user_id = ${userId}
  `;

  log.info('Trusted device removed', { userId, deviceId }, 'twoFactorService');
}

/**
 * AES-256-GCM encryption utilities for sensitive data at rest.
 * Requires ENCRYPTION_KEY env var (min 32 chars).
 */

import crypto from 'crypto';
import { log } from '@/lib/logger';

const ALGORITHM = 'aes-256-gcm';

function getEncryptionKey(): Buffer {
  const key = process.env.ENCRYPTION_KEY;
  if (!key || key.length < 32) {
    throw new Error('ENCRYPTION_KEY must be set (min 32 chars)');
  }
  return Buffer.from(key.slice(0, 32), 'utf-8');
}

export function isEncryptionAvailable(): boolean {
  const key = process.env.ENCRYPTION_KEY;
  return !!(key && key.length >= 32);
}

export function encrypt(plaintext: string): string {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return `${iv.toString('hex')}:${tag}:${encrypted}`;
}

export function decrypt(ciphertext: string): string {
  const key = getEncryptionKey();
  const [ivHex, tagHex, encryptedHex] = ciphertext.split(':');
  if (!ivHex || !tagHex || !encryptedHex) {
    throw new Error('Invalid encrypted format');
  }
  const iv = Buffer.from(ivHex, 'hex');
  const tag = Buffer.from(tagHex, 'hex');
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

/** Encrypt token if key is available, otherwise warn and return plaintext. */
export function encryptToken(plaintext: string): string {
  if (!isEncryptionAvailable()) {
    log.warn('ENCRYPTION_KEY not set — storing token as plaintext', {}, 'encryption');
    return plaintext;
  }
  return encrypt(plaintext);
}

/** Decrypt token if it looks encrypted, otherwise return as-is (plaintext fallback). */
export function decryptToken(value: string): string {
  if (!value) return value;
  // Encrypted format: hex:hex:hex (iv:tag:ciphertext)
  const parts = value.split(':');
  if (parts.length !== 3) {
    // Stored as plaintext — likely pre-encryption-key migration
    return value;
  }
  try {
    return decrypt(value);
  } catch {
    log.warn('Failed to decrypt token — returning as-is', {}, 'encryption');
    return value;
  }
}

const REQUIRED_VARS = ['DATABASE_URL', 'JWT_SECRET'] as const;
const RECOMMENDED_VARS = ['ENCRYPTION_KEY', 'SMTP_HOST', 'SMTP_USER', 'SMTP_PASS'] as const;

export function validateEnv(): void {
  const missing = REQUIRED_VARS.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  const missingRecommended = RECOMMENDED_VARS.filter(v => !process.env[v]);
  if (missingRecommended.length > 0) {
    console.warn(`[env] Missing recommended variables: ${missingRecommended.join(', ')}`);
  }
}

/**
 * Admin Billing Plan Detail API
 * GET    /api/admin/billing/plans/[id] — Get a single plan
 * PATCH  /api/admin/billing/plans/[id] — Update a plan
 * DELETE /api/admin/billing/plans/[id] — Archive a plan
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getPlan, updatePlan, archivePlan } from '@/modules/admin/services/planService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const plan = await getPlan(id);
      if (!plan) return apiResponse.notFound(res, 'Plan not found');
      return apiResponse.success(res, plan);
    } catch (err) {
      log.error('Failed to get plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get plan');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as Record<string, unknown>;
      await updatePlan(id, body);

      await logAdminAction(
        req.user.id,
        'plan.update',
        'plan',
        id,
        body,
        getIp(req)
      );

      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update plan');
    }
  }

  if (req.method === 'DELETE') {
    try {
      await archivePlan(id);

      await logAdminAction(
        req.user.id,
        'plan.archive',
        'plan',
        id,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { archived: true });
    } catch (err) {
      log.error('Failed to archive plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to archive plan');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH', 'DELETE']);
}

export default withAdmin(handler);

/**
 * POST /api/auth/change-password
 * Allows the authenticated user to change their password.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword, hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userId = authReq.user.id;

  const { oldPassword, newPassword, confirmPassword } = req.body as {
    oldPassword?: string;
    newPassword?: string;
    confirmPassword?: string;
  };

  if (!oldPassword || !newPassword || !confirmPassword) {
    return apiResponse.badRequest(res, 'All password fields are required');
  }

  if (newPassword !== confirmPassword) {
    return apiResponse.badRequest(res, 'New passwords do not match');
  }

  const strength = checkPasswordStrength(newPassword);
  if (strength.score < 2) {
    return apiResponse.badRequest(
      res,
      `Password too weak: ${strength.issues[0] ?? 'Please choose a stronger password'}`
    );
  }

  // Fetch current password hash
  const rows = (await sql`
    SELECT password_hash FROM users WHERE id = ${userId} LIMIT 1
  `) as Row[];

  if (!rows.length) {
    return apiResponse.notFound(res, 'User');
  }

  const currentHash: string = rows[0].password_hash;
  const valid = await verifyPassword(oldPassword, currentHash);

  if (!valid) {
    return apiResponse.badRequest(res, 'Current password is incorrect');
  }

  const newHash = await hashPassword(newPassword);

  await sql`
    UPDATE users SET password_hash = ${newHash} WHERE id = ${userId}
  `;

  log.info('Password changed', { userId }, 'auth/change-password');

  return apiResponse.success(res, null, 'Password changed successfully');
}

export default withAuth(withErrorHandler(handler) as any);

/**
 * Plan Service
 * CRUD operations for billing plans in the ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Plan } from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

function rowToPlan(r: Row): Plan {
  return {
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    monthly_price_cents: r.monthly_price_cents as number,
    annual_price_cents: r.annual_price_cents as number,
    currency: r.currency as string,
    features: (r.features ?? {}) as Record<string, unknown>,
    limits: (r.limits ?? {}) as Record<string, unknown>,
    is_active: r.is_active as boolean,
    display_order: r.display_order as number,
    created_at: toIso(r.created_at),
    updated_at: toIso(r.updated_at),
  };
}

export async function listPlans(includeArchived = false): Promise<Plan[]> {
  const rows = includeArchived
    ? await sql`
        SELECT * FROM plans
        ORDER BY display_order ASC, name ASC
      `
    : await sql`
        SELECT * FROM plans
        WHERE is_active = true
        ORDER BY display_order ASC, name ASC
      `;

  log.info(`listPlans: ${rows.length} plans (includeArchived=${includeArchived})`, {}, 'PlanService');
  return (rows as Row[]).map(rowToPlan);
}

export async function getPlan(planId: string): Promise<Plan | null> {
  const rows = await sql`
    SELECT * FROM plans
    WHERE id = ${planId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToPlan(rows[0] as Row);
}

export interface CreatePlanData {
  code: string;
  name: string;
  description?: string;
  monthly_price_cents: number;
  annual_price_cents: number;
  currency?: string;
  features?: Record<string, unknown>;
  limits?: Record<string, unknown>;
  display_order?: number;
}

export async function createPlan(data: CreatePlanData): Promise<Plan> {
  const {
    code,
    name,
    description = null,
    monthly_price_cents,
    annual_price_cents,
    currency = 'ZAR',
    features = {},
    limits = {},
    display_order = 0,
  } = data;

  const rows = await sql`
    INSERT INTO plans (
      code, name, description,
      monthly_price_cents, annual_price_cents, currency,
      features, limits, is_active, display_order,
      created_at, updated_at
    ) VALUES (
      ${code}, ${name}, ${description},
      ${monthly_price_cents}, ${annual_price_cents}, ${currency},
      ${JSON.stringify(features)}::jsonb, ${JSON.stringify(limits)}::jsonb,
      true, ${display_order},
      NOW(), NOW()
    )
    RETURNING *
  `;

  const plan = rowToPlan(rows[0] as Row);
  log.info('createPlan', { planId: plan.id, code }, 'PlanService');
  return plan;
}

export async function updatePlan(
  planId: string,
  data: Partial<Plan>
): Promise<void> {
  const {
    name, description, monthly_price_cents, annual_price_cents,
    currency, features, limits, is_active, display_order,
  } = data;

  await sql`
    UPDATE plans SET
      name                 = COALESCE(${name ?? null}, name),
      description          = COALESCE(${description ?? null}, description),
      monthly_price_cents  = COALESCE(${monthly_price_cents ?? null}, monthly_price_cents),
      annual_price_cents   = COALESCE(${annual_price_cents ?? null}, annual_price_cents),
      currency             = COALESCE(${currency ?? null}, currency),
      features             = COALESCE(${features != null ? JSON.stringify(features) : null}::jsonb, features),
      limits               = COALESCE(${limits != null ? JSON.stringify(limits) : null}::jsonb, limits),
      is_active            = COALESCE(${is_active ?? null}, is_active),
      display_order        = COALESCE(${display_order ?? null}, display_order),
      updated_at           = NOW()
    WHERE id = ${planId}
  `;

  log.info('updatePlan', { planId, fields: Object.keys(data) }, 'PlanService');
}

export async function archivePlan(planId: string): Promise<void> {
  await sql`
    UPDATE plans
    SET is_active  = false,
        updated_at = NOW()
    WHERE id = ${planId}
  `;
  log.info('archivePlan', { planId }, 'PlanService');
}

/**
 * Admin Billing Subscription Detail API
 * GET   /api/admin/billing/subscriptions/[id] — Get a single subscription
 * PATCH /api/admin/billing/subscriptions/[id] — Update a subscription
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getSubscription, updateSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';
import { getIp } from '@/utils/getIp';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const subscription = await getSubscription(id);
      if (!subscription) return apiResponse.notFound(res, 'Subscription not found');
      return apiResponse.success(res, subscription);
    } catch (err) {
      log.error('Failed to get subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get subscription');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as {
        plan_id?: string;
        billing_cycle?: string;
        discount_percent?: number;
