/**
 * Two-Factor Authentication Service
 * Handles TOTP setup, verification, backup codes, and trusted devices.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import * as OTPAuth from 'otpauth';
import QRCode from 'qrcode';
import { createHash, randomBytes } from 'crypto';
import { encryptToken, decryptToken } from '@/lib/encryption';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface TrustedDevice {
  id: string;
  deviceName: string | null;
  deviceFingerprint: string;
  trustedUntil: string;
  lastUsedAt: string;
  createdAt: string;
}

export interface TwoFactorStatus {
  enabled: boolean;
  method: string | null;
  verifiedAt: string | null;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function hashBackupCode(code: string): string {
  return createHash('sha256').update(code).digest('hex');
}

function generateBackupCodes(): string[] {
  return Array.from({ length: 10 }, () =>
    randomBytes(4).toString('hex').toUpperCase()
  );
}

// ── TOTP Setup ────────────────────────────────────────────────────────────────

export async function generateTOTPSecret(
  userId: string,
  userEmail: string
): Promise<{ secret: string; uri: string; qrCodeDataUrl: string }> {
  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: `ISAFlow:${userEmail}`,
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromUTF8(randomBytes(20).toString('hex').slice(0, 32)),
  });

  const secret = totp.secret.base32;
  const uri = totp.toString();

  // Upsert — replace any unverified pending setup (encrypt secret at rest)
  const encryptedSecret = encryptToken(secret);
  await sql`
    INSERT INTO user_2fa (user_id, method, secret_encrypted, is_enabled, is_verified, updated_at)
    VALUES (${userId}, 'totp', ${encryptedSecret}, false, false, NOW())
    ON CONFLICT (user_id, method)
    DO UPDATE SET
      secret_encrypted = EXCLUDED.secret_encrypted,
      is_enabled = false,
      is_verified = false,
      updated_at = NOW()
  `;

  const qrCodeDataUrl = await QRCode.toDataURL(uri, {
    errorCorrectionLevel: 'M',
    margin: 1,
    width: 280,
    color: { dark: '#000000', light: '#ffffff' },
  });

  log.info('TOTP secret generated', { userId }, 'twoFactorService');

  return { secret, uri, qrCodeDataUrl };
}

// ── TOTP Verify Setup ─────────────────────────────────────────────────────────

export async function verifyTOTPSetup(
  userId: string,
  code: string
): Promise<{ success: boolean; backupCodes?: string[] }> {
  const rows = await sql`
    SELECT secret_encrypted FROM user_2fa
    WHERE user_id = ${userId} AND method = 'totp'
    LIMIT 1
  `;

  const row = rows[0];
  if (!row?.secret_encrypted) {
    log.warn('TOTP setup verify: no pending setup found', { userId }, 'twoFactorService');
    return { success: false };
  }

  const decryptedSecret = decryptToken(row.secret_encrypted as string);
  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: `ISAFlow`,
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromBase32(decryptedSecret),
  });

  const delta = totp.validate({ token: code, window: 1 });
  if (delta === null) {
    log.warn('TOTP setup verify: invalid code', { userId }, 'twoFactorService');
    return { success: false };
  }

  const plainCodes = generateBackupCodes();
  const hashedCodes = plainCodes.map(hashBackupCode);

  await sql`
    UPDATE user_2fa
    SET is_enabled = true,
        is_verified = true,
        backup_codes = ${hashedCodes},
        updated_at = NOW()
    WHERE user_id = ${userId} AND method = 'totp'
  `;

  log.info('TOTP setup verified and enabled', { userId }, 'twoFactorService');

  return { success: true, backupCodes: plainCodes };
}

// ── TOTP Verify (during login) ────────────────────────────────────────────────

export async function verifyTOTPCode(userId: string, code: string): Promise<boolean> {
  const rows = await sql`
    SELECT secret_encrypted, backup_codes FROM user_2fa
    WHERE user_id = ${userId} AND method = 'totp' AND is_enabled = true AND is_verified = true
    LIMIT 1
  `;

  const row = rows[0];
  if (!row?.secret_encrypted) return false;

  // Check TOTP
  const totp = new OTPAuth.TOTP({
    issuer: 'ISAFlow',
    label: 'ISAFlow',
    algorithm: 'SHA1',
    digits: 6,
    period: 30,
    secret: OTPAuth.Secret.fromBase32(row.secret_encrypted as string),
  });

  const delta = totp.validate({ token: code, window: 1 });
  if (delta !== null) {
    log.info('TOTP code verified', { userId }, 'twoFactorService');
    return true;
  }

  // Check backup codes (one-time use)
  const storedCodes = (row.backup_codes as string[]) || [];
  const codeHash = hashBackupCode(code.toUpperCase().trim());
  const matchIndex = storedCodes.indexOf(codeHash);

  if (matchIndex !== -1) {
    // Remove used backup code
    const updatedCodes = storedCodes.filter((_, i) => i !== matchIndex);
    await sql`
      UPDATE user_2fa SET backup_codes = ${updatedCodes}, updated_at = NOW()
      WHERE user_id = ${userId} AND method = 'totp'
    `;
    log.info('Backup code used', { userId, remaining: updatedCodes.length }, 'twoFactorService');
    return true;
  }

  log.warn('TOTP code invalid', { userId }, 'twoFactorService');
  return false;
}

// ── Disable 2FA ───────────────────────────────────────────────────────────────

export async function disable2FA(userId: string, code: string): Promise<boolean> {
  const valid = await verifyTOTPCode(userId, code);
  if (!valid) return false;

  await sql`
    DELETE FROM user_2fa WHERE user_id = ${userId} AND method = 'totp'
  `;

  log.info('2FA disabled', { userId }, 'twoFactorService');
  return true;
}

// ── Status ────────────────────────────────────────────────────────────────────

export async function get2FAStatus(userId: string): Promise<TwoFactorStatus> {
  const rows = await sql`
    SELECT method, is_enabled, updated_at FROM user_2fa
    WHERE user_id = ${userId} AND is_enabled = true AND is_verified = true
    LIMIT 1
  `;

  const row = rows[0];
  if (!row) return { enabled: false, method: null, verifiedAt: null };

  const updatedAt = row.updated_at;
  const verifiedAt =
    updatedAt instanceof Date
      ? updatedAt.toISOString()
      : typeof updatedAt === 'string'
        ? updatedAt
        : null;

  return {
    enabled: true,
    method: row.method as string,
    verifiedAt,
  };
}

// ── Trusted Devices ───────────────────────────────────────────────────────────

export async function addTrustedDevice(
  userId: string,
  fingerprint: string,
  deviceName: string
): Promise<void> {
  const trustedUntil = new Date();
  trustedUntil.setDate(trustedUntil.getDate() + 30);

  await sql`
    INSERT INTO user_trusted_devices (user_id, device_fingerprint, device_name, trusted_until, last_used_at)
    VALUES (${userId}, ${fingerprint}, ${deviceName}, ${trustedUntil.toISOString()}, NOW())
    ON CONFLICT (user_id, device_fingerprint)
    DO UPDATE SET
      trusted_until = EXCLUDED.trusted_until,
      device_name = EXCLUDED.device_name,
      last_used_at = NOW()
  `;

  log.info('Device trusted', { userId, deviceName }, 'twoFactorService');
}

export async function isTrustedDevice(
  userId: string,
  fingerprint: string
): Promise<boolean> {
  const rows = await sql`
    SELECT id FROM user_trusted_devices
    WHERE user_id = ${userId}
      AND device_fingerprint = ${fingerprint}
      AND trusted_until > NOW()
    LIMIT 1
  `;

  return rows.length > 0;
}

export async function getTrustedDevices(userId: string): Promise<TrustedDevice[]> {
  const rows = await sql`
    SELECT id, device_name, device_fingerprint, trusted_until, last_used_at, created_at
    FROM user_trusted_devices
    WHERE user_id = ${userId} AND trusted_until > NOW()
    ORDER BY last_used_at DESC
  `;

  return rows.map(r => {
    const trustedUntil = r.trusted_until instanceof Date
      ? r.trusted_until.toISOString() : r.trusted_until as string;
    const lastUsedAt = r.last_used_at instanceof Date
      ? r.last_used_at.toISOString() : r.last_used_at as string;
    const createdAt = r.created_at instanceof Date
      ? r.created_at.toISOString() : r.created_at as string;

    return {
      id: r.id as string,
      deviceName: (r.device_name as string | null),
      deviceFingerprint: r.device_fingerprint as string,
      trustedUntil,
      lastUsedAt,
      createdAt,
    };
  });
}

export async function removeTrustedDevice(
  userId: string,
  deviceId: string
): Promise<void> {
  await sql`
    DELETE FROM user_trusted_devices
    WHERE id = ${deviceId}::UUID AND user_id = ${userId}
  `;

  log.info('Trusted device removed', { userId, deviceId }, 'twoFactorService');
}

/**
 * Webhook Service — WS-8.1
 * Fire-and-forget HMAC-signed webhook delivery with delivery logging.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { WEBHOOK_EVENTS } from '@/modules/accounting/constants/webhookEvents';

export { WEBHOOK_EVENTS };
export type { WebhookEvent } from '@/modules/accounting/constants/webhookEvents';

type Row = Record<string, unknown>;

export interface Webhook {
  id: string;
  companyId: string;
  name: string;
  url: string;
  secret: string | null;
  events: string[];
  isActive: boolean;
  lastTriggeredAt: string | null;
  failureCount: number;
  createdAt: string;
}

export interface WebhookInput {
  name: string;
  url: string;
  secret?: string | null;
  events: string[];
  isActive?: boolean;
}

export interface Delivery {
  id: string;
  webhookId: string;
  event: string;
  payload: Record<string, unknown>;
  responseStatus: number | null;
  responseBody: string | null;
  deliveredAt: string;
  success: boolean;
}

function mapWebhook(row: Row): Webhook {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    name: String(row.name),
    url: String(row.url),
    secret: row.secret ? String(row.secret) : null,
    events: Array.isArray(row.events) ? row.events : [],
    isActive: Boolean(row.is_active),
    lastTriggeredAt: row.last_triggered_at ? String(row.last_triggered_at) : null,
    failureCount: Number(row.failure_count),
    createdAt: String(row.created_at),
  };
}

function mapDelivery(row: Row): Delivery {
  return {
    id: String(row.id),
    webhookId: String(row.webhook_id),
    event: String(row.event),
    payload: (typeof row.payload === 'object' && row.payload !== null ? row.payload : JSON.parse(typeof row.payload === 'string' ? row.payload : '{}')) as Record<string, unknown>,
    responseStatus: row.response_status != null ? Number(row.response_status) : null,
    responseBody: row.response_body ? String(row.response_body) : null,
    deliveredAt: String(row.delivered_at),
    success: Boolean(row.success),
  };
}

function signPayload(secret: string, body: string): string {
  return crypto.createHmac('sha256', secret).update(body).digest('hex');
}

/** Fire webhook for an event — non-blocking, never throws to caller. */
export async function fireWebhook(
  companyId: string,
  event: string,
  payload: Record<string, unknown>,
): Promise<void> {
  // Intentionally fire-and-forget — wrap everything in try/catch
  void (async () => {
    try {
      const rows = (await sql`
        SELECT * FROM webhook_endpoints
        WHERE company_id = ${companyId}
          AND is_active = true
          AND ${event} = ANY(events)
      `) as Row[];

      for (const row of rows) {
        const endpoint = mapWebhook(row);
        const body = JSON.stringify(payload);
        const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

        let responseStatus: number | null = null;
        let responseBody: string | null = null;
        let success = false;

        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);
          const resp = await fetch(endpoint.url, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-Webhook-Event': event,
              ...(signature ? { 'X-Webhook-Signature': signature } : {}),
            },
            body,
            signal: controller.signal,
          });
          clearTimeout(timeout);
          responseStatus = resp.status;
          responseBody = await resp.text().catch(() => null);
          success = resp.ok;
        } catch (fetchErr) {
          log.warn('Webhook delivery failed', { endpointId: endpoint.id, error: fetchErr }, 'webhook');
        }

        // Record delivery
        await sql`
          INSERT INTO webhook_deliveries (webhook_id, event, payload, response_status, response_body, success)
          VALUES (${endpoint.id}::UUID, ${event}, ${JSON.stringify(payload)}::JSONB,
                  ${responseStatus}, ${responseBody}, ${success})
        `;

        if (success) {
          await sql`
            UPDATE webhook_endpoints
            SET last_triggered_at = NOW(), failure_count = 0
            WHERE id = ${endpoint.id}::UUID
          `;
        } else {
          await sql`
            UPDATE webhook_endpoints
            SET failure_count = failure_count + 1,
                is_active = CASE WHEN failure_count + 1 >= 10 THEN false ELSE is_active END
            WHERE id = ${endpoint.id}::UUID
          `;
        }
      }
    } catch (err) {
      log.error('fireWebhook error', { companyId, event, error: err }, 'webhook');
    }
  })();
}

export async function getWebhooks(companyId: string): Promise<Webhook[]> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE company_id = ${companyId} ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapWebhook);
}

export async function createWebhook(companyId: string, input: WebhookInput): Promise<Webhook> {
  const rows = (await sql`
    INSERT INTO webhook_endpoints (company_id, name, url, secret, events, is_active)
    VALUES (${companyId}, ${input.name}, ${input.url}, ${input.secret ?? null},
            ${JSON.stringify(input.events)}::TEXT[], ${input.isActive ?? true})
    RETURNING *
  `) as Row[];
  log.info('Webhook created', { id: rows[0]?.id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function updateWebhook(
  companyId: string,
  id: string,
  updates: Partial<WebhookInput>,
): Promise<Webhook> {
  // Build individual field updates to avoid array casting complexity
  if (updates.name !== undefined) {
    await sql`UPDATE webhook_endpoints SET name = ${updates.name} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.url !== undefined) {
    await sql`UPDATE webhook_endpoints SET url = ${updates.url} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.secret !== undefined) {
    await sql`UPDATE webhook_endpoints SET secret = ${updates.secret ?? null} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.events !== undefined) {
    await sql`UPDATE webhook_endpoints SET events = ${updates.events}::TEXT[] WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.isActive !== undefined) {
    await sql`UPDATE webhook_endpoints SET is_active = ${updates.isActive} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  log.info('Webhook updated', { id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function deleteWebhook(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Webhook deleted', { id }, 'webhook');
}

export async function getDeliveries(
  companyId: string,
  webhookId: string,
  limit = 50,
): Promise<Delivery[]> {
  // Verify ownership
  const rows = (await sql`
    SELECT wd.* FROM webhook_deliveries wd
    JOIN webhook_endpoints we ON we.id = wd.webhook_id
    WHERE wd.webhook_id = ${webhookId}::UUID AND we.company_id = ${companyId}
    ORDER BY wd.delivered_at DESC
    LIMIT ${limit}
  `) as Row[];
  return rows.map(mapDelivery);
}

export async function testWebhook(
  companyId: string,
  id: string,
): Promise<{ success: boolean; status: number; body: string }> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  const endpoint = mapWebhook(rows[0]!);

  const payload = { test: true, event: 'webhook.test', timestamp: new Date().toISOString() };
  const body = JSON.stringify(payload);
  const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    const resp = await fetch(endpoint.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Event': 'webhook.test',
        ...(signature ? { 'X-Webhook-Signature': signature } : {}),
      },
      body,
      signal: controller.signal,
    });
    clearTimeout(timeout);
    const respBody = await resp.text().catch(() => '');
    log.info('Webhook test sent', { id, status: resp.status }, 'webhook');
    return { success: resp.ok, status: resp.status, body: respBody };
  } catch (err) {
    log.warn('Webhook test failed', { id, error: err }, 'webhook');
    return { success: false, status: 0, body: err instanceof Error ? err.message : 'Request failed' };
  }
}

