/**
 * EMP201 Generation Service
 * Generates SARS EMP201 (PAYE/UIF/SDL) data from payroll tables.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface EMP201Data {
  periodStart: string;
  periodEnd: string;
  totalPAYE: number;
  totalUIF_employee: number;
  totalUIF_employer: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
  totalTaxableRemuneration: number;
  totalDeductions: number;
  payrollRuns: EMP201PayrollRun[];
}

export interface EMP201PayrollRun {
  id: string;
  runDate: string;
  employeeCount: number;
  grossPay: number;
  paye: number;
  uif: number;
  sdl: number;
}

function roundCents(n: number): number {
  return Math.round(n * 100) / 100;
}

/**
 * Generate EMP201 (monthly PAYE/UIF/SDL) data from payroll tables.
 * Handles missing payroll tables gracefully by returning zero-filled data.
 */
export async function generateEMP201(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<EMP201Data> {
  log.info('Generating EMP201', { periodStart, periodEnd }, 'emp201Service');

  const emptyResult: EMP201Data = {
    periodStart,
    periodEnd,
    totalPAYE: 0,
    totalUIF_employee: 0,
    totalUIF_employer: 0,
    totalUIF: 0,
    totalSDL: 0,
    employeeCount: 0,
    totalTaxableRemuneration: 0,
    totalDeductions: 0,
    payrollRuns: [],
  };

  let hasPayrollTables = false;
  try {
    const tables = (await sql`
      SELECT table_name FROM information_schema.tables
      WHERE table_schema = 'public'
        AND table_name IN ('payroll_runs', 'payslips')
    `) as Row[];
    hasPayrollTables = tables.length >= 2;
  } catch (err) {
    log.warn('Could not check payroll tables', { error: err }, 'emp201Service');
  }

  if (!hasPayrollTables) {
    log.info('Payroll tables not found, returning empty EMP201', {}, 'emp201Service');
    return emptyResult;
  }

  try {
    const runs = (await sql`
      SELECT
        pr.id,
        pr.run_date,
        COUNT(DISTINCT ps.employee_id) AS employee_count,
        COALESCE(SUM(ps.gross_pay), 0) AS gross_pay,
        COALESCE(SUM(ps.paye), 0) AS paye,
        COALESCE(SUM(ps.uif_employee), 0) AS uif_employee,
        COALESCE(SUM(ps.uif_employer), 0) AS uif_employer,
        COALESCE(SUM(ps.sdl), 0) AS sdl
      FROM payroll_runs pr
      LEFT JOIN payslips ps ON ps.payroll_run_id = pr.id
      WHERE pr.run_date >= ${periodStart}
        AND pr.run_date <= ${periodEnd}
        AND pr.status != 'cancelled'
      GROUP BY pr.id, pr.run_date
      ORDER BY pr.run_date
    `) as Row[];

    if (runs.length === 0) return emptyResult;

    let totalPAYE = 0;
    let totalUIFEmployee = 0;
    let totalUIFEmployer = 0;
    let totalSDL = 0;
    let totalGross = 0;

    const payrollRuns: EMP201PayrollRun[] = runs.map((r: Row) => {
      const paye = Number(r.paye) || 0;
      const uifEmp = Number(r.uif_employee) || 0;
      const uifEr = Number(r.uif_employer) || 0;
      const sdl = Number(r.sdl) || 0;
      const gross = Number(r.gross_pay) || 0;

      totalPAYE += paye;
      totalUIFEmployee += uifEmp;
      totalUIFEmployer += uifEr;
      totalSDL += sdl;
      totalGross += gross;

      return {
        id: String(r.id),
        runDate: String(r.run_date),
        employeeCount: Number(r.employee_count) || 0,
        grossPay: roundCents(gross),
        paye: roundCents(paye),
        uif: roundCents(uifEmp + uifEr),
        sdl: roundCents(sdl),
      };
    });

    const totalUIF = roundCents(totalUIFEmployee + totalUIFEmployer);
    const totalDeductions = roundCents(totalPAYE + totalUIF + totalSDL);

    return {
      periodStart,
      periodEnd,
      totalPAYE: roundCents(totalPAYE),
      totalUIF_employee: roundCents(totalUIFEmployee),
      totalUIF_employer: roundCents(totalUIFEmployer),
      totalUIF,
      totalSDL: roundCents(totalSDL),
      employeeCount: payrollRuns.reduce((max, r) => Math.max(max, r.employeeCount), 0),
      totalTaxableRemuneration: roundCents(totalGross),
      totalDeductions,
      payrollRuns,
    };
  } catch (err) {
    log.warn('Error generating EMP201 from payroll data', { error: err }, 'emp201Service');
    return emptyResult;
  }
}

/**
 * Invoice PDF Builder — generates Tax Invoice PDFs using jsPDF + jspdf-autotable.
 * Returns a Node.js Buffer suitable for API responses and email attachments.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fmtZAR, fmtDate, TEAL, getCompanyDetailsFromCompany, renderPageFooters } from './pdfShared';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function generateInvoicePdf(companyId: string, invoiceId: string): Promise<Buffer> {
  const COMPANY = await getCompanyDetailsFromCompany(companyId);

  const invoiceRows = (await sql`
    SELECT ci.*,
           c.name AS client_name,
           c.email AS client_email,
           c.phone AS client_phone,
           c.vat_number AS client_vat,
           c.billing_address AS client_address,
           c.contact_person AS client_contact,
           p.name AS project_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
    LEFT JOIN projects p ON p.id = ci.project_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) throw new Error(`Invoice not found: ${invoiceId}`);
  const invoice = invoiceRows[0];

  const items = (await sql`
    SELECT * FROM customer_invoice_items
    WHERE invoice_id = ${invoiceId}::UUID
    ORDER BY created_at
  `) as Row[];

  log.info('Generating invoice PDF', {
    invoiceId,
    invoiceNumber: invoice.invoice_number,
    itemCount: items.length,
  }, 'invoicePdfBuilder');

  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PAGE_W = doc.internal.pageSize.getWidth();
  const PAGE_H = doc.internal.pageSize.getHeight();
  const MARGIN = 14;
  const CONTENT_W = PAGE_W - MARGIN * 2;

  // Header bar
  doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
  doc.rect(0, 0, PAGE_W, 28, 'F');
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(255, 255, 255);
  doc.text('TAX INVOICE', MARGIN, 18);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(invoice.invoice_number || '', PAGE_W - MARGIN, 12, { align: 'right' });
  doc.setFontSize(8);
  doc.text(`Date: ${fmtDate(invoice.invoice_date)}`, PAGE_W - MARGIN, 18, { align: 'right' });
  doc.text(`Due: ${fmtDate(invoice.due_date)}`, PAGE_W - MARGIN, 23, { align: 'right' });

  let y = 36;

  // Company details (left)
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(30, 30, 30);
  doc.text(COMPANY.name, MARGIN, y);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  y += 5; doc.text(COMPANY.address, MARGIN, y);
  y += 4; doc.text(`Tel: ${COMPANY.phone}`, MARGIN, y);
  y += 4; doc.text(`Email: ${COMPANY.email}`, MARGIN, y);
  y += 4; doc.text(`VAT No: ${COMPANY.vatNumber}`, MARGIN, y);

  // Client details (right)
  const rightX = PAGE_W / 2 + 10;
  let ry = 36;
  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('BILL TO:', rightX, ry);
  ry += 5;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(30, 30, 30);
  doc.text(invoice.client_name || 'Unknown Client', rightX, ry);
  ry += 5;
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  if (invoice.client_address) {
    for (const line of String(invoice.client_address).split('\n')) {
      doc.text(line.trim(), rightX, ry); ry += 4;
    }
  }
  if (invoice.client_contact) { doc.text(`Attn: ${invoice.client_contact}`, rightX, ry); ry += 4; }
  if (invoice.client_email) { doc.text(invoice.client_email, rightX, ry); ry += 4; }
  if (invoice.client_phone) { doc.text(`Tel: ${invoice.client_phone}`, rightX, ry); ry += 4; }
  if (invoice.client_vat) { doc.text(`VAT No: ${invoice.client_vat}`, rightX, ry); ry += 4; }

  y = Math.max(y, ry) + 6;

  // Reference info bar
  doc.setFillColor(245, 247, 250);
  doc.setDrawColor(210, 215, 225);
  doc.roundedRect(MARGIN, y, CONTENT_W, 12, 1.5, 1.5, 'FD');
  const refCols = [
    { label: 'Invoice #', value: invoice.invoice_number || '' },
    { label: 'Project', value: invoice.project_name || '—' },
    { label: 'Period', value: invoice.billing_period_start ? `${fmtDate(invoice.billing_period_start)} - ${fmtDate(invoice.billing_period_end)}` : '—' },
    { label: 'Terms', value: invoice.due_date ? `Due ${fmtDate(invoice.due_date)}` : 'On receipt' },
  ];
  const colW = CONTENT_W / refCols.length;
  refCols.forEach((col, i) => {
    const cx = MARGIN + colW * i + 4;
    doc.setFontSize(6); doc.setFont('helvetica', 'normal'); doc.setTextColor(120, 120, 120);
    doc.text(col.label.toUpperCase(), cx, y + 4);
    doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(30, 30, 30);
    doc.text(col.value, cx, y + 9);
  });
  y += 18;

  // Line items table
  autoTable(doc, {
    startY: y,
    head: [['Description', 'Qty', 'Unit Price', 'VAT', 'Amount']],
    body: items.map((item: Row) => [
      item.description || '—',
      Number(item.quantity).toFixed(2),
      fmtZAR(Number(item.unit_price)),
      fmtZAR(Number(item.tax_amount || 0)),
      fmtZAR(Number(item.line_total || item.amount || 0)),
    ]),
    styles: { fontSize: 8, cellPadding: 3 },
    headStyles: { fillColor: [TEAL.r, TEAL.g, TEAL.b], textColor: 255, fontStyle: 'bold', fontSize: 8.5 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    columnStyles: {
      0: { cellWidth: 'auto' },
      1: { halign: 'right', cellWidth: 20 },
      2: { halign: 'right', cellWidth: 30 },
      3: { halign: 'right', cellWidth: 28 },
      4: { halign: 'right', cellWidth: 32, fontStyle: 'bold' },
    },
    tableWidth: CONTENT_W,
    margin: { left: MARGIN, right: MARGIN },
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  y = (doc as any).lastAutoTable?.finalY || y + 40;
  y += 6;

  // Totals section
  const totalsX = PAGE_W - MARGIN - 70;
  const totalsW = 70;
  const subtotal = Number(invoice.subtotal || 0);
  const taxAmount = Number(invoice.tax_amount || 0);
  const totalAmount = Number(invoice.total_amount || 0);
  const amountPaid = Number(invoice.amount_paid || 0);
  const balanceDue = totalAmount - amountPaid;

  const totalsData: Array<{ label: string; value: string; bold?: boolean }> = [
    { label: 'Subtotal', value: fmtZAR(subtotal) },
    { label: `VAT (${Number(invoice.tax_rate || 15)}%)`, value: fmtZAR(taxAmount) },
    { label: 'Total', value: fmtZAR(totalAmount), bold: true },
  ];
  if (amountPaid > 0) {
    totalsData.push({ label: 'Paid', value: `(${fmtZAR(amountPaid)})` });
    totalsData.push({ label: 'Balance Due', value: fmtZAR(balanceDue), bold: true });
  }

  totalsData.forEach((row, i) => {
    const rowY = y + i * 7;
    if (row.bold) {
      doc.setFillColor(TEAL.r, TEAL.g, TEAL.b);
      doc.rect(totalsX - 2, rowY - 4, totalsW + 4, 7, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
    } else {
      doc.setTextColor(60, 60, 60);
      doc.setFont('helvetica', 'normal');
    }
    doc.setFontSize(8.5);
    doc.text(row.label, totalsX, rowY);
    doc.text(row.value, totalsX + totalsW, rowY, { align: 'right' });
  });
  y += totalsData.length * 7 + 10;

  // Payment details
  if (y + 40 > PAGE_H - 30) { doc.addPage(); y = MARGIN + 10; }
  doc.setFontSize(9); doc.setFont('helvetica', 'bold'); doc.setTextColor(TEAL.r, TEAL.g, TEAL.b);
  doc.text('PAYMENT DETAILS', MARGIN, y); y += 5;
  doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b); doc.setLineWidth(0.5);
  doc.line(MARGIN, y, MARGIN + 50, y); y += 5;

  const paymentDetails = [
    { label: 'Bank', value: COMPANY.bankName },
    { label: 'Account Name', value: COMPANY.bankAccountName },
    { label: 'Account Number', value: COMPANY.bankAccountNumber },
    { label: 'Branch Code', value: COMPANY.bankBranchCode },
    { label: 'Reference', value: invoice.invoice_number || '' },
  ];
  doc.setFontSize(8);
  paymentDetails.forEach((pd) => {
    doc.setFont('helvetica', 'bold'); doc.setTextColor(60, 60, 60);
    doc.text(`${pd.label}:`, MARGIN, y);
    doc.setFont('helvetica', 'normal'); doc.setTextColor(30, 30, 30);
    doc.text(pd.value, MARGIN + 32, y);
    y += 5;
  });
  y += 5;

  // Notes
  if (invoice.notes) {
    doc.setFontSize(8); doc.setFont('helvetica', 'bold'); doc.setTextColor(80, 80, 80);
    doc.text('Notes:', MARGIN, y); y += 4;
    doc.setFont('helvetica', 'normal');
    const noteLines = doc.splitTextToSize(String(invoice.notes), CONTENT_W);
    doc.text(noteLines, MARGIN, y);
    y += noteLines.length * 4 + 4;
  }

  // Terms
  if (y + 20 > PAGE_H - 20) { doc.addPage(); y = MARGIN + 10; }
  doc.setFontSize(7); doc.setFont('helvetica', 'normal'); doc.setTextColor(130, 130, 130);
  doc.text('Terms & Conditions: Payment is due within the stated terms. Late payments may incur interest at 2% per month.', MARGIN, y);
  y += 4;
  doc.text('E&OE - Errors and Omissions Excepted. Please advise of any discrepancies within 7 days.', MARGIN, y);

  renderPageFooters(doc, PAGE_W, PAGE_H, MARGIN);

  return Buffer.from(doc.output('arraybuffer'));
}

/**
 * PDF Shared Utilities — formatting helpers, company details, and branding constants.
 * Used by invoicePdfBuilder and creditNotePdfBuilder.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Formatting ────────────────────────────────────────────────────────────────

export const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

export const fmtDate = (d: string | Date | null | undefined): string => {
  if (!d) return '—';
  const str = d instanceof Date ? d.toISOString() : String(d);
  const parts = str.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return str;
};

// ── Branding ──────────────────────────────────────────────────────────────────

export const TEAL = { r: 20, g: 184, b: 166 }; // #14b8a6

// ── Company Details ────────────────────────────────────────────────────────────

export interface CompanyDetails {
  name: string;
  address: string;
  phone: string;
  email: string;
  vatNumber: string;
  bankName: string;
  bankAccountName: string;
  bankAccountNumber: string;
  bankBranchCode: string;
  bankReference: string;
}

const COMPANY_SETTINGS_KEYS = [
  'company_name', 'company_address', 'company_phone', 'company_email',
  'company_vat_number', 'bank_name', 'bank_account_name',
  'bank_account_number', 'bank_branch_code',
] as const;

async function getCompanyDetailsFromSettings(): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT key, value FROM app_settings
      WHERE key = ANY(${COMPANY_SETTINGS_KEYS as unknown as string[]})
    `;
    const settings: Record<string, string> = {};
    for (const row of rows) {
      settings[row.key as string] = String(row.value ?? '');
    }
    return {
      name: settings.company_name || 'Company Name Not Set',
      address: settings.company_address || '',
      phone: settings.company_phone || '',
      email: settings.company_email || '',
      vatNumber: settings.company_vat_number || '',
      bankName: settings.bank_name || '',
      bankAccountName: settings.bank_account_name || '',
      bankAccountNumber: settings.bank_account_number || '',
      bankBranchCode: settings.bank_branch_code || '',
      bankReference: '',
    };
  } catch {
    log.warn('Failed to load company settings for PDF, using fallbacks', {}, 'pdfShared');
    return {
      name: 'Company Name Not Set',
      address: '', phone: '', email: '', vatNumber: '',
      bankName: '', bankAccountName: '', bankAccountNumber: '',
      bankBranchCode: '', bankReference: '',
    };
  }
}

/**
 * Load company details from the companies table, with fallback to app_settings.
 */
export async function getCompanyDetailsFromCompany(companyId: string): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT name, address_line1, address_line2, city, province, postal_code,
             phone, email, vat_number,
             bank_name, bank_account_number, bank_branch_code
      FROM companies WHERE id = ${companyId}::UUID
    `;
    if (rows.length > 0) {
      const c = rows[0] as Row;
      const addressParts = [c.address_line1, c.address_line2, c.city, c.province, c.postal_code].filter(Boolean);
      return {
        name: c.name || 'Company Name Not Set',
        address: addressParts.join(', '),
        phone: c.phone || '',
        email: c.email || '',
        vatNumber: c.vat_number || '',
        bankName: c.bank_name || '',
        bankAccountName: c.name || '',
        bankAccountNumber: c.bank_account_number || '',
        bankBranchCode: c.bank_branch_code || '',
        bankReference: '',
      };
    }
  } catch {
    log.warn('Failed to load company from companies table, trying app_settings', {}, 'pdfShared');
  }
  return getCompanyDetailsFromSettings();
}

// ── Page footer renderer ──────────────────────────────────────────────────────

/**
 * Render IsaFlow teal footer lines on every page of a jsPDF document.
 */
export function renderPageFooters(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  doc: any,
  pageW: number,
  pageH: number,
  margin: number,
): void {
  const totalPages = (doc as { internal: { getNumberOfPages: () => number } })
    .internal.getNumberOfPages();

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);

    doc.setDrawColor(TEAL.r, TEAL.g, TEAL.b);
    doc.setLineWidth(0.3);
    doc.line(margin, pageH - 12, pageW - margin, pageH - 12);

    doc.text(`Page ${i} of ${totalPages}`, pageW - margin, pageH - 7, { align: 'right' });
    doc.text('Generated by IsaFlow', margin, pageH - 7);
  }
}

/**
 * Permission Service — Granular module-level permissions (WS-4.1).
 * Role defaults: owner/admin → full, manager → read+write+export, viewer → read+export.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface ModulePermission {
  moduleKey: string; moduleName: string;
  canRead: boolean; canWrite: boolean; canDelete: boolean;
  canExport: boolean; canApprove: boolean;
  accountRangeFrom: string | null; accountRangeTo: string | null;
  restrictions: Record<string, unknown>;
}
export interface PermissionModule {
  moduleKey: string; moduleName: string; description: string | null; displayOrder: number;
}
export interface UserWithPermissions {
  userId: string; email: string; firstName: string; lastName: string;
  role: string; permissions: ModulePermission[];
}

type Action = 'read' | 'write' | 'delete' | 'export' | 'approve';
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const FULL_ACCESS_ROLES = ['owner', 'admin'];

function roleDefault(role: string, action: Action): boolean {
  if (FULL_ACCESS_ROLES.includes(role)) return true;
  if (role === 'manager') return action === 'read' || action === 'write' || action === 'export';
  if (role === 'viewer') return action === 'read' || action === 'export';
  return false;
}

function defaultPerm(role: string, moduleKey: string, moduleName: string): ModulePermission {
  return {
    moduleKey, moduleName,
    canRead: roleDefault(role, 'read'), canWrite: roleDefault(role, 'write'),
    canDelete: roleDefault(role, 'delete'), canExport: roleDefault(role, 'export'),
    canApprove: roleDefault(role, 'approve'),
    accountRangeFrom: null, accountRangeTo: null, restrictions: {},
  };
}

function rowToPerm(r: Row): ModulePermission {
  return {
    moduleKey: r.module_key as string, moduleName: r.module_name as string,
    canRead: Boolean(r.can_read), canWrite: Boolean(r.can_write),
    canDelete: Boolean(r.can_delete), canExport: Boolean(r.can_export),
    canApprove: Boolean(r.can_approve),
    accountRangeFrom: r.account_range_from as string | null,
    accountRangeTo: r.account_range_to as string | null,
    restrictions: (r.restrictions as Record<string, unknown>) ?? {},
  };
}

export async function getPermissionModules(): Promise<PermissionModule[]> {
  const rows = await sql`
    SELECT module_key, module_name, description, display_order
    FROM permission_modules ORDER BY display_order ASC
  `;
  return rows.map((r: Row) => ({
    moduleKey: r.module_key as string, moduleName: r.module_name as string,
    description: r.description as string | null, displayOrder: r.display_order as number,
  }));
}

export async function getUserPermissions(
  companyId: string, userId: string
): Promise<Map<string, ModulePermission>> {
  const rows = await sql`
    SELECT cup.module_key, pm.module_name, cup.can_read, cup.can_write,
      cup.can_delete, cup.can_export, cup.can_approve,
      cup.account_range_from, cup.account_range_to, cup.restrictions
    FROM company_user_permissions cup
    JOIN permission_modules pm ON pm.module_key = cup.module_key
    WHERE cup.company_id = ${companyId}::UUID AND cup.user_id = ${userId}
  `;
  const map = new Map<string, ModulePermission>();
  for (const r of rows as Row[]) map.set(r.module_key as string, rowToPerm(r));
  return map;
}

export async function setUserModulePermission(
  companyId: string, userId: string, moduleKey: string, perms: Partial<ModulePermission>
): Promise<void> {
  await sql`
    INSERT INTO company_user_permissions (
      company_id, user_id, module_key,
      can_read, can_write, can_delete, can_export, can_approve,
      account_range_from, account_range_to, restrictions, updated_at
    ) VALUES (
      ${companyId}::UUID, ${userId}, ${moduleKey},
      ${perms.canRead ?? false}, ${perms.canWrite ?? false}, ${perms.canDelete ?? false},
      ${perms.canExport ?? false}, ${perms.canApprove ?? false},
      ${perms.accountRangeFrom ?? null}, ${perms.accountRangeTo ?? null},
      ${JSON.stringify(perms.restrictions ?? {})}::JSONB, NOW()
    )
    ON CONFLICT (company_id, user_id, module_key) DO UPDATE SET
      can_read = EXCLUDED.can_read, can_write = EXCLUDED.can_write,
      can_delete = EXCLUDED.can_delete, can_export = EXCLUDED.can_export,
      can_approve = EXCLUDED.can_approve,
      account_range_from = EXCLUDED.account_range_from,
      account_range_to   = EXCLUDED.account_range_to,
      restrictions       = EXCLUDED.restrictions,
      updated_at         = NOW()
  `;
  log.info('Module permission updated', { companyId, userId, moduleKey }, 'PermissionService');
}

export async function resetUserPermissions(companyId: string, userId: string): Promise<void> {
  await sql`
    DELETE FROM company_user_permissions
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
  `;
  log.info('User permissions reset to defaults', { companyId, userId }, 'PermissionService');
}

export async function checkPermission(
  companyId: string, userId: string, companyRole: string, moduleKey: string, action: Action
): Promise<boolean> {
  if (FULL_ACCESS_ROLES.includes(companyRole)) return true;

  const rows = await sql`
    SELECT can_read, can_write, can_delete, can_export, can_approve
    FROM company_user_permissions
    WHERE company_id = ${companyId}::UUID
      AND user_id    = ${userId}
      AND module_key = ${moduleKey}
    LIMIT 1
  `;
  if (rows.length > 0) {
    const r = rows[0] as Row;
    const col = `can_${action}` as keyof typeof r;
    return Boolean(r[col]);
  }
  return roleDefault(companyRole, action);
}

export async function getCompanyUsersWithPermissions(companyId: string): Promise<UserWithPermissions[]> {
  const userRows = await sql`
    SELECT cu.user_id, cu.role, u.email, u.first_name, u.last_name
    FROM company_users cu
    JOIN users u ON u.id = cu.user_id
    WHERE cu.company_id = ${companyId}::UUID
    ORDER BY cu.created_at ASC
  `;
  if (userRows.length === 0) return [];

  const modules = await getPermissionModules();

  const permRows = await sql`
    SELECT cup.user_id, cup.module_key, pm.module_name,
      cup.can_read, cup.can_write, cup.can_delete, cup.can_export, cup.can_approve,
      cup.account_range_from, cup.account_range_to, cup.restrictions
    FROM company_user_permissions cup
    JOIN permission_modules pm ON pm.module_key = cup.module_key
    WHERE cup.company_id = ${companyId}::UUID
  `;

  const customMap = new Map<string, Map<string, ModulePermission>>();
  for (const r of permRows as Row[]) {
    const uid = r.user_id as string;
    if (!customMap.has(uid)) customMap.set(uid, new Map());
    customMap.get(uid)!.set(r.module_key as string, rowToPerm(r));
  }

  return (userRows as Row[]).map((u: Row) => {
    const role = u.role as string;
    const uid = u.user_id as string;
    const custom = customMap.get(uid);
    const isFullAccess = FULL_ACCESS_ROLES.includes(role);

    const permissions: ModulePermission[] = modules.map((mod) => {
      if (isFullAccess) {
        return {
          moduleKey: mod.moduleKey, moduleName: mod.moduleName,
          canRead: true, canWrite: true, canDelete: true, canExport: true, canApprove: true,
          accountRangeFrom: null, accountRangeTo: null, restrictions: {},
        };
      }
      return custom?.get(mod.moduleKey) ?? defaultPerm(role, mod.moduleKey, mod.moduleName);
    });

    return {
      userId: uid, email: u.email as string,
      firstName: (u.first_name as string) ?? '',
      lastName: (u.last_name as string) ?? '',
      role, permissions,
    };
  });
}

/**
 * POST /api/accounting/company-logo
 * Upload/update company logo as a base64 data URL.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { companyId, logoData } = req.body as {
    companyId?: string;
    logoData?: string;
  };

  if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
  if (!logoData) return apiResponse.badRequest(res, 'logoData is required');

  // Validate ownership (owner or admin)
  const membership = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
  `) as Row[];

  if (membership.length === 0) {
    return apiResponse.forbidden(res, 'You do not have access to this company');
  }
  if (!['owner', 'admin'].includes(membership[0].role)) {
    return apiResponse.forbidden(res, 'Only owners and admins can update the company logo');
  }

  // Validate data URL format
  if (!logoData.startsWith('data:image/')) {
    return apiResponse.badRequest(res, 'logoData must be a valid data:image/ URL');
  }

  // Validate size < 5MB (base64 is ~1.33x raw, so 5MB raw ~ 6.8M chars)
  if (logoData.length > 6_800_000) {
    return apiResponse.badRequest(res, 'Logo must be smaller than 5MB');
  }

  await sql`
    UPDATE companies SET logo_data = ${logoData} WHERE id = ${companyId}::UUID
  `;

  return apiResponse.success(res, { updated: true });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '10mb' } },
};

/**
