/**
 * Customer Sales Order Service — CRUD with items
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface SalesOrderItem {
  id: string;
  salesOrderId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
}

export interface SalesOrder {
  id: string;
  orderNumber: string;
  customerId: string | null;
  customerName: string;
  orderDate: string;
  deliveryDate: string | null;
  reference: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  notes: string | null;
  internalNotes: string | null;
  createdAt: string;
  updatedAt: string;
  items?: SalesOrderItem[];
}

interface SalesOrderFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface SalesOrderInput {
  customer_id?: string;
  order_date?: string;
  delivery_date?: string;
  reference?: string;
  notes?: string;
  internal_notes?: string;
  items: { description: string; quantity: number; unit_price: number; tax_rate?: number }[];
}

function mapOrder(r: Row): SalesOrder {
  return {
    id: r.id,
    orderNumber: r.order_number,
    customerId: r.customer_id,
    customerName: r.customer_name || '',
    orderDate: r.order_date,
    deliveryDate: r.delivery_date,
    reference: r.reference,
    status: r.status,
    subtotal: Number(r.subtotal),
    taxAmount: Number(r.tax_amount),
    totalAmount: Number(r.total_amount),
    notes: r.notes,
    internalNotes: r.internal_notes,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function mapItem(r: Row): SalesOrderItem {
  return {
    id: r.id,
    salesOrderId: r.sales_order_id,
    lineNumber: r.line_number,
    description: r.description,
    quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price),
    taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total),
  };
}

async function nextOrderNumber(companyId: string): Promise<string> {
  // Use company_document_numbers for sequential numbering
  const rows = (await sql`
    INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number)
    VALUES (${companyId}::UUID, 'sales_order', 'SO-', 1)
    ON CONFLICT (company_id, document_type)
    DO UPDATE SET next_number = company_document_numbers.next_number + 1
    RETURNING next_number - 1 AS current_number, prefix
  `) as Row[];

  if (rows.length === 0) return 'SO-00001';
  const num = Number(rows[0].current_number);
  const prefix = rows[0].prefix || 'SO-';
  return `${prefix}${String(num).padStart(5, '0')}`;
}

function calcTotals(items: SalesOrderInput['items']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lt = item.quantity * item.unit_price;
    subtotal += lt;
    taxAmount += lt * ((item.tax_rate ?? 15) / 100);
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

export async function getSalesOrders(companyId: string, filters?: SalesOrderFilters): Promise<{ orders: SalesOrder[]; total: number }> {
  const limit = filters?.limit || 100;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search && filters?.status) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID
    `) as Row[];
  }

  return { orders: rows.map(mapOrder), total: Number(countRows[0]?.cnt || 0) };
}

export async function getSalesOrder(companyId: string, id: string): Promise<SalesOrder | null> {
  const rows = (await sql`
    SELECT so.*, c.name AS customer_name
    FROM customer_sales_orders so
    LEFT JOIN customers c ON c.id = so.customer_id
    WHERE so.id = ${id}::UUID AND so.company_id = ${companyId}::UUID
  `) as Row[];
  if (rows.length === 0) return null;
  const order = mapOrder(rows[0]);
  const itemRows = (await sql`
    SELECT * FROM customer_sales_order_items
    WHERE sales_order_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  order.items = itemRows.map(mapItem);
  return order;
}

export async function createSalesOrder(companyId: string, input: SalesOrderInput, userId?: string): Promise<SalesOrder> {
  const orderNumber = await nextOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);
  const orderDate = input.order_date || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_sales_orders (
      company_id, order_number, customer_id, order_date, delivery_date,
      reference, subtotal, tax_amount, total_amount, notes, internal_notes, created_by
    ) VALUES (
      ${companyId}::UUID, ${orderNumber}, ${input.customer_id || null},
      ${orderDate}, ${input.delivery_date || null}, ${input.reference || null},
      ${subtotal}, ${taxAmount}, ${totalAmount},
      ${input.notes || null}, ${input.internal_notes || null}, ${userId || null}
    ) RETURNING *
  `) as Row[];

  const order = mapOrder(rows[0]);
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${order.id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order created', { orderNumber, totalAmount });
  return (await getSalesOrder(companyId, order.id))!;
}

export async function updateSalesOrder(companyId: string, id: string, input: SalesOrderInput): Promise<SalesOrder | null> {
  const existing = await getSalesOrder(companyId, id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);

  await sql`
    UPDATE customer_sales_orders SET
      customer_id = ${input.customer_id || existing.customerId},
      order_date = ${input.order_date || existing.orderDate},
      delivery_date = ${input.delivery_date || null},
      reference = ${input.reference || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total_amount = ${totalAmount},
      notes = ${input.notes || null}, internal_notes = ${input.internal_notes || null},
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
  `;

  await sql`DELETE FROM customer_sales_order_items WHERE sales_order_id = ${id}::UUID`;
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order updated', { id });
  return getSalesOrder(companyId, id);
}

export async function deleteSalesOrder(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`
    DELETE FROM customer_sales_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
    RETURNING id
  `) as Row[];
  return rows.length > 0;
}

/**
 * SARS Compliance Service
 * Submissions CRUD and DB-backed compliance calendar for SA tax obligations.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getComplianceCalendar } from './sarsTaxPeriodsService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type { TaxPeriod, ComplianceEvent } from './sarsTaxPeriodsService';
export { getTaxPeriods, getComplianceCalendar } from './sarsTaxPeriodsService';

import type { ComplianceEvent } from './sarsTaxPeriodsService';

export interface SARSSubmission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  formData: Record<string, unknown>;
  submissionReference: string | null;
  submittedAt: string | null;
  submittedBy: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
}

function mapSubmissionRow(row: Row): SARSSubmission {
  return {
    id: String(row.id),
    formType: String(row.form_type),
    periodStart: String(row.period_start).slice(0, 10),
    periodEnd: String(row.period_end).slice(0, 10),
    status: String(row.status),
    formData: row.form_data || {},
    submissionReference: row.submission_reference ? String(row.submission_reference) : null,
    submittedAt: row.submitted_at ? String(row.submitted_at) : null,
    submittedBy: row.submitted_by ? String(row.submitted_by) : null,
    notes: row.notes ? String(row.notes) : null,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

// ---------------------------------------------------------------------------
// Submissions CRUD
// ---------------------------------------------------------------------------

export async function saveDraftSubmission(
  companyId: string,
  formType: string,
  periodStart: string,
  periodEnd: string,
  formData: Record<string, unknown>,
  userId: string
): Promise<SARSSubmission> {
  log.info('Saving draft submission', { formType, periodStart, periodEnd }, 'sarsComplianceService');

  const rows = (await sql`
    INSERT INTO sars_submissions (form_type, period_start, period_end, status, form_data, submitted_by)
    VALUES (${formType}, ${periodStart}, ${periodEnd}, 'draft', ${JSON.stringify(formData)}::jsonb, ${userId})
    RETURNING *
  `) as Row[];

  return mapSubmissionRow(rows[0]);
}

export async function listSubmissions(companyId: string,
  formType?: string
): Promise<SARSSubmission[]> {
  let rows: Row[];
  if (formType) {
    rows = (await sql`
      SELECT * FROM sars_submissions
      WHERE form_type = ${formType}
      ORDER BY created_at DESC
      LIMIT 500
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM sars_submissions
      ORDER BY created_at DESC
      LIMIT 500
    `) as Row[];
  }
  return rows.map(mapSubmissionRow);
}

export async function getSubmission(companyId: string, id: string): Promise<SARSSubmission | null> {
  const rows = (await sql`
    SELECT * FROM sars_submissions WHERE id = ${id}
  `) as Row[];
  if (rows.length === 0) return null;
  return mapSubmissionRow(rows[0]);
}

export async function markSubmitted(companyId: string,
  id: string,
  reference: string
): Promise<SARSSubmission> {
  log.info('Marking submission as submitted', { id, reference }, 'sarsComplianceService');

  const rows = (await sql`
    UPDATE sars_submissions
    SET status = 'submitted',
        submission_reference = ${reference},
        submitted_at = NOW(),
        updated_at = NOW()
    WHERE id = ${id}
    RETURNING *
  `) as Row[];

  if (rows.length === 0) throw new Error(`Submission ${id} not found`);
  return mapSubmissionRow(rows[0]);
}

// ---------------------------------------------------------------------------
// DB-merged Compliance Calendar
// ---------------------------------------------------------------------------

/**
 * Load compliance events from the database (if any exist), merged with
 * the static calendar. DB events can override status (e.g. marked completed).
 */
export async function getComplianceCalendarWithDB(companyId: string, year?: number): Promise<ComplianceEvent[]> {
  const staticEvents = getComplianceCalendar(year);

  try {
    const y = year || new Date().getFullYear();
    const dbEvents = (await sql`
      SELECT
        ce.id, ce.event_type, ce.due_date, ce.description,
        ce.status, ce.submission_id
      FROM sars_compliance_events ce
      WHERE EXTRACT(YEAR FROM ce.due_date) = ${y}
         OR EXTRACT(YEAR FROM ce.due_date) = ${y + 1}
      ORDER BY ce.due_date
    `) as Row[];

    const dbMap = new Map<string, Row>();
    for (const dbe of dbEvents) {
      const key = `${dbe.event_type}_${String(dbe.due_date).slice(0, 10)}`;
      dbMap.set(key, dbe);
    }

    return staticEvents.map((se) => {
      const key = `${se.eventType}_${se.dueDate}`;
      const dbMatch = dbMap.get(key);
      if (dbMatch) {
        return {
          ...se,
          id: String(dbMatch.id),
          status: dbMatch.status as ComplianceEvent['status'],
          submissionId: dbMatch.submission_id ? String(dbMatch.submission_id) : undefined,
        };
      }
      return se;
    });
  } catch (err) {
    log.warn('Could not load compliance events from DB, using static calendar', { error: err }, 'sarsComplianceService');
    return staticEvents;
  }
}

/**
 * WS-1.2: Soft Delete / Undo Service
 * Provides a 5-minute undo window for deletes on key entities.
 * Uses explicit per-table queries — the Neon tagged template driver
 * does not support dynamic identifier interpolation.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// Allowlist of entity types that support soft-delete
const ALLOWED_ENTITY_TYPES = new Set([
  'customer',
  'supplier',
  'item',
  'bank_rule',
  'customer_invoice',
  'supplier_invoice',
]);

// Invoice entity types require a status guard (no deleting posted records)
const INVOICE_ENTITY_TYPES = new Set(['customer_invoice', 'supplier_invoice']);

export function isValidEntityType(entityType: string): boolean {
  return ALLOWED_ENTITY_TYPES.has(entityType);
}

// ── Status guard helpers ─────────────────────────────────────────────────────

async function getInvoiceStatus(
  entityType: string,
  entityId: string,
  companyId: string,
): Promise<string | null> {
  let rows: { status: string }[];
  if (entityType === 'customer_invoice') {
    rows = await sql`
      SELECT status FROM customer_invoices
      WHERE id = ${entityId}::UUID
        AND company_id = ${companyId}::UUID
        AND deleted_at IS NULL
      LIMIT 1
    ` as { status: string }[];
  } else {
    rows = await sql`
      SELECT status FROM supplier_invoices
      WHERE id = ${entityId}::UUID
        AND company_id = ${companyId}::UUID
        AND deleted_at IS NULL
      LIMIT 1
    ` as { status: string }[];
  }
  return rows.length > 0 ? String(rows[0]!.status) : null;
}

// ── Soft-delete per table ────────────────────────────────────────────────────

async function softDeleteRow(
  entityType: string,
  entityId: string,
  companyId: string,
): Promise<boolean> {
  let rows: { id: string }[];

  switch (entityType) {
    case 'customer':
      rows = await sql`
        UPDATE customers SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'supplier':
      rows = await sql`
        UPDATE suppliers SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'item':
      rows = await sql`
        UPDATE items SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'bank_rule':
      rows = await sql`
        UPDATE bank_rules SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'customer_invoice':
      rows = await sql`
        UPDATE customer_invoices SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'supplier_invoice':
      rows = await sql`
        UPDATE supplier_invoices SET deleted_at = NOW()
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NULL
        RETURNING id
      ` as { id: string }[];
      break;
    default:
      throw new Error(`Unknown entity type: ${entityType}`);
  }

  return rows.length > 0;
}

// ── Restore per table ────────────────────────────────────────────────────────

async function restoreRow(
  entityType: string,
  entityId: string,
  companyId: string,
): Promise<boolean> {
  let rows: { id: string }[];

  switch (entityType) {
    case 'customer':
      rows = await sql`
        UPDATE customers SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'supplier':
      rows = await sql`
        UPDATE suppliers SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'item':
      rows = await sql`
        UPDATE items SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'bank_rule':
      rows = await sql`
        UPDATE bank_rules SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'customer_invoice':
      rows = await sql`
        UPDATE customer_invoices SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    case 'supplier_invoice':
      rows = await sql`
        UPDATE supplier_invoices SET deleted_at = NULL
        WHERE id = ${entityId}::UUID AND company_id = ${companyId}::UUID AND deleted_at IS NOT NULL
        RETURNING id
      ` as { id: string }[];
      break;
    default:
      throw new Error(`Unknown entity type: ${entityType}`);
  }

  return rows.length > 0;
}

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Soft-delete a single entity owned by the given company.
 * For invoice entities the record must have status = 'draft'.
 * Returns the entity id as the undoToken (sufficient for undo within the session).
 */
export async function softDelete(
  companyId: string,
  entityType: string,
  entityId: string,
): Promise<{ undoToken: string }> {
  if (!ALLOWED_ENTITY_TYPES.has(entityType)) {
    throw new Error(`Unknown entity type: ${entityType}`);
  }

  try {
    if (INVOICE_ENTITY_TYPES.has(entityType)) {
      const status = await getInvoiceStatus(entityType, entityId, companyId);
      if (status === null) {
        throw new Error(`${entityType} not found or already deleted`);
      }
      if (status === 'posted') {
        throw new Error(`Cannot delete a posted ${entityType}`);
      }
    }

    const deleted = await softDeleteRow(entityType, entityId, companyId);
    if (!deleted) {
      throw new Error(`${entityType} not found or already deleted`);
    }

    log.info('Soft deleted entity', { entityType, entityId, companyId }, 'accounting');
    return { undoToken: entityId };
  } catch (err) {
    log.error('Soft delete failed', { entityType, entityId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Restore a soft-deleted entity within the undo window.
 * Returns true when restored, false when the record was not found
 * (already purged or never deleted).
 */
export async function undoDelete(
  companyId: string,
  entityType: string,
  entityId: string,
): Promise<boolean> {
  if (!ALLOWED_ENTITY_TYPES.has(entityType)) {
    throw new Error(`Unknown entity type: ${entityType}`);
  }

  try {
    const restored = await restoreRow(entityType, entityId, companyId);
    if (restored) {
      log.info('Undo delete — entity restored', { entityType, entityId, companyId }, 'accounting');
    } else {
      log.warn('Undo delete — entity not found or already purged', { entityType, entityId }, 'accounting');
    }
    return restored;
  } catch (err) {
    log.error('Undo delete failed', { entityType, entityId, error: err }, 'accounting');
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Hard-purge records that were soft-deleted more than 5 minutes ago.
 * Intended to be called by a scheduled background job.
 * Returns the total count of purged records across all tables.
 */
export async function purgeExpiredDeletes(): Promise<number> {
  let total = 0;

  // One entry per soft-deletable table
  const tables: Array<{ entityType: string; fn: () => Promise<Row[]> }> = [
    { entityType: 'customer',         fn: () => sql`DELETE FROM customers WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
    { entityType: 'supplier',         fn: () => sql`DELETE FROM suppliers WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
    { entityType: 'item',             fn: () => sql`DELETE FROM items WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
    { entityType: 'bank_rule',        fn: () => sql`DELETE FROM bank_rules WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
    { entityType: 'customer_invoice', fn: () => sql`DELETE FROM customer_invoices WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
    { entityType: 'supplier_invoice', fn: () => sql`DELETE FROM supplier_invoices WHERE deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '5 minutes' RETURNING id` as Promise<Row[]> },
  ];

  for (const { entityType, fn } of tables) {
    try {
      const rows = await fn();
      if (rows.length > 0) {
        log.info('Purged expired soft-deletes', { entityType, count: rows.length }, 'accounting');
        total += rows.length;
      }
    } catch (err) {
      log.error('Failed to purge expired deletes', { entityType, error: err }, 'accounting');
    }
  }

  return total;
}

/**
 * System Account Resolver
 *
 * Resolves system GL accounts by their account_subtype instead of hardcoded
 * account codes. This decouples business logic from specific numbering schemes,
 * allowing customers to use any chart of accounts numbering (Sage, Xero, etc.).
 *
 * Usage:
 *   const arAccountId = await getSystemAccountId('receivable');
 *   const arAccount   = await getSystemAccount('receivable');
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { GLAccount, GLAccountSubtype } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Subtypes that the system requires for auto-posting and reporting.
 * Each maps to exactly one system account (is_system_account = true).
 */
export type SystemAccountKey =
  | 'bank'                      // Primary bank account
  | 'receivable'                // Accounts Receivable
  | 'payable'                   // Accounts Payable
  | 'vat_input'                 // VAT Input (claimable)
  | 'vat_output'                // VAT Output (payable)
  | 'retained_earnings'         // Retained Earnings
  | 'default_revenue'           // Default revenue account
  | 'other_income'              // Other Income
  | 'default_expense'           // Default expense (Materials & Supplies)
  | 'admin_expense'             // Administrative Expenses
  | 'accumulated_depreciation'  // Accumulated Depreciation
  | 'depreciation_expense';     // Depreciation Expense

// ── In-memory cache ─────────────────────────────────────────────────────────

interface CachedAccount {
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string;
}

let cache: Map<string, CachedAccount> | null = null;
let cacheLoadedAt = 0;
const CACHE_TTL_MS = 60_000; // 1 minute

/** Clear the cache (call after chart of accounts changes) */
export function clearSystemAccountCache(): void {
  cache = null;
  cacheLoadedAt = 0;
}

async function ensureCache(): Promise<Map<string, CachedAccount>> {
  if (cache && Date.now() - cacheLoadedAt < CACHE_TTL_MS) return cache;

  const rows = (await sql`
    SELECT id, account_code, account_name, account_type, account_subtype
    FROM gl_accounts
    WHERE is_system_account = true
      AND is_active = true
      AND account_subtype IS NOT NULL
  `) as Row[];

  const map = new Map<string, CachedAccount>();
  for (const r of rows) {
    const subtype = String(r.account_subtype);
    map.set(subtype, {
      id: String(r.id),
      accountCode: String(r.account_code),
      accountName: String(r.account_name),
      accountType: String(r.account_type),
      accountSubtype: subtype,
    });
  }

  cache = map;
  cacheLoadedAt = Date.now();
  return map;
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * Get a system account by its subtype key.
 * Throws if the account is not found (misconfigured chart of accounts).
 */
export async function getSystemAccount(key: SystemAccountKey): Promise<CachedAccount> {
  const map = await ensureCache();
  const account = map.get(key);
  if (!account) {
    log.error('System account not found', { key }, 'accounting');
    throw new Error(
      `System account with subtype '${key}' not found. ` +
      `Ensure the chart of accounts has a system account with account_subtype = '${key}'.`
    );
  }
  return account;
}

/**
 * Get only the account ID for a system account.
 * Convenience wrapper for the most common use case (building journal lines).
 */
export async function getSystemAccountId(key: SystemAccountKey): Promise<string> {
  const account = await getSystemAccount(key);
  return account.id;
}

/**
 * Check whether all required system accounts are configured.
 * Returns a list of missing subtypes (empty = all good).
 */
export async function validateSystemAccounts(): Promise<string[]> {
  const required: SystemAccountKey[] = [
    'bank', 'receivable', 'payable',
    'vat_input', 'vat_output', 'retained_earnings',
    'default_revenue', 'default_expense', 'admin_expense',
  ];

  const map = await ensureCache();
  return required.filter(key => !map.has(key));
}

/**
 * User Access Service
 * Manages company users and invitations — mirrors Sage's "Control User Access".
 */

import crypto from 'crypto';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const VALID_ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
type CompanyRole = (typeof VALID_ROLES)[number];

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CompanyUserRecord {
  userId: string;
  name: string;
  email: string;
  role: string;
  joinedAt: string;
}

export interface PendingInvitation {
  id: string;
  companyId: string;
  email: string;
  role: string;
  invitedBy: string;
  token: string;
  expiresAt: string;
  createdAt: string;
  emailSentAt: string | null;
  emailError: string | null;
}

export interface InvitationResult {
  autoAdded: boolean;
  invitation?: PendingInvitation;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function isValidRole(role: string): role is CompanyRole {
  return (VALID_ROLES as readonly string[]).includes(role);
}

async function countOwners(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COUNT(*) AS cnt FROM company_users
    WHERE company_id = ${companyId}::UUID AND role = 'owner'
  `) as Row[];
  return parseInt(rows[0]?.cnt ?? '0', 10);
}

function toIso(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString();
  return val;
}

// ── Company Users ─────────────────────────────────────────────────────────────

export async function listCompanyUsers(companyId: string): Promise<CompanyUserRecord[]> {
  const rows = (await sql`
    SELECT
      cu.user_id,
      u.first_name,
      u.last_name,
      u.email,
      cu.role,
      cu.created_at
    FROM company_users cu
    JOIN users u ON u.id = cu.user_id::VARCHAR
    WHERE cu.company_id = ${companyId}::UUID
    ORDER BY cu.created_at ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    userId: r.user_id,
    name: `${r.first_name ?? ''} ${r.last_name ?? ''}`.trim() || r.email,
    email: r.email,
    role: r.role,
    joinedAt: toIso(r.created_at) ?? '',
  }));
}

export async function updateCompanyUserRole(
  companyId: string,
  userId: string,
  newRole: string,
): Promise<void> {
  if (!isValidRole(newRole)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Prevent stripping last owner
  const currentRows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  const currentRole = currentRows[0]?.role as string | undefined;
  if (currentRole === 'owner' && newRole !== 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot change role: this is the last owner of the company.');
    }
  }

  await sql`
    UPDATE company_users
    SET role = ${newRole}
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user role updated', { companyId, userId, newRole }, 'accounting');
}

export async function removeCompanyUser(companyId: string, userId: string): Promise<void> {
  // Prevent removing last owner
  const rows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  if (rows[0]?.role === 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot remove the last owner of the company.');
    }
  }

  await sql`
    DELETE FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user removed', { companyId, userId }, 'accounting');
}

// ── Invitations ───────────────────────────────────────────────────────────────

export async function createInvitation(
  companyId: string,
  email: string,
  role: string,
  invitedBy: string,
): Promise<InvitationResult> {
  if (!isValidRole(role)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Check if a user with this email already exists
  const existing = (await sql`
    SELECT id FROM users WHERE email = ${email} LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    const existingUserId = existing[0].id as string;

    // Check if already in company
    const alreadyMember = (await sql`
      SELECT 1 FROM company_users
      WHERE company_id = ${companyId}::UUID AND user_id = ${existingUserId}::UUID
    `) as Row[];

    if (alreadyMember.length > 0) {
      throw new Error('This user is already a member of the company.');
    }

    // Auto-add directly
    await sql`
      INSERT INTO company_users (company_id, user_id, role)
      VALUES (${companyId}::UUID, ${existingUserId}::UUID, ${role})
      ON CONFLICT (company_id, user_id) DO NOTHING
    `;
    log.info('User auto-added to company', { companyId, email, role }, 'accounting');
    return { autoAdded: true };
  }

  // Create invitation row — upsert on (company_id, email) to allow re-invite
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  const rows = (await sql`
    INSERT INTO company_invitations (company_id, email, role, invited_by, token, expires_at)
    VALUES (${companyId}::UUID, ${email}, ${role}, ${invitedBy}, ${token}, ${expiresAt}::TIMESTAMPTZ)
    ON CONFLICT (company_id, email) DO UPDATE SET
      role = EXCLUDED.role,
      invited_by = EXCLUDED.invited_by,
      token = EXCLUDED.token,
      expires_at = EXCLUDED.expires_at,
      accepted_at = NULL,
      created_at = NOW()
    RETURNING *
  `) as Row[];

  const inv = rows[0];
  log.info('Invitation created', { companyId, email, role }, 'accounting');
  return {
    autoAdded: false,
    invitation: mapInvitation(inv),
  };
}

export async function listPendingInvitations(companyId: string): Promise<PendingInvitation[]> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE company_id = ${companyId}::UUID
      AND accepted_at IS NULL
      AND expires_at > NOW()
    ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapInvitation);
}

export async function markInvitationEmailSent(invitationId: string): Promise<void> {
  await sql`
    UPDATE company_invitations
    SET email_sent_at = NOW(), email_error = NULL
    WHERE id = ${invitationId}::UUID
  `;
}

export async function markInvitationEmailFailed(invitationId: string, error: string): Promise<void> {
  await sql`
    UPDATE company_invitations
    SET email_error = ${error}
    WHERE id = ${invitationId}::UUID
  `;
}

export async function cancelInvitation(invitationId: string, companyId: string): Promise<void> {
  await sql`
    DELETE FROM company_invitations
    WHERE id = ${invitationId}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Invitation cancelled', { invitationId, companyId }, 'accounting');
}

export async function acceptInvitation(token: string, userId: string): Promise<void> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    throw new Error('Invitation not found or has expired.');
  }

  const inv = rows[0];

  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  log.info('Invitation accepted', { token, userId, companyId: inv.company_id }, 'accounting');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

function mapInvitation(r: Row): PendingInvitation {
  return {
    id: r.id,
    companyId: r.company_id,
    email: r.email,
    role: r.role,
    invitedBy: r.invited_by,
    token: r.token,
    expiresAt: toIso(r.expires_at) ?? '',
    createdAt: toIso(r.created_at) ?? '',
    emailSentAt: r.email_sent_at ? (toIso(r.email_sent_at) ?? null) : null,
    emailError: r.email_error ?? null,
  };
}

/**
 * VAT201 Generation Service
 * Generates SARS VAT201 return data from customer/supplier invoices.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const SA_VAT_RATE = 0.15;

export interface VAT201Data {
  periodStart: string;
  periodEnd: string;
  field1_standardRatedSupplies: number;
  field2_zeroRatedSupplies: number;
  field3_exemptSupplies: number;
  field4_totalImports: number;
  field5_outputVAT: number;
  field6_capitalGoods: number;
  field7_otherGoods: number;
  field8_services: number;
  field9_imports: number;
  field10_totalInputVAT: number;
  field11_vatPayableOrRefundable: number;
  outputInvoices: VAT201Invoice[];
  inputInvoices: VAT201Invoice[];
}

export interface VAT201Invoice {
  id: string;
  invoiceNumber: string;
  counterpartyName: string;
  invoiceDate: string;
  totalExclVat: number;
  vatAmount: number;
  vatType: string;
}

function roundCents(n: number): number {
  return Math.round(n * 100) / 100;
}

/**
 * Generate a VAT201 return from customer and supplier invoices for the period.
 * Output VAT comes from customer_invoices; input VAT from supplier_invoices.
 * GL account codes 2120 (Output VAT) and 1140 (Input VAT) are cross-referenced.
 */
export async function generateVAT201(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<VAT201Data> {
  log.info('Generating VAT201', { periodStart, periodEnd }, 'vat201Service');

  let customerInvoices: Row[] = [];
  try {
    customerInvoices = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.subtotal,
        ci.tax_amount,
        ci.total_amount,
        ci.tax_rate,
        COALESCE(c.name, cl.name) AS customer_name,
        COALESCE(
          (
            SELECT jl.vat_type
            FROM gl_journal_lines jl
            WHERE jl.journal_entry_id = ci.gl_journal_entry_id
              AND jl.vat_type IS NOT NULL
            LIMIT 1
          ),
          CASE WHEN ci.tax_rate = 0 THEN 'zero_rated' ELSE 'standard' END
        ) AS vat_type
      FROM customer_invoices ci
      LEFT JOIN customers c ON c.id = ci.customer_id
      LEFT JOIN clients cl ON cl.id = ci.client_id
      WHERE ci.company_id = ${companyId}
        AND ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status != 'cancelled'
      ORDER BY ci.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query customer_invoices for VAT201', { error: err }, 'vat201Service');
  }

  let supplierInvoices: Row[] = [];
  try {
    supplierInvoices = (await sql`
      SELECT
        si.id,
        si.invoice_number,
        si.invoice_date,
        si.subtotal,
        si.tax_amount,
        si.total_amount,
        si.tax_rate,
        s.name AS supplier_name
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.company_id = ${companyId}
        AND si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status != 'cancelled'
      ORDER BY si.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query supplier_invoices for VAT201', { error: err }, 'vat201Service');
  }

  let supplierVatByClass: Row[] = [];
  try {
    supplierVatByClass = (await sql`
      SELECT
        COALESCE(sii.vat_classification, 'standard') AS classification,
        COALESCE(SUM(sii.tax_amount), 0) AS vat_total
      FROM supplier_invoice_items sii
      JOIN supplier_invoices si ON si.id = sii.supplier_invoice_id
      WHERE si.company_id = ${companyId}
        AND si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status != 'cancelled'
      GROUP BY COALESCE(sii.vat_classification, 'standard')
    `) as Row[];
  } catch (err) {
    log.warn('Could not query supplier_invoice_items for VAT201 classification', { error: err }, 'vat201Service');
  }

  let field1_standardRated = 0;
  let field2_zeroRated = 0;
  let field3_exempt = 0;

  const outputInvoices: VAT201Invoice[] = customerInvoices.map((inv: Row) => {
    const subtotal = Number(inv.subtotal) || 0;
    const vatAmt = Number(inv.tax_amount) || 0;
    const vatType = String(inv.vat_type || 'standard');

    if (vatType === 'exempt' || vatType === 'no_vat') {
      field3_exempt += subtotal;
    } else if (vatType === 'zero_rated' || vatType === 'export') {
      field2_zeroRated += subtotal;
    } else {
      field1_standardRated += subtotal;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.customer_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  const field5_outputVAT = roundCents(field1_standardRated * SA_VAT_RATE);

  let field6_capitalGoods = 0;
  let field7_otherGoods = 0;
  let field8_services = 0;
  let field9_imports = 0;

  for (const row of supplierVatByClass) {
    const cls = String(row.classification);
    const amount = Number(row.vat_total) || 0;
    if (cls === 'capital_goods') field6_capitalGoods += amount;
    else if (cls === 'services') field8_services += amount;
    else if (cls === 'imported' || cls === 'reverse_charge') field9_imports += amount;
    else field7_otherGoods += amount;
  }

  if (supplierVatByClass.length === 0) {
    for (const inv of supplierInvoices) {
      const vatAmt = Number(inv.tax_amount) || 0;
      const taxRate = Number(inv.tax_rate) || 0;
      if (taxRate > 0) field7_otherGoods += vatAmt;
    }
  }

  const inputInvoices: VAT201Invoice[] = supplierInvoices.map((inv: Row) => {
    const vatAmt = Number(inv.tax_amount) || 0;
    const subtotal = Number(inv.subtotal) || 0;
    const taxRate = Number(inv.tax_rate) || 0;
    const vatType = taxRate === 0 ? 'zero_rated' : 'standard';

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.supplier_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  const field10_totalInputVAT = roundCents(
    field6_capitalGoods + field7_otherGoods + field8_services + field9_imports
  );
  const field11_vatPayable = roundCents(field5_outputVAT - field10_totalInputVAT);

  return {
    periodStart,
    periodEnd,
    field1_standardRatedSupplies: roundCents(field1_standardRated),
    field2_zeroRatedSupplies: roundCents(field2_zeroRated),
    field3_exemptSupplies: roundCents(field3_exempt),
    field4_totalImports: roundCents(field9_imports > 0 ? field9_imports / SA_VAT_RATE : 0),
    field5_outputVAT,
    field6_capitalGoods: roundCents(field6_capitalGoods),
    field7_otherGoods: roundCents(field7_otherGoods),
    field8_services: roundCents(field8_services),
    field9_imports: roundCents(field9_imports),
    field10_totalInputVAT,
    field11_vatPayableOrRefundable: field11_vatPayable,
    outputInvoices,
    inputInvoices,
  };
}

/**
 * Bank Match Candidates API
 * GET /api/accounting/bank-match-candidates?bankTransactionId=<uuid>
 *
 * Smart matching strategy:
 * 1. Extract entity name from description → filter to that customer/supplier
 * 2. Direction-based: receipts → customer invoices, payments → supplier invoices/POs
 * 3. Invoice reference detection: if description contains "INV-00478" → boost that invoice
 * 4. Exact amount match on outstanding balance → highest score
 * 5. Multi-invoice combo: find 2-3 invoices whose balances sum to the payment amount
 * 6. Journal lines as fallback
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import type { MatchCandidate } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/* ── Scoring helpers ──────────────────────────────────────────────────────── */

function scoreAmount(txAmount: number, candidateAmount: number): number {
  const diff = Math.abs(Math.abs(txAmount) - Math.abs(candidateAmount));
  if (diff === 0) return 50;
  if (diff < 0.01) return 48;
  if (diff < 1) return 40;
  if (diff < 10) return 30;
  if (diff < 100) return 20;
  if (diff < 1000) return 10;
  return 0;
}

function scoreDate(txDate: string, candidateDate: string): number {
  const tx = new Date(txDate).getTime();
  const cand = new Date(candidateDate).getTime();
  const diffDays = Math.abs(tx - cand) / (1000 * 60 * 60 * 24);
  if (diffDays === 0) return 30;
  if (diffDays <= 1) return 28;
  if (diffDays <= 3) return 24;
  if (diffDays <= 7) return 20;
  if (diffDays <= 14) return 14;
  if (diffDays <= 30) return 8;
  if (diffDays <= 60) return 4;
  return 0;
}

function scoreDescription(txDesc: string, candidateLabel: string): number {
  if (!txDesc || !candidateLabel) return 0;
  const txWords = new Set(txDesc.toLowerCase().split(/\W+/).filter(w => w.length > 2));
  const candWords = candidateLabel.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  if (txWords.size === 0 || candWords.length === 0) return 0;
  const matches = candWords.filter(w => txWords.has(w)).length;
  const ratio = matches / Math.max(txWords.size, candWords.length);
  return Math.round(ratio * 20);
}

function fmtDate(val: unknown): string {
  if (val instanceof Date) return val.toISOString().split('T')[0]!;
  return val ? String(val).split('T')[0]! : '';
}

/* ── Entity extraction ────────────────────────────────────────────────────── */

const DESC_PREFIXES = [
  'EFT REC', 'EFT PMT', 'EFT PAYMENT', 'EFT RECEIPT',
  'PAYMENT TO', 'PAYMENT FROM', 'PMT TO', 'PMT FROM',
  'DEBIT ORDER', 'DEBI ORDER', 'STOP ORDER',
  'MAGTAPE', 'INTERNET TRF', 'CASH DEPOSIT',
];

function extractEntityName(description: string): string {
  let cleaned = description.toUpperCase().trim();
  for (const prefix of DESC_PREFIXES) {
    if (cleaned.startsWith(prefix)) {
      cleaned = cleaned.slice(prefix.length).trim();
      break;
    }
  }
  cleaned = cleaned.replace(/\s+\d{4}\/\d{2}$/, '').trim();
  cleaned = cleaned.replace(/\s+\d{6,}$/, '').trim();
  cleaned = cleaned.replace(/\s*\(PTY\)\s*(LTD)?/gi, '').trim();
  cleaned = cleaned.replace(/\s*\(SOC\)/gi, '').trim();
  return cleaned;
}

/**
 * Extract invoice reference numbers from description/reference.
 * Matches patterns like INV-00478, SINV-00548, INV00478, #478, etc.
 */
function extractInvoiceRefs(text: string): string[] {
  if (!text) return [];
  const refs: string[] = [];
  // Match INV-00478, SINV-00548, INV00478
  const invPattern = /(?:S?INV)[- ]?(\d{3,})/gi;
  let m: RegExpExecArray | null;
  while ((m = invPattern.exec(text)) !== null) {
    refs.push(m[1]!);
  }
  // Match PO-00123, PO00123
  const poPattern = /PO[- ]?(\d{3,})/gi;
  while ((m = poPattern.exec(text)) !== null) {
    refs.push(m[1]!);
  }
  return refs;
}

function entityNameMatches(entityName: string, extractedName: string): boolean {
  if (!entityName || !extractedName) return false;
  const entityWords = entityName.toUpperCase().split(/\W+/).filter(w => w.length > 2);
  const extractedWords = new Set(extractedName.toUpperCase().split(/\W+/).filter(w => w.length > 2));
  return entityWords.some(w => extractedWords.has(w));
}

/** Check if an invoice number matches any extracted references */
function invoiceRefMatches(invoiceNumber: string, refs: string[]): boolean {
  if (!invoiceNumber || refs.length === 0) return false;
  // Extract just the digits from the invoice number
  const invDigits = invoiceNumber.replace(/\D/g, '');
  return refs.some(ref => invDigits === ref || invDigits.endsWith(ref));
}

/* ── Multi-invoice combo detection ────────────────────────────────────────── */

interface InvoiceRow {
  id: string;
  invoiceNumber: string;
  entityName: string;
  balance: number;
  date: string;
  type: 'supplier_invoice' | 'customer_invoice';
}

/**
 * Find combinations of 2-3 invoices whose balances sum to the target amount.
 * Only checks invoices from the same entity. Tolerance: R0.01.
 */
function findInvoiceCombos(invoices: InvoiceRow[], targetAmount: number): InvoiceRow[][] {
  const combos: InvoiceRow[][] = [];
  const tolerance = 0.01;

  // 2-invoice combos
  for (let i = 0; i < invoices.length && combos.length < 3; i++) {
    for (let j = i + 1; j < invoices.length && combos.length < 3; j++) {
      const sum = invoices[i]!.balance + invoices[j]!.balance;
      if (Math.abs(sum - targetAmount) <= tolerance) {
        combos.push([invoices[i]!, invoices[j]!]);
      }
    }
  }

  // 3-invoice combos (only if no 2-combos found)
  if (combos.length === 0) {
    for (let i = 0; i < invoices.length && combos.length < 2; i++) {
      for (let j = i + 1; j < invoices.length && combos.length < 2; j++) {
        for (let k = j + 1; k < invoices.length && combos.length < 2; k++) {
          const sum = invoices[i]!.balance + invoices[j]!.balance + invoices[k]!.balance;
          if (Math.abs(sum - targetAmount) <= tolerance) {
            combos.push([invoices[i]!, invoices[j]!, invoices[k]!]);
          }
        }
      }
    }
  }

  return combos;
}

/* ── Handler ──────────────────────────────────────────────────────────────── */

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { bankTransactionId } = req.query;
  if (!bankTransactionId || typeof bankTransactionId !== 'string') {
    return apiResponse.badRequest(res, 'bankTransactionId query param is required');
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const txRows = (await sql`
      SELECT id, amount, transaction_date, description, reference
      FROM bank_transactions
      WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    `) as Row[];

    if (txRows.length === 0) {
      return apiResponse.notFound(res, 'Bank transaction', bankTransactionId);
    }

    const tx = txRows[0]!;
    const txAmount = Number(tx.amount);
    const txDate = fmtDate(tx.transaction_date);
    const txDesc = String(tx.description ?? tx.reference ?? '');
    const txRef = String(tx.reference ?? '');
    const absAmount = Math.abs(txAmount);

    const extractedEntity = extractEntityName(txDesc);
    const invoiceRefs = extractInvoiceRefs(`${txDesc} ${txRef}`);
    const isReceipt = txAmount > 0;

    const candidates: MatchCandidate[] = [];

    // ── 1. Supplier invoices (payments only) ────────────────────────────────
    if (!isReceipt) {
      const allRows = (await sql`
        SELECT si.id, si.invoice_number, COALESCE(s.company_name, s.name) AS supplier_name,
               si.total_amount, si.invoice_date
        FROM supplier_invoices si
        JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.status IN ('approved', 'partially_paid')
          AND si.company_id = ${companyId}
        ORDER BY ABS(si.total_amount - ${absAmount}::NUMERIC) ASC
        LIMIT 50
      `) as Row[];

      let rows = allRows;
      if (extractedEntity) {
        const filtered = allRows.filter((r: Row) =>
          entityNameMatches(String(r.supplier_name), extractedEntity));
        if (filtered.length > 0) rows = filtered;
      }

      // Collect for combo detection
      const comboPool: InvoiceRow[] = [];

      for (const row of rows.slice(0, 20)) {
        const invNum = String(row.invoice_number);
        const label = `${String(row.supplier_name)} — Inv ${invNum}`;
        const candAmount = Number(row.total_amount);
        const candDate = fmtDate(row.invoice_date);

        let score = scoreAmount(txAmount, candAmount)
          + scoreDate(txDate, candDate)
          + scoreDescription(txDesc, label);

        let matchReason: string | undefined;

        // Bonus: invoice reference in bank description
        if (invoiceRefMatches(invNum, invoiceRefs)) {
          score += 30;
          matchReason = `Reference ${invNum} found in description`;
        }

        // Bonus: exact amount match
        if (Math.abs(candAmount - absAmount) < 0.01) {
          matchReason = matchReason
            ? `${matchReason} + exact amount`
            : 'Exact amount match';
        }

        candidates.push({
          type: 'supplier_invoice', id: String(row.id),
          label, amount: candAmount, date: candDate, score, matchReason,
        });

        comboPool.push({
          id: String(row.id), invoiceNumber: invNum,
          entityName: String(row.supplier_name),
          balance: candAmount, date: candDate,
          type: 'supplier_invoice',
        });
      }

      // Multi-invoice combos
      const combos = findInvoiceCombos(comboPool, absAmount);
      for (const combo of combos) {
        const invNums = combo.map(c => c.invoiceNumber).join(' + ');
        const label = `${combo[0]!.entityName} — ${combo.length} invoices (${invNums})`;
        candidates.push({
          type: 'supplier_invoice',
          id: combo.map(c => c.id).join(','),
          label,
          amount: combo.reduce((sum, c) => sum + c.balance, 0),
          date: combo[0]!.date,
          score: 95,
          matchReason: `${combo.length} invoices sum to exact payment amount`,
        });
      }
    }

    // ── 2. Customer invoices (receipts only) ─────────────────────────────────
    if (isReceipt) {
      const allRows = (await sql`
        SELECT ci.id, ci.invoice_number, c.name AS customer_name,
               ci.total_amount, ci.invoice_date, ci.amount_paid
        FROM customer_invoices ci
        JOIN customers c ON c.id = ci.customer_id
        WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND ci.company_id = ${companyId}
        ORDER BY ABS(ci.total_amount - ci.amount_paid - ${absAmount}::NUMERIC) ASC
        LIMIT 50
      `) as Row[];

      let rows = allRows;
      if (extractedEntity) {
        const filtered = allRows.filter((r: Row) =>
          entityNameMatches(String(r.customer_name), extractedEntity));
        if (filtered.length > 0) rows = filtered;
      }

      const comboPool: InvoiceRow[] = [];

      for (const row of rows.slice(0, 20)) {
        const invNum = String(row.invoice_number);
        const label = `${String(row.customer_name)} — Inv ${invNum}`;
        const balance = Number(row.total_amount) - Number(row.amount_paid || 0);
        const candDate = fmtDate(row.invoice_date);

        let score = scoreAmount(txAmount, balance)
          + scoreDate(txDate, candDate)
          + scoreDescription(txDesc, label);

        let matchReason: string | undefined;

        if (invoiceRefMatches(invNum, invoiceRefs)) {
          score += 30;
          matchReason = `Reference ${invNum} found in description`;
        }

        if (Math.abs(balance - absAmount) < 0.01) {
          matchReason = matchReason
            ? `${matchReason} + exact amount`
            : 'Exact amount match';
        }

        candidates.push({
          type: 'customer_invoice', id: String(row.id),
          label, amount: balance, date: candDate, score, matchReason,
        });

        comboPool.push({
          id: String(row.id), invoiceNumber: invNum,
          entityName: String(row.customer_name),
          balance, date: candDate,
          type: 'customer_invoice',
        });
      }

      // Multi-invoice combos
      const combos = findInvoiceCombos(comboPool, absAmount);
      for (const combo of combos) {
        const invNums = combo.map(c => c.invoiceNumber).join(' + ');
        const label = `${combo[0]!.entityName} — ${combo.length} invoices (${invNums})`;
        candidates.push({
          type: 'customer_invoice',
          id: combo.map(c => c.id).join(','),
          label,
          amount: combo.reduce((sum, c) => sum + c.balance, 0),
          date: combo[0]!.date,
          score: 95,
          matchReason: `${combo.length} invoices sum to exact receipt amount`,
        });
      }
    }

    // ── 3. Purchase orders (payments only) ───────────────────────────────────
    if (!isReceipt) {
      const allRows = (await sql`
        SELECT po.id, po.po_number, COALESCE(s.company_name, s.name) AS supplier_name,
               po.total, po.created_at
        FROM purchase_orders po
        JOIN suppliers s ON s.id = po.supplier_id
        WHERE po.status IN ('approved', 'partially_paid')
          AND po.company_id = ${companyId}
        ORDER BY ABS(po.total - ${absAmount}::NUMERIC) ASC
        LIMIT 50
      `) as Row[];

      let rows = allRows;
      if (extractedEntity) {
        const filtered = allRows.filter((r: Row) =>
          entityNameMatches(String(r.supplier_name), extractedEntity));
        if (filtered.length > 0) rows = filtered;
      }

      for (const row of rows.slice(0, 20)) {
        const poNum = String(row.po_number);
        const label = `${String(row.supplier_name)} — PO ${poNum}`;
        const candAmount = Number(row.total);
        const candDate = fmtDate(row.created_at);

        let score = scoreAmount(txAmount, candAmount)
          + scoreDate(txDate, candDate)
          + scoreDescription(txDesc, label);

        let matchReason: string | undefined;

        if (invoiceRefMatches(poNum, invoiceRefs)) {
          score += 30;
          matchReason = `Reference ${poNum} found in description`;
        }

        if (Math.abs(candAmount - absAmount) < 0.01) {
          matchReason = matchReason
            ? `${matchReason} + exact amount`
            : 'Exact amount match';
        }

        candidates.push({
          type: 'purchase_order', id: String(row.id),
          label, amount: candAmount, date: candDate, score, matchReason,
        });
      }
    }

    // ── 4. GL journal lines ──────────────────────────────────────────────────
    const jlRows = (await sql`
      SELECT jl.id, jl.description, jl.debit, jl.credit, je.entry_date
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}
        AND jl.id NOT IN (
          SELECT matched_journal_line_id FROM bank_transactions
          WHERE matched_journal_line_id IS NOT NULL
        )
      ORDER BY ABS((jl.debit - jl.credit) - ${txAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of jlRows) {
      const lineNet = Number(row.debit) - Number(row.credit);
      const label = String(row.description ?? 'Journal line');
      const candDate = fmtDate(row.entry_date);
      const score = scoreAmount(txAmount, lineNet)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);

      let matchReason: string | undefined;
      if (Math.abs(lineNet - txAmount) < 0.01) {
        matchReason = 'Exact amount match';
      }

      candidates.push({
        type: 'journal_line', id: String(row.id),
        label, amount: lineNet, date: candDate, score, matchReason,
      });
    }

    // Sort by score descending
    candidates.sort((a, b) => b.score - a.score);

    log.info('Fetched bank match candidates', {
      bankTransactionId,
      extractedEntity: extractedEntity || '(none)',
      invoiceRefs: invoiceRefs.length > 0 ? invoiceRefs.join(',') : '(none)',
      count: candidates.length,
    }, 'accounting-api');

    return apiResponse.success(res, { candidates });
  } catch (err) {
    log.error('Failed to fetch bank match candidates', { bankTransactionId, error: err }, 'accounting-api');
    return apiResponse.internalError(res, err);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Customer Write-Off Service
 * Phase 1 Sage Alignment: Bad debt write-offs with GL posting
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { CustomerWriteOff, WriteOffCreateInput } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getWriteOffs(companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: CustomerWriteOff[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT wo.*, c.name AS client_name, ci.invoice_number
      FROM customer_write_offs wo
      LEFT JOIN customers c ON c.id = wo.client_id
      LEFT JOIN customer_invoices ci ON ci.id = wo.invoice_id
      WHERE wo.company_id = ${companyId} AND wo.client_id = ${filters.clientId}::UUID
      ORDER BY wo.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_write_offs
      WHERE company_id = ${companyId} AND client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT wo.*, c.name AS client_name, ci.invoice_number
      FROM customer_write_offs wo
      LEFT JOIN customers c ON c.id = wo.client_id
      LEFT JOIN customer_invoices ci ON ci.id = wo.invoice_id
      WHERE wo.company_id = ${companyId} AND wo.status = ${filters.status}
      ORDER BY wo.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_write_offs
      WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT wo.*, c.name AS client_name, ci.invoice_number
      FROM customer_write_offs wo
      LEFT JOIN customers c ON c.id = wo.client_id
      LEFT JOIN customer_invoices ci ON ci.id = wo.invoice_id
      WHERE wo.company_id = ${companyId}
      ORDER BY wo.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_write_offs WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createWriteOff(companyId: string, 
  input: WriteOffCreateInput,
  userId: string
): Promise<CustomerWriteOff> {
  // Validate amount against invoice balance
  const invRows = (await sql`
    SELECT total_amount, amount_paid FROM customer_invoices
    WHERE id = ${input.invoiceId}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!invRows[0]) throw new Error('Invoice not found');
  const balance = Number(invRows[0].total_amount) - Number(invRows[0].amount_paid);
  if (input.amount > balance + 0.01) {
    throw new Error(`Write-off amount R${input.amount.toFixed(2)} exceeds invoice balance R${balance.toFixed(2)}`);
  }

  const rows = (await sql`
    INSERT INTO customer_write_offs (
      company_id, client_id, invoice_id, amount, reason, write_off_date, created_by
    ) VALUES (
      ${companyId}, ${input.clientId}::UUID, ${input.invoiceId}::UUID, ${input.amount},
      ${input.reason}, ${input.writeOffDate || new Date().toISOString().split('T')[0]},
      ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created write-off', { id: rows[0]?.id, amount: input.amount }, 'accounting');
  return mapRow(rows[0]!);
}

export async function approveWriteOff(companyId: string, id: string, userId: string): Promise<CustomerWriteOff> {
  const woRows = (await sql`
    SELECT wo.*, ci.invoice_number FROM customer_write_offs wo
    LEFT JOIN customer_invoices ci ON ci.id = wo.invoice_id
    WHERE wo.id = ${id} AND wo.company_id = ${companyId}
  `) as Row[];
  if (!woRows[0]) throw new Error('Write-off not found');
  if (woRows[0].status !== 'draft') throw new Error('Write-off is not in draft status');

  const wo = woRows[0];
  const amount = Number(wo.amount);

  // GL: DR Bad Debts Expense, CR Accounts Receivable
  const expenseAccount = await getSystemAccount('admin_expense');
  const arAccount = await getSystemAccount('receivable');

  const lines: JournalLineInput[] = [
    { glAccountId: expenseAccount.id, debit: amount, credit: 0,
      description: `Bad debt write-off: ${wo.invoice_number}` },
    { glAccountId: arAccount.id, debit: 0, credit: amount,
      description: `Write-off AR: ${wo.invoice_number}` },
  ];

  const je = await createJournalEntry('', {
    entryDate: String(wo.write_off_date),
    description: `Write-off ${wo.write_off_number} — ${wo.invoice_number}`,
    source: 'auto_write_off',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry('', je.id, userId);

  // Update invoice balance
  await sql`
    UPDATE customer_invoices
    SET amount_paid = amount_paid + ${amount},
        status = CASE WHEN (total_amount - amount_paid - ${amount}) <= 0.01 THEN 'paid' ELSE status END
    WHERE id = ${wo.invoice_id}::UUID
  `;

  const updated = (await sql`
    UPDATE customer_write_offs
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved write-off', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelWriteOff(companyId: string, id: string): Promise<void> {
  await sql`UPDATE customer_write_offs SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

function mapRow(row: Row): CustomerWriteOff {
  return {
    id: String(row.id),
    writeOffNumber: row.write_off_number ? String(row.write_off_number) : '',
    clientId: String(row.client_id),
    invoiceId: String(row.invoice_id),
    amount: Number(row.amount),
    reason: String(row.reason),
    writeOffDate: String(row.write_off_date),
    status: String(row.status) as CustomerWriteOff['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * Bank Match Confirm API
 * POST /api/accounting/bank-match-confirm
 * Body: { bankTransactionId, candidateType, candidateId }
 *
 * Confirms a manual match selection from the FindMatchModal.
 * Creates proper double-entry journal entries and handles partial payments:
 *
 * Customer invoice (receipt):  DR Bank, CR Accounts Receivable
 * Supplier invoice (payment):  DR Accounts Payable, CR Bank
 * Purchase order (payment):    DR Accounts Payable, CR Bank
 * Journal line:                Direct match to existing GL entry
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  matchTransaction,
} from '@/modules/accounting/services/bankReconciliationService';
import type { CandidateType } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const {
    bankTransactionId,
    candidateType,
    candidateId,
  } = req.body as {
    bankTransactionId?: string;
    candidateType?: CandidateType;
    candidateId?: string;
  };

  const { companyId } = req;
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!candidateType) return apiResponse.badRequest(res, 'candidateType is required');
  if (!candidateId) return apiResponse.badRequest(res, 'candidateId is required');

  const validTypes: CandidateType[] = ['supplier_invoice', 'customer_invoice', 'purchase_order', 'journal_line'];
  if (!validTypes.includes(candidateType)) {
    return apiResponse.badRequest(res, `candidateType must be one of: ${validTypes.join(', ')}`);
  }

  try {
    // Get the bank transaction amount for partial payment calculations
    const txRows = (await sql`
      SELECT amount FROM bank_transactions WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    `) as Row[];
    if (txRows.length === 0) {
      return apiResponse.notFound(res, 'Bank transaction', bankTransactionId);
    }
    const paymentAmount = Math.abs(Number(txRows[0]!.amount));

    if (candidateType === 'supplier_invoice') {
      const invRows = (await sql`
        SELECT id, supplier_id, total_amount, amount_paid, balance
        FROM supplier_invoices WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (invRows.length === 0) {
        return apiResponse.notFound(res, 'Supplier invoice', candidateId);
      }
      const inv = invRows[0]!;
      const supplierId = String(inv.supplier_id);
      const currentPaid = Number(inv.amount_paid || 0);
      const invoiceTotal = Number(inv.total_amount);
      const outstandingBalance = invoiceTotal - currentPaid;

      // Create GL entry: DR Accounts Payable, CR Bank
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'supplier', supplierId,
      );

      // Update invoice payment tracking
      const newPaid = currentPaid + Math.min(paymentAmount, outstandingBalance);
      const newBalance = invoiceTotal - newPaid;
      const newStatus = newBalance <= 0.01 ? 'paid' : 'partially_paid';

      await sql`
        UPDATE supplier_invoices
        SET amount_paid = ${newPaid}::NUMERIC,
            balance = ${newBalance}::NUMERIC,
            status = ${newStatus},
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: supplier invoice', {
        bankTransactionId, candidateId,
        paymentAmount, outstandingBalance, newStatus,
      }, 'accounting-api');

    } else if (candidateType === 'customer_invoice') {
      const ciRows = (await sql`
        SELECT id, customer_id, total_amount, amount_paid
        FROM customer_invoices WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (ciRows.length === 0) {
        return apiResponse.notFound(res, 'Customer invoice', candidateId);
      }
      const ci = ciRows[0]!;
      const customerId = String(ci.customer_id);
      const currentPaid = Number(ci.amount_paid || 0);
      const invoiceTotal = Number(ci.total_amount);
      const outstandingBalance = invoiceTotal - currentPaid;

      // Create GL entry: DR Bank, CR Accounts Receivable
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'customer', customerId,
      );

      // Update invoice payment tracking
      const newPaid = currentPaid + Math.min(paymentAmount, outstandingBalance);
      const newStatus = (newPaid >= invoiceTotal - 0.01) ? 'paid' : 'partially_paid';

      await sql`
        UPDATE customer_invoices
        SET amount_paid = ${newPaid}::NUMERIC,
            status = ${newStatus},
            paid_at = ${newStatus === 'paid' ? new Date().toISOString() : null},
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: customer invoice', {
        bankTransactionId, candidateId,
        paymentAmount, outstandingBalance, newStatus,
      }, 'accounting-api');

    } else if (candidateType === 'purchase_order') {
      const poRows = (await sql`
        SELECT id, supplier_id, total FROM purchase_orders WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (poRows.length === 0) {
        return apiResponse.notFound(res, 'Purchase order', candidateId);
      }
      const supplierId = String(poRows[0]!.supplier_id);

      // Create GL entry: DR Accounts Payable, CR Bank
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'supplier', supplierId,
      );

      await sql`
        UPDATE purchase_orders SET status = 'paid', updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: purchase order', { bankTransactionId, candidateId }, 'accounting-api');

    } else {
      // journal_line — match to existing GL entry
      await matchTransaction(companyId, bankTransactionId, candidateId);
      log.info('Confirmed match: journal line', { bankTransactionId, candidateId }, 'accounting-api');
    }

    return apiResponse.success(res, { matched: true, candidateType, candidateId });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Match confirmation failed';
    log.error('Failed to confirm bank match', { bankTransactionId, candidateType, candidateId, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

