/**
 * Company Documents API
 * GET  ?companyId=      — list active documents (without file_data)
 * GET  ?id=&download=1  — single doc with file_data for download
 * POST                  — create a new document
 * DELETE ?id=           — soft-delete a document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { isVlmAvailable } from '@/modules/accounting/services/vlmService';
import { extractStatutoryDocWithVlm } from '@/modules/accounting/services/vlmService';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // ── Helper: validate company membership ──
  async function validateMembership(companyId: string): Promise<boolean> {
    const rows = (await sql`
      SELECT role FROM company_users
      WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
    `) as Row[];
    return rows.length > 0;
  }

  // ── GET ──
  if (req.method === 'GET') {
    // Download single doc
    if (req.query.id && req.query.download === '1') {
      const rows = (await sql`
        SELECT id, company_id, document_type, document_name, file_data,
               mime_type, file_size, uploaded_at, notes
        FROM company_documents
        WHERE id = ${req.query.id as string}::UUID AND is_active = true
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Document');
      const doc = rows[0];
      if (!(await validateMembership(doc.company_id))) {
        return apiResponse.forbidden(res, 'You do not have access to this company');
      }
      return apiResponse.success(res, {
        id: doc.id,
        documentType: doc.document_type,
        documentName: doc.document_name,
        fileData: doc.file_data,
        mimeType: doc.mime_type,
        fileSize: doc.file_size,
        uploadedAt: doc.uploaded_at,
        notes: doc.notes,
      });
    }

    // List docs for a company
    const companyId = req.query.companyId as string;
    if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
    if (!(await validateMembership(companyId))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    const rows = (await sql`
      SELECT id, document_type, document_name, mime_type,
             file_size, uploaded_at, notes
      FROM company_documents
      WHERE company_id = ${companyId}::UUID AND is_active = true
      ORDER BY uploaded_at DESC
    `) as Row[];

    return apiResponse.success(res, {
      items: rows.map((r: Row) => ({
        id: r.id,
        documentType: r.document_type,
        documentName: r.document_name,
        mimeType: r.mime_type,
        fileSize: r.file_size,
        uploadedAt: r.uploaded_at,
        notes: r.notes,
      })),
    });
  }

  // ── POST ──
  if (req.method === 'POST') {
    const { companyId, documentType, documentName, fileData, mimeType, fileSize, notes } = req.body;
    if (!companyId || !documentType || !documentName || !fileData) {
      return apiResponse.badRequest(res, 'companyId, documentType, documentName, and fileData are required');
    }
    if (!(await validateMembership(companyId))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    const rows = (await sql`
      INSERT INTO company_documents (
        company_id, document_type, document_name,
        file_data, mime_type, file_size, uploaded_by, notes
      ) VALUES (
        ${companyId}::UUID, ${documentType}, ${documentName},
        ${fileData}, ${mimeType || 'application/octet-stream'},
        ${fileSize || 0}, ${userId}, ${notes || null}
      )
      RETURNING id
    `) as Row[];

    const docId = rows[0].id as string;

    // Fire-and-forget VLM extraction for statutory documents
    if (isVlmAvailable() && fileData) {
      extractStatutoryDocData(fileData, documentType, docId).catch(err =>
        log.warn('Statutory doc extraction failed', { error: err instanceof Error ? err.message : String(err) }, 'company-docs')
      );
    }

    return apiResponse.created(res, { id: docId });
  }

  // ── DELETE (soft) ──
  if (req.method === 'DELETE') {
    const docId = req.query.id as string;
    if (!docId) return apiResponse.badRequest(res, 'id is required');

    const rows = (await sql`
      SELECT company_id FROM company_documents
      WHERE id = ${docId}::UUID AND is_active = true
    `) as Row[];
    if (rows.length === 0) return apiResponse.notFound(res, 'Document');
    if (!(await validateMembership(rows[0].company_id))) {
      return apiResponse.forbidden(res, 'You do not have access to this company');
    }

    await sql`
      UPDATE company_documents SET is_active = false WHERE id = ${docId}::UUID
    `;
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'DELETE']);
}

/** Background statutory document VLM extraction */
async function extractStatutoryDocData(fileData: string, docType: string, docId: string) {
  // fileData is a base64 data URL
  const match = fileData.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return;
  const mimeType = match[1]!;
  const base64 = match[2]!;

  const docTypeMap: Record<string, string> = {
    cipc_certificate: 'cipc',
    tax_clearance: 'tax_clearance',
    bbbee_certificate: 'bbee',
    vat_registration: 'vat_registration',
  };

  const result = await extractStatutoryDocWithVlm(base64, mimeType, docTypeMap[docType] || undefined);
  if (result) {
    await sql`
      UPDATE company_documents
      SET extracted_data = ${JSON.stringify(result)}::jsonb
      WHERE id = ${docId}::uuid
    `;
    log.info('Statutory doc extraction stored', { docId, docType: result.documentType }, 'company-docs');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '50mb' } },
};

/**
 * Company Invitations API
 * GET    — list pending invitations for the active company
 * POST   — create invitation { email, role }   (owner/admin only)
 * DELETE — cancel invitation { invitationId }  (owner/admin only)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  listPendingInvitations,
  createInvitation,
  cancelInvitation,
  markInvitationEmailSent,
  markInvitationEmailFailed,
} from '@/modules/accounting/services/userAccessService';
import { sendInviteEmail } from '@/modules/accounting/services/emailService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const ADMIN_ROLES = ['owner', 'admin'];
const BASE_URL = process.env.NEXT_PUBLIC_APP_URL ?? 'https://app.isaflow.co.za';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const companyReq = req as CompanyApiRequest;
  const { companyId, companyRole } = companyReq;

  // GET — list pending invitations
  if (req.method === 'GET') {
    if (!ADMIN_ROLES.includes(companyRole)) {
      return apiResponse.forbidden(res, 'Only owners and admins can view invitations.');
    }
    const invitations = await listPendingInvitations(companyId);
    return apiResponse.success(res, invitations);
  }

  // POST — send invitation
  if (req.method === 'POST') {
    if (!ADMIN_ROLES.includes(companyRole)) {
      return apiResponse.forbidden(res, 'Only owners and admins can invite users.');
    }

    const { email, role } = req.body as { email?: string; role?: string };
    if (!email || !role) {
      return apiResponse.badRequest(res, 'email and role are required.');
    }

    const emailLower = email.toLowerCase().trim();
    if (!emailLower.includes('@')) {
      return apiResponse.badRequest(res, 'A valid email address is required.');
    }

    const invitedBy = companyReq.user.id;
    const inviterName = companyReq.user.name || companyReq.user.email;

    try {
      const result = await createInvitation(companyId, emailLower, role, invitedBy);

      // Path 1: user already existed — auto-added, no email needed
      if (result.autoAdded || !result.invitation) {
        return apiResponse.success(res, { ...result, emailSent: false });
      }

      // Path 2: invitation token created — look up company name and send email
      const companyRows = (await sql`
        SELECT name FROM companies WHERE id = ${companyId}::UUID LIMIT 1
      `) as Row[];
      const companyName = (companyRows[0]?.name as string | undefined) ?? 'ISaFlow';

      const invitationId = result.invitation.id;
      const token = result.invitation.token;

      let emailSent = false;
      try {
        const emailResult = await sendInviteEmail({
          recipientEmail: emailLower,
          inviteToken: token,
          companyName,
          inviterName,
          role,
          baseUrl: BASE_URL,
        });

        if (emailResult.success) {
          emailSent = true;
          await markInvitationEmailSent(invitationId);
          log.info('Invite email sent', { invitationId, to: emailLower }, 'company-invitations');
        } else {
          await markInvitationEmailFailed(invitationId, emailResult.error ?? 'Unknown error');
          log.warn('Invite email failed to send', { invitationId, error: emailResult.error }, 'company-invitations');
        }
      } catch (emailErr) {
        const errMsg = emailErr instanceof Error ? emailErr.message : 'Email send threw';
        await markInvitationEmailFailed(invitationId, errMsg).catch(() => undefined);
        log.error('Invite email threw', { invitationId, error: errMsg }, 'company-invitations');
      }

      return apiResponse.success(res, { ...result, emailSent });
    } catch (err) {
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Invite failed.');
    }
  }

  // DELETE — cancel invitation
  if (req.method === 'DELETE') {
    if (!ADMIN_ROLES.includes(companyRole)) {
      return apiResponse.forbidden(res, 'Only owners and admins can cancel invitations.');
    }

    const { invitationId } = req.body as { invitationId?: string };
    if (!invitationId) {
      return apiResponse.badRequest(res, 'invitationId is required.');
    }

    await cancelInvitation(invitationId, companyId);
    return apiResponse.success(res, { cancelled: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * POST /api/accounting/company-logo
 * Upload/update company logo as a base64 data URL.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { companyId, logoData } = req.body as {
    companyId?: string;
    logoData?: string;
  };

  if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
  if (!logoData) return apiResponse.badRequest(res, 'logoData is required');

  // Validate ownership (owner or admin)
  const membership = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
  `) as Row[];

  if (membership.length === 0) {
    return apiResponse.forbidden(res, 'You do not have access to this company');
  }
  if (!['owner', 'admin'].includes(membership[0].role)) {
    return apiResponse.forbidden(res, 'Only owners and admins can update the company logo');
  }

  // Validate data URL format
  if (!logoData.startsWith('data:image/')) {
    return apiResponse.badRequest(res, 'logoData must be a valid data:image/ URL');
  }

  // Validate size < 5MB (base64 is ~1.33x raw, so 5MB raw ~ 6.8M chars)
  if (logoData.length > 6_800_000) {
    return apiResponse.badRequest(res, 'Logo must be smaller than 5MB');
  }

  await sql`
    UPDATE companies SET logo_data = ${logoData} WHERE id = ${companyId}::UUID
  `;

  return apiResponse.success(res, { updated: true });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '10mb' } },
};

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  try {
    const userId = String(req.user?.id || 'system');

    // Auto-generate invoice number (use MAX to avoid duplicates)
    const maxRows = (await sql`
      SELECT MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INTEGER)) as max_num
      FROM customer_invoices WHERE company_id = ${companyId} AND invoice_number LIKE 'INV-%'
    `) as Row[];
    const nextNum = (Number(maxRows[0]?.max_num) || 0) + 1;
    const invoiceNumber = `INV-${String(nextNum).padStart(5, '0')}`;

    // Calculate totals
    const rate = taxRate ?? 15;
    let subtotal = 0;
    for (const item of items) {
      subtotal += (item.quantity || 1) * item.unitPrice;
    }
    subtotal = Math.round(subtotal * 100) / 100;
    const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
    const totalAmount = subtotal + taxAmount;

    const today = new Date().toISOString().split('T')[0];
    const invDate = invoiceDate || today;
    const bpStart = billingPeriodStart || null;
    const bpEnd = billingPeriodEnd || null;

    // Find project from client (optional)
    let projectId: string | null = null;
    try {
      const projRows = (await sql`SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1`) as Row[];
      projectId = projRows[0]?.id || null;
    } catch { /* projects table may not exist */ }

    const invRows = (await sql`
      INSERT INTO customer_invoices (
        company_id, invoice_number, project_id, customer_id, client_id, billing_period_start, billing_period_end,
        subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
        notes, status, created_by
      ) VALUES (
        ${companyId}, ${invoiceNumber}, ${projectId}, ${clientId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
        ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
        ${dueDate || null}, ${notes || null}, 'draft', ${userId}
      ) RETURNING id
    `) as Row[];

    const invoiceId = invRows[0].id;

    for (const item of items) {
      const qty = item.quantity || 1;
      const lineAmount = Math.round(qty * item.unitPrice * 100) / 100;
      await sql`
        INSERT INTO customer_invoice_items (invoice_id, description, unit_price, quantity, amount, tax_rate)
        VALUES (${invoiceId}::UUID, ${item.description}, ${item.unitPrice}, ${qty}, ${lineAmount}, ${rate})
      `;
    }

    log.info('Customer invoice created', { invoiceNumber, totalAmount });
    return apiResponse.created(res, { id: invoiceId, invoiceNumber });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Invoice create failed', { error: msg });
    const clientMessage = process.env.NODE_ENV === 'development' ? msg : 'Failed to create invoice';
    return res.status(500).json({ success: false, error: { code: 'CREATE_FAILED', message: clientMessage } });
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Customer Invoice Detail API
 * GET  ?id=UUID — single invoice with line items
 * PUT  { id, ...fields } — update draft invoice
 * POST { id, action } — status actions (approve, send, cancel)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { postCustomerInvoiceToGL } from '@/modules/accounting/services/customerPaymentService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const { id } = req.query;
    if (!id) return apiResponse.badRequest(res, 'id is required');

    try {
      const rows = (await sql`
        SELECT ci.id, ci.invoice_number, ci.customer_id, ci.client_id,
               ci.billing_period_start, ci.billing_period_end,
               ci.subtotal, ci.tax_rate, ci.tax_amount, ci.total_amount,
               ci.amount_paid, ci.status, ci.invoice_date, ci.due_date,
               ci.sent_at, ci.paid_at, ci.notes, ci.internal_notes,
               ci.project_id, ci.gl_journal_entry_id,
               ci.email_sent_at, ci.email_sent_to,
               ci.online_payment_enabled, ci.payment_url,
               ci.created_at, ci.updated_at,
               c.name AS client_name, c.email AS client_email
        FROM customer_invoices ci
        LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
        WHERE ci.id = ${id as string}::UUID AND ci.company_id = ${companyId}
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Invoice', id as string);

      const items = (await sql`
        SELECT * FROM customer_invoice_items WHERE invoice_id = ${id as string}::UUID ORDER BY created_at
      `) as Row[];

      return apiResponse.success(res, { ...rows[0], items });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log.error('Customer invoice detail GET error', { error: msg }, 'customer-invoice-detail');
      return apiResponse.internalError(res, err, `Failed to load invoice: ${msg}`);
    }
  }

  if (req.method === 'PUT') {
    const { id, notes, internalNotes, dueDate } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');

    await sql`
      UPDATE customer_invoices
      SET notes = COALESCE(${notes || null}, notes),
          internal_notes = COALESCE(${internalNotes || null}, internal_notes),
          due_date = COALESCE(${dueDate || null}, due_date),
          updated_at = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId} AND status = 'draft'
    `;
    log.info('Customer invoice updated', { id });
    return apiResponse.success(res, { updated: true });
  }

  if (req.method === 'POST') {
    const { id, action } = req.body;
    if (!id || !action) return apiResponse.badRequest(res, 'id and action required');

    const validActions: Record<string, string> = {
      approve: 'approved', send: 'sent', cancel: 'cancelled',
    };
    const newStatus = validActions[action];
    if (!newStatus) return apiResponse.badRequest(res, `Unknown action: ${action}`);

    await sql`UPDATE customer_invoices SET status = ${newStatus}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;

    // Post to GL on approve (accrual accounting: DR AR, CR Revenue, CR VAT Output)
    let glJournalEntryId: string | null = null;
    if (action === 'approve') {
      try {
        const userId = (req as CompanyApiRequest).user?.id || 'system';
        glJournalEntryId = await postCustomerInvoiceToGL(companyId, id, userId);
        log.info('Customer invoice GL posted on approve', { id, glJournalEntryId });
      } catch (glErr) {
        log.error('GL posting failed on invoice approve (invoice still approved)', { id, error: glErr });
      }
    }

    log.info('Customer invoice action', { id, action, newStatus });
    return apiResponse.success(res, { id, status: newStatus, glJournalEntryId });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

