/**
 * POPIA Data Subject Rights — M9
 * GET  ?action=access  — returns all PII stored for the authenticated user
 * GET  ?action=export  — returns user data as JSON download
 * POST { action: 'erasure' } — anonymizes user PII (soft delete pattern)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import type { CompanyApiRequest } from '@/lib/auth/withCompany';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function getUserPii(userId: string, companyId: string) {
  const userRows = (await sql`
    SELECT id, first_name, last_name, email, created_at, updated_at
    FROM users
    WHERE id = ${userId}::UUID
  `) as Row[];

  const companyUserRows = (await sql`
    SELECT cu.role, cu.created_at AS joined_at, c.name AS company_name
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId}::UUID
      AND cu.company_id = ${companyId}::UUID
  `) as Row[];

  const invitationRows = (await sql`
    SELECT email, role, created_at, accepted_at
    FROM company_invitations
    WHERE invited_by = ${userId}::VARCHAR
      AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
    LIMIT 50
  `) as Row[];

  return {
    user: userRows[0] ?? null,
    companyMemberships: companyUserRows,
    invitationsSent: invitationRows,
  };
}

async function handleAccess(req: NextApiRequest, res: NextApiResponse) {
  const companyReq = req as CompanyApiRequest;
  const userId = companyReq.user.id;
  const companyId = companyReq.companyId;

  const data = await getUserPii(userId, companyId);

  return apiResponse.success(res, data, 'PII access report compiled');
}

async function handleExport(req: NextApiRequest, res: NextApiResponse) {
  const companyReq = req as CompanyApiRequest;
  const userId = companyReq.user.id;
  const companyId = companyReq.companyId;

  const data = await getUserPii(userId, companyId);
  const json = JSON.stringify({ exportedAt: new Date().toISOString(), ...data }, null, 2);

  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Disposition', 'attachment; filename="isaflow-data-export.json"');
  res.status(200).send(json);
}

async function handleErasure(req: NextApiRequest, res: NextApiResponse) {
  const companyReq = req as CompanyApiRequest;
  const userId = companyReq.user.id;

  const placeholder = `anonymized_${userId.slice(0, 8)}`;

  await sql`
    UPDATE users SET
      first_name  = 'Anonymized',
      last_name   = ${placeholder},
      email       = ${`${placeholder}@deleted.invalid`},
      updated_at  = NOW()
    WHERE id = ${userId}::UUID
  `;

  log.info('Data subject erasure completed', { userId }, 'data-subject-rights');

  return apiResponse.success(res, { anonymized: true }, 'Personal data has been anonymized');
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { action } = req.query as { action?: string };
    if (action === 'export') return handleExport(req, res);
    return handleAccess(req, res);
  }

  if (req.method === 'POST') {
    const { action } = req.body as { action?: string };
    if (action === 'erasure') return handleErasure(req, res);
    return apiResponse.badRequest(res, 'Unknown action. Valid POST action: erasure');
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { generateCloseChecklist, checkCompleteness, buildCloseProgressSummary } from '@/modules/accounting/services/monthEndCloseService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { companyId } = req;
    const period = new Date().toISOString().slice(0, 7); // YYYY-MM
    const monthStart = `${period}-01`;
    const monthEnd = new Date(Number(period.split('-')[0]), Number(period.split('-')[1]), 0).toISOString().split('T')[0];

    // Query actual completion status from DB (with graceful fallbacks for missing tables)
    const safeCount = async (query: Promise<Row[]>) => {
      try { const rows = await query; return Number(rows[0]?.cnt ?? 0) > 0; }
      catch { return false; }
    };

    const [hasPayrollPosted, hasDepreciationRun, hasBankRecon, hasVATRecon, hasAccruals] = await Promise.all([
      safeCount(sql`SELECT COUNT(*) as cnt FROM payroll_runs WHERE company_id = ${companyId} AND status = 'completed' AND pay_date >= ${monthStart}::DATE AND pay_date <= ${monthEnd}::DATE` as Promise<Row[]>),
      safeCount(sql`SELECT COUNT(*) as cnt FROM gl_journal_entries WHERE company_id = ${companyId} AND source = 'auto_depreciation' AND entry_date >= ${monthStart}::DATE AND entry_date <= ${monthEnd}::DATE` as Promise<Row[]>),
      safeCount(sql`SELECT COUNT(*) as cnt FROM bank_reconciliations WHERE company_id = ${companyId} AND status = 'completed' AND statement_end_date >= ${monthStart}::DATE` as Promise<Row[]>),
      safeCount(sql`SELECT COUNT(*) as cnt FROM gl_journal_entries WHERE company_id = ${companyId} AND source = 'vat' AND entry_date >= ${monthStart}::DATE AND entry_date <= ${monthEnd}::DATE` as Promise<Row[]>),
      safeCount(sql`SELECT COUNT(*) as cnt FROM gl_journal_entries WHERE company_id = ${companyId} AND description ILIKE '%accrual%' AND entry_date >= ${monthStart}::DATE AND entry_date <= ${monthEnd}::DATE` as Promise<Row[]>),
    ]);

    const checklist = generateCloseChecklist('with_payroll');
    const completeness = checkCompleteness({ hasPayrollPosted, hasDepreciationRun, hasBankRecon, hasVATRecon, hasAccruals });
    const completedCount = [hasPayrollPosted, hasDepreciationRun, hasBankRecon, hasVATRecon, hasAccruals].filter(Boolean).length;
    const progress = buildCloseProgressSummary(completedCount, checklist.length, period);
    return apiResponse.success(res, { checklist, completeness, progress });
  }
  return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Asset Depreciation API
 * POST — run monthly depreciation for all eligible assets
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { postAssetDepreciationToGL } from '@/modules/accounting/services/glCrossModuleHooks';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { companyId } = req as CompanyApiRequest;
  const userId = String(req.user.id);

  // Find assets eligible for depreciation:
  // - Status = available or assigned (active assets)
  // - Has purchase_price and useful_life_years
  // - current_book_value > salvage_value
  const assets = (await sql`
    SELECT id, asset_number, name, purchase_price, useful_life_years,
           salvage_value, current_book_value, accumulated_depreciation
    FROM assets
    WHERE company_id = ${companyId}::UUID
      AND status IN ('available', 'assigned', 'in_maintenance')
      AND purchase_price IS NOT NULL
      AND purchase_price > 0
      AND useful_life_years IS NOT NULL
      AND useful_life_years > 0
      AND COALESCE(current_book_value, purchase_price) > COALESCE(salvage_value, 0)
  `) as Row[];

  let processed = 0;
  let skipped = 0;
  const results: { assetNumber: string; amount: number; entryId: string | null }[] = [];

  for (const asset of assets) {
    const purchasePrice = Number(asset.purchase_price);
    const salvageValue = Number(asset.salvage_value || 0);
    const usefulLifeYears = Number(asset.useful_life_years);
    const bookValue = Number(asset.current_book_value ?? purchasePrice);

    // Straight-line monthly depreciation
    const annualDepreciation = (purchasePrice - salvageValue) / usefulLifeYears;
    const monthlyDepreciation = Math.round((annualDepreciation / 12) * 100) / 100;

    // Don't depreciate below salvage value
    const maxDepreciation = Math.max(0, bookValue - salvageValue);
    const amount = Math.min(monthlyDepreciation, maxDepreciation);

    if (amount < 0.01) { skipped++; continue; }

    const entryId = await postAssetDepreciationToGL(companyId, String(asset.id), amount, userId);
    results.push({ assetNumber: String(asset.asset_number), amount, entryId });
    processed++;
  }

  log.info('Depreciation run completed', { processed, skipped, total: assets.length }, 'accounting');

  return apiResponse.success(res, {
    processed,
    skipped,
    total: assets.length,
    results,
  });
}

