/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';
type Row = any;


export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id}`) as Row[]; // NOTE: id-only lookup used internally — callers must ensure companyId scoping
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Cross-Module GL Integration Hooks
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccountId } from './systemAccountResolver';
type Row = any;


// ── Asset Depreciation → GL ────────────────────────────────────────────────

export async function postAssetDepreciationToGL(
  companyId: string,
  assetId: string,
  depreciationAmount: number,
  userId: string
): Promise<string | null> {
  try {
    if (depreciationAmount <= 0) return null;

    const asset = (await sql`
      SELECT id, asset_number, name FROM assets WHERE id = ${assetId}
    `) as Row[];

    if (!asset[0]) {
      log.warn('Asset not found for depreciation GL', { assetId }, 'accounting');
      return null;
    }

    const depExpenseId = await getSystemAccountId('depreciation_expense');
    const accumDepId = await getSystemAccountId('accumulated_depreciation');

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${companyId}, ${`DEP-${asset[0].asset_number}-${new Date().toISOString().slice(0, 7)}`}, CURRENT_DATE,
        ${`Depreciation: ${asset[0].name} (${asset[0].asset_number})`},
        'auto_depreciation', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${depExpenseId}::UUID, ${depreciationAmount}, 0,
        ${`Depreciation: ${asset[0].asset_number}`})
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${accumDepId}::UUID, 0, ${depreciationAmount},
        ${`Depreciation: ${asset[0].asset_number}`})
    `;

    await sql`
      UPDATE assets SET
        accumulated_depreciation = COALESCE(accumulated_depreciation, 0) + ${depreciationAmount},
        current_book_value = COALESCE(purchase_price, 0) - (COALESCE(accumulated_depreciation, 0) + ${depreciationAmount}),
        updated_at = NOW()
      WHERE id = ${assetId}
    `;

    log.info('Asset depreciation GL posted', { assetId, entryId, depreciationAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post asset depreciation to GL', { assetId, error: err }, 'accounting');
    return null;
  }
}

/**
 * GL Import Service — WS-6.3 Excel Import Wizard
 * Validates and imports journal entries from spreadsheet uploads.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VatType } from '../types/gl.types';
type Row = any;


export interface ImportRow {
  date: string;          // YYYY-MM-DD
  accountCode: string;   // Must exist in gl_accounts for this company
  description: string;
  reference?: string;
  debit: number;
  credit: number;
  vatCode?: string;
  costCentre?: string;
}

export interface ValidationResult {
  row: number;
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface ValidationSummary {
  validations: ValidationResult[];
  validCount: number;
  errorCount: number;
  warningCount: number;
  totalDebit: number;
  totalCredit: number;
  isBalanced: boolean;
}

export interface ImportResult {
  entriesCreated: number;
  linesCreated: number;
  totalValue: number;
}

const VALID_VAT_CODES: VatType[] = [
  'standard', 'zero_rated', 'exempt', 'capital_goods',
  'export', 'imported', 'reverse_charge', 'bad_debt', 'no_vat',
];

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d;
}

export async function validateImportRows(
  companyId: string,
  rows: ImportRow[],
): Promise<ValidationSummary> {
  try {
    // Load chart of accounts for this company
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load open fiscal periods
    const periodRows = (await sql`
      SELECT start_date, end_date
      FROM fiscal_periods
      WHERE company_id = ${companyId}::UUID
        AND status = 'open'
      ORDER BY start_date
    `) as Row[];

    // Load cost centres
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccSet = new Set<string>(ccRows.map((r: Row) => String(r.code).toLowerCase()));

    const validations: ValidationResult[] = [];
    let totalDebit = 0;
    let totalCredit = 0;
    let validCount = 0;
    let errorCount = 0;
    let warningCount = 0;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]!;
      const errors: string[] = [];
      const warnings: string[] = [];
      const rowNum = i + 2; // 1-indexed + header row

      // Description required
      if (!row.description || row.description.trim() === '') {
        errors.push('Description is required');
      }

      // Date validation
      const parsedDate = parseDate(row.date);
      if (!parsedDate) {
        errors.push(`Invalid date: "${row.date}" — expected YYYY-MM-DD`);
      } else {
        // Check if date falls within an open fiscal period
        const inOpenPeriod = periodRows.some((p: Row) => {
          const start = new Date(p.start_date);
          const end = new Date(p.end_date);
          return parsedDate >= start && parsedDate <= end;
        });
        if (!inOpenPeriod) {
          warnings.push(`Date ${row.date} does not fall within an open fiscal period`);
        }
      }

      // Account code validation
      if (!row.accountCode || row.accountCode.trim() === '') {
        errors.push('Account code is required');
      } else if (!accountMap.has(String(row.accountCode).trim())) {
        errors.push(`Account code "${row.accountCode}" not found in chart of accounts`);
      }

      // Debit / credit validation
      const debit = Number(row.debit) || 0;
      const credit = Number(row.credit) || 0;

      if (debit < 0) errors.push('Debit cannot be negative');
      if (credit < 0) errors.push('Credit cannot be negative');

      if (debit > 0 && credit > 0) {
        errors.push('Debit and credit cannot both be greater than zero on the same line');
      }
      if (debit === 0 && credit === 0) {
        errors.push('At least one of debit or credit must be greater than zero');
      }

      // VAT code validation (optional)
      if (row.vatCode && row.vatCode.trim() !== '') {
        const code = row.vatCode.trim() as VatType;
        if (!VALID_VAT_CODES.includes(code)) {
          errors.push(
            `Invalid VAT code "${row.vatCode}". Valid codes: ${VALID_VAT_CODES.join(', ')}`,
          );
        }
      }

      // Cost centre validation (optional)
      if (row.costCentre && row.costCentre.trim() !== '') {
        if (!ccSet.has(row.costCentre.trim().toLowerCase())) {
          warnings.push(`Cost centre "${row.costCentre}" not found — will be ignored`);
        }
      }

      const valid = errors.length === 0;
      if (valid) {
        validCount++;
        totalDebit += debit;
        totalCredit += credit;
      } else {
        errorCount++;
      }
      if (warnings.length > 0) warningCount++;

      validations.push({ row: rowNum, valid, errors, warnings });
    }

    // For balanced check, only consider valid rows
    const diff = Math.abs(totalDebit - totalCredit);
    const isBalanced = diff < 0.005; // tolerance for floating point

    return {
      validations,
      validCount,
      errorCount,
      warningCount,
      totalDebit,
      totalCredit,
      isBalanced,
    };
  } catch (err) {
    log.error('Failed to validate import rows', { error: err }, 'gl-import');
    throw err;
  }
}

export async function importJournalEntries(
  companyId: string,
  rows: ImportRow[],
  userId: string,
  postImmediately: boolean,
): Promise<ImportResult> {
  try {
    // Load account code → id mapping
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load cost centre code → id mapping
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccMap = new Map<string, string>(
      ccRows.map((r: Row) => [String(r.code).toLowerCase(), String(r.id)]),
    );

    // Group rows into journal entries: same date + same reference = one entry
    const grouped = new Map<string, ImportRow[]>();
    for (const row of rows) {
      const key = `${row.date}||${row.reference || ''}`;
      const group = grouped.get(key) ?? [];
      group.push(row);
      grouped.set(key, group);
    }

    let entriesCreated = 0;
    let linesCreated = 0;
    let totalValue = 0;
    const status = postImmediately ? 'posted' : 'draft';

    for (const [, groupRows] of grouped) {
      const firstRow = groupRows[0]!;

      // Find fiscal period for entry date
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE company_id = ${companyId}::UUID
          AND start_date <= ${firstRow.date}::DATE
          AND end_date >= ${firstRow.date}::DATE
        LIMIT 1
      `) as Row[];
      const fiscalPeriodId = periodRows.length > 0 ? String(periodRows[0].id) : null;

      const description = firstRow.reference
        ? `${firstRow.reference}: ${firstRow.description}`
        : firstRow.description;

      const postedBy = postImmediately ? userId : null;

      const entryInsert = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, fiscal_period_id, description,
          source, created_by, status,
          posted_by, posted_at
        ) VALUES (
          ${companyId}::UUID,
          ${firstRow.date}::DATE,
          ${fiscalPeriodId}::UUID,
          ${description},
          'import',
          ${userId}::UUID,
          ${status},
          ${postedBy}::UUID,
          ${postImmediately ? sql`NOW()` : sql`NULL`}
        )
        RETURNING id
      `) as Row[];

      const entryId = String(entryInsert[0].id);
      entriesCreated++;

      for (const row of groupRows) {
        const accountId = accountMap.get(String(row.accountCode).trim());
        if (!accountId) continue; // already validated upstream

        const ccId = row.costCentre
          ? (ccMap.get(row.costCentre.trim().toLowerCase()) ?? null)
          : null;

        const vatType = (row.vatCode?.trim() as VatType) || null;

        await sql`
          INSERT INTO gl_journal_lines (
            journal_entry_id, gl_account_id, debit, credit,
            description, vat_type, cost_center_id
          ) VALUES (
            ${entryId}::UUID,
            ${accountId}::UUID,
            ${Number(row.debit) || 0},
            ${Number(row.credit) || 0},
            ${row.description},
            ${vatType},
            ${ccId}::UUID
          )
        `;

        linesCreated++;
        totalValue += Number(row.debit) || 0;
      }
    }

    log.info('Imported journal entries', {
      companyId, entriesCreated, linesCreated, totalValue, postImmediately,
    }, 'gl-import');

    return { entriesCreated, linesCreated, totalValue };
  } catch (err) {
    log.error('Failed to import journal entries', { error: err }, 'gl-import');
    throw err;
  }
}

/**
 * Item Service — CRUD for inventory / service items
 * All queries are scoped to company_id for multi-tenant safety.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = any;


export interface ItemFilters {
  q?: string;
  type?: 'physical' | 'service';
  active?: 'true' | 'false';
  category_id?: string;
}

export interface CreateItemInput {
  code?: string;
  description: string;
  item_type?: string;
  category_id?: string | null;
  is_active?: boolean;
  unit?: string;
  cost_price?: number;
  selling_price_excl?: number;
  selling_price_incl?: number;
  gp_percent?: number;
  vat_on_sales?: string;
  vat_on_purchases?: string;
  sales_account_id?: string | null;
  purchases_account_id?: string | null;
  opening_qty?: number;
  opening_cost?: number;
  opening_date?: string | null;
  notes?: string | null;
  image_url?: string | null;
}

export interface UpdateItemInput {
  id: string;
  code?: string;
  description?: string;
  item_type?: string;
  category_id?: string;
  is_active?: boolean;
  unit?: string;
  cost_price?: number;
  selling_price_excl?: number;
  selling_price_incl?: number;
  gp_percent?: number;
  vat_on_sales?: string;
  vat_on_purchases?: string;
  sales_account_id?: string;
  purchases_account_id?: string;
  opening_qty?: number;
  opening_cost?: number;
  opening_date?: string;
  current_qty?: number;
  notes?: string;
  image_url?: string;
}

// ── Queries ───────────────────────────────────────────────────────────────────

export async function getItem(companyId: string, itemId: string): Promise<Row | null> {
  const rows = await sql`
    SELECT i.*, ic.name AS category_name
    FROM items i
    LEFT JOIN item_categories ic ON i.category_id = ic.id
    WHERE i.id = ${itemId} AND i.company_id = ${companyId}
    LIMIT 1
  ` as Row[];
  return rows[0] ?? null;
}

export async function listItems(companyId: string, filters: ItemFilters = {}): Promise<Row[]> {
  const { q, type, active, category_id } = filters;

  // Validate and build safe extra conditions (all values are validated before use)
  const extraParts: string[] = [];

  if (type === 'physical' || type === 'service') {
    // type is a validated enum — safe to embed
    extraParts.push(`AND i.item_type = '${type}'`);
  }

  if (active === 'true') {
    extraParts.push('AND i.is_active = true');
  } else if (active === 'false') {
    extraParts.push('AND i.is_active = false');
  }

  const extraSql = extraParts.join(' ');

  // Branch on the two parameterised filter dimensions (search term + category_id)
  // using sql.unsafe only for pre-validated, non-user-interpolated fragments.
  if (q && category_id) {
    const term = `%${q}%`;
    return sql`
      SELECT i.*, ic.name AS category_name
      FROM items i LEFT JOIN item_categories ic ON i.category_id = ic.id
      WHERE i.company_id = ${companyId}
        AND i.deleted_at IS NULL
        AND (i.code ILIKE ${term} OR i.description ILIKE ${term})
        AND i.category_id = ${category_id}::UUID
        ${sql.unsafe(extraSql)}
      ORDER BY i.code ASC LIMIT 500
    ` as Promise<Row[]>;
  }

  if (q) {
    const term = `%${q}%`;
    return sql`
      SELECT i.*, ic.name AS category_name
      FROM items i LEFT JOIN item_categories ic ON i.category_id = ic.id
      WHERE i.company_id = ${companyId}
        AND i.deleted_at IS NULL
        AND (i.code ILIKE ${term} OR i.description ILIKE ${term})
        ${sql.unsafe(extraSql)}
      ORDER BY i.code ASC LIMIT 500
    ` as Promise<Row[]>;
  }

  if (category_id) {
    return sql`
      SELECT i.*, ic.name AS category_name
      FROM items i LEFT JOIN item_categories ic ON i.category_id = ic.id
      WHERE i.company_id = ${companyId}
        AND i.deleted_at IS NULL
        AND i.category_id = ${category_id}::UUID
        ${sql.unsafe(extraSql)}
      ORDER BY i.code ASC LIMIT 500
    ` as Promise<Row[]>;
  }

  return sql`
    SELECT i.*, ic.name AS category_name
    FROM items i LEFT JOIN item_categories ic ON i.category_id = ic.id
    WHERE i.company_id = ${companyId}
      AND i.deleted_at IS NULL
      ${sql.unsafe(extraSql)}
    ORDER BY i.code ASC LIMIT 500
  ` as Promise<Row[]>;
}

// ── Validation helpers ────────────────────────────────────────────────────────

async function generateItemCode(companyId: string): Promise<string> {
  const countRows = await sql`
    SELECT COUNT(*)::int AS cnt FROM items WHERE company_id = ${companyId}
  ` as Row[];
  const nextNum = (Number((countRows[0] as Row)?.cnt) || 0) + 1;
  return `ITEM-${String(nextNum).padStart(4, '0')}`;
}

export async function checkCodeDuplicate(
  companyId: string,
  code: string,
  excludeId?: string
): Promise<boolean> {
  if (excludeId) {
    const rows = await sql`
      SELECT id FROM items
      WHERE company_id = ${companyId} AND code = ${code} AND id != ${excludeId}
      LIMIT 1
    ` as Row[];
    return rows.length > 0;
  }
  const rows = await sql`
    SELECT id FROM items WHERE company_id = ${companyId} AND code = ${code} LIMIT 1
  ` as Row[];
  return rows.length > 0;
}

// ── Mutations ─────────────────────────────────────────────────────────────────

export async function createItem(companyId: string, input: CreateItemInput): Promise<Row> {
  const code = input.code?.trim() || (await generateItemCode(companyId));
  const itemType = input.item_type || 'physical';
  const categoryId = input.category_id ?? null;
  const salesAccountId = input.sales_account_id ?? null;
  const purchasesAccountId = input.purchases_account_id ?? null;
  const costPrice = input.cost_price ?? 0;
  const sellingPriceExcl = input.selling_price_excl ?? 0;
  const sellingPriceIncl = input.selling_price_incl ?? 0;
  const gpPercent = input.gp_percent ?? 0;
  const openingQty = input.opening_qty ?? 0;
  const openingCost = input.opening_cost ?? 0;
  const openingDate = input.opening_date ?? null;
  const isActive = input.is_active !== false;
  const unit = input.unit || 'each';
  const vatOnSales = input.vat_on_sales || 'standard';
  const vatOnPurchases = input.vat_on_purchases || 'standard';
  const notes = input.notes ?? null;
  const imageUrl = input.image_url ?? null;

  const inserted = await sql`
    INSERT INTO items (
      company_id, code, description, item_type, category_id, is_active,
      unit, cost_price, selling_price_excl, selling_price_incl, gp_percent,
      vat_on_sales, vat_on_purchases, sales_account_id, purchases_account_id,
      opening_qty, opening_cost, opening_date, current_qty, notes, image_url
    ) VALUES (
      ${companyId}, ${code}, ${input.description}, ${itemType},
      ${categoryId}::UUID, ${isActive}, ${unit},
      ${costPrice}, ${sellingPriceExcl}, ${sellingPriceIncl}, ${gpPercent},
      ${vatOnSales}, ${vatOnPurchases},
      ${salesAccountId}::UUID, ${purchasesAccountId}::UUID,
      ${openingQty}, ${openingCost}, ${openingDate},
      ${openingQty}, ${notes}, ${imageUrl}
    ) RETURNING *
  ` as Row[];

  log.info('Item created', { code, description: input.description, companyId }, 'accounting');
  return inserted[0];
}

export async function updateItem(companyId: string, input: UpdateItemInput): Promise<Row> {
  const { id } = input;

  const updated = await sql`
    UPDATE items SET
      code               = COALESCE(${input.code !== undefined ? String(input.code) : null}, code),
      description        = COALESCE(${input.description !== undefined ? String(input.description) : null}, description),
      item_type          = COALESCE(${input.item_type !== undefined ? String(input.item_type) : null}, item_type),
      category_id        = COALESCE(${input.category_id !== undefined ? String(input.category_id) : null}::UUID, category_id),
      is_active          = COALESCE(${input.is_active !== undefined ? Boolean(input.is_active) : null}, is_active),
      unit               = COALESCE(${input.unit !== undefined ? String(input.unit) : null}, unit),
      cost_price         = COALESCE(${input.cost_price !== undefined ? Number(input.cost_price) : null}, cost_price),
      selling_price_excl = COALESCE(${input.selling_price_excl !== undefined ? Number(input.selling_price_excl) : null}, selling_price_excl),
      selling_price_incl = COALESCE(${input.selling_price_incl !== undefined ? Number(input.selling_price_incl) : null}, selling_price_incl),
      gp_percent         = COALESCE(${input.gp_percent !== undefined ? Number(input.gp_percent) : null}, gp_percent),
      vat_on_sales       = COALESCE(${input.vat_on_sales !== undefined ? String(input.vat_on_sales) : null}, vat_on_sales),
      vat_on_purchases   = COALESCE(${input.vat_on_purchases !== undefined ? String(input.vat_on_purchases) : null}, vat_on_purchases),
      sales_account_id   = COALESCE(${input.sales_account_id !== undefined ? String(input.sales_account_id) : null}::UUID, sales_account_id),
      purchases_account_id = COALESCE(${input.purchases_account_id !== undefined ? String(input.purchases_account_id) : null}::UUID, purchases_account_id),
      opening_qty        = COALESCE(${input.opening_qty !== undefined ? Number(input.opening_qty) : null}, opening_qty),
      opening_cost       = COALESCE(${input.opening_cost !== undefined ? Number(input.opening_cost) : null}, opening_cost),
      opening_date       = COALESCE(${input.opening_date !== undefined ? String(input.opening_date) : null}, opening_date),
      current_qty        = COALESCE(${input.current_qty !== undefined ? Number(input.current_qty) : null}, current_qty),
      notes              = COALESCE(${input.notes !== undefined ? String(input.notes) : null}, notes),
      image_url          = COALESCE(${input.image_url !== undefined ? String(input.image_url) : null}, image_url),
      updated_at         = NOW()
    WHERE id = ${id} AND company_id = ${companyId}
    RETURNING *
  ` as Row[];

  log.info('Item updated', { id, companyId }, 'accounting');
  return updated[0];
}

export async function softDeleteItem(companyId: string, itemId: string): Promise<void> {
  await sql`
    UPDATE items SET is_active = false, updated_at = NOW()
    WHERE id = ${itemId} AND company_id = ${companyId}
  `;
  log.info('Item soft-deleted', { id: itemId, companyId }, 'accounting');
}

export async function itemExists(companyId: string, itemId: string): Promise<boolean> {
  const rows = await sql`
    SELECT id FROM items WHERE id = ${itemId} AND company_id = ${companyId} LIMIT 1
  ` as Row[];
  return rows.length > 0;
}

/**
 * Client Portal Service
 * Customer-facing self-service: view invoices, download statements, payment links.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import bcrypt from 'bcryptjs';
type Row = any;


// ── Types ────────────────────────────────────────────────────────────────────

export interface PortalUser {
  id: string;
  clientId: string;
  email: string;
  name: string;
  isActive: boolean;
  lastLoginAt: string | null;
}

export interface PortalInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string;
  total: number;
  amountPaid: number;
  balance: number;
  status: string;
}

export interface PortalStatement {
  clientName: string;
  clientEmail: string;
  asOfDate: string;
  openingBalance: number;
  transactions: Array<{
    date: string;
    reference: string;
    description: string;
    debit: number;
    credit: number;
    balance: number;
  }>;
  closingBalance: number;
}

// ── Portal Auth ──────────────────────────────────────────────────────────────

export async function createPortalUser(input: {
  clientId: string;
  email: string;
  password: string;
  name: string;
}): Promise<PortalUser> {
  const hash = await bcrypt.hash(input.password, 12);
  const rows = (await sql`
    INSERT INTO portal_access (client_id, email, password_hash, name)
    VALUES (${input.clientId}::UUID, ${input.email}, ${hash}, ${input.name})
    RETURNING *
  `) as Row[];
  log.info('Portal user created', { email: input.email }, 'portal');
  return mapPortalUser(rows[0]);
}

export async function authenticatePortalUser(email: string, password: string): Promise<PortalUser | null> {
  const rows = (await sql`
    SELECT * FROM portal_access WHERE email = ${email} AND is_active = true
  `) as Row[];
  if (!rows[0]) return null;

  const valid = await bcrypt.compare(password, rows[0].password_hash);
  if (!valid) return null;

  await sql`UPDATE portal_access SET last_login_at = NOW() WHERE id = ${rows[0].id}::UUID`;
  return mapPortalUser(rows[0]);
}

export async function listPortalUsers(clientId?: string): Promise<PortalUser[]> {
  const rows = clientId
    ? (await sql`SELECT * FROM portal_access WHERE client_id = ${clientId}::UUID ORDER BY name`) as Row[]
    : (await sql`SELECT * FROM portal_access ORDER BY name`) as Row[];
  return rows.map(mapPortalUser);
}

// ── Portal Data ──────────────────────────────────────────────────────────────

export async function getClientInvoices(clientId: string): Promise<PortalInvoice[]> {
  const rows = (await sql`
    SELECT id, invoice_number, invoice_date, due_date, total,
           COALESCE(amount_paid, 0) AS amount_paid,
           (total - COALESCE(amount_paid, 0)) AS balance,
           status
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID
      AND status NOT IN ('draft', 'cancelled')
    ORDER BY invoice_date DESC
  `) as Row[];

  return rows.map((r: Row) => ({
    id: r.id,
    invoiceNumber: r.invoice_number,
    invoiceDate: r.invoice_date,
    dueDate: r.due_date,
    total: Number(r.total),
    amountPaid: Number(r.amount_paid),
    balance: Number(r.balance),
    status: r.status,
  }));
}

export async function getClientStatement(clientId: string, asOfDate: string): Promise<PortalStatement> {
  // Get client info
  const clients = (await sql`SELECT name, email FROM customers WHERE id = ${clientId}::UUID`) as Row[];
  const client = clients[0] || { name: 'Unknown', email: '' };

  // Get all transactions for this client
  const rows = (await sql`
    SELECT invoice_date AS date, invoice_number AS reference,
           'Invoice' AS description, total AS debit, 0 AS credit
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID AND status NOT IN ('draft', 'cancelled')
      AND invoice_date <= ${asOfDate}::DATE
    UNION ALL
    SELECT payment_date AS date, reference AS reference,
           'Payment' AS description, 0 AS debit, amount AS credit
    FROM customer_payments
    WHERE client_id = ${clientId}::UUID AND status = 'posted'
      AND payment_date <= ${asOfDate}::DATE
    ORDER BY date ASC
  `) as Row[];

  let runningBalance = 0;
  const transactions = rows.map((r: Row) => {
    const debit = Number(r.debit);
    const credit = Number(r.credit);
    runningBalance += debit - credit;
    return {
      date: r.date,
      reference: r.reference || '',
      description: r.description,
      debit,
      credit,
      balance: runningBalance,
    };
  });

  return {
    clientName: client.name,
    clientEmail: client.email || '',
    asOfDate,
    openingBalance: 0,
    transactions,
    closingBalance: runningBalance,
  };
}

// ── Payment Links ────────────────────────────────────────────────────────────

export async function createPaymentLink(invoiceId: string, clientId: string, amount: number): Promise<string> {
