const PAYFAST_LIVE_URL = 'https://www.payfast.co.za/eng/process';

// PayFast valid IP ranges (production)
const PAYFAST_IP_RANGES = [
  '197.97.145.144/28',
  '41.74.179.192/27',
  '196.12.62.128/27',
];

// Sandbox allows any IP, but we still check in production
const PAYFAST_SANDBOX_IPS = ['127.0.0.1', '::1'];

function getConfig() {
  return {
    merchantId: process.env.PAYFAST_MERCHANT_ID || '',
    merchantKey: process.env.PAYFAST_MERCHANT_KEY || '',
    passphrase: process.env.PAYFAST_PASSPHRASE || '',
    isSandbox: process.env.PAYFAST_SANDBOX === 'true',
  };
}

function getPayFastUrl(): string {
  return getConfig().isSandbox ? PAYFAST_SANDBOX_URL : PAYFAST_LIVE_URL;
}

// ── Signature Generation ────────────────────────────────────────────────────

function generateSignature(data: Record<string, string>, passphrase: string): string {
  // Sort keys alphabetically, exclude blank values and 'signature' key
  const sortedKeys = Object.keys(data)
    .filter(k => k !== 'signature' && data[k] !== '' && data[k] !== undefined && data[k] !== null)
    .sort();

  const queryString = sortedKeys
    .map(k => `${k}=${encodeURIComponent(data[k]!).replace(/%20/g, '+')}`)
    .join('&');

  const toHash = passphrase ? `${queryString}&passphrase=${encodeURIComponent(passphrase).replace(/%20/g, '+')}` : queryString;

  return crypto.createHash('md5').update(toHash).digest('hex');
}

// ── IP Validation ───────────────────────────────────────────────────────────

function ipInCidr(ip: string, cidr: string): boolean {
  const [range, bitsStr] = cidr.split('/');
  if (!range || !bitsStr) return false;
  const bits = parseInt(bitsStr, 10);

  const ipParts = ip.split('.').map(Number);
  const rangeParts = range.split('.').map(Number);

  const ipNum = ((ipParts[0]! << 24) | (ipParts[1]! << 16) | (ipParts[2]! << 8) | ipParts[3]!) >>> 0;
  const rangeNum = ((rangeParts[0]! << 24) | (rangeParts[1]! << 16) | (rangeParts[2]! << 8) | rangeParts[3]!) >>> 0;
  const mask = (~0 << (32 - bits)) >>> 0;

  return (ipNum & mask) === (rangeNum & mask);
}

function isPayFastIp(ip: string): boolean {
  const config = getConfig();
  if (config.isSandbox) return true; // Sandbox mode: accept any IP

  // Strip IPv6 prefix
  const cleanIp = ip.startsWith('::ffff:') ? ip.slice(7) : ip;

  for (const cidr of PAYFAST_IP_RANGES) {
    if (ipInCidr(cleanIp, cidr)) return true;
  }
  return PAYFAST_SANDBOX_IPS.includes(cleanIp);
}

// ── Public Functions ────────────────────────────────────────────────────────

export interface PayFastFormData {
  paymentUrl: string;
  fields: Record<string, string>;
  transactionId: string;
}

/**
 * Generate PayFast payment form data for an invoice.
 */
export async function generatePayFastForm(
  companyId: string,
  invoiceId: string,
  returnUrl: string,
  cancelUrl: string,
  notifyUrl: string,
): Promise<PayFastFormData> {
  const config = getConfig();
  if (!config.merchantId || !config.merchantKey) {
    throw new Error('PayFast merchant credentials not configured');
  }

  // Look up invoice details
  const invoices = (await sql`
    SELECT ci.id, ci.invoice_number, ci.total_amount, ci.amount_paid,
           ci.client_name, ci.status,
           c.email AS client_email
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Invoice not found');

  const inv = invoices[0];
  const balance = Number(inv.total_amount) - Number(inv.amount_paid || 0);
  if (balance <= 0) throw new Error('Invoice is already fully paid');

  // Create payment transaction record
  const txRows = (await sql`
    INSERT INTO payment_transactions (company_id, invoice_id, gateway, amount, currency, customer_email, customer_name, status)
    VALUES (${companyId}::UUID, ${invoiceId}::UUID, 'payfast', ${balance}, 'ZAR', ${inv.client_email || ''}, ${inv.client_name || ''}, 'pending')
    RETURNING id
  `) as Row[];

  const transactionId = txRows[0].id as string;

  // Build PayFast form fields
  const fields: Record<string, string> = {
    merchant_id: config.merchantId,
    merchant_key: config.merchantKey,
    return_url: returnUrl,
    cancel_url: cancelUrl,
    notify_url: notifyUrl,
    m_payment_id: transactionId,
    amount: balance.toFixed(2),
    item_name: `Invoice ${inv.invoice_number}`.slice(0, 100),
    item_description: `Payment for invoice ${inv.invoice_number}`.slice(0, 255),
  };

  // Add customer email if available
  if (inv.client_email) {
    fields.email_address = inv.client_email;
  }

  // Add customer name if available
  if (inv.client_name) {
    const nameParts = (inv.client_name as string).split(' ');
    fields.name_first = (nameParts[0] || '').slice(0, 100);
    fields.name_last = (nameParts.slice(1).join(' ') || '').slice(0, 100);
  }

  // Generate signature
  fields.signature = generateSignature(fields, config.passphrase);

  log.info('PayFast form generated', { transactionId, invoiceId, amount: balance }, 'PaymentGateway');

  return {
    paymentUrl: getPayFastUrl(),
    fields,
    transactionId,
  };
}

/**
 * Handle PayFast ITN (Instant Transaction Notification).
 * Validates the notification and updates payment status.
 */
export async function handleITN(
  body: Record<string, string>,
  sourceIp: string,
): Promise<{ valid: boolean; transactionId: string | null }> {
  const config = getConfig();

  // 1. Verify source IP
  if (!isPayFastIp(sourceIp)) {
    log.error('ITN rejected: invalid source IP', { sourceIp }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 2. Verify signature
  const receivedSignature = body.signature;
  if (!receivedSignature) {
    log.error('ITN rejected: no signature', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const dataForSig = { ...body };
  delete dataForSig.signature;
  const expectedSignature = generateSignature(dataForSig, config.passphrase);

  if (receivedSignature !== expectedSignature) {
    log.error('ITN rejected: signature mismatch', { received: receivedSignature, expected: expectedSignature }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const transactionId = body.m_payment_id || null;
  if (!transactionId) {
    log.error('ITN rejected: no m_payment_id', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 3. Look up the transaction
  const txRows = (await sql`
    SELECT id, company_id, invoice_id, amount, status
    FROM payment_transactions WHERE id = ${transactionId}::UUID
  `) as Row[];

  if (!txRows[0]) {
    log.error('ITN rejected: transaction not found', { transactionId }, 'PaymentGateway');
    return { valid: false, transactionId };
  }

  const tx = txRows[0];

  // 4. Verify amount matches
  const itnAmount = parseFloat(body.amount_gross || '0');
  const expectedAmount = Number(tx.amount);
  if (Math.abs(itnAmount - expectedAmount) > 0.01) {
    log.error('ITN rejected: amount mismatch', { expected: expectedAmount, received: itnAmount }, 'PaymentGateway');
    await sql`
      UPDATE payment_transactions SET status = 'failed', error_message = 'Amount mismatch', updated_at = NOW()
      WHERE id = ${transactionId}::UUID
    `;
    return { valid: false, transactionId };
  }

  // 5. Map PayFast status to our status
  const pfStatus = (body.payment_status || '').toUpperCase();
  let newStatus: string;
  switch (pfStatus) {
    case 'COMPLETE':
      newStatus = 'completed';
      break;
    case 'FAILED':
      newStatus = 'failed';
      break;
    case 'PENDING':
      newStatus = 'processing';
      break;
    case 'CANCELLED':
      newStatus = 'cancelled';
      break;
    default:
      newStatus = 'processing';
  }

  // 6. Update transaction
  await sql`
    UPDATE payment_transactions
    SET status = ${newStatus},
        gateway_ref = ${body.pf_payment_id || ''},
        payment_method = ${body.payment_method || ''},
        paid_at = ${newStatus === 'completed' ? new Date().toISOString() : null},
        metadata = ${JSON.stringify(body)}::JSONB,
        updated_at = NOW()
    WHERE id = ${transactionId}::UUID
  `;

  // 7. If completed, update the invoice
  if (newStatus === 'completed' && tx.invoice_id) {
    await sql`
      UPDATE customer_invoices
      SET amount_paid = COALESCE(amount_paid, 0) + ${itnAmount},
          status = CASE
            WHEN COALESCE(amount_paid, 0) + ${itnAmount} >= total_amount THEN 'paid'
            ELSE 'partially_paid'
          END,
          updated_at = NOW()
      WHERE id = ${tx.invoice_id}::UUID AND company_id = ${tx.company_id}::UUID
    `;

    log.info('Invoice payment recorded via PayFast', {
      transactionId, invoiceId: tx.invoice_id, amount: itnAmount, status: 'completed',
    }, 'PaymentGateway');
  }

  log.info('ITN processed', { transactionId, pfStatus, newStatus }, 'PaymentGateway');
  return { valid: true, transactionId };
}

/**
 * Get payment transaction details.
 */
export async function getPaymentStatus(companyId: string, transactionId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE id = ${transactionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];

  if (!rows[0]) return null;
  return mapTransaction(rows[0]);
}

/**
 * List all payment attempts for an invoice.
 */
export async function getInvoicePayments(companyId: string, invoiceId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE invoice_id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
  `) as Row[];

  return rows.map(mapTransaction);
}

/**
 * Enable online payment for an invoice and generate a payment URL.
 */
export async function enableOnlinePayment(companyId: string, invoiceId: string): Promise<string> {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';

  // Create a portal payment link token for public access
  const linkRows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    SELECT ci.id, ci.client_id, ci.total_amount - COALESCE(ci.amount_paid, 0)
    FROM customer_invoices ci
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
    RETURNING token
  `) as Row[];

  if (!linkRows[0]) throw new Error('Invoice not found or no balance due');

  const token = linkRows[0].token as string;
  const paymentUrl = `${appUrl}/portal/pay/${token}`;

  // Store the payment URL and enable online payments on the invoice
  await sql`
    UPDATE customer_invoices
    SET online_payment_enabled = true, payment_url = ${paymentUrl}, updated_at = NOW()
    WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
  `;

  log.info('Online payment enabled', { invoiceId, paymentUrl }, 'PaymentGateway');
  return paymentUrl;
}

// ── Mapper ──────────────────────────────────────────────────────────────────

interface PaymentTransaction {
  id: string;
  companyId: string;
  invoiceId: string | null;
  gateway: string;
  gatewayRef: string | null;
  amount: number;
  currency: string;
  status: string;
  customerEmail: string | null;
  customerName: string | null;
  paymentMethod: string | null;
  metadata: Record<string, unknown>;
  errorMessage: string | null;
  paidAt: string | null;
  createdAt: string;
  updatedAt: string;
}

function mapTransaction(r: Row): PaymentTransaction {
  return {
    id: r.id,
    companyId: r.company_id,
    invoiceId: r.invoice_id,
    gateway: r.gateway,
    gatewayRef: r.gateway_ref,
    amount: Number(r.amount),
    currency: r.currency,
    status: r.status,
    customerEmail: r.customer_email,
    customerName: r.customer_name,
    paymentMethod: r.payment_method,
    metadata: r.metadata || {},
    errorMessage: r.error_message,
    paidAt: r.paid_at,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import { validatePaymentAllocations } from '../utils/paymentAllocation';
import type {
  SupplierPayment,
  PaymentAllocation,
  PaymentAllocationInput,
  PaymentMethod,
  PaymentStatus,
  InvoiceForAllocation,
} from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = any;


interface PaymentFilters {
  status?: PaymentStatus;
  supplierId?: number;
  limit?: number;
  offset?: number;
}

export interface CreatePaymentInput {
  supplierId: number;
  paymentDate: string;
  totalAmount: number;
  paymentMethod?: PaymentMethod;
  bankAccountId?: string;
  reference?: string;
  description?: string;
  allocations: PaymentAllocationInput[];
}

export async function getSupplierPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: SupplierPayment[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status} AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_payments`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierPaymentById(companyId: string, 
  id: string
): Promise<(SupplierPayment & { allocations: PaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT sp.*, s.name AS supplier_name
      FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
      WHERE sp.id = ${id}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT pa.*, si.invoice_number
      FROM payment_allocations pa
      LEFT JOIN supplier_invoices si ON si.id = pa.invoice_id
      WHERE pa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierPayment(companyId: string, 
  input: CreatePaymentInput,
  userId: string
): Promise<SupplierPayment> {
  try {
    // Load invoices for allocation validation
    const invoiceIds = input.allocations.map(a => a.invoiceId);
    const invoiceRows = (await sql`
      SELECT id, invoice_number, total_amount, amount_paid, balance
      FROM supplier_invoices
      WHERE id = ANY(${invoiceIds}::UUID[])
    `) as Row[];

    const invoices: InvoiceForAllocation[] = invoiceRows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const validation = validatePaymentAllocations(input.totalAmount, input.allocations, invoices);
    if (!validation.valid) {
      throw new Error(`Invalid allocations: ${validation.errors.join('; ')}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_payments (
          supplier_id, payment_date, total_amount, payment_method,
          bank_account_id, reference, description, created_by
        ) VALUES (
          ${input.supplierId}, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankAccountId || null},
          ${input.reference || null}, ${input.description || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier payment', {
      paymentId: String(paymentRow.id),
      paymentNumber: String(paymentRow.payment_number),
      totalAmount: input.totalAmount,
    }, 'accounting');

    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create supplier payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function processSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'approved') throw new Error(`Payment must be approved before processing`);

    // Auto-post GL entry: DR Accounts Payable, CR Bank
    const apAccount = await getSystemAccount('payable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT * FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');

    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      {
        glAccountId: apAccount.id,
        debit: payment.totalAmount,
        credit: 0,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
      {
        glAccountId: bankAccount.id || String(bankAccount.id),
        debit: 0,
        credit: payment.totalAmount,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
    ];

    const journalEntry = await createJournalEntry('', {
      entryDate: payment.paymentDate,
      description: `Supplier payment ${payment.paymentNumber}`,
      source: 'auto_supplier_payment',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry('', journalEntry.id, userId);

    // Update invoice balances and mark payment processed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}
        `;
        await tx`
          UPDATE supplier_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${alloc.invoiceId}
        `;
      }

      const rows = (await tx`
        UPDATE supplier_payments
        SET status = 'processed', processed_at = NOW(),
            gl_journal_entry_id = ${journalEntry.id}::UUID
        WHERE id = ${id}
        RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Processed supplier payment', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to process supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot approve payment with status: ${payment.status}`);

    const rows = (await sql`
      UPDATE supplier_payments
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW()
      WHERE id = ${id}
      RETURNING *
    `) as Row[];

    return mapPaymentRow(rows[0]!);
  } catch (err) {
    log.error('Failed to approve supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): SupplierPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    supplierId: String(row.supplier_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as SupplierPayment['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as SupplierPayment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    batchId: row.batch_id ? String(row.batch_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
  };
}

function mapAllocationRow(row: Row): PaymentAllocation {
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: Number(row.amount_allocated),
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
