/**
 * Client Portal Service
 * Customer-facing self-service: view invoices, download statements, payment links.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import bcrypt from 'bcryptjs';
type Row = any;


// ── Types ────────────────────────────────────────────────────────────────────

export interface PortalUser {
  id: string;
  clientId: string;
  email: string;
  name: string;
  isActive: boolean;
  lastLoginAt: string | null;
}

export interface PortalInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string;
  total: number;
  amountPaid: number;
  balance: number;
  status: string;
}

export interface PortalStatement {
  clientName: string;
  clientEmail: string;
  asOfDate: string;
  openingBalance: number;
  transactions: Array<{
    date: string;
    reference: string;
    description: string;
    debit: number;
    credit: number;
    balance: number;
  }>;
  closingBalance: number;
}

// ── Portal Auth ──────────────────────────────────────────────────────────────

export async function createPortalUser(input: {
  clientId: string;
  email: string;
  password: string;
  name: string;
}): Promise<PortalUser> {
  const hash = await bcrypt.hash(input.password, 12);
  const rows = (await sql`
    INSERT INTO portal_access (client_id, email, password_hash, name)
    VALUES (${input.clientId}::UUID, ${input.email}, ${hash}, ${input.name})
    RETURNING *
  `) as Row[];
  log.info('Portal user created', { email: input.email }, 'portal');
  return mapPortalUser(rows[0]);
}

export async function authenticatePortalUser(email: string, password: string): Promise<PortalUser | null> {
  const rows = (await sql`
    SELECT * FROM portal_access WHERE email = ${email} AND is_active = true
  `) as Row[];
  if (!rows[0]) return null;

  const valid = await bcrypt.compare(password, rows[0].password_hash);
  if (!valid) return null;

  await sql`UPDATE portal_access SET last_login_at = NOW() WHERE id = ${rows[0].id}::UUID`;
  return mapPortalUser(rows[0]);
}

export async function listPortalUsers(clientId?: string): Promise<PortalUser[]> {
  const rows = clientId
    ? (await sql`SELECT * FROM portal_access WHERE client_id = ${clientId}::UUID ORDER BY name`) as Row[]
    : (await sql`SELECT * FROM portal_access ORDER BY name`) as Row[];
  return rows.map(mapPortalUser);
}

// ── Portal Data ──────────────────────────────────────────────────────────────

export async function getClientInvoices(clientId: string): Promise<PortalInvoice[]> {
  const rows = (await sql`
    SELECT id, invoice_number, invoice_date, due_date, total,
           COALESCE(amount_paid, 0) AS amount_paid,
           (total - COALESCE(amount_paid, 0)) AS balance,
           status
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID
      AND status NOT IN ('draft', 'cancelled')
    ORDER BY invoice_date DESC
  `) as Row[];

  return rows.map((r: Row) => ({
    id: r.id,
    invoiceNumber: r.invoice_number,
    invoiceDate: r.invoice_date,
    dueDate: r.due_date,
    total: Number(r.total),
    amountPaid: Number(r.amount_paid),
    balance: Number(r.balance),
    status: r.status,
  }));
}

export async function getClientStatement(clientId: string, asOfDate: string): Promise<PortalStatement> {
  // Get client info
  const clients = (await sql`SELECT name, email FROM customers WHERE id = ${clientId}::UUID`) as Row[];
  const client = clients[0] || { name: 'Unknown', email: '' };

  // Get all transactions for this client
  const rows = (await sql`
    SELECT invoice_date AS date, invoice_number AS reference,
           'Invoice' AS description, total AS debit, 0 AS credit
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID AND status NOT IN ('draft', 'cancelled')
      AND invoice_date <= ${asOfDate}::DATE
    UNION ALL
    SELECT payment_date AS date, reference AS reference,
           'Payment' AS description, 0 AS debit, amount AS credit
    FROM customer_payments
    WHERE client_id = ${clientId}::UUID AND status = 'posted'
      AND payment_date <= ${asOfDate}::DATE
    ORDER BY date ASC
  `) as Row[];

  let runningBalance = 0;
  const transactions = rows.map((r: Row) => {
    const debit = Number(r.debit);
    const credit = Number(r.credit);
    runningBalance += debit - credit;
    return {
      date: r.date,
      reference: r.reference || '',
      description: r.description,
      debit,
      credit,
      balance: runningBalance,
    };
  });

  return {
    clientName: client.name,
    clientEmail: client.email || '',
    asOfDate,
    openingBalance: 0,
    transactions,
    closingBalance: runningBalance,
  };
}

// ── Payment Links ────────────────────────────────────────────────────────────

export async function createPaymentLink(invoiceId: string, clientId: string, amount: number): Promise<string> {
  const rows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    VALUES (${invoiceId}::UUID, ${clientId}::UUID, ${amount})
    RETURNING token
  `) as Row[];
  return rows[0].token;
}

export async function getPaymentLink(token: string): Promise<{
  invoiceId: string;
  clientId: string;
  amount: number;
  status: string;
  expiresAt: string;
} | null> {
  const rows = (await sql`
    SELECT * FROM portal_payment_links WHERE token = ${token} AND status = 'active' AND expires_at > NOW()
  `) as Row[];
  if (!rows[0]) return null;
  return {
    invoiceId: rows[0].invoice_id,
    clientId: rows[0].client_id,
    amount: Number(rows[0].amount),
    status: rows[0].status,
    expiresAt: rows[0].expires_at,
  };
}

export async function markPaymentLinkPaid(token: string, reference: string): Promise<void> {
  await sql`
    UPDATE portal_payment_links SET status = 'paid', paid_at = NOW(), payment_reference = ${reference}
    WHERE token = ${token}
  `;
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapPortalUser(r: Row): PortalUser {
  return {
    id: r.id,
    clientId: r.client_id,
    email: r.email,
    name: r.name,
    isActive: r.is_active,
    lastLoginAt: r.last_login_at,
  };
}

/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

type Row = any;

export async function getRecurringInvoices(companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices
      WHERE company_id = ${companyId} AND client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(companyId: string, 
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      company_id, template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring invoice not found');
  const ri = rows[0];
  if (ri.status !== 'active') throw new Error('Recurring invoice is not active');

  const nextDate = advanceDate(String(ri.next_run_date), String(ri.frequency));
  const endDate = ri.end_date ? String(ri.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  const invoiceId = await withTransaction(async (tx) => {
    const inv = (await tx`
      INSERT INTO customer_invoices (
        client_id, project_id, invoice_date, due_date, subtotal,
        tax_amount, total_amount, status, description, created_by
      ) VALUES (
        ${ri.client_id}::UUID, ${ri.project_id || null},
        CURRENT_DATE, CURRENT_DATE + INTERVAL '30 days',
        ${Number(ri.subtotal)}, ${Number(ri.tax_amount)}, ${Number(ri.total_amount)},
        'approved', ${ri.description || ri.template_name}, ${userId}::UUID
      ) RETURNING id
    `) as Row[];

    await tx`
      UPDATE recurring_invoices
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;

    return String(inv[0]!.id);
  });

  log.info('Generated invoice from recurring', { recurringId: id, invoiceId }, 'accounting');
  return invoiceId;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringInvoice {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    clientId: String(row.client_id),
    projectId: row.project_id ? String(row.project_id) : undefined,
    frequency: String(row.frequency) as RecurringInvoice['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringInvoice['status'],
    description: row.description ? String(row.description) : undefined,
    lineItems: Array.isArray(row.line_items) ? row.line_items : JSON.parse(row.line_items || '[]'),
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * Recurring Journal Service
 * Phase 1 Sage Alignment: Scheduled automated journal entries
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { RecurringJournal, RecurringJournalCreateInput, JournalLineInput } from '../types/gl.types';
type Row = any;


export async function getRecurringJournals(companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringJournal[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM recurring_journals WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_journals WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM recurring_journals WHERE company_id = ${companyId}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_journals WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringJournal(companyId: string, 
  input: RecurringJournalCreateInput,
  userId: string
): Promise<RecurringJournal> {
  // Validate lines balance
  const totalDebit = input.lines.reduce((s, l) => s + l.debit, 0);
  const totalCredit = input.lines.reduce((s, l) => s + l.credit, 0);
  if (Math.abs(totalDebit - totalCredit) > 0.01) {
    throw new Error(`Journal lines do not balance: DR ${totalDebit.toFixed(2)} vs CR ${totalCredit.toFixed(2)}`);
  }

  const rows = (await sql`
    INSERT INTO recurring_journals (
      company_id, template_name, description, frequency, next_run_date,
      end_date, lines, total_amount, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.description || null}, ${input.frequency},
      ${input.nextRunDate}, ${input.endDate || null},
      ${JSON.stringify(input.lines)}::JSONB, ${totalDebit}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring journal', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringJournalStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_journals SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring journal status', { id, status }, 'accounting');
}

export async function generateJournalFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_journals WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring journal not found');
  const rj = rows[0];
  if (rj.status !== 'active') throw new Error('Recurring journal is not active');

  const lines: JournalLineInput[] = Array.isArray(rj.lines) ? rj.lines : JSON.parse(rj.lines || '[]');

  const je = await createJournalEntry('', {
    entryDate: new Date().toISOString().split('T')[0]!,
    description: rj.description || rj.template_name,
    source: 'auto_recurring',
    lines,
  }, userId);
  await postJournalEntry('', je.id, userId);

  // Advance next run date and mark last run atomically so a failure here
  // doesn't leave an orphaned GL entry with the recurring template unadvanced.
  const nextDate = advanceDate(String(rj.next_run_date), String(rj.frequency));
  const endDate = rj.end_date ? String(rj.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  await withTransaction(async (tx) => {
    await tx`
      UPDATE recurring_journals
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;
  });

  log.info('Generated journal from recurring', { recurringId: id, journalId: je.id }, 'accounting');
  return je.id;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringJournal {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    description: row.description ? String(row.description) : undefined,
    frequency: String(row.frequency) as RecurringJournal['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringJournal['status'],
    lines: Array.isArray(row.lines) ? row.lines : JSON.parse(row.lines || '[]'),
    totalAmount: Number(row.total_amount),
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Email Service
 * Generic email sending via SMTP (nodemailer) + invoice-specific helpers
 * Gracefully handles missing SMTP configuration
 */

import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { generateInvoicePdf } from './invoicePdfService';
import { inviteEmailHtml, invoiceEmailHtml } from '@/lib/email-templates';
import type { InviteEmailData, InvoiceEmailData } from '@/lib/email-templates';
type Row = any;


// ─── Types ──────────────────────────────────────────────────────────────────

export interface EmailAttachment {
  filename: string;
  content: Buffer;
  contentType: string;
}

export interface EmailOptions {
  to: string | string[];
  subject: string;
  html: string;
  attachments?: EmailAttachment[];
}

export interface EmailResult {
  success: boolean;
  messageId?: string;
  error?: string;
}

// ─── SMTP Configuration ────────────────────────────────────────────────────

interface SmtpConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
}

function getSmtpConfig(): SmtpConfig | null {
  const host = process.env.SMTP_HOST;
  const port = process.env.SMTP_PORT;
  const user = process.env.SMTP_USER;
  const pass = process.env.SMTP_PASS;
  const from = process.env.SMTP_FROM || 'accounts@isaflow.co.za';

  if (!host || !user || !pass) {
    return null;
  }

  return {
    host,
    port: port ? parseInt(port, 10) : 587,
    user,
    pass,
    from,
  };
}

// ─── Generic Email Sender ───────────────────────────────────────────────────

export async function sendEmail(options: EmailOptions): Promise<EmailResult> {
  const config = getSmtpConfig();

  if (!config) {
    log.warn('SMTP not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS environment variables.', {}, 'emailService');
    return { success: false, error: 'SMTP not configured' };
  }

  try {
    // Dynamic import to avoid loading nodemailer when not needed
    const nodemailer = await import('nodemailer');

    const transporter = nodemailer.createTransport({
      host: config.host,
      port: config.port,
      secure: config.port === 465,
      auth: {
        user: config.user,
        pass: config.pass,
      },
      tls: {
        // Allow self-signed certs in dev; enforce TLS validation in production
        rejectUnauthorized: process.env.NODE_ENV === 'production',
      },
    });

    const recipients = Array.isArray(options.to) ? options.to.join(', ') : options.to;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const mailOptions: any = {
      from: config.from,
      to: recipients,
      subject: options.subject,
      html: options.html,
      attachments: options.attachments?.map((att) => ({
        filename: att.filename,
        content: att.content,
        contentType: att.contentType,
      })),
    };

    const info = await transporter.sendMail(mailOptions);

    log.info('Email sent', {
      messageId: info.messageId,
      to: recipients,
      subject: options.subject,
    }, 'emailService');

    return {
      success: true,
      messageId: info.messageId,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown email error';
    log.error('Failed to send email', { error: message, to: options.to }, 'emailService');
    return { success: false, error: message };
  }
}

// ─── Invoice Email ──────────────────────────────────────────────────────────

const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const fmtDate = (d: string | null | undefined): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

export async function sendInvoiceEmail(companyId: string, 
  invoiceId: string,
  recipientEmail: string
): Promise<EmailResult> {
  // Fetch invoice summary for email body
  const invoiceRows = (await sql`
    SELECT ci.invoice_number, ci.invoice_date, ci.due_date,
           ci.total_amount, ci.amount_paid,
           c.name AS client_name
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID
  `) as Row[];

  if (invoiceRows.length === 0) {
    throw new Error(`Invoice not found: ${invoiceId}`);
  }

  const invoice = invoiceRows[0];
  const balance = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
  const companyName = 'IsaFlow';

  // Generate PDF
  const pdfBuffer = await generateInvoicePdf('', invoiceId);

  // Build email HTML (table-based for email client compatibility)
  const invoiceData: InvoiceEmailData = {
    invoiceNumber: invoice.invoice_number,
    clientName: invoice.client_name || 'Valued Customer',
    invoiceDate: fmtDate(invoice.invoice_date),
    dueDate: fmtDate(invoice.due_date),
    totalAmount: fmtZAR(Number(invoice.total_amount)),
    balanceDue: fmtZAR(balance),
    companyName,
  };
  const html = invoiceEmailHtml(invoiceData);

  // Send email with PDF attachment
  const result = await sendEmail({
    to: recipientEmail,
    subject: `Invoice ${invoice.invoice_number} from ${companyName}`,
    html,
    attachments: [
      {
        filename: `${invoice.invoice_number || 'Invoice'}.pdf`,
        content: pdfBuffer,
        contentType: 'application/pdf',
      },
    ],
  });

  // Update tracking fields on the invoice
  if (result.success) {
    await sql`
      UPDATE customer_invoices
      SET email_sent_at = NOW(),
          email_sent_to = ${recipientEmail},
          email_message_id = ${result.messageId || null},
          updated_at = NOW()
      WHERE id = ${invoiceId}::UUID
    `;

    log.info('Invoice email sent and tracked', {
      invoiceId,
      recipientEmail,
      messageId: result.messageId,
    }, 'emailService');
  }

  return result;
}

