export async function deleteRecurringTemplate(companyId: string, id: string): Promise<void> {
  await sql`
    DELETE FROM recurring_transaction_templates WHERE id = ${id}::UUID AND company_id = ${companyId}
  `;
  log.info('Recurring template deleted', { id }, 'recurring');
}

export async function executeRecurring(
  companyId: string,
  templateId: string,
  userId: string,
): Promise<{ entityType: string; entityId: string; posted: boolean }> {
  const rows = (await sql`
    SELECT * FROM recurring_transaction_templates
    WHERE id = ${templateId}::UUID AND company_id = ${companyId} AND is_active = true
  `) as Row[];
  if (!rows[0]) throw new Error('Template not found or inactive');
  const template = mapRow(rows[0]!);

  let entityId: string;
  let posted = false;

  if (template.entityType === 'journal_entry') {
    const { createJournalEntry, postJournalEntry } =
      await import('./journalEntryService');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const data = template.templateData as any;
    const je = await createJournalEntry(companyId, {
      entryDate: new Date().toISOString().split('T')[0]!,
      description: data.description || template.name,
      source: 'auto_recurring',
      lines: data.lines || [],
    }, userId);
    entityId = je.id;
    if (template.autoPost) {
      await postJournalEntry(companyId, je.id, userId);
      posted = true;
    }
  } else if (template.entityType === 'customer_invoice') {
    // Customer invoice: insert with template_data fields
    const data = template.templateData as Record<string, unknown>;
    const ciRows = (await sql`
      INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date,
        reference, notes, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.clientId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.notes || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(ciRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE customer_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  } else {
    // Supplier invoice
    const data = template.templateData as Record<string, unknown>;
    const siRows = (await sql`
      INSERT INTO supplier_invoices (company_id, supplier_id, invoice_date, due_date,
        reference, description, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.supplierId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.description || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(siRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE supplier_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  }

  // Advance schedule
  const now = new Date();
  const nextDate = calculateNextRunDate(now, template.frequency).toISOString().split('T')[0]!;
  await sql`
    UPDATE recurring_transaction_templates
    SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE
    WHERE id = ${templateId}::UUID AND company_id = ${companyId}
  `;

  log.info('Recurring template executed', { templateId, entityId, entityType: template.entityType }, 'recurring');
  return { entityType: template.entityType, entityId, posted };
}

export async function getUpcomingRecurring(
  companyId: string,
  days = 7,
): Promise<UpcomingItem[]> {
  const rows = (await sql`
    SELECT id, name, entity_type, next_run_date, frequency
    FROM recurring_transaction_templates
    WHERE company_id = ${companyId}
      AND is_active = true
      AND next_run_date <= CURRENT_DATE + ${days} * INTERVAL '1 day'
    ORDER BY next_run_date ASC
  `) as Row[];
  return rows.map(r => ({
    id: String(r.id),
    name: String(r.name),
    entityType: String(r.entity_type),
    nextRunDate: String(r.next_run_date),
    frequency: String(r.frequency),
  }));
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';
type Row = any;


export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id}`) as Row[]; // NOTE: id-only lookup used internally — callers must ensure companyId scoping
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Cross-Module GL Integration Hooks
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccountId } from './systemAccountResolver';
type Row = any;


// ── Asset Depreciation → GL ────────────────────────────────────────────────

export async function postAssetDepreciationToGL(
  companyId: string,
  assetId: string,
  depreciationAmount: number,
  userId: string
): Promise<string | null> {
  try {
    if (depreciationAmount <= 0) return null;

    const asset = (await sql`
      SELECT id, asset_number, name FROM assets WHERE id = ${assetId}
    `) as Row[];

    if (!asset[0]) {
      log.warn('Asset not found for depreciation GL', { assetId }, 'accounting');
      return null;
    }

    const depExpenseId = await getSystemAccountId('depreciation_expense');
    const accumDepId = await getSystemAccountId('accumulated_depreciation');

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${companyId}, ${`DEP-${asset[0].asset_number}-${new Date().toISOString().slice(0, 7)}`}, CURRENT_DATE,
        ${`Depreciation: ${asset[0].name} (${asset[0].asset_number})`},
        'auto_depreciation', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${depExpenseId}::UUID, ${depreciationAmount}, 0,
        ${`Depreciation: ${asset[0].asset_number}`})
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${accumDepId}::UUID, 0, ${depreciationAmount},
        ${`Depreciation: ${asset[0].asset_number}`})
    `;

    await sql`
      UPDATE assets SET
        accumulated_depreciation = COALESCE(accumulated_depreciation, 0) + ${depreciationAmount},
        current_book_value = COALESCE(purchase_price, 0) - (COALESCE(accumulated_depreciation, 0) + ${depreciationAmount}),
        updated_at = NOW()
      WHERE id = ${assetId}
    `;

    log.info('Asset depreciation GL posted', { assetId, entryId, depreciationAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post asset depreciation to GL', { assetId, error: err }, 'accounting');
    return null;
  }
}

/**
 * Sage Customer Invoice Importer
 * Moves sage_customer_invoices → customer_invoices + customer_invoice_items
 * Matches Sage's approach: invoices are standalone AR documents,
 * no separate GL journal entries are created per invoice.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';
type Row = any;


/**
 * Import sage_customer_invoices into customer_invoices with line items
 */
export async function importCustomerInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('customer_invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_customer_id, client_id,
        invoice_number, invoice_date, due_date,
        subtotal, tax_amount, total_amount, outstanding_amount,
        status, raw_data
      FROM sage_customer_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        const clientId = inv.client_id;
        if (!clientId) {
          await sql`
            UPDATE sage_customer_invoices SET migration_status = 'failed'
            WHERE id = ${inv.id}
          `;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;
        const isPaid = inv.status === 'paid'
          || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data
        const rawData = parseRawData(inv.raw_data);
        const reference = rawData?.Reference || inv.invoice_number || null;

        const newInv = (await sql`
          INSERT INTO customer_invoices (
            invoice_number, client_id, invoice_date, due_date,
            billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${clientId}::UUID,
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)},
            ${totalAmount},
            ${isPaid ? totalAmount : 0},
            ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id},
            ${reference},
            ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = rawData?.Lines;
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);

            await sql`
              INSERT INTO customer_invoice_items (
                invoice_id, description, unit_price, quantity,
                tax_amount, line_total, income_type
              ) VALUES (
                ${newInvoiceId}::UUID,
                ${line.Description || 'Line item'},
                ${price}, ${qty}, ${lineTax}, ${lineTotal}, 'other'
              )
            `;
          }
        }

        await sql`
          UPDATE sage_customer_invoices
          SET migration_status = 'imported',
              gl_customer_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import customer invoice',
          { invoiceId: inv.id, error: err }, 'accounting');
        await sql`
          UPDATE sage_customer_invoices SET migration_status = 'failed'
          WHERE id = ${inv.id}
        `;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown): any {
  if (!rawData) return null;
  if (typeof rawData === 'string') {
    try { return JSON.parse(rawData); } catch { return null; }
  }
  return rawData;
}

/**
 * GL Import Service — WS-6.3 Excel Import Wizard
 * Validates and imports journal entries from spreadsheet uploads.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VatType } from '../types/gl.types';
type Row = any;


export interface ImportRow {
  date: string;          // YYYY-MM-DD
  accountCode: string;   // Must exist in gl_accounts for this company
  description: string;
  reference?: string;
  debit: number;
  credit: number;
  vatCode?: string;
  costCentre?: string;
}

export interface ValidationResult {
  row: number;
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface ValidationSummary {
  validations: ValidationResult[];
  validCount: number;
  errorCount: number;
  warningCount: number;
  totalDebit: number;
  totalCredit: number;
  isBalanced: boolean;
}

export interface ImportResult {
  entriesCreated: number;
  linesCreated: number;
  totalValue: number;
}

const VALID_VAT_CODES: VatType[] = [
  'standard', 'zero_rated', 'exempt', 'capital_goods',
  'export', 'imported', 'reverse_charge', 'bad_debt', 'no_vat',
];

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d;
}

export async function validateImportRows(
  companyId: string,
  rows: ImportRow[],
): Promise<ValidationSummary> {
  try {
    // Load chart of accounts for this company
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load open fiscal periods
    const periodRows = (await sql`
      SELECT start_date, end_date
      FROM fiscal_periods
      WHERE company_id = ${companyId}::UUID
        AND status = 'open'
      ORDER BY start_date
    `) as Row[];

    // Load cost centres
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccSet = new Set<string>(ccRows.map((r: Row) => String(r.code).toLowerCase()));

    const validations: ValidationResult[] = [];
    let totalDebit = 0;
    let totalCredit = 0;
    let validCount = 0;
    let errorCount = 0;
    let warningCount = 0;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]!;
      const errors: string[] = [];
      const warnings: string[] = [];
      const rowNum = i + 2; // 1-indexed + header row

      // Description required
      if (!row.description || row.description.trim() === '') {
        errors.push('Description is required');
      }

      // Date validation
      const parsedDate = parseDate(row.date);
      if (!parsedDate) {
        errors.push(`Invalid date: "${row.date}" — expected YYYY-MM-DD`);
      } else {
        // Check if date falls within an open fiscal period
        const inOpenPeriod = periodRows.some((p: Row) => {
          const start = new Date(p.start_date);
          const end = new Date(p.end_date);
          return parsedDate >= start && parsedDate <= end;
        });
        if (!inOpenPeriod) {
          warnings.push(`Date ${row.date} does not fall within an open fiscal period`);
        }
      }

      // Account code validation
      if (!row.accountCode || row.accountCode.trim() === '') {
        errors.push('Account code is required');
      } else if (!accountMap.has(String(row.accountCode).trim())) {
        errors.push(`Account code "${row.accountCode}" not found in chart of accounts`);
      }

      // Debit / credit validation
      const debit = Number(row.debit) || 0;
      const credit = Number(row.credit) || 0;

      if (debit < 0) errors.push('Debit cannot be negative');
      if (credit < 0) errors.push('Credit cannot be negative');

      if (debit > 0 && credit > 0) {
        errors.push('Debit and credit cannot both be greater than zero on the same line');
      }
      if (debit === 0 && credit === 0) {
        errors.push('At least one of debit or credit must be greater than zero');
      }

      // VAT code validation (optional)
      if (row.vatCode && row.vatCode.trim() !== '') {
        const code = row.vatCode.trim() as VatType;
        if (!VALID_VAT_CODES.includes(code)) {
          errors.push(
            `Invalid VAT code "${row.vatCode}". Valid codes: ${VALID_VAT_CODES.join(', ')}`,
          );
        }
      }

      // Cost centre validation (optional)
      if (row.costCentre && row.costCentre.trim() !== '') {
        if (!ccSet.has(row.costCentre.trim().toLowerCase())) {
          warnings.push(`Cost centre "${row.costCentre}" not found — will be ignored`);
        }
      }

      const valid = errors.length === 0;
      if (valid) {
        validCount++;
        totalDebit += debit;
        totalCredit += credit;
      } else {
        errorCount++;
      }
      if (warnings.length > 0) warningCount++;

      validations.push({ row: rowNum, valid, errors, warnings });
    }

    // For balanced check, only consider valid rows
    const diff = Math.abs(totalDebit - totalCredit);
    const isBalanced = diff < 0.005; // tolerance for floating point

    return {
      validations,
      validCount,
      errorCount,
      warningCount,
      totalDebit,
      totalCredit,
      isBalanced,
    };
  } catch (err) {
    log.error('Failed to validate import rows', { error: err }, 'gl-import');
    throw err;
  }
}

export async function importJournalEntries(
  companyId: string,
  rows: ImportRow[],
  userId: string,
  postImmediately: boolean,
): Promise<ImportResult> {
  try {
    // Load account code → id mapping
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load cost centre code → id mapping
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccMap = new Map<string, string>(
      ccRows.map((r: Row) => [String(r.code).toLowerCase(), String(r.id)]),
    );

    // Group rows into journal entries: same date + same reference = one entry
    const grouped = new Map<string, ImportRow[]>();
    for (const row of rows) {
      const key = `${row.date}||${row.reference || ''}`;
      const group = grouped.get(key) ?? [];
      group.push(row);
      grouped.set(key, group);
    }

    let entriesCreated = 0;
    let linesCreated = 0;
    let totalValue = 0;
    const status = postImmediately ? 'posted' : 'draft';

    for (const [, groupRows] of grouped) {
      const firstRow = groupRows[0]!;

      // Find fiscal period for entry date
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE company_id = ${companyId}::UUID
          AND start_date <= ${firstRow.date}::DATE
          AND end_date >= ${firstRow.date}::DATE
        LIMIT 1
      `) as Row[];
      const fiscalPeriodId = periodRows.length > 0 ? String(periodRows[0].id) : null;

      const description = firstRow.reference
        ? `${firstRow.reference}: ${firstRow.description}`
        : firstRow.description;

      const postedBy = postImmediately ? userId : null;

      const entryInsert = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, fiscal_period_id, description,
          source, created_by, status,
          posted_by, posted_at
        ) VALUES (
          ${companyId}::UUID,
          ${firstRow.date}::DATE,
          ${fiscalPeriodId}::UUID,
          ${description},
          'import',
          ${userId}::UUID,
          ${status},
          ${postedBy}::UUID,
          ${postImmediately ? sql`NOW()` : sql`NULL`}
        )
        RETURNING id
      `) as Row[];

      const entryId = String(entryInsert[0].id);
      entriesCreated++;

      for (const row of groupRows) {
        const accountId = accountMap.get(String(row.accountCode).trim());
        if (!accountId) continue; // already validated upstream

        const ccId = row.costCentre
          ? (ccMap.get(row.costCentre.trim().toLowerCase()) ?? null)
          : null;

        const vatType = (row.vatCode?.trim() as VatType) || null;

        await sql`
          INSERT INTO gl_journal_lines (
            journal_entry_id, gl_account_id, debit, credit,
            description, vat_type, cost_center_id
          ) VALUES (
            ${entryId}::UUID,
            ${accountId}::UUID,
            ${Number(row.debit) || 0},
            ${Number(row.credit) || 0},
            ${row.description},
            ${vatType},
            ${ccId}::UUID
          )
        `;

        linesCreated++;
        totalValue += Number(row.debit) || 0;
      }
    }

    log.info('Imported journal entries', {
      companyId, entriesCreated, linesCreated, totalValue, postImmediately,
    }, 'gl-import');

    return { entriesCreated, linesCreated, totalValue };
  } catch (err) {
    log.error('Failed to import journal entries', { error: err }, 'gl-import');
    throw err;
  }
}

/**
 * PRD-060 Phase 6: Sage Data Importers
 * Ledger transaction → GL journal entries
 * Supplier invoices → AP supplier_invoices
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';
type Row = any;


// ── Ledger Transaction Import ───────────────────────────────────────────────

/**
 * Import sage_ledger_transactions as GL journal entries
 * Groups by document_number + transaction_date into balanced entries
 */
export async function importLedgerTransactions(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('ledger_import', userId);

  try {
    // Fetch all pending lines in a single SELECT — eliminates N+1 per-group queries
    const allLines = (await sql`
      SELECT slt.id, slt.document_number, slt.transaction_date, slt.description,
        slt.debit, slt.credit, slt.reference, slt.ff_project_id,
        sa.gl_account_id
      FROM sage_ledger_transactions slt
      JOIN sage_accounts sa ON sa.sage_account_id = slt.sage_account_id
      WHERE slt.migration_status = 'pending'
        AND sa.gl_account_id IS NOT NULL
      ORDER BY slt.transaction_date, slt.document_number
    `) as Row[];

    // Group lines in JavaScript rather than with a separate query per group
    const groupMap = new Map<string, { document_number: string; transaction_date: unknown; description: string; lines: Row[] }>();
    for (const line of allLines) {
      const key = `${line.document_number}::${String(line.transaction_date)}`;
      if (!groupMap.has(key)) {
        groupMap.set(key, {
          document_number: line.document_number,
          transaction_date: line.transaction_date,
          description: line.description,
          lines: [],
        });
      }
      groupMap.get(key)!.lines.push(line);
    }

    const groups = Array.from(groupMap.values());
    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const group of groups) {
      try {
        const lines = group.lines;
        if (lines.length === 0) { skipped++; continue; }

        const totalDebit = lines.reduce((s: number, l: Row) => s + Number(l.debit || 0), 0);
        const totalCredit = lines.reduce((s: number, l: Row) => s + Number(l.credit || 0), 0);

        if (Math.abs(totalDebit - totalCredit) > 0.02) {
          await transaction((txSql) =>
            lines.map(line => txSql`
              UPDATE sage_ledger_transactions SET migration_status = 'failed' WHERE id = ${line.id}
            `)
          );
          failed++;
          continue;
        }

        const entryRef = group.document_number
          ? `SAGE-${group.document_number}`
          : `SAGE-${group.transaction_date}`;

        const entry = (await sql`
          INSERT INTO gl_journal_entries (
            entry_number, entry_date, description, source, status, created_by
          ) VALUES (
            ${entryRef}, ${group.transaction_date},
            ${group.description || `Sage import: ${entryRef}`},
            'manual', 'posted', ${userId}
          ) RETURNING id
        `) as Row[];

        const entryId = String(entry[0].id);

        // Batch all line inserts + status updates into one HTTP round-trip
        const activeLines = lines.filter(l => Number(l.debit || 0) !== 0 || Number(l.credit || 0) !== 0);
        if (activeLines.length > 0) {
          await transaction((txSql) =>
            activeLines.flatMap(line => {
              const debit = Number(line.debit || 0);
              const credit = Number(line.credit || 0);
              const projectId = line.ff_project_id || null;
              const lineInsert = projectId
                ? txSql`
                    INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
                    VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                      ${line.description || group.description || ''}, ${projectId}::UUID)
                  `
                : txSql`
                    INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
                    VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                      ${line.description || group.description || ''})
                  `;
              const statusUpdate = txSql`
                UPDATE sage_ledger_transactions
                SET migration_status = 'imported', gl_journal_entry_id = ${entryId}::UUID
                WHERE id = ${line.id}
              `;
              return [lineInsert, statusUpdate];
            })
          );
        }

        succeeded++;
      } catch (err) {
        log.error('Failed to import ledger group', { docNum: group.document_number, error: err }, 'accounting');
        failed++;
      }
    }

    return await completeRun(runId, groups.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Supplier Invoice Import ─────────────────────────────────────────────────

/**
 * Import sage_supplier_invoices into the supplier_invoices table.
 * Matches Sage's approach: invoices are standalone AP documents,
 * no separate GL journal entries are created per invoice.
 */
export async function importSupplierInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_supplier_id, invoice_number,
        invoice_date, due_date, subtotal, tax_amount, total_amount,
        outstanding_amount, status, ff_purchase_order_id, supplier_id,
        raw_data, line_items
      FROM sage_supplier_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        // NOTE: purchase_orders table is not available in standalone accounting app.
        // Supplier ID must come from the Sage import data directly; PO lookup is stubbed.
        const supplierId = inv.supplier_id;

        if (!supplierId) {
          await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;

        // project_id cannot be resolved from purchase_orders in standalone mode
        const projectId: string | null = null;

        const isPaid = inv.status === 'paid' || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data if available
        const rawObj = parseJson(inv.raw_data);
        const reference = rawObj?.Reference || null;

        const newInv = (await sql`
          INSERT INTO supplier_invoices (
            invoice_number, supplier_id, purchase_order_id, project_id,
            invoice_date, due_date, subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${supplierId}, ${inv.ff_purchase_order_id || null}, ${projectId},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)}, ${totalAmount},
            ${isPaid ? totalAmount : 0}, ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id}, ${reference}, ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = parseRawData(inv.raw_data, inv.line_items);
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);
            const lineTaxPct = Number(line.TaxPercentage || 0) * 100;

            if (projectId) {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total, project_id
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal},
                  ${projectId}::UUID
                )
              `;
            } else {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal}
                )
              `;
            }
          }
        }

        await sql`
          UPDATE sage_supplier_invoices
          SET migration_status = 'imported', gl_supplier_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import sage invoice', { invoiceId: inv.id, error: err }, 'accounting');
        await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown, lineItems: unknown): any[] | null {
  // Try raw_data.Lines first (full Sage response with includeDetail)
  const raw = parseJson(rawData);
  if (raw?.Lines && Array.isArray(raw.Lines) && raw.Lines.length > 0) {
    return raw.Lines;
  }
  // Fall back to line_items JSONB column
  const items = parseJson(lineItems);
  if (Array.isArray(items) && items.length > 0) return items;
  return null;
}

function parseJson(val: unknown): Record<string, unknown> | null {
  if (!val) return null;
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch { return null; }
  }
  return val as Record<string, unknown>;
}

/**
 * Migration AP Service — Supplier Invoice Import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { updateSession, type ImportResult, type MigrationError } from './migrationService';
import { matchContact } from './migrationImportService';
type Row = any;


export interface APInvoiceRow {
  invoiceNumber: string;
  supplierName: string;
  invoiceDate: string;
  dueDate: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  amountPaid: number;
  reference?: string;
}

// ── AP Invoice Import ────────────────────────────────────────────────────────

export async function importAPInvoices(
  companyId: string,
  sessionId: string,
  invoices: APInvoiceRow[],
  userId: string,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const apAccountId      = await getSystemAccountId('payable');
  const expenseAccountId = await getSystemAccountId('default_expense');
  const vatInputId       = await getSystemAccountId('vat_input');

  const supRows = (await sql`
    SELECT id, COALESCE(company_name, name) AS name FROM suppliers
    WHERE company_id = ${companyId}::UUID
  `) as Row[];

  for (let i = 0; i < invoices.length; i++) {
    const inv = invoices[i]!;
    try {
      const supplierId = matchContact(inv.supplierName, supRows);
      if (!supplierId) {
        errors.push({ step: 'ap_invoices', row: i, field: 'supplierName', message: `Supplier not found: ${inv.supplierName}` });
        skipped++;
        continue;
      }

      const balance = inv.totalAmount - (inv.amountPaid ?? 0);
      const status  = balance <= 0 ? 'paid' : inv.amountPaid > 0 ? 'partially_paid' : 'approved';

      const invRows = (await sql`
        INSERT INTO supplier_invoices (
          company_id, supplier_id, invoice_number, invoice_date, due_date,
          subtotal, tax_amount, total_amount, amount_paid, balance_due,
          status, reference, created_by
        ) VALUES (
          ${companyId}::UUID, ${supplierId}::UUID, ${inv.invoiceNumber},
          ${inv.invoiceDate}::DATE, ${inv.dueDate}::DATE,
          ${inv.subtotal}, ${inv.taxAmount}, ${inv.totalAmount},
          ${inv.amountPaid ?? 0}, ${balance}, ${status},
          ${inv.reference ?? null}, ${userId}::UUID
        )
        ON CONFLICT DO NOTHING
        RETURNING id
      `) as Row[];

      if (invRows.length === 0) { skipped++; continue; }
      const invoiceId = String(invRows[0].id);

      // Post GL: DR Expense + VAT Input, CR Payable
      const journalLines = [
        { glAccountId: expenseAccountId, debit: inv.subtotal,   credit: 0,              description: `Expense — ${inv.invoiceNumber}` },
        { glAccountId: apAccountId,      debit: 0,              credit: inv.totalAmount, description: `AP — ${inv.invoiceNumber}` },
      ];
      if (inv.taxAmount > 0) {
        // DR VAT Input (claimable input tax), AP credit already equals totalAmount
        journalLines.push({ glAccountId: vatInputId, debit: inv.taxAmount, credit: 0, description: `VAT Input — ${inv.invoiceNumber}` });
      }

      const entry = await createJournalEntry(companyId, {
        entryDate: inv.invoiceDate,
        description: `Migrated AP invoice ${inv.invoiceNumber}`,
        source: 'auto_migration',
        sourceDocumentId: invoiceId,
        lines: journalLines,
      }, userId);
      await postJournalEntry(companyId, entry.id, userId);
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'ap_invoices', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { apInvoicesImported: imported, stepsCompleted: { ap_invoices: true }, errors });
  log.info('AP invoices imported', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

/**
 * Migration COA Service — Chart of Accounts import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { clearSystemAccountCache } from './systemAccountResolver';
import { updateSession } from './migrationService';
import type { ImportResult, MigrationError } from './migrationService';
import type { GLAccountType } from '../types/gl.types';
type Row = any;


export interface AccountImportRow {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentCode?: string;
  normalBalance: 'debit' | 'credit';
  description?: string;
}

export interface SystemAccountMap {
  bank: string;
  receivable: string;
  payable: string;
  vat_input: string;
  vat_output: string;
  retained_earnings: string;
  default_revenue: string;
  default_expense: string;
  admin_expense: string;
}

// ── Public API ───────────────────────────────────────────────────────────────

export async function importChartOfAccounts(
  companyId: string,
  sessionId: string,
  accounts: AccountImportRow[],
  systemAccountMap: SystemAccountMap,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  // Sort: accounts without parents first, then those with parents (preserves hierarchy)
  const sorted = [...accounts.filter(a => !a.parentCode), ...accounts.filter(a => a.parentCode)];

  for (let i = 0; i < sorted.length; i++) {
    const acct = sorted[i]!;
    try {
      let parentAccountId: string | null = null;
      if (acct.parentCode) {
        const parentRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE account_code = ${acct.parentCode} AND company_id = ${companyId}::UUID
        `) as Row[];
        if (parentRows.length === 0) {
          errors.push({ step: 'coa', row: i, field: 'parentCode', message: `Parent code ${acct.parentCode} not found` });
          skipped++;
          continue;
        }
        parentAccountId = String(parentRows[0].id);
      }

      const subtypeEntry = Object.entries(systemAccountMap).find(([, code]) => code === acct.accountCode);
      const accountSubtype = subtypeEntry ? subtypeEntry[0] : (acct.accountSubtype ?? null);
      const isSystem = subtypeEntry != null;

      await sql`
        INSERT INTO gl_accounts (
          company_id, account_code, account_name, account_type, account_subtype,
          normal_balance, parent_account_id, description, is_system_account,
          level, display_order
        ) VALUES (
          ${companyId}::UUID,
          ${acct.accountCode},
          ${acct.accountName},
          ${acct.accountType},
          ${accountSubtype},
          ${acct.normalBalance},
          ${parentAccountId}::UUID,
          ${acct.description ?? null},
          ${isSystem},
          ${parentAccountId ? 2 : 1},
          0
        )
        ON CONFLICT (company_id, account_code) DO UPDATE SET
          account_name      = EXCLUDED.account_name,
          account_type      = EXCLUDED.account_type,
          account_subtype   = COALESCE(EXCLUDED.account_subtype, gl_accounts.account_subtype),
          normal_balance    = EXCLUDED.normal_balance,
          description       = COALESCE(EXCLUDED.description, gl_accounts.description),
          is_system_account = EXCLUDED.is_system_account OR gl_accounts.is_system_account
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'coa', row: i, field: 'accountCode', message: msg });
      skipped++;
    }
  }

  // Enforce system account subtype + flag for explicitly mapped accounts
  for (const [subtype, accountCode] of Object.entries(systemAccountMap)) {
    await sql`
      UPDATE gl_accounts
      SET account_subtype = ${subtype}, is_system_account = true
      WHERE company_id = ${companyId}::UUID AND account_code = ${accountCode}
    `;
  }

  clearSystemAccountCache();

  await updateSession(sessionId, companyId, {
    coaRecordsImported: imported,
    stepsCompleted: { coa: true },
    errors,
  });

  log.info('COA import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

