// ── Execute ──────────────────────────────────────────────────────────────────

export async function executeMigration(
  companyId: string,
  userId: string,
  source: MigrationSource,
  accounts: ParsedAccount[],
  customers: ParsedEntity[],
  suppliers: ParsedEntity[],
): Promise<ExecuteMigrationResult> {
  const errors: string[] = [];
  let accountsImported = 0;
  let customersImported = 0;
  let suppliersImported = 0;
  let openingBalancesSet = 0;

  log.info('Starting migration execution', { companyId, source, accountCount: accounts.length }, 'migration');

  // 1. Import GL accounts
  const validAccounts = accounts.filter(acct => {
    if (!acct.sourceCode && !acct.sourceName) return false;
    if (!acct.mappedType) {
      errors.push(`Account "${acct.sourceCode} ${acct.sourceName}": unmapped type "${acct.sourceType}" — skipped`);
      return false;
    }
    return true;
  });

  if (validAccounts.length > 0) {
    try {
      await transaction((txSql) =>
        validAccounts.map(acct => txSql`
          INSERT INTO gl_accounts (
            company_id, account_code, account_name, account_type, account_subtype,
            normal_balance, description, level, display_order, imported_from
          ) VALUES (
            ${companyId}::UUID,
            ${acct.sourceCode || acct.sourceName.substring(0, 20)},
            ${acct.sourceName},
            ${acct.mappedType},
            ${acct.mappedSubtype ?? null},
            ${acct.mappedNormalBalance ?? 'debit'},
            ${'Imported from ' + source},
            3,
            0,
            ${source}
          )
          ON CONFLICT (company_id, account_code) DO UPDATE SET
            account_name  = EXCLUDED.account_name,
            account_type  = EXCLUDED.account_type,
            imported_from = EXCLUDED.imported_from
        `)
      );
      accountsImported = validAccounts.length;
    } catch (err) {
      errors.push(`Accounts batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Set opening balances via journal entry
  const balanceAccounts = accounts.filter(a => a.openingBalance !== 0 && a.sourceCode && a.mappedType);
  if (balanceAccounts.length > 0) {
    try {
      const jeRows = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, reference, description, status, created_by
        ) VALUES (
          ${companyId}::UUID,
          CURRENT_DATE,
          ${'OB-' + source.toUpperCase()},
          ${'Opening balances imported from ' + source},
          'posted',
          ${userId}::UUID
        ) RETURNING id
      `) as Row[];

      const jeId = String(jeRows[0].id);

      for (const acct of balanceAccounts) {
        const glRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE company_id = ${companyId}::UUID AND account_code = ${acct.sourceCode}
          LIMIT 1
        `) as Row[];

        if (glRows.length === 0) continue;
        const glId = String(glRows[0].id);
        const isDebitNormal = acct.mappedNormalBalance === 'debit';
        const debit  = isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;
        const credit = !isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;

        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${jeId}::UUID, ${glId}::UUID, ${debit}, ${credit}, ${'Opening balance — ' + source})
        `;
        openingBalancesSet++;
      }
    } catch (err) {
      errors.push(`Opening balances: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 3. Import customers
  const validCustomers = customers.filter(c => c.name?.trim());
  if (validCustomers.length > 0) {
    try {
      await transaction((txSql) =>
        validCustomers.map(cust => txSql`
          INSERT INTO customers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${cust.name},
            ${cust.email ?? null},
            ${cust.phone ?? null},
            ${cust.vatNumber ?? null},
            ${cust.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      customersImported = validCustomers.length;
    } catch (err) {
      errors.push(`Customers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 4. Import suppliers
  const validSuppliers = suppliers.filter(s => s.name?.trim());
  if (validSuppliers.length > 0) {
    try {
      await transaction((txSql) =>
        validSuppliers.map(sup => txSql`
          INSERT INTO suppliers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${sup.name},
            ${sup.email ?? null},
            ${sup.phone ?? null},
            ${sup.vatNumber ?? null},
            ${sup.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      suppliersImported = validSuppliers.length;
    } catch (err) {
      errors.push(`Suppliers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  log.info('Migration execution complete', {
    companyId, source, accountsImported, customersImported, suppliersImported,
  }, 'migration');

  return { accountsImported, customersImported, suppliersImported, openingBalancesSet, errors };
}

// ── Verify balances ───────────────────────────────────────────────────────────

export async function verifyBalances(
  companyId: string,
  sourceAccounts: ParsedAccount[],
): Promise<VerifyEntry[]> {
  const results: VerifyEntry[] = [];

  for (const acct of sourceAccounts) {
    if (!acct.sourceCode) continue;

    try {
      const glRows = (await sql`
        SELECT ga.account_name,
          COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_debit,
          ga.normal_balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
        WHERE ga.company_id = ${companyId}::UUID AND ga.account_code = ${acct.sourceCode}
        GROUP BY ga.id, ga.account_name, ga.normal_balance
        LIMIT 1
      `) as Row[];

      const isaflowBalance = glRows.length > 0
        ? (String(glRows[0].normal_balance) === 'debit'
          ? Number(glRows[0].net_debit)
          : -Number(glRows[0].net_debit))
        : 0;

      const difference = acct.openingBalance - isaflowBalance;

      results.push({
        accountCode:    acct.sourceCode,
        sourceName:     acct.sourceName,
        sourceBalance:  acct.openingBalance,
        isaflowBalance,
        difference,
        matched:        Math.abs(difference) < 0.01,
      });
    } catch (err) {
      log.warn('Balance verification failed for account', { code: acct.sourceCode, error: err }, 'migration');
    }
  }

  return results;
}

// ── Rollback ─────────────────────────────────────────────────────────────────

export async function rollbackMigration(
  companyId: string,
  source: MigrationSource,
): Promise<{ deleted: number }> {
  let deleted = 0;

  try {
    // Remove GL accounts imported from this source
    const acctRows = (await sql`
      DELETE FROM gl_accounts
      WHERE company_id = ${companyId}::UUID AND imported_from = ${source}
      RETURNING id
    `) as Row[];
    deleted += acctRows.length;

    log.info('Rollback complete', { companyId, source, deleted }, 'migration');
  } catch (err) {
    log.error('Rollback failed', { companyId, source, error: err }, 'migration');
    throw err;
  }

  return { deleted };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import { validatePaymentAllocations } from '../utils/paymentAllocation';
import type {
  SupplierPayment,
  PaymentAllocation,
  PaymentAllocationInput,
  PaymentMethod,
  PaymentStatus,
  InvoiceForAllocation,
} from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = any;


interface PaymentFilters {
  status?: PaymentStatus;
  supplierId?: number;
  limit?: number;
  offset?: number;
}

export interface CreatePaymentInput {
  supplierId: number;
  paymentDate: string;
  totalAmount: number;
  paymentMethod?: PaymentMethod;
  bankAccountId?: string;
  reference?: string;
  description?: string;
  allocations: PaymentAllocationInput[];
}

export async function getSupplierPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: SupplierPayment[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status} AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_payments`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierPaymentById(companyId: string, 
  id: string
): Promise<(SupplierPayment & { allocations: PaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT sp.*, s.name AS supplier_name
      FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
      WHERE sp.id = ${id}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT pa.*, si.invoice_number
      FROM payment_allocations pa
      LEFT JOIN supplier_invoices si ON si.id = pa.invoice_id
      WHERE pa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierPayment(companyId: string, 
  input: CreatePaymentInput,
  userId: string
): Promise<SupplierPayment> {
  try {
    // Load invoices for allocation validation
    const invoiceIds = input.allocations.map(a => a.invoiceId);
    const invoiceRows = (await sql`
      SELECT id, invoice_number, total_amount, amount_paid, balance
      FROM supplier_invoices
      WHERE id = ANY(${invoiceIds}::UUID[])
    `) as Row[];

    const invoices: InvoiceForAllocation[] = invoiceRows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const validation = validatePaymentAllocations(input.totalAmount, input.allocations, invoices);
    if (!validation.valid) {
      throw new Error(`Invalid allocations: ${validation.errors.join('; ')}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_payments (
          supplier_id, payment_date, total_amount, payment_method,
          bank_account_id, reference, description, created_by
        ) VALUES (
          ${input.supplierId}, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankAccountId || null},
          ${input.reference || null}, ${input.description || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier payment', {
      paymentId: String(paymentRow.id),
      paymentNumber: String(paymentRow.payment_number),
      totalAmount: input.totalAmount,
    }, 'accounting');

    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create supplier payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function processSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'approved') throw new Error(`Payment must be approved before processing`);

    // Auto-post GL entry: DR Accounts Payable, CR Bank
    const apAccount = await getSystemAccount('payable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT * FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');

    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      {
        glAccountId: apAccount.id,
        debit: payment.totalAmount,
        credit: 0,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
      {
        glAccountId: bankAccount.id || String(bankAccount.id),
        debit: 0,
        credit: payment.totalAmount,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
    ];

    const journalEntry = await createJournalEntry('', {
      entryDate: payment.paymentDate,
      description: `Supplier payment ${payment.paymentNumber}`,
      source: 'auto_supplier_payment',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry('', journalEntry.id, userId);

    // Update invoice balances and mark payment processed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}
        `;
        await tx`
          UPDATE supplier_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${alloc.invoiceId}
        `;
      }

      const rows = (await tx`
        UPDATE supplier_payments
        SET status = 'processed', processed_at = NOW(),
            gl_journal_entry_id = ${journalEntry.id}::UUID
        WHERE id = ${id}
        RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Processed supplier payment', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to process supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot approve payment with status: ${payment.status}`);

    const rows = (await sql`
      UPDATE supplier_payments
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW()
      WHERE id = ${id}
      RETURNING *
    `) as Row[];

    return mapPaymentRow(rows[0]!);
  } catch (err) {
    log.error('Failed to approve supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): SupplierPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    supplierId: String(row.supplier_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as SupplierPayment['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as SupplierPayment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    batchId: row.batch_id ? String(row.batch_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
  };
}

function mapAllocationRow(row: Row): PaymentAllocation {
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: Number(row.amount_allocated),
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * Migration Import Service — Opening Balances + AR Invoices
 * PRD: Customer Migration Wizard — Phase 1
 *
 * AP invoice import is in migrationApService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { updateSession, type ImportResult, type MigrationError } from './migrationService';
type Row = any;


export interface OpeningBalanceRow {
  accountCode: string;
  debit: number;
  credit: number;
}

export interface ARInvoiceRow {
  invoiceNumber: string;
  customerName: string;
  invoiceDate: string;
  dueDate: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  amountPaid: number;
  reference?: string;
}

// ── Opening Balances ─────────────────────────────────────────────────────────

export async function importOpeningBalances(
  companyId: string,
  sessionId: string,
  effectiveDate: string,
  balances: OpeningBalanceRow[],
  userId: string,
): Promise<{ journalEntryId: string; errors: MigrationError[] }> {
  const errors: MigrationError[] = [];

  const totalDebit  = balances.reduce((s, b) => s + (b.debit ?? 0), 0);
  const totalCredit = balances.reduce((s, b) => s + (b.credit ?? 0), 0);

  if (Math.abs(totalDebit - totalCredit) > 0.01) {
    throw new Error(
      `Trial balance is not balanced: debits ${totalDebit.toFixed(2)} ≠ credits ${totalCredit.toFixed(2)}`
    );
  }

  const lines = [];
  for (let i = 0; i < balances.length; i++) {
    const bal = balances[i]!;
    if (bal.debit === 0 && bal.credit === 0) continue;

    const acctRows = (await sql`
      SELECT id FROM gl_accounts
      WHERE account_code = ${bal.accountCode} AND company_id = ${companyId}::UUID
    `) as Row[];

    if (acctRows.length === 0) {
      errors.push({ step: 'opening_balances', row: i, field: 'accountCode', message: `Account ${bal.accountCode} not found` });
      continue;
    }

    lines.push({
      glAccountId: String(acctRows[0].id),
      debit: bal.debit ?? 0,
      credit: bal.credit ?? 0,
      description: `Opening balance — ${bal.accountCode}`,
    });
  }

  if (lines.length === 0) {
    throw new Error('No valid balance rows to import');
  }

  const entry = await createJournalEntry(companyId, {
    entryDate: effectiveDate,
    description: 'Opening balances — migration import',
    source: 'auto_migration',
    lines,
  }, userId);

  await postJournalEntry(companyId, entry.id, userId);

  await updateSession(sessionId, companyId, {
    openingBalancesSet: true,
    stepsCompleted: { opening_balances: true },
    errors,
  });

  log.info('Opening balances imported', { companyId, journalEntryId: entry.id, lines: lines.length }, 'migration');
  return { journalEntryId: entry.id, errors };
}

// ── AR Invoice Import ────────────────────────────────────────────────────────

export async function importARInvoices(
  companyId: string,
  sessionId: string,
  invoices: ARInvoiceRow[],
  userId: string,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const arAccountId      = await getSystemAccountId('receivable');
  const revenueAccountId = await getSystemAccountId('default_revenue');
  const vatOutputId      = await getSystemAccountId('vat_output');

  const custRows = (await sql`
    SELECT id, name FROM customers WHERE company_id = ${companyId}::UUID
  `) as Row[];

  for (let i = 0; i < invoices.length; i++) {
    const inv = invoices[i]!;
    try {
      const customerId = matchContact(inv.customerName, custRows);
      if (!customerId) {
        errors.push({ step: 'ar_invoices', row: i, field: 'customerName', message: `Customer not found: ${inv.customerName}` });
        skipped++;
        continue;
      }

      const balance = inv.totalAmount - (inv.amountPaid ?? 0);
      const status  = balance <= 0 ? 'paid' : inv.amountPaid > 0 ? 'partially_paid' : 'approved';

      const invRows = (await sql`
        INSERT INTO customer_invoices (
          company_id, customer_id, invoice_number, invoice_date, due_date,
          subtotal, tax_amount, total_amount, amount_paid, balance_due,
          status, reference, created_by
        ) VALUES (
          ${companyId}::UUID, ${customerId}::UUID, ${inv.invoiceNumber},
          ${inv.invoiceDate}::DATE, ${inv.dueDate}::DATE,
          ${inv.subtotal}, ${inv.taxAmount}, ${inv.totalAmount},
          ${inv.amountPaid ?? 0}, ${balance}, ${status},
          ${inv.reference ?? null}, ${userId}::UUID
        )
        ON CONFLICT DO NOTHING
        RETURNING id
      `) as Row[];

      if (invRows.length === 0) { skipped++; continue; }
      const invoiceId = String(invRows[0].id);

      const journalLines = [
        { glAccountId: arAccountId,      debit: inv.totalAmount, credit: 0,             description: `AR — ${inv.invoiceNumber}` },
        { glAccountId: revenueAccountId, debit: 0,               credit: inv.subtotal,  description: `Revenue — ${inv.invoiceNumber}` },
      ];
      if (inv.taxAmount > 0) {
        journalLines.push({ glAccountId: vatOutputId, debit: 0, credit: inv.taxAmount, description: `VAT — ${inv.invoiceNumber}` });
      }

      const entry = await createJournalEntry(companyId, {
        entryDate: inv.invoiceDate,
        description: `Migrated AR invoice ${inv.invoiceNumber}`,
        source: 'auto_migration',
        sourceDocumentId: invoiceId,
        lines: journalLines,
      }, userId);
      await postJournalEntry(companyId, entry.id, userId);
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'ar_invoices', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { arInvoicesImported: imported, stepsCompleted: { ar_invoices: true }, errors });
  log.info('AR invoices imported', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

export function matchContact(name: string, candidates: Row[]): string | null {
  const normalized = name.toLowerCase().trim();
  const exact = candidates.find(c => String(c.name).toLowerCase().trim() === normalized);
  if (exact) return String(exact.id);
  let best: { id: string; score: number } | null = null;
  for (const c of candidates) {
    const score = diceCoefficient(normalized, String(c.name).toLowerCase().trim());
    if (score >= 0.7 && (!best || score > best.score)) best = { id: String(c.id), score };
  }
  return best?.id ?? null;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const ba = new Set<string>(), bb = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) ba.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bb.add(b.substring(i, i + 2));
  let n = 0;
  for (const g of ba) { if (bb.has(g)) n++; }
  return (2 * n) / (ba.size + bb.size);
}

/**
 * Time Tracking Service
 * Billable hours and project time management
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = any;


export interface TimeEntry {
  id: string;
  companyId: string;
  userId: string;
  projectName: string | null;
  taskDescription: string;
  entryDate: string;
  hours: number;
  rate: number | null;
  amount: number | null;
  billable: boolean;
  invoiced: boolean;
  invoiceId: string | null;
  customerId: string | null;
  customerName: string | null;
  notes: string | null;
  status: string;
  createdAt: string;
  updatedAt: string;
}

export interface TimeEntryInput {
  projectName?: string;
  taskDescription: string;
  entryDate?: string;
  hours: number;
  rate?: number;
  billable?: boolean;
  customerId?: string;
  notes?: string;
}

export interface TimeSummary {
  totalHours: number;
  billableHours: number;
  nonBillableHours: number;
  totalValue: number;
  byProject: { projectName: string; hours: number; value: number }[];
  byCustomer: { customerId: string; customerName: string; hours: number; value: number }[];
}

function mapEntry(r: Row): TimeEntry {
  const hours = Number(r.hours || 0);
  const rate = r.rate != null ? Number(r.rate) : null;
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    userId: String(r.user_id),
    projectName: r.project_name ? String(r.project_name) : null,
    taskDescription: String(r.task_description),
    entryDate: String(r.entry_date),
    hours,
    rate,
    amount: rate != null ? hours * rate : null,
    billable: Boolean(r.billable),
    invoiced: Boolean(r.invoiced),
    invoiceId: r.invoice_id ? String(r.invoice_id) : null,
    customerId: r.customer_id ? String(r.customer_id) : null,
    customerName: r.customer_name ? String(r.customer_name) : null,
    notes: r.notes ? String(r.notes) : null,
    status: String(r.status),
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

/**
 * Helper: call sql as a parameterized query string.
 * The neon() function supports sql(queryString, params[]) in addition to tagged templates.
 */
export async function getTimeEntries(
  companyId: string,
  _filters?: {
    userId?: string;
    customerId?: string;
    projectName?: string;
    status?: string;
    billable?: boolean;
    dateFrom?: string;
    dateTo?: string;
    limit?: number;
    offset?: number;
  },
): Promise<{ entries: TimeEntry[]; total: number }> {
  const lim = _filters?.limit || 50;
  const off = _filters?.offset || 0;

  try {
    const countRows = (await sql`
      SELECT COUNT(*)::int AS cnt FROM time_entries WHERE company_id = ${companyId}::UUID
    `) as Row[];

    const rows = (await sql`
      SELECT te.*, c.name AS customer_name
      FROM time_entries te
      LEFT JOIN customers c ON c.id = te.customer_id
      WHERE te.company_id = ${companyId}::UUID
      ORDER BY te.entry_date DESC, te.created_at DESC
      LIMIT ${lim} OFFSET ${off}
    `) as Row[];

    return {
      entries: rows.map(mapEntry),
      total: Number(countRows[0]?.cnt || 0),
    };
  } catch (err) {
    log.error('getTimeEntries failed', { error: err instanceof Error ? err.message : String(err) }, 'time-tracking');
    return { entries: [], total: 0 };
  }
}

export async function getTimeEntry(
  companyId: string,
  id: string,
): Promise<TimeEntry | null> {
  const rows = (await sql`
    SELECT te.*, c.name AS customer_name
    FROM time_entries te
    LEFT JOIN customers c ON c.id = te.customer_id
    WHERE te.id = ${id}::UUID AND te.company_id = ${companyId}::UUID
  `) as Row[];
  if (!rows.length) return null;
  return mapEntry(rows[0]);
}

export async function createTimeEntry(
  companyId: string,
  input: TimeEntryInput,
  userId: string,
): Promise<TimeEntry> {
  const entryDate = input.entryDate || new Date().toISOString().split('T')[0];
  const rows = (await sql`
    INSERT INTO time_entries (
      company_id, user_id, project_name, task_description, entry_date,
      hours, rate, billable, customer_id, notes
    ) VALUES (
      ${companyId}::UUID, ${userId}::UUID, ${input.projectName || null},
      ${input.taskDescription}, ${entryDate}::DATE,
      ${input.hours}, ${input.rate ?? null},
      ${input.billable !== false}, ${input.customerId || null}::UUID,
      ${input.notes || null}
    ) RETURNING *
  `) as Row[];

  log.info('Created time entry', { id: rows[0]?.id, userId }, 'accounting');
  return mapEntry(rows[0]!);
}

export async function updateTimeEntry(
  companyId: string,
  id: string,
  input: Partial<TimeEntryInput>,
): Promise<TimeEntry> {
  const existing = (await sql`
    SELECT status FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];
  if (!existing.length) throw new Error('Time entry not found');
  if (existing[0].status !== 'draft') throw new Error('Only draft entries can be edited');

  const rows = (await sql`
    UPDATE time_entries SET
      project_name = COALESCE(${input.projectName ?? null}, project_name),
      task_description = COALESCE(${input.taskDescription ?? null}, task_description),
      entry_date = COALESCE(${input.entryDate ?? null}::DATE, entry_date),
      hours = COALESCE(${input.hours ?? null}, hours),
      rate = COALESCE(${input.rate ?? null}, rate),
      billable = COALESCE(${input.billable ?? null}, billable),
      customer_id = COALESCE(${input.customerId ?? null}::UUID, customer_id),
      notes = COALESCE(${input.notes ?? null}, notes),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];

  log.info('Updated time entry', { id }, 'accounting');
  return mapEntry(rows[0]!);
}

export async function deleteTimeEntry(
  companyId: string,
  id: string,
): Promise<void> {
  const existing = (await sql`
    SELECT status FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];
  if (!existing.length) throw new Error('Time entry not found');
  if (existing[0].status !== 'draft') throw new Error('Only draft entries can be deleted');

  await sql`
    DELETE FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Deleted time entry', { id }, 'accounting');
}

export async function submitEntries(
  companyId: string,
  ids: string[],
): Promise<number> {
  if (!ids.length) return 0;
  const result = (await sql`
    UPDATE time_entries SET status = 'submitted', updated_at = NOW()
    WHERE company_id = ${companyId}::UUID
      AND id = ANY(${ids}::UUID[])
      AND status = 'draft'
  `) as Row[];
  const count = Array.isArray(result) ? result.length : 0;
  log.info('Submitted time entries', { count, ids }, 'accounting');
  return count;
}

export async function approveEntries(
  companyId: string,
  ids: string[],
