import { sql } from '@/lib/neon';
/**
 * Customer Statement Detail API
 * GET /api/accounting/customer-statement-detail?client_id=UUID
 * Returns full transaction-level statement with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;



async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const clientId = req.query.client_id as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'client_id is required');
  }

  try {
    // Get client info
    const clientRows = (await sql`
      SELECT id, name, email, phone FROM customers WHERE id = ${clientId}::UUID AND company_id = ${companyId}
    `) as Row[];
    if (clientRows.length === 0) {
      return apiResponse.notFound(res, 'Client', clientId);
    }
    const client = clientRows[0];

    // Get invoices
    const invoices = (await sql`
      SELECT id, invoice_number, invoice_date, reference, total_amount, status
      FROM customer_invoices
      WHERE client_id = ${clientId}::UUID AND company_id = ${companyId} AND status != 'cancelled'
      ORDER BY invoice_date
    `) as Row[];

    // Get confirmed payments — includes both allocated and unallocated (bank-sourced)
    const payments = (await sql`
      SELECT cp.id, cp.payment_number, cp.payment_date, cp.bank_reference,
        COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
      FROM customer_payments cp
      LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
      WHERE cp.client_id = ${clientId}::UUID AND cp.company_id = ${companyId} AND cp.status IN ('confirmed', 'reconciled')
      GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.bank_reference, cp.total_amount
    `) as Row[];

    // Get approved customer credit notes
    const creditNotes = (await sql`
      SELECT id, credit_note_number, credit_date, reason, total_amount
      FROM credit_notes
      WHERE client_id = ${clientId}::UUID AND company_id = ${companyId} AND type = 'customer' AND status = 'approved'
    `) as Row[];

    // Normalize date to YYYY-MM-DD regardless of input format
    const toISODate = (val: unknown): string => {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0] ?? '1970-01-01';
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0] ?? '1970-01-01';
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : (d.toISOString().split('T')[0] ?? '1970-01-01');
    };

    // Build transaction list
    interface Transaction {
      id: number | string;
      date: string;
      type: 'invoice' | 'payment' | 'credit_note';
      reference: string;
      description: string;
      debit: number;
      credit: number;
      balance: number;
    }

    const transactions: Transaction[] = [];

    for (const inv of invoices) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.invoice_date),
        type: 'invoice',
        reference: String(inv.invoice_number),
        description: inv.reference ? String(inv.reference) : '',
        debit: Number(inv.total_amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.payment_date),
        type: 'payment',
        reference: String(pmt.payment_number),
        description: pmt.bank_reference ? String(pmt.bank_reference) : '',
        debit: 0,
        credit: Number(pmt.amount_allocated),
        balance: 0,
      });
    }

    for (const cn of creditNotes) {
      transactions.push({
        id: cn.id,
        date: toISODate(cn.credit_date),
        type: 'credit_note',
        reference: String(cn.credit_note_number),
        description: cn.reason ? String(cn.reason) : '',
        debit: 0,
        credit: Number(cn.total_amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let runningBalance = 0;
    let totalInvoiced = 0;
    let totalPaid = 0;
    let totalCredits = 0;

    for (const txn of transactions) {
      runningBalance += txn.debit - txn.credit;
      txn.balance = runningBalance;
      totalInvoiced += txn.debit;
      if (txn.type === 'payment') totalPaid += txn.credit;
      if (txn.type === 'credit_note') totalCredits += txn.credit;
    }

    return apiResponse.success(res, {
      client: {
        id: String(client.id),
        name: String(client.name),
        email: client.email ? String(client.email) : null,
        phone: client.phone ? String(client.phone) : null,
      },
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalCredits,
        balance: runningBalance,
      },
    });
  } catch (err) {
    log.error('Failed to fetch customer statement detail', { clientId, error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer statement');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';
type Row = Record<string, unknown>;


export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id}`) as Row[]; // NOTE: id-only lookup used internally — callers must ensure companyId scoping
    return rows.length > 0 ? mapRow(rows[0]!) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]!) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

