export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Admin Dashboard Service
 * Aggregates platform-wide KPIs for the ISAFlow Admin Platform.
 * Queries: company counts, user counts, MRR/ARR, recent activity.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { DashboardStats, ActivityEvent } from '../types/admin.types';
type Row = Record<string, unknown>;


function toISOString(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

/**
 * Fetch platform-wide dashboard statistics.
 * Runs aggregate queries in parallel for performance.
 */
export async function getDashboardStats(): Promise<DashboardStats> {
  const [companyStats, userStats, mrrStats, signupCount, recentActivity] =
    await Promise.all([
      getCompanyStats(),
      getUserStats(),
      getMrrStats(),
      getNewSignupCount(),
      getRecentActivity(),
    ]);

  const stats: DashboardStats = {
    total_companies: companyStats.total,
    active_companies: companyStats.active,
    total_users: userStats.total,
    active_users_30d: userStats.active_30d,
    mrr_cents: mrrStats.mrr_cents,
    arr_cents: mrrStats.arr_cents,
    new_signups_30d: signupCount,
    recent_activity: recentActivity,
  };

  log.info('Admin dashboard stats fetched', {
    total_companies: stats.total_companies,
    active_companies: stats.active_companies,
    total_users: stats.total_users,
    mrr_cents: stats.mrr_cents,
  }, 'AdminDashboardService');

  return stats;
}

async function getCompanyStats(): Promise<{ total: number; active: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'active') AS active
    FROM companies
    WHERE status IS DISTINCT FROM 'deleted'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active: parseInt(row.active as string, 10),
  };
}

async function getUserStats(): Promise<{ total: number; active_30d: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS active_30d
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active_30d: parseInt(row.active_30d as string, 10),
  };
}

async function getMrrStats(): Promise<{ mrr_cents: number; arr_cents: number }> {
  // Monthly: sum monthly_price_cents
  // Annual: normalise to monthly (divide by 12)
  const rows = await sql`
    SELECT
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM subscriptions s
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.status IN ('active', 'trial')
  `;
  const mrr = parseInt((rows[0] as Row).mrr_cents as string, 10);
  return { mrr_cents: mrr, arr_cents: mrr * 12 };
}

async function getNewSignupCount(): Promise<number> {
  const rows = await sql`
    SELECT COUNT(*) AS count
    FROM companies
    WHERE created_at >= NOW() - INTERVAL '30 days'
      AND status IS DISTINCT FROM 'deleted'
  `;
  return parseInt((rows[0] as Row).count as string, 10);
}

/**
 * Most recent 50 events from admin_audit_log + recent user_sessions.
 */
async function getRecentActivity(): Promise<ActivityEvent[]> {
  const rows = await sql`
    SELECT
      a.id::text                                                     AS id,
      'admin_action'                                                 AS type,
      a.action || ' ' || a.target_type                              AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      a.created_at
    FROM admin_audit_log a
    LEFT JOIN users u ON u.id = a.admin_user_id

    UNION ALL

    SELECT
      s.id::text                                                     AS id,
      'user_login'                                                   AS type,
      'User login'                                                   AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      s.created_at
    FROM user_sessions s
    INNER JOIN users u ON u.id = s.user_id
    WHERE s.created_at >= NOW() - INTERVAL '7 days'

    ORDER BY created_at DESC
    LIMIT 50
  `;

  return (rows as Row[]).map((row) => ({
    id: row.id as string,
    type: row.type as string,
    description: row.description as string,
    user_name: row.user_name as string | null,
    company_name: row.company_name as string | null,
    created_at: toISOString(row.created_at),
  }));
}

/**
 * Billing Service — Overview & Subscriptions
 * Aggregate KPIs and subscription lifecycle for the ISAFlow Admin Platform.
 * Invoice operations are in invoiceService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  BillingOverview,
  SubscriptionListItem,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

// ---------------------------------------------------------------------------
// Overview
// ---------------------------------------------------------------------------

export async function getBillingOverview(): Promise<BillingOverview> {
  const [[subRow], [churnRow], [revRow]] = await Promise.all([
    sql`
      SELECT COUNT(*) AS total,
        COUNT(*) FILTER (WHERE s.status = 'active')   AS active,
        COUNT(*) FILTER (WHERE s.status = 'past_due') AS past_due,
        COUNT(*) FILTER (WHERE s.status = 'trial')    AS trial,
        COALESCE(SUM(CASE
          WHEN s.status NOT IN ('active','trial') THEN 0
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0 END), 0) AS mrr_cents
      FROM subscriptions s INNER JOIN plans p ON p.id = s.plan_id
    `,
    sql`
      SELECT
        COUNT(*) FILTER (WHERE status = 'cancelled'
          AND cancelled_at >= NOW() - INTERVAL '30 days')::float AS cancelled_30d,
        GREATEST(COUNT(*) FILTER (WHERE status IN ('active','trial','past_due')
          OR (status = 'cancelled' AND cancelled_at >= NOW() - INTERVAL '30 days')), 1)::float AS base
      FROM subscriptions
    `,
    sql`
      SELECT
        COALESCE(SUM(total_cents) FILTER (WHERE status = 'paid'), 0)              AS total_revenue_cents,
        COALESCE(SUM(total_cents) FILTER (WHERE status IN ('sent','overdue')), 0)  AS outstanding_cents
      FROM admin_invoices
    `,
  ]);

  const s = subRow as Row;
  const c = churnRow as Row;
  const rv = revRow as Row;
  const mrr = parseInt(s.mrr_cents as string, 10);
  const active = parseInt(s.active as string, 10);
  const churnRate = Math.round(((c.cancelled_30d as number) / (c.base as number)) * 10000) / 100;

  const overview: BillingOverview = {
    mrr_cents: mrr,
    arr_cents: mrr * 12,
    total_subscriptions: parseInt(s.total as string, 10),
    active_subscriptions: active,
    past_due_count: parseInt(s.past_due as string, 10),
    trial_count: parseInt(s.trial as string, 10),
    churn_rate_percent: churnRate,
    arpu_cents: active > 0 ? Math.round(mrr / active) : 0,
    total_revenue_cents: parseInt(rv.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(rv.outstanding_cents as string, 10),
  };

  log.info('getBillingOverview', { mrr_cents: mrr, active }, 'BillingService');
  return overview;
}

// ---------------------------------------------------------------------------
// Subscriptions
// ---------------------------------------------------------------------------

const ALLOWED_SUB_SORT: Record<string, string> = {
  created_at: 's.created_at',
  status: 's.status',
  company_name: 'c.name',
  plan_name: 'p.name',
};

function rowToSubscription(r: Row): SubscriptionListItem {
  return {
    id: r.id as string,
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    plan_id: r.plan_id as string,
    plan_name: r.plan_name as string,
    plan_code: r.plan_code as string,
    status: r.status as string,
    billing_cycle: r.billing_cycle as string,
    current_period_start: toIso(r.current_period_start),
    current_period_end: toIso(r.current_period_end),
    cancel_at_period_end: r.cancel_at_period_end as boolean,
    discount_percent: r.discount_percent as number,
    monthly_amount_cents: parseInt(r.monthly_amount_cents as string, 10),
    created_at: toIso(r.created_at) ?? '',
  };
}

export async function listSubscriptions(filters: {
  status?: string;
  plan_id?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<SubscriptionListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SUB_SORT[filters.sort_by ?? ''] ?? 's.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
  `;

  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listSubscriptions: ${rows.length} rows (page ${page})`, {}, 'BillingService');

  return {
    items: (rows as Row[]).map(rowToSubscription),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getSubscription(
  subscriptionId: string
): Promise<SubscriptionListItem | null> {
  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.id = ${subscriptionId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToSubscription(rows[0] as Row);
}

export async function createSubscription(data: {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_percent?: number;
  notes?: string;
}): Promise<string> {
  const { company_id, plan_id, billing_cycle, discount_percent = 0, notes = null } = data;
  const periodDays = billing_cycle === 'annual' ? 365 : 30;

  const rows = await sql`
    INSERT INTO subscriptions (
      company_id, plan_id, status, billing_cycle,
      current_period_start, current_period_end,
      cancel_at_period_end, discount_percent, notes,
      created_at, updated_at
    ) VALUES (
      ${company_id}::uuid, ${plan_id}::uuid,
      'active', ${billing_cycle},
      NOW(), NOW() + INTERVAL '1 day' * ${periodDays},
      false, ${discount_percent}, ${notes},
      NOW(), NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createSubscription', { id, company_id, plan_id, billing_cycle }, 'BillingService');
  return id;
}

export async function updateSubscription(
  subscriptionId: string,
  data: {
    plan_id?: string;
    billing_cycle?: string;
    discount_percent?: number;
    status?: string;
    notes?: string;
  }
): Promise<void> {
  const { plan_id, billing_cycle, discount_percent, status, notes } = data;

  await sql`
    UPDATE subscriptions SET
      plan_id          = COALESCE(${plan_id ?? null}::uuid, plan_id),
      billing_cycle    = COALESCE(${billing_cycle ?? null}, billing_cycle),
      discount_percent = COALESCE(${discount_percent ?? null}, discount_percent),
      status           = COALESCE(${status ?? null}, status),
      notes            = COALESCE(${notes ?? null}, notes),
      updated_at       = NOW()
    WHERE id = ${subscriptionId}
  `;

  log.info('updateSubscription', { subscriptionId }, 'BillingService');
}

export async function cancelSubscription(
  subscriptionId: string,
  atPeriodEnd: boolean
): Promise<void> {
  if (atPeriodEnd) {
    await sql`
      UPDATE subscriptions
      SET cancel_at_period_end = true,
          updated_at           = NOW()
      WHERE id = ${subscriptionId}
    `;
  } else {
    await sql`
      UPDATE subscriptions
      SET status       = 'cancelled',
          cancelled_at = NOW(),
          updated_at   = NOW()
      WHERE id = ${subscriptionId}
    `;
  }
  log.info('cancelSubscription', { subscriptionId, atPeriodEnd }, 'BillingService');
}

/**
 * Invoice Service
 * Admin invoice lifecycle for the ISAFlow Admin Platform.
 * Subscription operations are in billingService.ts.
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { InvoiceListItem, PaginatedResult } from '../types/admin.types';
type Row = Record<string, unknown>;


function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT: Record<string, string> = {
  created_at: 'i.created_at',
  due_date: 'i.due_date',
  status: 'i.status',
  total_cents: 'i.total_cents',
  company_name: 'c.name',
  invoice_number: 'i.invoice_number',
};

export async function listInvoices(filters: {
  company_id?: string;
  status?: string;
  from_date?: string;
  to_date?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<InvoiceListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT[filters.sort_by ?? ''] ?? 'i.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      i.id, i.company_id, c.name AS company_name,
      i.invoice_number, i.status,
      i.subtotal_cents, i.tax_cents, i.total_cents, i.currency,
      i.due_date, i.paid_at, i.payment_method,
      i.created_at
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listInvoices: ${rows.length} rows (page ${page})`, {}, 'InvoiceService');

  return {
    items: (rows as Row[]).map((r: Row) => ({
      id: r.id as string,
      company_id: r.company_id as string,
      company_name: r.company_name as string,
      invoice_number: r.invoice_number as string,
      status: r.status as string,
      subtotal_cents: r.subtotal_cents as number,
      tax_cents: r.tax_cents as number,
      total_cents: r.total_cents as number,
      currency: r.currency as string,
      due_date: toIso(r.due_date),
      paid_at: toIso(r.paid_at),
      payment_method: r.payment_method as string | null,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function createInvoice(data: {
  company_id: string;
  subscription_id?: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_date?: string;
  line_items?: unknown[];
  notes?: string;
}): Promise<string> {
  const {
    company_id,
    subscription_id = null,
    subtotal_cents,
    tax_cents,
    total_cents,
    due_date = null,
    line_items = [],
    notes = null,
  } = data;

  // Sequential invoice number: INV-YYYYMM-XXXX
  // Wrapped in a transaction to prevent race conditions on sequence generation.
  const id = await withTransaction(async (tx) => {
    const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
    const prefix = `INV-${yyyymm}-`;

    const seqRows = (await tx`
      SELECT COUNT(*) AS count FROM admin_invoices
      WHERE invoice_number LIKE ${prefix + '%'}
    `) as Row[];
    const seq = parseInt((seqRows[0] as Row).count as string, 10) + 1;
    const invoice_number = `${prefix}${String(seq).padStart(4, '0')}`;

    const rows = (await tx`
      INSERT INTO admin_invoices (
        company_id, subscription_id, invoice_number, status,
        subtotal_cents, tax_cents, total_cents, currency,
        due_date, line_items, notes, created_at
      ) VALUES (
        ${company_id}::uuid,
        ${subscription_id}::uuid,
        ${invoice_number}, 'draft',
        ${subtotal_cents}, ${tax_cents}, ${total_cents}, 'ZAR',
        ${due_date}::date,
        ${JSON.stringify(line_items)}::jsonb,
        ${notes},
        NOW()
      )
      RETURNING id
    `) as Row[];

    log.info('createInvoice', { id: (rows[0] as Row).id, invoice_number, company_id }, 'InvoiceService');
    return (rows[0] as Row).id as string;
  });

  return id;
}

export async function markInvoicePaid(
  invoiceId: string,
  paymentMethod: string
): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
  `;
  log.info('markInvoicePaid', { invoiceId, paymentMethod }, 'InvoiceService');
}

export async function sendInvoice(invoiceId: string): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status = 'sent'
    WHERE id   = ${invoiceId}
      AND status = 'draft'
  `;
  log.info('sendInvoice', { invoiceId }, 'InvoiceService');
}

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  AdminUserCompany,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getCompanyDetail(
  companyId: string
): Promise<AdminCompanyDetail | null> {
  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')    AS status,
      p.name                          AS plan_name,
      p.code                          AS plan_code,
      c.registration_number,
      c.vat_number,
      c.tax_number,
      c.address_line1,
      c.city,
      c.province,
      c.postal_code,
      c.phone,
      c.email,
      c.website,
      c.billing_email,
      c.billing_contact,
      c.stripe_customer_id,
      c.trial_ends_at,
      c.suspended_at,
      c.suspended_reason,
      c.metadata,
      c.created_at,
      c.updated_at                    AS last_active,
      (SELECT COUNT(*)
         FROM company_users cu
        WHERE cu.company_id = c.id)::int AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int AS mrr_cents
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.id = ${companyId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    name: r.name as string,
    trading_name: r.trading_name as string | null,
    status: r.status as string,
    plan_name: r.plan_name as string | null,
    plan_code: r.plan_code as string | null,
    user_count: r.user_count as number,
    mrr_cents: r.mrr_cents as number,
    created_at: toIso(r.created_at) ?? '',
    last_active: toIso(r.last_active),
    registration_number: r.registration_number as string | null,
    vat_number: r.vat_number as string | null,
    tax_number: r.tax_number as string | null,
    address_line1: r.address_line1 as string | null,
    city: r.city as string | null,
    province: r.province as string | null,
    postal_code: r.postal_code as string | null,
    phone: r.phone as string | null,
    email: r.email as string | null,
    website: r.website as string | null,
    billing_email: r.billing_email as string | null,
    billing_contact: r.billing_contact as string | null,
    stripe_customer_id: r.stripe_customer_id as string | null,
    trial_ends_at: toIso(r.trial_ends_at),
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    metadata: (r.metadata ?? {}) as Record<string, unknown>,
  };
}

export async function updateCompany(
  companyId: string,
  data: Partial<AdminCompanyDetail>
): Promise<void> {
  // Only update safe, explicitly listed fields
  const {
    name, trading_name, phone, email, website,
    billing_email, billing_contact,
    address_line1, city, province, postal_code,
  } = data;

  await sql`
    UPDATE companies SET
      name             = COALESCE(${name ?? null}, name),
      trading_name     = COALESCE(${trading_name ?? null}, trading_name),
      phone            = COALESCE(${phone ?? null}, phone),
      email            = COALESCE(${email ?? null}, email),
      website          = COALESCE(${website ?? null}, website),
      billing_email    = COALESCE(${billing_email ?? null}, billing_email),
      billing_contact  = COALESCE(${billing_contact ?? null}, billing_contact),
      address_line1    = COALESCE(${address_line1 ?? null}, address_line1),
      city             = COALESCE(${city ?? null}, city),
      province         = COALESCE(${province ?? null}, province),
      postal_code      = COALESCE(${postal_code ?? null}, postal_code),
      updated_at       = NOW()
    WHERE id = ${companyId}
  `;

  log.info('updateCompany', { companyId }, 'AdminCompanyService');
}

export async function suspendCompany(
  companyId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'suspended',
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('suspendCompany', { companyId, reason }, 'AdminCompanyService');
}

export async function activateCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'active',
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('activateCompany', { companyId }, 'AdminCompanyService');
}

/** Soft delete — sets status='deleted', preserves data for audit trail. */
export async function deleteCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status     = 'deleted',
        updated_at = NOW()
    WHERE id = ${companyId}
  `;
  log.info('deleteCompany (soft)', { companyId }, 'AdminCompanyService');
}

export async function getCompanyUsers(
  companyId: string
): Promise<AdminUserCompany[]> {
  const rows = await sql`
    SELECT
      cu.company_id,
      c.name    AS company_name,
      cu.role,
      COALESCE(cu.is_default, false) AS is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.company_id = ${companyId}
    ORDER BY cu.role, c.name
  `;

  return (rows as Row[]).map((r) => ({
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    role: r.role as string,
    is_default: r.is_default as boolean,
  }));
}

