    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
      AND status IN ('sent', 'overdue')
    RETURNING id
  `;
  const updated = rows.length > 0;
  log.info('markInvoicePaid', { invoiceId, paymentMethod, updated }, 'InvoiceService');
  return updated;
}

