/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  AdminUserCompany,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getCompanyDetail(
  companyId: string
): Promise<AdminCompanyDetail | null> {
  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')    AS status,
      p.name                          AS plan_name,
      p.code                          AS plan_code,
      c.registration_number,
      c.vat_number,
      c.tax_number,
      c.address_line1,
      c.city,
      c.province,
      c.postal_code,
      c.phone,
      c.email,
      c.website,
      c.billing_email,
      c.billing_contact,
      c.stripe_customer_id,
      c.trial_ends_at,
      c.suspended_at,
      c.suspended_reason,
      c.metadata,
      c.created_at,
      c.updated_at                    AS last_active,
      (SELECT COUNT(*)
         FROM company_users cu
        WHERE cu.company_id = c.id)::int AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int AS mrr_cents
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.id = ${companyId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    name: r.name as string,
    trading_name: r.trading_name as string | null,
    status: r.status as string,
    plan_name: r.plan_name as string | null,
    plan_code: r.plan_code as string | null,
    user_count: r.user_count as number,
    mrr_cents: r.mrr_cents as number,
    created_at: toIso(r.created_at) ?? '',
    last_active: toIso(r.last_active),
    registration_number: r.registration_number as string | null,
    vat_number: r.vat_number as string | null,
    tax_number: r.tax_number as string | null,
    address_line1: r.address_line1 as string | null,
    city: r.city as string | null,
    province: r.province as string | null,
    postal_code: r.postal_code as string | null,
    phone: r.phone as string | null,
    email: r.email as string | null,
    website: r.website as string | null,
    billing_email: r.billing_email as string | null,
    billing_contact: r.billing_contact as string | null,
    stripe_customer_id: r.stripe_customer_id as string | null,
    trial_ends_at: toIso(r.trial_ends_at),
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    metadata: (r.metadata ?? {}) as Record<string, unknown>,
  };
}

export async function updateCompany(
  companyId: string,
  data: Partial<AdminCompanyDetail>
): Promise<void> {
  // Only update safe, explicitly listed fields
  const {
    name, trading_name, phone, email, website,
    billing_email, billing_contact,
    address_line1, city, province, postal_code,
  } = data;

  await sql`
    UPDATE companies SET
      name             = COALESCE(${name ?? null}, name),
      trading_name     = COALESCE(${trading_name ?? null}, trading_name),
      phone            = COALESCE(${phone ?? null}, phone),
      email            = COALESCE(${email ?? null}, email),
      website          = COALESCE(${website ?? null}, website),
      billing_email    = COALESCE(${billing_email ?? null}, billing_email),
      billing_contact  = COALESCE(${billing_contact ?? null}, billing_contact),
      address_line1    = COALESCE(${address_line1 ?? null}, address_line1),
      city             = COALESCE(${city ?? null}, city),
      province         = COALESCE(${province ?? null}, province),
      postal_code      = COALESCE(${postal_code ?? null}, postal_code),
      updated_at       = NOW()
    WHERE id = ${companyId}
  `;

  log.info('updateCompany', { companyId }, 'AdminCompanyService');
}

export async function suspendCompany(
  companyId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'suspended',
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('suspendCompany', { companyId, reason }, 'AdminCompanyService');
}

export async function activateCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'active',
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('activateCompany', { companyId }, 'AdminCompanyService');
}

/** Soft delete — sets status='deleted', preserves data for audit trail. */
export async function deleteCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status     = 'deleted',
        updated_at = NOW()
    WHERE id = ${companyId}
  `;
  log.info('deleteCompany (soft)', { companyId }, 'AdminCompanyService');
}

export async function getCompanyUsers(
  companyId: string
): Promise<AdminUserCompany[]> {
  const rows = await sql`
    SELECT
      cu.company_id,
      c.name    AS company_name,
      cu.role,
      COALESCE(cu.is_default, false) AS is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.company_id = ${companyId}
    ORDER BY cu.role, c.name
  `;

  return (rows as Row[]).map((r) => ({
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    role: r.role as string,
    is_default: r.is_default as boolean,
  }));
}

/**
 * GL Import Service — WS-6.3 Excel Import Wizard
 * Validates and imports journal entries from spreadsheet uploads.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VatType } from '../types/gl.types';
type Row = Record<string, unknown>;


export interface ImportRow {
  date: string;          // YYYY-MM-DD
  accountCode: string;   // Must exist in gl_accounts for this company
  description: string;
  reference?: string;
  debit: number;
  credit: number;
  vatCode?: string;
  costCentre?: string;
}

export interface ValidationResult {
  row: number;
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface ValidationSummary {
  validations: ValidationResult[];
  validCount: number;
  errorCount: number;
  warningCount: number;
  totalDebit: number;
  totalCredit: number;
  isBalanced: boolean;
}

export interface ImportResult {
  entriesCreated: number;
  linesCreated: number;
  totalValue: number;
}

const VALID_VAT_CODES: VatType[] = [
  'standard', 'zero_rated', 'exempt', 'capital_goods',
  'export', 'imported', 'reverse_charge', 'bad_debt', 'no_vat',
];

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d;
}

export async function validateImportRows(
  companyId: string,
  rows: ImportRow[],
): Promise<ValidationSummary> {
  try {
    // Load chart of accounts for this company
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load open fiscal periods
    const periodRows = (await sql`
      SELECT start_date, end_date
      FROM fiscal_periods
      WHERE company_id = ${companyId}::UUID
        AND status = 'open'
      ORDER BY start_date
    `) as Row[];

    // Load cost centres
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccSet = new Set<string>(ccRows.map((r: Row) => String(r.code).toLowerCase()));

    const validations: ValidationResult[] = [];
    let totalDebit = 0;
    let totalCredit = 0;
    let validCount = 0;
    let errorCount = 0;
    let warningCount = 0;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]!;
      const errors: string[] = [];
      const warnings: string[] = [];
      const rowNum = i + 2; // 1-indexed + header row

      // Description required
      if (!row.description || row.description.trim() === '') {
        errors.push('Description is required');
      }

      // Date validation
      const parsedDate = parseDate(row.date);
      if (!parsedDate) {
        errors.push(`Invalid date: "${row.date}" — expected YYYY-MM-DD`);
      } else {
        // Check if date falls within an open fiscal period
        const inOpenPeriod = periodRows.some((p: Row) => {
          const start = new Date(String(p.start_date));
          const end = new Date(String(p.end_date));
          return parsedDate >= start && parsedDate <= end;
        });
        if (!inOpenPeriod) {
          warnings.push(`Date ${row.date} does not fall within an open fiscal period`);
        }
      }

      // Account code validation
      if (!row.accountCode || row.accountCode.trim() === '') {
        errors.push('Account code is required');
      } else if (!accountMap.has(String(row.accountCode).trim())) {
        errors.push(`Account code "${row.accountCode}" not found in chart of accounts`);
      }

      // Debit / credit validation
      const debit = Number(row.debit) || 0;
      const credit = Number(row.credit) || 0;

      if (debit < 0) errors.push('Debit cannot be negative');
      if (credit < 0) errors.push('Credit cannot be negative');

      if (debit > 0 && credit > 0) {
        errors.push('Debit and credit cannot both be greater than zero on the same line');
      }
      if (debit === 0 && credit === 0) {
        errors.push('At least one of debit or credit must be greater than zero');
      }

      // VAT code validation (optional)
      if (row.vatCode && row.vatCode.trim() !== '') {
        const code = row.vatCode.trim() as VatType;
        if (!VALID_VAT_CODES.includes(code)) {
          errors.push(
            `Invalid VAT code "${row.vatCode}". Valid codes: ${VALID_VAT_CODES.join(', ')}`,
          );
        }
      }

      // Cost centre validation (optional)
      if (row.costCentre && row.costCentre.trim() !== '') {
        if (!ccSet.has(row.costCentre.trim().toLowerCase())) {
          warnings.push(`Cost centre "${row.costCentre}" not found — will be ignored`);
        }
      }

      const valid = errors.length === 0;
      if (valid) {
        validCount++;
        totalDebit += debit;
        totalCredit += credit;
      } else {
        errorCount++;
      }
      if (warnings.length > 0) warningCount++;

      validations.push({ row: rowNum, valid, errors, warnings });
    }

    // For balanced check, only consider valid rows
    const diff = Math.abs(totalDebit - totalCredit);
    const isBalanced = diff < 0.005; // tolerance for floating point

    return {
      validations,
      validCount,
      errorCount,
      warningCount,
      totalDebit,
      totalCredit,
      isBalanced,
    };
  } catch (err) {
    log.error('Failed to validate import rows', { error: err }, 'gl-import');
    throw err;
  }
}

export async function importJournalEntries(
  companyId: string,
  rows: ImportRow[],
  userId: string,
  postImmediately: boolean,
): Promise<ImportResult> {
  try {
    // Load account code → id mapping
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load cost centre code → id mapping
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccMap = new Map<string, string>(
      ccRows.map((r: Row) => [String(r.code).toLowerCase(), String(r.id)]),
    );

    // Group rows into journal entries: same date + same reference = one entry
    const grouped = new Map<string, ImportRow[]>();
    for (const row of rows) {
      const key = `${row.date}||${row.reference || ''}`;
      const group = grouped.get(key) ?? [];
      group.push(row);
      grouped.set(key, group);
    }

    let entriesCreated = 0;
    let linesCreated = 0;
    let totalValue = 0;
    const status = postImmediately ? 'posted' : 'draft';

    for (const [, groupRows] of grouped) {
      const firstRow = groupRows[0]!;

      // Find fiscal period for entry date
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE company_id = ${companyId}::UUID
          AND start_date <= ${firstRow.date}::DATE
          AND end_date >= ${firstRow.date}::DATE
        LIMIT 1
      `) as Row[];
      const fiscalPeriodId = periodRows.length > 0 ? String(periodRows[0]!.id) : null;

      const description = firstRow.reference
        ? `${firstRow.reference}: ${firstRow.description}`
        : firstRow.description;

      const postedBy = postImmediately ? userId : null;

      const entryInsert = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, fiscal_period_id, description,
          source, created_by, status,
          posted_by, posted_at
        ) VALUES (
          ${companyId}::UUID,
          ${firstRow.date}::DATE,
          ${fiscalPeriodId}::UUID,
          ${description},
          'import',
          ${userId}::UUID,
          ${status},
          ${postedBy}::UUID,
          ${postImmediately ? sql`NOW()` : sql`NULL`}
        )
        RETURNING id
      `) as Row[];

      const entryId = String(entryInsert[0].id);
      entriesCreated++;

      for (const row of groupRows) {
        const accountId = accountMap.get(String(row.accountCode).trim());
        if (!accountId) continue; // already validated upstream

        const ccId = row.costCentre
          ? (ccMap.get(row.costCentre.trim().toLowerCase()) ?? null)
          : null;

        const vatType = (row.vatCode?.trim() as VatType) || null;

        await sql`
          INSERT INTO gl_journal_lines (
            journal_entry_id, gl_account_id, debit, credit,
            description, vat_type, cost_center_id
          ) VALUES (
            ${entryId}::UUID,
            ${accountId}::UUID,
            ${Number(row.debit) || 0},
            ${Number(row.credit) || 0},
            ${row.description},
            ${vatType},
            ${ccId}::UUID
          )
        `;

        linesCreated++;
        totalValue += Number(row.debit) || 0;
      }
    }

    log.info('Imported journal entries', {
      companyId, entriesCreated, linesCreated, totalValue, postImmediately,
    }, 'gl-import');

    return { entriesCreated, linesCreated, totalValue };
  } catch (err) {
    log.error('Failed to import journal entries', { error: err }, 'gl-import');
    throw err;
  }
}

/**
 * Time Tracking Service
 * Billable hours and project time management
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = Record<string, unknown>;


export interface TimeEntry {
  id: string;
  companyId: string;
  userId: string;
  projectName: string | null;
  taskDescription: string;
  entryDate: string;
  hours: number;
  rate: number | null;
  amount: number | null;
  billable: boolean;
  invoiced: boolean;
  invoiceId: string | null;
  customerId: string | null;
  customerName: string | null;
  notes: string | null;
  status: string;
  createdAt: string;
  updatedAt: string;
}

export interface TimeEntryInput {
  projectName?: string;
  taskDescription: string;
  entryDate?: string;
  hours: number;
  rate?: number;
  billable?: boolean;
  customerId?: string;
  notes?: string;
}

export interface TimeSummary {
  totalHours: number;
  billableHours: number;
  nonBillableHours: number;
  totalValue: number;
  byProject: { projectName: string; hours: number; value: number }[];
  byCustomer: { customerId: string; customerName: string; hours: number; value: number }[];
}

function mapEntry(r: Row): TimeEntry {
  const hours = Number(r.hours || 0);
  const rate = r.rate != null ? Number(r.rate) : null;
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    userId: String(r.user_id),
    projectName: r.project_name ? String(r.project_name) : null,
    taskDescription: String(r.task_description),
    entryDate: String(r.entry_date),
    hours,
    rate,
    amount: rate != null ? hours * rate : null,
    billable: Boolean(r.billable),
    invoiced: Boolean(r.invoiced),
    invoiceId: r.invoice_id ? String(r.invoice_id) : null,
    customerId: r.customer_id ? String(r.customer_id) : null,
    customerName: r.customer_name ? String(r.customer_name) : null,
    notes: r.notes ? String(r.notes) : null,
    status: String(r.status),
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

/**
 * Helper: call sql as a parameterized query string.
 * The neon() function supports sql(queryString, params[]) in addition to tagged templates.
 */
export async function getTimeEntries(
  companyId: string,
  _filters?: {
    userId?: string;
    customerId?: string;
    projectName?: string;
    status?: string;
    billable?: boolean;
    dateFrom?: string;
    dateTo?: string;
    limit?: number;
    offset?: number;
  },
): Promise<{ entries: TimeEntry[]; total: number }> {
  const lim = _filters?.limit || 50;
  const off = _filters?.offset || 0;

  try {
    const countRows = (await sql`
      SELECT COUNT(*)::int AS cnt FROM time_entries WHERE company_id = ${companyId}::UUID
    `) as Row[];

    const rows = (await sql`
      SELECT te.*, c.name AS customer_name
      FROM time_entries te
      LEFT JOIN customers c ON c.id = te.customer_id
      WHERE te.company_id = ${companyId}::UUID
      ORDER BY te.entry_date DESC, te.created_at DESC
      LIMIT ${lim} OFFSET ${off}
    `) as Row[];

    return {
      entries: rows.map(mapEntry),
      total: Number(countRows[0]?.cnt || 0),
    };
  } catch (err) {
    log.error('getTimeEntries failed', { error: err instanceof Error ? err.message : String(err) }, 'time-tracking');
    return { entries: [], total: 0 };
  }
}

export async function getTimeEntry(
  companyId: string,
  id: string,
): Promise<TimeEntry | null> {
  const rows = (await sql`
    SELECT te.*, c.name AS customer_name
    FROM time_entries te
    LEFT JOIN customers c ON c.id = te.customer_id
    WHERE te.id = ${id}::UUID AND te.company_id = ${companyId}::UUID
  `) as Row[];
  if (!rows.length) return null;
  return mapEntry(rows[0]);
}

export async function createTimeEntry(
  companyId: string,
  input: TimeEntryInput,
  userId: string,
): Promise<TimeEntry> {
  const entryDate = input.entryDate || new Date().toISOString().split('T')[0];
  const rows = (await sql`
    INSERT INTO time_entries (
      company_id, user_id, project_name, task_description, entry_date,
      hours, rate, billable, customer_id, notes
    ) VALUES (
      ${companyId}::UUID, ${userId}::UUID, ${input.projectName || null},
      ${input.taskDescription}, ${entryDate}::DATE,
      ${input.hours}, ${input.rate ?? null},
      ${input.billable !== false}, ${input.customerId || null}::UUID,
      ${input.notes || null}
    ) RETURNING *
  `) as Row[];

  log.info('Created time entry', { id: rows[0]?.id, userId }, 'accounting');
  return mapEntry(rows[0]!);
}

export async function updateTimeEntry(
  companyId: string,
  id: string,
  input: Partial<TimeEntryInput>,
): Promise<TimeEntry> {
  const existing = (await sql`
    SELECT status FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];
  if (!existing.length) throw new Error('Time entry not found');
  if (existing[0].status !== 'draft') throw new Error('Only draft entries can be edited');

  const rows = (await sql`
    UPDATE time_entries SET
      project_name = COALESCE(${input.projectName ?? null}, project_name),
      task_description = COALESCE(${input.taskDescription ?? null}, task_description),
      entry_date = COALESCE(${input.entryDate ?? null}::DATE, entry_date),
      hours = COALESCE(${input.hours ?? null}, hours),
      rate = COALESCE(${input.rate ?? null}, rate),
      billable = COALESCE(${input.billable ?? null}, billable),
      customer_id = COALESCE(${input.customerId ?? null}::UUID, customer_id),
      notes = COALESCE(${input.notes ?? null}, notes),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];

  log.info('Updated time entry', { id }, 'accounting');
  return mapEntry(rows[0]!);
}

export async function deleteTimeEntry(
  companyId: string,
  id: string,
): Promise<void> {
  const existing = (await sql`
    SELECT status FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];
  if (!existing.length) throw new Error('Time entry not found');
  if (existing[0].status !== 'draft') throw new Error('Only draft entries can be deleted');

  await sql`
    DELETE FROM time_entries
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Deleted time entry', { id }, 'accounting');
}

export async function submitEntries(
  companyId: string,
  ids: string[],
): Promise<number> {
  if (!ids.length) return 0;
  const result = (await sql`
    UPDATE time_entries SET status = 'submitted', updated_at = NOW()
    WHERE company_id = ${companyId}::UUID
      AND id = ANY(${ids}::UUID[])
      AND status = 'draft'
  `) as Row[];
  const count = Array.isArray(result) ? result.length : 0;
  log.info('Submitted time entries', { count, ids }, 'accounting');
  return count;
}

export async function approveEntries(
  companyId: string,
  ids: string[],
): Promise<number> {
  if (!ids.length) return 0;
  const result = (await sql`
    UPDATE time_entries SET status = 'approved', updated_at = NOW()
    WHERE company_id = ${companyId}::UUID
      AND id = ANY(${ids}::UUID[])
      AND status = 'submitted'
  `) as Row[];
  const count = Array.isArray(result) ? result.length : 0;
  log.info('Approved time entries', { count, ids }, 'accounting');
  return count;
}

export async function getTimeSummary(
  companyId: string,
  _filters?: { dateFrom?: string; dateTo?: string; userId?: string },
): Promise<TimeSummary> {
  try {
    const totals = (await sql`
      SELECT
        COALESCE(SUM(hours), 0) AS total_hours,
        COALESCE(SUM(CASE WHEN billable THEN hours ELSE 0 END), 0) AS billable_hours,
        COALESCE(SUM(CASE WHEN NOT billable THEN hours ELSE 0 END), 0) AS non_billable_hours,
        COALESCE(SUM(CASE WHEN billable AND rate IS NOT NULL THEN hours * rate ELSE 0 END), 0) AS total_value
      FROM time_entries WHERE company_id = ${companyId}::UUID
    `) as Row[];

    const byProject = (await sql`
      SELECT
        COALESCE(project_name, 'Unassigned') AS project_name,
        SUM(hours) AS hours,
        COALESCE(SUM(CASE WHEN rate IS NOT NULL THEN hours * rate ELSE 0 END), 0) AS value
      FROM time_entries WHERE company_id = ${companyId}::UUID
      GROUP BY COALESCE(project_name, 'Unassigned')
      ORDER BY hours DESC
    `) as Row[];

    const byCustomer = (await sql`
      SELECT
        COALESCE(te.customer_id::TEXT, 'none') AS customer_id,
        COALESCE(c.name, 'No Customer') AS customer_name,
        SUM(te.hours) AS hours,
        COALESCE(SUM(CASE WHEN te.rate IS NOT NULL THEN te.hours * te.rate ELSE 0 END), 0) AS value
      FROM time_entries te
      LEFT JOIN customers c ON c.id = te.customer_id
      WHERE te.company_id = ${companyId}::UUID
      GROUP BY COALESCE(te.customer_id::TEXT, 'none'), COALESCE(c.name, 'No Customer')
      ORDER BY hours DESC
    `) as Row[];

  const t = totals[0] || {};
  return {
    totalHours: Number(t.total_hours || 0),
    billableHours: Number(t.billable_hours || 0),
    nonBillableHours: Number(t.non_billable_hours || 0),
    totalValue: Number(t.total_value || 0),
    byProject: byProject.map((r: Row) => ({
      projectName: String(r.project_name),
      hours: Number(r.hours),
      value: Number(r.value),
    })),
    byCustomer: byCustomer.map((r: Row) => ({
      customerId: String(r.customer_id),
      customerName: String(r.customer_name),
      hours: Number(r.hours),
      value: Number(r.value),
    })),
  };
  } catch (err) {
    log.error('getTimeSummary failed', { error: err instanceof Error ? err.message : String(err) }, 'time-tracking');
    return { totalHours: 0, billableHours: 0, nonBillableHours: 0, totalValue: 0, byProject: [], byCustomer: [] };
  }
}

export async function getUninvoicedEntries(
  companyId: string,
  customerId?: string,
): Promise<TimeEntry[]> {
  let rows: Row[];
  if (customerId) {
    rows = (await sql`
      SELECT te.*, c.name AS customer_name
      FROM time_entries te
      LEFT JOIN customers c ON c.id = te.customer_id
      WHERE te.company_id = ${companyId}::UUID
        AND te.status = 'approved'
        AND te.billable = true
        AND te.invoiced = false
        AND te.customer_id = ${customerId}::UUID
      ORDER BY te.entry_date ASC
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT te.*, c.name AS customer_name
      FROM time_entries te
      LEFT JOIN customers c ON c.id = te.customer_id
      WHERE te.company_id = ${companyId}::UUID
        AND te.status = 'approved'
        AND te.billable = true
        AND te.invoiced = false
      ORDER BY te.entry_date ASC
    `) as Row[];
  }
  return rows.map(mapEntry);
}

export async function markAsInvoiced(
  companyId: string,
  entryIds: string[],
  invoiceId: string,
): Promise<number> {
  if (!entryIds.length) return 0;
  const result = (await sql`
    UPDATE time_entries SET
      invoiced = true,
      invoice_id = ${invoiceId}::UUID,
      status = 'invoiced',
      updated_at = NOW()
    WHERE company_id = ${companyId}::UUID
      AND id = ANY(${entryIds}::UUID[])
      AND status = 'approved'
      AND billable = true
  `) as Row[];
  const count = Array.isArray(result) ? result.length : 0;
  log.info('Marked time entries as invoiced', { count, invoiceId }, 'accounting');
  return count;
}

