/**
 * PRD-060: FibreFlow Accounting Module
 * Chart of Accounts Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import type { GLAccount, GLAccountType } from '../types/gl.types';

export interface CreateAccountInput {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentAccountId?: string;
  description?: string;
  normalBalance: 'debit' | 'credit';
  defaultVatCode?: 'none' | 'standard' | 'zero_rated' | 'exempt';
}

export interface UpdateAccountInput {
  accountName?: string;
  description?: string;
  isActive?: boolean;
  displayOrder?: number;
  defaultVatCode?: 'none' | 'standard' | 'zero_rated' | 'exempt';
}

interface AccountTreeNode extends GLAccount {
  children: AccountTreeNode[];
}

export async function getChartOfAccounts(companyId: string, includeInactive = false): Promise<GLAccount[]> {
  const cacheKey = includeInactive
    ? CACHE_KEYS.glAccountsInactive(companyId)
    : CACHE_KEYS.glAccounts(companyId);

  return cacheThrough(cacheKey, async () => {
    try {
      let rows;
      if (includeInactive) {
        rows = await sql`
          SELECT a.*,
            p.account_code AS parent_code,
            p.account_name AS parent_name
          FROM gl_accounts a
          LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
          WHERE a.company_id = ${companyId}
          ORDER BY a.account_code
        `;
      } else {
        rows = await sql`
          SELECT a.*,
            p.account_code AS parent_code,
            p.account_name AS parent_name
          FROM gl_accounts a
          LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
          WHERE a.company_id = ${companyId}
            AND a.is_active = true
          ORDER BY a.account_code
        `;
      }
      return (rows as { [key: string]: unknown }[]).map(mapRow);
    } catch (err) {
      log.error('Failed to get chart of accounts', { error: err }, 'accounting');
      throw err;
    }
  }, CACHE_TTL.REFERENCE_DATA);
}

export async function getAccountTree(companyId: string, includeInactive = false): Promise<AccountTreeNode[]> {
  const accounts = await getChartOfAccounts(companyId, includeInactive);
  const map = new Map<string, AccountTreeNode>();
  const roots: AccountTreeNode[] = [];

  for (const acc of accounts) {
    map.set(acc.id, { ...acc, children: [] });
  }

  for (const acc of accounts) {
    const node = map.get(acc.id)!;
    if (acc.parentAccountId) {
      const parent = map.get(acc.parentAccountId);
      if (parent) {
        parent.children.push(node);
        continue;
      }
    }
    roots.push(node);
  }

  return roots;
}

export async function getAccountById(companyId: string, id: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE id = ${id} AND company_id = ${companyId}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by id', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountByCode(code: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE account_code = ${code}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by code', { code, error: err }, 'accounting');
    throw err;
  }
}

export async function createAccount(companyId: string, input: CreateAccountInput): Promise<GLAccount> {
  try {
    const existing = await sql`
      SELECT id FROM gl_accounts WHERE account_code = ${input.accountCode} AND company_id = ${companyId}
    `;
    if ((existing as unknown[]).length > 0) {
      throw new Error(`Account code ${input.accountCode} already exists`);
    }

    let level = 1;
    if (input.parentAccountId) {
      const parent = await sql`
        SELECT id, level FROM gl_accounts WHERE id = ${input.parentAccountId}
      ` as { level: number }[];
      if (parent.length === 0) {
        throw new Error(`Parent account ${input.parentAccountId} not found`);
      }
      level = Number(parent[0]!.level) + 1;
    }

    const rows = await sql`
      INSERT INTO gl_accounts (
        company_id, account_code, account_name, account_type, account_subtype,
        parent_account_id, description, normal_balance, level
      ) VALUES (
        ${companyId}, ${input.accountCode}, ${input.accountName}, ${input.accountType},
        ${input.accountSubtype || null}, ${input.parentAccountId || null},
        ${input.description || null}, ${input.normalBalance}, ${level}
      )
      RETURNING *
    `;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to create account', { error: err }, 'accounting');
    throw err;
  }
}

export async function updateAccount(companyId: string, id: string, input: UpdateAccountInput): Promise<GLAccount> {
  try {
    const account = await sql`SELECT * FROM gl_accounts WHERE id = ${id} AND company_id = ${companyId}` as {
      is_system_account: boolean;
    }[];
    if (account.length === 0) throw new Error(`Account ${id} not found`);

    if (account[0]!.is_system_account && input.isActive === false) {
      throw new Error('Cannot deactivate a system account');
    }

    const rows = await sql`
      UPDATE gl_accounts SET
        account_name = COALESCE(${input.accountName || null}, account_name),
        description = COALESCE(${input.description ?? null}, description),
        is_active = COALESCE(${input.isActive ?? null}, is_active),
        display_order = COALESCE(${input.displayOrder ?? null}, display_order),
        default_vat_code = COALESCE(${input.defaultVatCode || null}, default_vat_code)
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to update account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function deleteAccount(companyId: string, id: string): Promise<void> {
  try {
    const lines = await sql`
      SELECT COUNT(*) AS cnt FROM gl_journal_lines WHERE gl_account_id = ${id}
    ` as { cnt: string }[];
    if (Number(lines[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with existing journal entries');
    }

    const children = await sql`
      SELECT COUNT(*) AS cnt FROM gl_accounts WHERE parent_account_id = ${id} AND is_active = true
    ` as { cnt: string }[];
    if (Number(children[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with active child accounts');
    }

    await sql`UPDATE gl_accounts SET is_active = false WHERE id = ${id} AND company_id = ${companyId}`;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
  } catch (err) {
    log.error('Failed to delete account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountBalance(
  accountId: string,
  fiscalPeriodId?: string
): Promise<{ debitTotal: number; creditTotal: number; balance: number }> {
  try {
    let rows: { debit_total: string; credit_total: string; balance: string }[];
    if (fiscalPeriodId) {
      rows = await sql`
        SELECT debit_total, credit_total, balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId} AND fiscal_period_id = ${fiscalPeriodId}
      ` as typeof rows;
    } else {
      rows = await sql`
        SELECT
          COALESCE(SUM(debit_total), 0) AS debit_total,
          COALESCE(SUM(credit_total), 0) AS credit_total,
          COALESCE(SUM(balance), 0) AS balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId}
      ` as typeof rows;
    }

    if (rows.length === 0) {
      return { debitTotal: 0, creditTotal: 0, balance: 0 };
    }

    return {
      debitTotal: Number(rows[0]!.debit_total),
      creditTotal: Number(rows[0]!.credit_total),
      balance: Number(rows[0]!.balance),
    };
  } catch (err) {
    log.error('Failed to get account balance', { accountId, error: err }, 'accounting');
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function mapRow(row: any): GLAccount {
  return {
    id: String(row.id),
    accountCode: String(row.account_code),
    accountName: String(row.account_name),
    accountType: String(row.account_type) as GLAccountType,
    accountSubtype: row.account_subtype ? String(row.account_subtype) : undefined,
    parentAccountId: row.parent_account_id ? String(row.parent_account_id) : undefined,
    isActive: Boolean(row.is_active),
    isSystemAccount: Boolean(row.is_system_account),
    description: row.description ? String(row.description) : undefined,
    normalBalance: String(row.normal_balance) as 'debit' | 'credit',
    level: Number(row.level),
    displayOrder: Number(row.display_order),
    bankAccountNumber: row.bank_account_number ? String(row.bank_account_number) : undefined,
    defaultVatCode: (row.default_vat_code || 'none') as GLAccount['defaultVatCode'],
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Migration Execute Service — import parsed Xero/QuickBooks/Pastel data into ISAFlow
 * Uses existing migrationCoaService and migrationContactService patterns.
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { ParsedAccount, ParsedEntity, MigrationSource } from './migrationParserService';
type Row = Record<string, unknown>;


export interface ExecuteMigrationResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

export interface VerifyEntry {
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}

// ── Execute ──────────────────────────────────────────────────────────────────

export async function executeMigration(
  companyId: string,
  userId: string,
  source: MigrationSource,
  accounts: ParsedAccount[],
  customers: ParsedEntity[],
  suppliers: ParsedEntity[],
): Promise<ExecuteMigrationResult> {
  const errors: string[] = [];
  let accountsImported = 0;
  let customersImported = 0;
  let suppliersImported = 0;
  let openingBalancesSet = 0;

  log.info('Starting migration execution', { companyId, source, accountCount: accounts.length }, 'migration');

  // 1. Import GL accounts
  const validAccounts = accounts.filter(acct => {
    if (!acct.sourceCode && !acct.sourceName) return false;
    if (!acct.mappedType) {
      errors.push(`Account "${acct.sourceCode} ${acct.sourceName}": unmapped type "${acct.sourceType}" — skipped`);
      return false;
    }
    return true;
  });

  if (validAccounts.length > 0) {
    try {
      await transaction((txSql) =>
        validAccounts.map(acct => txSql`
          INSERT INTO gl_accounts (
            company_id, account_code, account_name, account_type, account_subtype,
            normal_balance, description, level, display_order, imported_from
          ) VALUES (
            ${companyId}::UUID,
            ${acct.sourceCode || acct.sourceName.substring(0, 20)},
            ${acct.sourceName},
            ${acct.mappedType},
            ${acct.mappedSubtype ?? null},
            ${acct.mappedNormalBalance ?? 'debit'},
            ${'Imported from ' + source},
            3,
            0,
            ${source}
          )
          ON CONFLICT (company_id, account_code) DO UPDATE SET
            account_name  = EXCLUDED.account_name,
            account_type  = EXCLUDED.account_type,
            imported_from = EXCLUDED.imported_from
        `)
      );
      accountsImported = validAccounts.length;
    } catch (err) {
      errors.push(`Accounts batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Set opening balances via journal entry
  const balanceAccounts = accounts.filter(a => a.openingBalance !== 0 && a.sourceCode && a.mappedType);
  if (balanceAccounts.length > 0) {
    try {
      const jeRows = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, reference, description, status, created_by
        ) VALUES (
          ${companyId}::UUID,
          CURRENT_DATE,
          ${'OB-' + source.toUpperCase()},
          ${'Opening balances imported from ' + source},
          'posted',
          ${userId}::UUID
        ) RETURNING id
      `) as Row[];

      const jeId = String(jeRows[0].id);

      for (const acct of balanceAccounts) {
        const glRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE company_id = ${companyId}::UUID AND account_code = ${acct.sourceCode}
          LIMIT 1
        `) as Row[];

        if (glRows.length === 0) continue;
        const glId = String(glRows[0].id);
        const isDebitNormal = acct.mappedNormalBalance === 'debit';
        const debit  = isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;
        const credit = !isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;

        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${jeId}::UUID, ${glId}::UUID, ${debit}, ${credit}, ${'Opening balance — ' + source})
        `;
        openingBalancesSet++;
      }
    } catch (err) {
      errors.push(`Opening balances: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 3. Import customers
  const validCustomers = customers.filter(c => c.name?.trim());
  if (validCustomers.length > 0) {
    try {
      await transaction((txSql) =>
        validCustomers.map(cust => txSql`
          INSERT INTO customers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${cust.name},
            ${cust.email ?? null},
            ${cust.phone ?? null},
            ${cust.vatNumber ?? null},
            ${cust.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      customersImported = validCustomers.length;
    } catch (err) {
      errors.push(`Customers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 4. Import suppliers
  const validSuppliers = suppliers.filter(s => s.name?.trim());
  if (validSuppliers.length > 0) {
    try {
      await transaction((txSql) =>
        validSuppliers.map(sup => txSql`
          INSERT INTO suppliers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${sup.name},
            ${sup.email ?? null},
            ${sup.phone ?? null},
            ${sup.vatNumber ?? null},
            ${sup.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      suppliersImported = validSuppliers.length;
    } catch (err) {
      errors.push(`Suppliers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  log.info('Migration execution complete', {
    companyId, source, accountsImported, customersImported, suppliersImported,
  }, 'migration');

  return { accountsImported, customersImported, suppliersImported, openingBalancesSet, errors };
}

// ── Verify balances ───────────────────────────────────────────────────────────

export async function verifyBalances(
  companyId: string,
  sourceAccounts: ParsedAccount[],
): Promise<VerifyEntry[]> {
  const results: VerifyEntry[] = [];

  for (const acct of sourceAccounts) {
    if (!acct.sourceCode) continue;

    try {
      const glRows = (await sql`
        SELECT ga.account_name,
          COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_debit,
          ga.normal_balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
        WHERE ga.company_id = ${companyId}::UUID AND ga.account_code = ${acct.sourceCode}
        GROUP BY ga.id, ga.account_name, ga.normal_balance
        LIMIT 1
      `) as Row[];

      const isaflowBalance = glRows.length > 0
        ? (String(glRows[0].normal_balance) === 'debit'
          ? Number(glRows[0].net_debit)
          : -Number(glRows[0].net_debit))
        : 0;

      const difference = acct.openingBalance - isaflowBalance;

      results.push({
        accountCode:    acct.sourceCode,
        sourceName:     acct.sourceName,
        sourceBalance:  acct.openingBalance,
        isaflowBalance,
        difference,
        matched:        Math.abs(difference) < 0.01,
      });
    } catch (err) {
      log.warn('Balance verification failed for account', { code: acct.sourceCode, error: err }, 'migration');
    }
  }

  return results;
}

// ── Rollback ─────────────────────────────────────────────────────────────────

export async function rollbackMigration(
  companyId: string,
  source: MigrationSource,
): Promise<{ deleted: number }> {
  let deleted = 0;

  try {
    // Remove GL accounts imported from this source
    const acctRows = (await sql`
      DELETE FROM gl_accounts
      WHERE company_id = ${companyId}::UUID AND imported_from = ${source}
      RETURNING id
    `) as Row[];
    deleted += acctRows.length;

    log.info('Rollback complete', { companyId, source, deleted }, 'migration');
  } catch (err) {
    log.error('Rollback failed', { companyId, source, error: err }, 'migration');
    throw err;
  }

  return { deleted };
}

