/** Lookup a GL account UUID by account code */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Record<string, unknown>[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0]!.id);
}

/** Convert rule match type to SQL ILIKE pattern */
function toSqlPattern(matchType: string, matchPattern: string): string {
  switch (matchType) {
    case 'contains': return `%${matchPattern}%`;
    case 'starts_with': return `${matchPattern}%`;
    case 'ends_with': return `%${matchPattern}`;
    case 'exact': return matchPattern;
    default: return `%${matchPattern}%`;
  }
}

export async function applyRules(companyId: string, 
  bankAccountId: string,
  userId: string
): Promise<RuleApplyResult> {
  try {
    // Get active rules ordered by priority
    const rules = (await sql`
      SELECT * FROM bank_categorisation_rules
      WHERE is_active = true
      ORDER BY priority ASC
    `) as Record<string, unknown>[];

    if (rules.length === 0) return { applied: 0, skipped: 0, entries: [] };

    let totalApplied = 0;
    const entries: RuleApplyResult['entries'] = [];

    const autoCreateRules = rules.filter((r: Record<string, unknown>) => Boolean(r.auto_create_entry));
    const hasSuggestionRules = rules.some((r: Record<string, unknown>) => !r.auto_create_entry);

    if (hasSuggestionRules) {
      // Single-query approach: JOIN all suggestion-mode rules against all unmatched
      // transactions in one CTE, assign the highest-priority matching rule per tx.
      // ILIKE patterns are generated inline using CASE on match_type column —
      // one network round-trip to Neon regardless of rule count.
      const updated = (await sql`
        WITH matched AS (
          SELECT
            bt.id                                              AS tx_id,
            r.gl_account_id,
            r.supplier_id,
            r.client_id,
            r.rule_name,
            r.vat_code,
            ROW_NUMBER() OVER (PARTITION BY bt.id ORDER BY r.priority ASC) AS rn
          FROM bank_transactions bt
          JOIN bank_categorisation_rules r ON (
            r.is_active = true
            AND r.auto_create_entry = false
            AND (
              (r.match_field IN ('description', 'both')
                AND bt.description ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
              OR
              (r.match_field IN ('reference', 'both')
                AND bt.reference ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
            )
          )
          WHERE bt.bank_account_id = ${bankAccountId}::UUID
            AND bt.status IN ('imported', 'allocated')
            AND bt.suggested_gl_account_id IS NULL
            AND bt.suggested_supplier_id IS NULL
            AND bt.suggested_client_id IS NULL
            AND bt.suggested_category IS NULL
        ),
        top_match AS (SELECT * FROM matched WHERE rn = 1)
        UPDATE bank_transactions bt
        SET
          suggested_gl_account_id = tm.gl_account_id,
          suggested_supplier_id   = tm.supplier_id,
          suggested_client_id     = tm.client_id,
          suggested_category      = tm.rule_name,
          suggested_vat_code      = COALESCE(tm.vat_code, 'none')
        FROM top_match tm
        WHERE bt.id = tm.tx_id
        RETURNING bt.id, tm.rule_name
      `) as Record<string, unknown>[];

      for (const row of updated) {
        entries.push({ bankTxId: String(row.id), ruleName: String(row.rule_name), suggestion: true });
      }
      totalApplied += updated.length;

      // Backfill vat_code for already-suggested transactions (suggested before the vat_code column existed)
      await sql`
        UPDATE bank_transactions bt
        SET suggested_vat_code = r.vat_code
        FROM (
          SELECT DISTINCT ON (rule_name) rule_name, vat_code
          FROM bank_categorisation_rules
          WHERE is_active = true AND vat_code != 'none'
          ORDER BY rule_name, priority ASC
        ) r
        WHERE bt.bank_account_id = ${bankAccountId}::UUID
          AND bt.status IN ('imported', 'allocated')
          AND bt.suggested_category = r.rule_name
          AND bt.suggested_vat_code = 'none'
      `;
    }

    // Auto-create JE mode — sequential (each transaction needs its own JE)
    for (const rule of autoCreateRules) {
      const pattern = toSqlPattern(String(rule.match_type), String(rule.match_pattern));
      const field = String(rule.match_field);
      const ruleName = String(rule.rule_name);

      let matchingTxs: Record<string, unknown>[];
      if (field === 'description') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND description ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else if (field === 'reference') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND reference ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND (description ILIKE ${pattern} OR reference ILIKE ${pattern})
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      }

      for (const tx of matchingTxs) {
        const totalAmount = Math.abs(Number(tx.amount));
        const isDeposit = Number(tx.amount) > 0;
        const entryDesc = rule.description_template
          ? String(rule.description_template).replace('{description}', String(tx.description || '')).replace('{amount}', totalAmount.toFixed(2))
          : `Bank: ${tx.description || 'Categorised by rule'}`;

        // VAT splitting — mirrors allocateTransaction logic
        const vatCode = String(rule.vat_code || 'none');
        const hasVat = vatCode === 'standard';
        const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
        const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
        const vatAccountKey = isDeposit ? 'vat_output' as const : 'vat_input' as const;
        const mapVatType = vatCode === 'standard' ? 'standard' as const
          : vatCode === 'zero_rated' ? 'zero_rated' as const
          : vatCode === 'exempt' ? 'exempt' as const
          : undefined;

        let lines: JournalLineInput[];
        if (isDeposit) {
          lines = [
            { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
            { glAccountId: String(rule.gl_account_id), debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ 15%`, vatType: 'standard' });
          }
        } else {
          lines = [
            { glAccountId: String(rule.gl_account_id), debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
            { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ 15%`, vatType: 'standard' });
          }
        }

        const je = await createJournalEntry(companyId, {
          entryDate: tx.transaction_date instanceof Date
            ? tx.transaction_date.toISOString().split('T')[0]!
            : String(tx.transaction_date).split('T')[0]!,
          description: entryDesc,
          source: 'auto_bank_recon',
          lines,
        }, userId);
        await postJournalEntry('', je.id, userId);

        const bankLineRows = (await sql`
          SELECT id FROM gl_journal_lines
          WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID
          LIMIT 1
        `) as Record<string, unknown>[];

        if (bankLineRows[0]) {
          await sql`
            UPDATE bank_transactions
            SET status = 'allocated', matched_journal_line_id = ${bankLineRows[0].id}::UUID,
                allocation_type = 'account',
                allocated_entity_name = ${ruleName},
                updated_at = NOW()
            WHERE id = ${tx.id}::UUID
          `;
        }

        entries.push({ bankTxId: String(tx.id), ruleName, journalEntryId: je.id });
        totalApplied++;
      }
    }

    // Count remaining unmatched for the skipped total
    const remaining = (await sql`
      SELECT COUNT(*) AS cnt FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status IN ('imported', 'allocated')
        AND suggested_gl_account_id IS NULL
        AND matched_journal_line_id IS NULL
    `) as Record<string, unknown>[];
    const skipped = Number(remaining[0]?.cnt ?? 0);

    log.info('Applied bank rules', { bankAccountId, applied: totalApplied, skipped }, 'accounting');
    return { applied: totalApplied, skipped, entries };
  } catch (err) {
    log.error('Failed to apply bank rules', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapRuleRow(row: Record<string, unknown>): BankCategorisationRule {
  return {
    id: String(row.id),
    ruleName: String(row.rule_name),
    matchField: String(row.match_field) as BankCategorisationRule['matchField'],
    matchType: String(row.match_type) as BankCategorisationRule['matchType'],
    matchPattern: String(row.match_pattern ?? row.match_value ?? ''),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    clientId: row.client_id ? String(row.client_id) : undefined,
    descriptionTemplate: row.description_template ? String(row.description_template) : undefined,
    priority: Number(row.priority),
    isActive: Boolean(row.is_active),
    autoCreateEntry: Boolean(row.auto_create_entry),
    vatCode: (row.vat_code || 'none') as BankCategorisationRule['vatCode'],
    createdBy: row.created_by ? String(row.created_by) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
    glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * EMP201 Generation Service
 * Generates SARS EMP201 (PAYE/UIF/SDL) data from payroll tables.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface EMP201Data {
  periodStart: string;
  periodEnd: string;
  totalPAYE: number;
  totalUIF_employee: number;
  totalUIF_employer: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
  totalTaxableRemuneration: number;
  totalDeductions: number;
  payrollRuns: EMP201PayrollRun[];
}

export interface EMP201PayrollRun {
  id: string;
  runDate: string;
  employeeCount: number;
  grossPay: number;
  paye: number;
  uif: number;
  sdl: number;
}

function roundCents(n: number): number {
  return Math.round(n * 100) / 100;
}

/**
 * Generate EMP201 (monthly PAYE/UIF/SDL) data from payroll tables.
 * Handles missing payroll tables gracefully by returning zero-filled data.
 */
export async function generateEMP201(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<EMP201Data> {
  log.info('Generating EMP201', { periodStart, periodEnd }, 'emp201Service');

  const emptyResult: EMP201Data = {
    periodStart,
    periodEnd,
    totalPAYE: 0,
    totalUIF_employee: 0,
    totalUIF_employer: 0,
    totalUIF: 0,
    totalSDL: 0,
    employeeCount: 0,
    totalTaxableRemuneration: 0,
    totalDeductions: 0,
    payrollRuns: [],
  };

  let hasPayrollTables = false;
  try {
    const tables = (await sql`
      SELECT table_name FROM information_schema.tables
      WHERE table_schema = 'public'
        AND table_name IN ('payroll_runs', 'payslips')
    `) as Row[];
    hasPayrollTables = tables.length >= 2;
  } catch (err) {
    log.warn('Could not check payroll tables', { error: err }, 'emp201Service');
  }

  if (!hasPayrollTables) {
    log.info('Payroll tables not found, returning empty EMP201', {}, 'emp201Service');
    return emptyResult;
  }

  try {
    const runs = (await sql`
      SELECT
        pr.id,
        pr.run_date,
        COUNT(DISTINCT ps.employee_id) AS employee_count,
        COALESCE(SUM(ps.gross_pay), 0) AS gross_pay,
        COALESCE(SUM(ps.paye), 0) AS paye,
        COALESCE(SUM(ps.uif_employee), 0) AS uif_employee,
        COALESCE(SUM(ps.uif_employer), 0) AS uif_employer,
        COALESCE(SUM(ps.sdl), 0) AS sdl
      FROM payroll_runs pr
      LEFT JOIN payslips ps ON ps.payroll_run_id = pr.id
      WHERE pr.run_date >= ${periodStart}
        AND pr.run_date <= ${periodEnd}
        AND pr.status != 'cancelled'
      GROUP BY pr.id, pr.run_date
      ORDER BY pr.run_date
    `) as Row[];

    if (runs.length === 0) return emptyResult;

    let totalPAYE = 0;
    let totalUIFEmployee = 0;
    let totalUIFEmployer = 0;
    let totalSDL = 0;
    let totalGross = 0;

    const payrollRuns: EMP201PayrollRun[] = runs.map((r: Row) => {
      const paye = Number(r.paye) || 0;
      const uifEmp = Number(r.uif_employee) || 0;
      const uifEr = Number(r.uif_employer) || 0;
      const sdl = Number(r.sdl) || 0;
      const gross = Number(r.gross_pay) || 0;

      totalPAYE += paye;
      totalUIFEmployee += uifEmp;
      totalUIFEmployer += uifEr;
      totalSDL += sdl;
      totalGross += gross;

      return {
        id: String(r.id),
        runDate: String(r.run_date),
        employeeCount: Number(r.employee_count) || 0,
        grossPay: roundCents(gross),
        paye: roundCents(paye),
        uif: roundCents(uifEmp + uifEr),
        sdl: roundCents(sdl),
      };
    });

    const totalUIF = roundCents(totalUIFEmployee + totalUIFEmployer);
    const totalDeductions = roundCents(totalPAYE + totalUIF + totalSDL);

    return {
      periodStart,
      periodEnd,
      totalPAYE: roundCents(totalPAYE),
      totalUIF_employee: roundCents(totalUIFEmployee),
      totalUIF_employer: roundCents(totalUIFEmployer),
      totalUIF,
      totalSDL: roundCents(totalSDL),
      employeeCount: payrollRuns.reduce((max, r) => Math.max(max, r.employeeCount), 0),
      totalTaxableRemuneration: roundCents(totalGross),
      totalDeductions,
      payrollRuns,
    };
  } catch (err) {
    log.warn('Error generating EMP201 from payroll data', { error: err }, 'emp201Service');
    return emptyResult;
  }
}

/**
 * Consolidated Reports API
 * GET — consolidated trial balance, income statement, balance sheet, dashboard
 * POST — elimination adjustments
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  getConsolidatedTrialBalance,
  getConsolidatedIncomeStatement,
  getConsolidatedBalanceSheet,
  getGroupDashboardStats,
  getEliminationAdjustments,
  createEliminationAdjustment,
  postEliminationAdjustment,
  reverseEliminationAdjustment,
  autoGenerateEliminations,
} from '@/modules/accounting/services/consolidatedReportingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;
  const groupId = req.query.group_id as string;

  if (req.method === 'GET') {
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');

    if (action === 'trial-balance') {
      const periodStart = req.query.period_start as string;
      const periodEnd = req.query.period_end as string;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'period_start and period_end required');
      const report = await getConsolidatedTrialBalance(groupId, periodStart, periodEnd);
      return apiResponse.success(res, report);
    }

    if (action === 'income-statement') {
      const periodStart = req.query.period_start as string;
      const periodEnd = req.query.period_end as string;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'period_start and period_end required');
      const report = await getConsolidatedIncomeStatement(groupId, periodStart, periodEnd);
      return apiResponse.success(res, report);
    }

    if (action === 'balance-sheet') {
      const asAtDate = req.query.as_at_date as string;
      if (!asAtDate) return apiResponse.badRequest(res, 'as_at_date required');
      const report = await getConsolidatedBalanceSheet(groupId, asAtDate);
      return apiResponse.success(res, report);
    }

    if (action === 'dashboard') {
      const stats = await getGroupDashboardStats(groupId);
      return apiResponse.success(res, stats);
    }

    if (action === 'eliminations') {
      const periodStart = req.query.period_start as string | undefined;
      const periodEnd = req.query.period_end as string | undefined;
      const adjustments = await getEliminationAdjustments(groupId, periodStart, periodEnd);
      return apiResponse.success(res, { items: adjustments });
    }

    return apiResponse.badRequest(res, 'action required: trial-balance, income-statement, balance-sheet, dashboard, eliminations');
  }

  if (req.method === 'POST') {
    if (!groupId && !req.body.groupId) return apiResponse.badRequest(res, 'groupId required');
    const gId = groupId || req.body.groupId;

    if (action === 'create-elimination') {
      const { adjustmentType, description, periodStart, periodEnd, lines } = req.body;
      if (!adjustmentType || !lines?.length) {
        return apiResponse.badRequest(res, 'adjustmentType and lines required');
      }
      const adj = await createEliminationAdjustment(gId, {
        adjustmentType, description, periodStart, periodEnd, lines,
      });
      return apiResponse.success(res, adj);
    }

    if (action === 'post-elimination') {
      const { adjustmentId } = req.body;
      if (!adjustmentId) return apiResponse.badRequest(res, 'adjustmentId required');
      await postEliminationAdjustment(adjustmentId);
      return apiResponse.success(res, { posted: true });
    }

    if (action === 'reverse-elimination') {
      const { adjustmentId } = req.body;
      if (!adjustmentId) return apiResponse.badRequest(res, 'adjustmentId required');
      await reverseEliminationAdjustment(adjustmentId);
      return apiResponse.success(res, { reversed: true });
    }

    if (action === 'auto-eliminate') {
      const { periodStart, periodEnd } = req.body;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'periodStart and periodEnd required');
      const adjustments = await autoGenerateEliminations(gId, periodStart, periodEnd);
      return apiResponse.success(res, { items: adjustments, count: adjustments.length });
    }

    return apiResponse.badRequest(res, 'action required');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

/**
 * Company Groups API
 * GET    — list groups / get single group
 * POST   — create group / add member / manage COA
 * PUT    — update group / update member
 * DELETE — remove member / delete group
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import {
  listGroups,
  getGroup,
  createGroup,
  updateGroup,
  deleteGroup,
  addMember,
  updateMember,
  removeMember,
  getGroupMembers,
  getGroupAccounts,
  createGroupAccount,
  updateGroupAccount,
  deleteGroupAccount,
  autoGenerateGroupCOA,
  getCoaMappings,
  setCoaMapping,
  removeCoaMapping,
  autoMapAccounts,
  getUnmappedAccounts,
} from '@/modules/accounting/services/groupCompanyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const groupId = req.query.group_id as string | undefined;

    if (action === 'members' && groupId) {
      const members = await getGroupMembers(groupId);
      return apiResponse.success(res, { items: members });
    }

    if (action === 'accounts' && groupId) {
      const accounts = await getGroupAccounts(groupId);
      return apiResponse.success(res, { items: accounts });
    }

    if (action === 'mappings' && groupId) {
      const companyId = req.query.company_id as string | undefined;
      if (companyId) {
        const membership = await sql`SELECT 1 FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID LIMIT 1` as Record<string, unknown>[];
        if (!membership[0]) return apiResponse.forbidden(res, 'Access denied to the specified company');
      }
      const mappings = await getCoaMappings(groupId, companyId);
      return apiResponse.success(res, { items: mappings });
    }

    if (action === 'unmapped' && groupId) {
      const companyId = req.query.company_id as string;
      if (!companyId) return apiResponse.badRequest(res, 'company_id required');
      const membership = await sql`SELECT 1 FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID LIMIT 1` as Record<string, unknown>[];
      if (!membership[0]) return apiResponse.forbidden(res, 'Access denied to the specified company');
      const unmapped = await getUnmappedAccounts(groupId, companyId);
      return apiResponse.success(res, { items: unmapped });
    }

    if (groupId) {
      const group = await getGroup(groupId);
      if (!group) return apiResponse.notFound(res, 'Group');
      return apiResponse.success(res, group);
    }

    const groups = await listGroups();
    return apiResponse.success(res, { items: groups });
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    if (action === 'add-member') {
      const { groupId, companyId, ownershipPct, consolidationMethod } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      const member = await addMember(groupId, companyId, {
        ownershipPct: ownershipPct ?? 100,
        consolidationMethod: consolidationMethod ?? 'full',
      });
      return apiResponse.success(res, member);
    }

    if (action === 'create-group-account') {
      const { groupId, accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder } = req.body;
      if (!groupId || !accountCode || !accountName || !accountType) {
        return apiResponse.badRequest(res, 'groupId, accountCode, accountName, accountType required');
      }
      const account = await createGroupAccount(groupId, {
        accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder,
      });
      return apiResponse.success(res, account);
    }

    if (action === 'auto-generate-coa') {
      const { groupId, sourceCompanyId } = req.body;
      if (!groupId || !sourceCompanyId) return apiResponse.badRequest(res, 'groupId and sourceCompanyId required');
      const count = await autoGenerateGroupCOA(groupId, sourceCompanyId);
      return apiResponse.success(res, { accountsCreated: count });
    }

    if (action === 'set-mapping') {
      const { groupId, companyId, companyAccountId, groupAccountId } = req.body;
      if (!groupId || !companyId || !companyAccountId || !groupAccountId) {
        return apiResponse.badRequest(res, 'groupId, companyId, companyAccountId, groupAccountId required');
      }
      const mapping = await setCoaMapping(groupId, companyId, companyAccountId, groupAccountId);
      return apiResponse.success(res, mapping);
    }

    if (action === 'auto-map') {
      const { groupId, companyId } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      const count = await autoMapAccounts(groupId, companyId);
      return apiResponse.success(res, { mappedCount: count });
    }

    // Default POST: create group
    const { name, holdingCompanyId, defaultCurrency, financialYearStart } = req.body;
    if (!name) return apiResponse.badRequest(res, 'name is required');
    const group = await createGroup({ name, holdingCompanyId, defaultCurrency, financialYearStart }, userId);
    return apiResponse.success(res, group);
  }

  // ── PUT ────────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    if (action === 'update-member') {
      const { memberId, ownershipPct, consolidationMethod } = req.body;
      if (!memberId) return apiResponse.badRequest(res, 'memberId required');
      await updateMember(memberId, { ownershipPct, consolidationMethod });
      return apiResponse.success(res, { updated: true });
    }

    if (action === 'update-group-account') {
      const { accountId, ...updates } = req.body;
      if (!accountId) return apiResponse.badRequest(res, 'accountId required');
      const account = await updateGroupAccount(accountId, updates);
      return apiResponse.success(res, account);
    }

    const { groupId, ...updates } = req.body;
    if (!groupId) return apiResponse.badRequest(res, 'groupId required');
    const group = await updateGroup(groupId, updates);
    return apiResponse.success(res, group);
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    if (action === 'remove-member') {
      const memberId = req.query.member_id as string;
      if (!memberId) return apiResponse.badRequest(res, 'member_id required');
      await removeMember(memberId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'remove-mapping') {
      const mappingId = req.query.mapping_id as string;
      if (!mappingId) return apiResponse.badRequest(res, 'mapping_id required');
      await removeCoaMapping(mappingId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'delete-group-account') {
      const accountId = req.query.account_id as string;
      if (!accountId) return apiResponse.badRequest(res, 'account_id required');
      await deleteGroupAccount(accountId);
      return apiResponse.success(res, { deleted: true });
    }

    const groupId = req.query.group_id as string;
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');
    await deleteGroup(groupId);
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}

