import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
type Row = any;

/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig, Pool } from '@neondatabase/serverless';
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the Neon serverless driver.
 *
 * IMPORTANT: The Neon HTTP driver is stateless — each tagged template call is an
 * independent HTTP request. Issuing BEGIN/COMMIT as separate calls does NOT
 * guarantee they run on the same connection. We use the official `transaction()`
 * API from @neondatabase/serverless which batches queries into a single HTTP request.
 *
 * @param queries - Array of query-producing functions that receive the sql client
 * @returns Array of query results
 *
 * @example
 * const results = await transaction([
 *   (sql) => sql`INSERT INTO accounts (name) VALUES (${'Cash'}) RETURNING id`,
 *   (sql) => sql`UPDATE balances SET amount = 0 WHERE account_id = ${id}`,
 * ]);
 */
export async function transaction(
  queriesFn: (txSql: typeof sql) => Array<ReturnType<typeof sql>>
): Promise<unknown[]> {
  try {
    // Reuse module-level sql client instead of creating a new neon() client per call
    const results = await sql.transaction(
      (tx) => queriesFn(tx as unknown as typeof sql) as any,
      { isolationLevel: 'ReadCommitted' }
    );
    return results as unknown[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

/**
 * Execute a sequential, multi-step transaction using a dedicated pool client.
 *
 * Unlike `transaction()` above (which batches static queries in a single HTTP
 * round-trip), `withTransaction` allows intermediate `await` calls inside the
 * callback — necessary when later queries depend on IDs returned by earlier
 * inserts (INSERT … RETURNING id → INSERT … WHERE fk = id).
 *
 * The pool client issues genuine BEGIN / COMMIT / ROLLBACK, giving full ACID
 * guarantees. Any error thrown inside `fn` triggers an automatic ROLLBACK.
 *
 * @example
 * const invoiceId = await withTransaction(async (tx) => {
 *   const [row] = await tx`INSERT INTO invoices (total) VALUES (${total}) RETURNING id`;
 *   await tx`INSERT INTO invoice_items (invoice_id) VALUES (${row.id})`;
 *   return String(row.id);
 * });
 */
let _pool: Pool | null = null;

function getPool(): Pool {
  if (!_pool) {
    _pool = new Pool({
      connectionString: getDatabaseUrl(),
      max: 10,
      connectionTimeoutMillis: 10000,
      idleTimeoutMillis: 30000,
    });
  }
  return _pool;
}

// Type for a transaction-scoped sql tagged-template function
type TxSql = (strings: TemplateStringsArray, ...values: unknown[]) => Promise<unknown[]>;

export async function withTransaction<T>(fn: (tx: TxSql) => Promise<T>): Promise<T> {
  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Wrap the pool client's parameterised query as a tagged-template function
    // so callers can use tx`SELECT ...` instead of raw client.query strings.
    const tx: TxSql = async (strings, ...values) => {
      let text = '';
      strings.forEach((s, i) => {
        text += s;
        if (i < values.length) text += `$${i + 1}`;
      });
      const result = await client.query(text, values as unknown[]);
      return result.rows as unknown[];
    };

    const result = await fn(tx);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    log.error(
      'withTransaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  } finally {
    client.release();
  }
}

export default sql;

/**
 * Customer Quote Service — Sage-parity quotes with convert-to-invoice
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface QuoteLine {
  id: string;
  quoteId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
  accountId: string | null;
}

export interface Quote {
  id: string;
  quoteNumber: string;
  clientId: string | null;
  customerName: string;
  quoteDate: string;
  expiryDate: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  total: number;
  notes: string | null;
  terms: string | null;
  convertedInvoiceId: string | null;
  createdAt: string;
  updatedAt: string;
  lines?: QuoteLine[];
}

interface QuoteFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface QuoteInput {
  customerName: string;
  clientId?: string;
  quoteDate?: string;
  expiryDate?: string;
  notes?: string;
  terms?: string;
  lines: { description: string; quantity: number; unitPrice: number; taxRate?: number; accountId?: string }[];
}

function mapQuote(r: Row): Quote {
  return {
    id: String(r.id), quoteNumber: String(r.quote_number), clientId: r.client_id != null ? String(r.client_id) : null,
    customerName: String(r.customer_name), quoteDate: String(r.quote_date),
    expiryDate: r.expiry_date != null ? String(r.expiry_date) : null, status: String(r.status),
    subtotal: Number(r.subtotal), taxAmount: Number(r.tax_amount),
    total: Number(r.total), notes: r.notes != null ? String(r.notes) : null, terms: r.terms != null ? String(r.terms) : null,
    convertedInvoiceId: r.converted_invoice_id != null ? String(r.converted_invoice_id) : null,
    createdAt: String(r.created_at), updatedAt: String(r.updated_at),
  };
}

function mapLine(r: Row): QuoteLine {
  return {
    id: String(r.id), quoteId: String(r.quote_id), lineNumber: Number(r.line_number),
    description: String(r.description), quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price), taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total), accountId: r.account_id != null ? String(r.account_id) : null,
  };
}

async function nextQuoteNumber(): Promise<string> {
  const rows = (await sql`
    SELECT quote_number FROM customer_quotes ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  if (rows.length === 0) return 'QUO-00001';
  const last = String(rows[0]!.quote_number);
  const num = parseInt(last.replace('QUO-', ''), 10) || 0;
  return `QUO-${String(num + 1).padStart(5, '0')}`;
}

function calcTotals(lines: QuoteInput['lines']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const l of lines) {
    const lt = l.quantity * l.unitPrice;
    subtotal += lt;
    taxAmount += lt * ((l.taxRate ?? 15) / 100);
  }
  return { subtotal: Math.round(subtotal * 100) / 100, taxAmount: Math.round(taxAmount * 100) / 100, total: Math.round((subtotal + taxAmount) * 100) / 100 };
}

export async function getQuotes(companyId: string, filters?: QuoteFilters): Promise<{ quotes: Quote[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT * FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId}`) as Row[];
  }
  return { quotes: rows.map(mapQuote), total: Number(countRows[0]?.cnt || 0) };
}

export async function getQuote(companyId: string, id: string): Promise<Quote | null> {
  // companyId may be empty string for internal calls — skip company filter in that case
  const rows = companyId
    ? (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId}`) as Row[]
    : (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID`) as Row[];
  if (rows.length === 0) return null;
  const quote = mapQuote(rows[0]!);
  const lineRows = (await sql`
    SELECT * FROM customer_quote_lines WHERE quote_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  quote.lines = lineRows.map(mapLine);
  return quote;
}

export async function createQuote(companyId: string, input: QuoteInput, userId?: string): Promise<Quote> {
  const quoteNumber = await nextQuoteNumber();
  const { subtotal, taxAmount, total } = calcTotals(input.lines);
  const qd = input.quoteDate || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_quotes (company_id, quote_number, client_id, customer_name, quote_date, expiry_date,
      subtotal, tax_amount, total, notes, terms, created_by)
    VALUES (${companyId}, ${quoteNumber}, ${input.clientId || null}, ${input.customerName}, ${qd},
      ${input.expiryDate || null}, ${subtotal}, ${taxAmount}, ${total},
      ${input.notes || null}, ${input.terms || null}, ${userId || null})
    RETURNING *
  `) as Row[];

  const quote = mapQuote(rows[0]!);
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${quote.id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote created', { quoteNumber, total });
  return (await getQuote('', quote.id))!;
}

export async function updateQuote(companyId: string, id: string, input: QuoteInput): Promise<Quote | null> {
  const existing = await getQuote('', id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, total } = calcTotals(input.lines);

  await sql`
    UPDATE customer_quotes SET customer_name = ${input.customerName}, client_id = ${input.clientId || null},
      quote_date = ${input.quoteDate || existing.quoteDate}, expiry_date = ${input.expiryDate || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total = ${total},
      notes = ${input.notes || null}, terms = ${input.terms || null}, updated_at = NOW()
    WHERE id = ${id}::UUID AND status = 'draft'
  `;
  await sql`DELETE FROM customer_quote_lines WHERE quote_id = ${id}::UUID`;
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote updated', { id });
  return getQuote('', id);
}

export async function deleteQuote(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`DELETE FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId} AND status = 'draft' RETURNING id`) as Row[];
  return rows.length > 0;
}

export async function updateQuoteStatus(companyId: string, id: string, status: string): Promise<Quote | null> {
  await sql`UPDATE customer_quotes SET status = ${status}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Quote status changed', { id, status });
  return getQuote('', id);
}

export async function convertToInvoice(companyId: string, id: string, userId?: string): Promise<{ quote: Quote; invoiceId: string } | null> {
  const quote = await getQuote(companyId, id);
  if (!quote || quote.status !== 'accepted') return null;

  // Create invoice from quote
  const invRows = (await sql`
    INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date, subtotal, tax_amount, total, notes, status, created_by)
    VALUES (${companyId}, ${quote.clientId}, ${quote.quoteDate}, ${quote.expiryDate || quote.quoteDate}, ${quote.subtotal},
      ${quote.taxAmount}, ${quote.total}, ${'Converted from ' + quote.quoteNumber}, 'draft', ${userId || null})
    RETURNING id
  `) as Row[];
  const invoiceId = String(invRows[0]!.id);

  // Copy lines
  for (const line of quote.lines || []) {
    await sql`
      INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${invoiceId}::UUID, ${line.description}, ${line.quantity}, ${line.unitPrice}, ${line.taxRate}, ${line.lineTotal}, ${line.accountId})
    `;
  }

  await sql`UPDATE customer_quotes SET status = 'converted', converted_invoice_id = ${invoiceId}::UUID, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Quote converted to invoice', { quoteId: id, invoiceId });
  return { quote: (await getQuote('', id))!, invoiceId };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Credit Note Service (Customer & Supplier)
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import type { CreditNote, CreditNoteCreateInput, CreditNoteStatus } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

interface CreditNoteFilters {
  type?: 'customer' | 'supplier';
  status?: CreditNoteStatus;
  limit?: number;
  offset?: number;
}

export async function getCreditNotes(companyId: string, filters?: CreditNoteFilters): Promise<{
  creditNotes: CreditNote[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Record<string, unknown>[];
    let countRows: Record<string, unknown>[];

    if (filters?.type) {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId} AND cn.type = ${filters.type}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId} AND type = ${filters.type}
      `) as Record<string, unknown>[];
    } else {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Record<string, unknown>[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId}`) as Record<string, unknown>[];
    }

    return { creditNotes: rows.map(mapRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get credit notes', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCreditNoteById(companyId: string, id: string): Promise<CreditNote | null> {
  const rows = (await sql`
    SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
      COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
    FROM credit_notes cn
    LEFT JOIN customers c ON c.id = cn.client_id
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
    WHERE cn.id = ${id}::UUID AND cn.company_id = ${companyId}
  `) as Record<string, unknown>[];
  return rows.length > 0 ? mapRow(rows[0]!) : null;
}

export async function createCreditNote(companyId: string, 
  input: CreditNoteCreateInput,
  userId: string
): Promise<CreditNote> {
  try {
    const taxRate = input.taxRate ?? 15;
    const taxAmount = Math.round(input.subtotal * taxRate / 100 * 100) / 100;
    const totalAmount = input.subtotal + taxAmount;

    const rows = (await sql`
      INSERT INTO credit_notes (
        type, client_id, customer_invoice_id, supplier_id, supplier_invoice_id,
        credit_date, reason, subtotal, tax_rate, tax_amount, total_amount,
        project_id, created_by
      ) VALUES (
        ${input.type}, ${input.clientId || null}, ${input.customerInvoiceId || null},
        ${input.supplierId ? Number(input.supplierId) : null},
        ${input.supplierInvoiceId || null},
        ${input.creditDate}, ${input.reason || null},
        ${input.subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${input.projectId || null}, ${userId}::UUID
      ) RETURNING *
    `) as Record<string, unknown>[];

    log.info('Created credit note', { id: String(rows[0]!.id), type: input.type }, 'accounting');
    return mapRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create credit note', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveCreditNote(companyId: string, id: string, userId: string): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'draft') throw new Error(`Cannot approve credit note with status: ${cn.status}`);

    let lines: JournalLineInput[];

    if (String(cn.type) === 'customer') {
      // Customer CN: DR Revenue, CR Accounts Receivable
      const revenueAccount = await getSystemAccount('default_revenue');
      const arAccount = await getSystemAccount('receivable');
      const vatAccount = await getSystemAccount('vat_output');

      lines = [
        { glAccountId: revenueAccount.id, debit: Number(cn.subtotal), credit: 0,
          description: `Credit note ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: Number(cn.tax_amount), credit: 0,
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: arAccount.id, debit: 0, credit: Number(cn.total_amount),
        description: `AR credit: ${cn.credit_note_number}` });
    } else {
      // Supplier CN: DR Accounts Payable, CR Expense
      const apAccount = await getSystemAccount('payable');
      const expenseAccount = await getSystemAccount('default_expense');
      const vatAccount = await getSystemAccount('vat_input');

      lines = [
        { glAccountId: apAccount.id, debit: Number(cn.total_amount), credit: 0,
          description: `AP credit: ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: 0, credit: Number(cn.tax_amount),
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: expenseAccount.id, debit: 0, credit: Number(cn.subtotal),
        description: `Expense credit: ${cn.credit_note_number}` });
    }

    const je = await createJournalEntry('', {
      entryDate: String(cn.credit_date),
      description: `Credit note ${cn.credit_note_number}`,
      source: 'auto_credit_note',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry('', je.id, userId);

    // Update invoice balance and credit note status atomically
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes SET status = 'approved', approved_by = ${userId}::UUID,
          approved_at = NOW(), gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Record<string, unknown>[];

      return rows[0] as Record<string, unknown>;
    });

    log.info('Approved credit note', { id, journalEntryId: je.id }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to approve credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCreditNote(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Record<string, unknown>[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'approved') {
      throw new Error(`Cannot cancel credit note with status: ${cn.status}`);
    }

    // Reverse GL journal entry
    if (cn.gl_journal_entry_id) {
      await reverseJournalEntry('', String(cn.gl_journal_entry_id), userId);
    }

    // Reverse invoice balance adjustments
    if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
      await sql`
        UPDATE customer_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
      await sql`
        UPDATE customer_invoices SET status = CASE
          WHEN amount_paid <= 0.01 THEN 'approved'
          WHEN amount_paid < total_amount THEN 'partially_paid'
          ELSE status
        END
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
    } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
      await sql`
        UPDATE supplier_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.supplier_invoice_id}::UUID
      `;
    }

    const updated = (await sql`
      UPDATE credit_notes
      SET status = 'cancelled', cancelled_by = ${userId}::UUID,
          cancelled_at = NOW(), cancel_reason = ${reason || null}
      WHERE id = ${id} RETURNING *
    `) as Record<string, unknown>[];

    log.info('Cancelled credit note', { id, reason }, 'accounting');
    return mapRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Purchase Order DB Service
 * All SQL for supplier_purchase_orders and supplier_purchase_order_items.
 * Pure business logic (validation, calculations) stays in procurementService.ts.
 */

import sql from '@/lib/neon';

export interface PurchaseOrderItem {
  description: string;
  quantity: number;
  unit_price: number;
  tax_rate: number;
}

export interface CreatePurchaseOrderInput {
  companyId: string;
  userId: string;
  supplier_id: string;
  order_date: string;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items: PurchaseOrderItem[];
}

export interface UpdatePurchaseOrderInput {
  id: string;
  companyId: string;
  supplier_id?: string | null;
  order_date?: string | null;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items?: PurchaseOrderItem[];
}

export interface ListPurchaseOrdersInput {
  companyId: string;
  status?: string | null;
  search?: string | null;
  limit?: number;
  offset?: number;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function calcTotals(items: PurchaseOrderItem[]) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    subtotal += lineTotal;
    taxAmount += lineTax;
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

async function insertLineItems(purchaseOrderId: string, items: PurchaseOrderItem[]) {
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    await sql`
      INSERT INTO supplier_purchase_order_items (
        purchase_order_id, description, quantity, unit_price, tax_rate,
        line_total, tax_amount
      ) VALUES (
        ${purchaseOrderId}::UUID,
        ${item.description},
        ${item.quantity},
        ${item.unit_price},
        ${item.tax_rate},
        ${Math.round(lineTotal * 100) / 100},
        ${Math.round(lineTax * 100) / 100}
      )
    `;
  }
}

async function fetchItems(purchaseOrderId: string) {
  return sql`
    SELECT * FROM supplier_purchase_order_items
    WHERE purchase_order_id = ${purchaseOrderId}::UUID
    ORDER BY created_at ASC
  `;
}

// ─── Order number ─────────────────────────────────────────────────────────────

export async function generateOrderNumber(companyId: string): Promise<string> {
  const rows = await sql`
    UPDATE company_document_numbers
    SET next_number = next_number + 1
    WHERE company_id = ${companyId}::UUID AND document_type = 'purchase_order'
    RETURNING prefix, next_number - 1 AS current_number, padding
  `;

  if (rows.length === 0) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, 'purchase_order', 'PO', 2, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
    return 'PO-0000001';
  }

  const row = rows[0]!;
  return `${row.prefix}-${String(row.current_number).padStart(row.padding, '0')}`;
}

// ─── Queries ──────────────────────────────────────────────────────────────────

export async function getPurchaseOrder(id: string, companyId: string) {
  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.id = ${id}::UUID AND po.company_id = ${companyId}::UUID
  `;
  if (orders.length === 0) return null;
  const items = await fetchItems(id);
  return { order: orders[0]!, items };
}

export async function listPurchaseOrders(input: ListPurchaseOrdersInput) {
  const { companyId, status, search, limit = 100, offset = 0 } = input;
  const take = Math.min(limit, 500);
  const statusFilter = status ?? null;
  const searchTerm = search ? `%${search}%` : null;

  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
    ORDER BY po.created_at DESC
    LIMIT ${take} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::INT AS total
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
  `;

  return { orders, total: countResult[0]?.total ?? 0 };
}

// ─── Mutations ────────────────────────────────────────────────────────────────

export async function createPurchaseOrder(input: CreatePurchaseOrderInput) {
  const { companyId, userId, items } = input;
  const orderNumber = await generateOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(items);

  const created = await sql`
    INSERT INTO supplier_purchase_orders (
      company_id, supplier_id, order_number, order_date, delivery_date,
      reference, notes, internal_notes, status,
      subtotal, tax_amount, total_amount, created_by
    ) VALUES (
      ${companyId}::UUID,
      ${input.supplier_id}::UUID,
      ${orderNumber},
      ${input.order_date}::DATE,
      ${input.delivery_date ?? null}::DATE,
      ${input.reference ?? null},
      ${input.notes ?? null},
      ${input.internal_notes ?? null},
      'draft',
      ${subtotal},
      ${taxAmount},
      ${totalAmount},
      ${userId}::UUID
    )
    RETURNING *
  `;

  const order = created[0]!;
  await insertLineItems(order.id, items);
  const orderItems = await fetchItems(order.id);
  return { order, items: orderItems };
}

export async function updatePurchaseOrder(input: UpdatePurchaseOrderInput) {
  const { id, companyId, items } = input;

  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  let subtotal: number | null = null;
  let taxAmount: number | null = null;
  let totalAmount: number | null = null;

  if (items && items.length > 0) {
    const totals = calcTotals(items);
    subtotal = totals.subtotal;
    taxAmount = totals.taxAmount;
    totalAmount = totals.totalAmount;
  }

  const updated = await sql`
    UPDATE supplier_purchase_orders SET
      supplier_id    = COALESCE(${input.supplier_id ?? null}::UUID, supplier_id),
      order_date     = COALESCE(${input.order_date ?? null}::DATE, order_date),
      delivery_date  = COALESCE(${input.delivery_date ?? null}::DATE, delivery_date),
      reference      = COALESCE(${input.reference ?? null}, reference),
      notes          = COALESCE(${input.notes ?? null}, notes),
      internal_notes = COALESCE(${input.internal_notes ?? null}, internal_notes),
      subtotal       = COALESCE(${subtotal}, subtotal),
      tax_amount     = COALESCE(${taxAmount}, tax_amount),
      total_amount   = COALESCE(${totalAmount}, total_amount),
      updated_at     = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `;

  if (items && items.length > 0) {
    await sql`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
    await insertLineItems(id, items);
  }

  const orderItems = await fetchItems(id);

