/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Payment Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import { validatePaymentAllocations } from '../utils/paymentAllocation';
import type {
  SupplierPayment,
  PaymentAllocation,
  PaymentAllocationInput,
  PaymentMethod,
  PaymentStatus,
  InvoiceForAllocation,
} from '../types/ap.types';
import type { JournalLineInput } from '../types/gl.types';
type Row = Record<string, unknown>;


interface PaymentFilters {
  status?: PaymentStatus;
  supplierId?: number;
  limit?: number;
  offset?: number;
}

export interface CreatePaymentInput {
  supplierId: number;
  paymentDate: string;
  totalAmount: number;
  paymentMethod?: PaymentMethod;
  bankAccountId?: string;
  reference?: string;
  description?: string;
  allocations: PaymentAllocationInput[];
}

export async function getSupplierPayments(companyId: string, filters?: PaymentFilters): Promise<{
  payments: SupplierPayment[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status} AND sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments
        WHERE status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.status = ${filters.status}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        WHERE sp.supplier_id = ${filters.supplierId}
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_payments WHERE supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT sp.*, s.name AS supplier_name
        FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
        ORDER BY sp.payment_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_payments`) as Row[];
    }

    return { payments: rows.map(mapPaymentRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier payments', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierPaymentById(companyId: string, 
  id: string
): Promise<(SupplierPayment & { allocations: PaymentAllocation[] }) | null> {
  try {
    const rows = (await sql`
      SELECT sp.*, s.name AS supplier_name
      FROM supplier_payments sp LEFT JOIN suppliers s ON s.id = sp.supplier_id
      WHERE sp.id = ${id}
    `) as Row[];
    if (rows.length === 0) return null;

    const allocRows = (await sql`
      SELECT pa.*, si.invoice_number
      FROM payment_allocations pa
      LEFT JOIN supplier_invoices si ON si.id = pa.invoice_id
      WHERE pa.payment_id = ${id}
    `) as Row[];

    return { ...mapPaymentRow(rows[0]!), allocations: allocRows.map(mapAllocationRow) };
  } catch (err) {
    log.error('Failed to get supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierPayment(companyId: string, 
  input: CreatePaymentInput,
  userId: string
): Promise<SupplierPayment> {
  try {
    // Load invoices for allocation validation
    const invoiceIds = input.allocations.map(a => a.invoiceId);
    const invoiceRows = (await sql`
      SELECT id, invoice_number, total_amount, amount_paid, balance
      FROM supplier_invoices
      WHERE id = ANY(${invoiceIds}::UUID[])
    `) as Row[];

    const invoices: InvoiceForAllocation[] = invoiceRows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const validation = validatePaymentAllocations(input.totalAmount, input.allocations, invoices);
    if (!validation.valid) {
      throw new Error(`Invalid allocations: ${validation.errors.join('; ')}`);
    }

    const paymentRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_payments (
          supplier_id, payment_date, total_amount, payment_method,
          bank_account_id, reference, description, created_by
        ) VALUES (
          ${input.supplierId}, ${input.paymentDate}, ${input.totalAmount},
          ${input.paymentMethod || 'eft'}, ${input.bankAccountId || null},
          ${input.reference || null}, ${input.description || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const paymentId = String(rows[0]!.id);

      for (const alloc of input.allocations) {
        await tx`
          INSERT INTO payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}::UUID, ${alloc.invoiceId}::UUID, ${alloc.amount})
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier payment', {
      paymentId: String(paymentRow.id),
      paymentNumber: String(paymentRow.payment_number),
      totalAmount: input.totalAmount,
    }, 'accounting');

    return mapPaymentRow(paymentRow);
  } catch (err) {
    log.error('Failed to create supplier payment', { error: err }, 'accounting');
    throw err;
  }
}

export async function processSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'approved') throw new Error(`Payment must be approved before processing`);

    // Auto-post GL entry: DR Accounts Payable, CR Bank
    const apAccount = await getSystemAccount('payable');
    const bankAccount = payment.bankAccountId
      ? ((await sql`SELECT * FROM gl_accounts WHERE id = ${payment.bankAccountId}`) as Row[])[0]
      : await getSystemAccount('bank');

    if (!bankAccount) throw new Error('Bank account not found');

    const lines: JournalLineInput[] = [
      {
        glAccountId: apAccount.id,
        debit: payment.totalAmount,
        credit: 0,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
      {
        glAccountId: String(bankAccount.id),
        debit: 0,
        credit: payment.totalAmount,
        description: `Payment ${payment.paymentNumber} to supplier`,
      },
    ];

    const journalEntry = await createJournalEntry('', {
      entryDate: payment.paymentDate,
      description: `Supplier payment ${payment.paymentNumber}`,
      source: 'auto_supplier_payment',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry('', journalEntry.id, userId);

    // Update invoice balances and mark payment processed atomically
    const updated = await withTransaction(async (tx) => {
      for (const alloc of payment.allocations) {
        await tx`
          UPDATE supplier_invoices
          SET amount_paid = amount_paid + ${alloc.amountAllocated}
          WHERE id = ${alloc.invoiceId}
        `;
        await tx`
          UPDATE supplier_invoices SET status = CASE
            WHEN (total_amount - amount_paid) <= 0.01 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partially_paid'
            ELSE status
          END
          WHERE id = ${alloc.invoiceId}
        `;
      }

      const rows = (await tx`
        UPDATE supplier_payments
        SET status = 'processed', processed_at = NOW(),
            gl_journal_entry_id = ${journalEntry.id}::UUID
        WHERE id = ${id}
        RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Processed supplier payment', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapPaymentRow(updated);
  } catch (err) {
    log.error('Failed to process supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierPayment(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierPayment> {
  try {
    const payment = await getSupplierPaymentById('', id);
    if (!payment) throw new Error(`Payment ${id} not found`);
    if (payment.status !== 'draft') throw new Error(`Cannot approve payment with status: ${payment.status}`);

    const rows = (await sql`
      UPDATE supplier_payments
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW()
      WHERE id = ${id}
      RETURNING *
    `) as Row[];

    return mapPaymentRow(rows[0]!);
  } catch (err) {
    log.error('Failed to approve supplier payment', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapPaymentRow(row: Row): SupplierPayment {
  return {
    id: String(row.id),
    paymentNumber: row.payment_number ? String(row.payment_number) : '',
    supplierId: String(row.supplier_id),
    paymentDate: String(row.payment_date),
    totalAmount: Number(row.total_amount),
    paymentMethod: String(row.payment_method) as SupplierPayment['paymentMethod'],
    bankAccountId: row.bank_account_id ? String(row.bank_account_id) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    description: row.description ? String(row.description) : undefined,
    status: String(row.status) as SupplierPayment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    batchId: row.batch_id ? String(row.batch_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    processedAt: row.processed_at ? String(row.processed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
  };
}

function mapAllocationRow(row: Row): PaymentAllocation {
  return {
    id: String(row.id),
    paymentId: String(row.payment_id),
    invoiceId: String(row.invoice_id),
    amountAllocated: Number(row.amount_allocated),
    createdAt: String(row.created_at),
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * AP Aging Report Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { calculateAgingBuckets } from '../utils/aging';
import type { AgingBucket, AgingInvoice } from '../types/ap.types';
type Row = Record<string, unknown>;


export async function getAPAging(companyId: string, asAtDate?: string): Promise<AgingBucket[]> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const rows = (await sql`
      SELECT si.id, si.supplier_id AS entity_id, s.name AS entity_name,
        si.due_date, si.total_amount, si.amount_paid, si.balance
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.status IN ('approved', 'partially_paid')
        AND si.balance > 0
        AND si.due_date IS NOT NULL
      ORDER BY si.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    return calculateAgingBuckets(invoices, asAt);
  } catch (err) {
    log.error('Failed to get AP aging', { error: err }, 'accounting');
    throw err;
  }
}

export async function getAPAgingDetail(companyId: string, 
  supplierId: string,
  asAtDate?: string
): Promise<{ supplier: { id: string; name: string }; invoices: AgingInvoice[]; buckets: AgingBucket | null }> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const supplierRows = (await sql`SELECT id, name FROM suppliers WHERE id = ${Number(supplierId)}`) as Row[];
    if (supplierRows.length === 0) throw new Error(`Supplier ${supplierId} not found`);

    const rows = (await sql`
      SELECT si.id, si.supplier_id AS entity_id, s.name AS entity_name,
        si.due_date, si.invoice_number, si.total_amount, si.amount_paid, si.balance
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.supplier_id = ${Number(supplierId)}
        AND si.status IN ('approved', 'partially_paid')
        AND si.balance > 0
        AND si.due_date IS NOT NULL
      ORDER BY si.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const buckets = calculateAgingBuckets(invoices, asAt);

    return {
      supplier: { id: String(supplierRows[0]!.id), name: String(supplierRows[0]!.name) },
      invoices,
      buckets: buckets.length > 0 ? buckets[0]! : null,
    };
  } catch (err) {
    log.error('Failed to get AP aging detail', { supplierId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * Phase 2: Bank Categorisation Rules Service
 * Quick entry rules + statement mapping for auto-categorisation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type {
  BankCategorisationRule, RuleCreateInput, RuleApplyResult,
} from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// ── CRUD ────────────────────────────────────────────────────────────────────

export async function getRules(companyId: string): Promise<BankCategorisationRule[]> {
  const rows = (await sql`
    SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name,
           s.company_name AS supplier_name, c.name AS client_name
    FROM bank_categorisation_rules r
    LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
    LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN customers c ON c.id = r.client_id
    WHERE r.company_id = ${companyId}::UUID
    ORDER BY r.priority ASC, r.rule_name ASC
  `) as Record<string, unknown>[];
  return rows.map(mapRuleRow);
}

export async function createRule(companyId: string, input: RuleCreateInput, userId: string): Promise<BankCategorisationRule> {
  const vatCode = input.vatCode || 'none';
  const rows = (await sql`
    INSERT INTO bank_categorisation_rules (
      company_id, rule_name, match_field, match_type, match_pattern,
      gl_account_id, supplier_id, client_id, description_template,
      priority, auto_create_entry, vat_code, created_by
    ) VALUES (
      ${companyId}::UUID, ${input.ruleName}, ${input.matchField}, ${input.matchType}, ${input.matchPattern},
      ${input.glAccountId || null}::UUID, ${input.supplierId || null}::UUID,
      ${input.clientId || null}::UUID,
      ${input.descriptionTemplate || null},
      ${input.priority || 100}, ${input.autoCreateEntry !== false}, ${vatCode}, ${userId}
    ) RETURNING *
  `) as Record<string, unknown>[];
  log.info('Created bank rule', { id: rows[0]!.id, ruleName: input.ruleName }, 'accounting');
  return mapRuleRow(rows[0]!);
}

export async function updateRule(companyId: string, id: string, input: Partial<RuleCreateInput>): Promise<BankCategorisationRule> {
  const rows = (await sql`
    UPDATE bank_categorisation_rules SET
      rule_name = COALESCE(${input.ruleName || null}, rule_name),
      match_field = COALESCE(${input.matchField || null}, match_field),
      match_type = COALESCE(${input.matchType || null}, match_type),
      match_pattern = COALESCE(${input.matchPattern || null}, match_pattern),
      gl_account_id = COALESCE(${input.glAccountId || null}::UUID, gl_account_id),
      supplier_id = COALESCE(${input.supplierId || null}::UUID, supplier_id),
      client_id = COALESCE(${input.clientId || null}::UUID, client_id),
      description_template = COALESCE(${input.descriptionTemplate || null}, description_template),
      priority = COALESCE(${input.priority || null}, priority),
      auto_create_entry = COALESCE(${input.autoCreateEntry ?? null}, auto_create_entry),
      vat_code = COALESCE(${input.vatCode || null}, vat_code)
    WHERE id = ${id}::UUID RETURNING *
  `) as Record<string, unknown>[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRuleRow(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM bank_categorisation_rules WHERE id = ${id}::UUID`;
}

export async function deleteRules(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  const rows = await sql`
    DELETE FROM bank_categorisation_rules
    WHERE id = ANY(${ids}::UUID[])
    RETURNING id
  ` as { id: string }[];
  return rows.length;
}

export async function toggleRule(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE bank_categorisation_rules SET is_active = ${isActive} WHERE id = ${id}::UUID`;
}

// ── Apply Rules ─────────────────────────────────────────────────────────────

/** Lookup a GL account UUID by account code */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Record<string, unknown>[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0]!.id);
}

/** Convert rule match type to SQL ILIKE pattern */
function toSqlPattern(matchType: string, matchPattern: string): string {
  switch (matchType) {
    case 'contains': return `%${matchPattern}%`;
    case 'starts_with': return `${matchPattern}%`;
    case 'ends_with': return `%${matchPattern}`;
    case 'exact': return matchPattern;
    default: return `%${matchPattern}%`;
  }
}

export async function applyRules(companyId: string, 
  bankAccountId: string,
  userId: string
): Promise<RuleApplyResult> {
  try {
    // Get active rules ordered by priority
    const rules = (await sql`
      SELECT * FROM bank_categorisation_rules
      WHERE is_active = true
      ORDER BY priority ASC
    `) as Record<string, unknown>[];

    if (rules.length === 0) return { applied: 0, skipped: 0, entries: [] };

    let totalApplied = 0;
    const entries: RuleApplyResult['entries'] = [];

    const autoCreateRules = rules.filter((r: Record<string, unknown>) => Boolean(r.auto_create_entry));
    const hasSuggestionRules = rules.some((r: Record<string, unknown>) => !r.auto_create_entry);

    if (hasSuggestionRules) {
      // Single-query approach: JOIN all suggestion-mode rules against all unmatched
      // transactions in one CTE, assign the highest-priority matching rule per tx.
      // ILIKE patterns are generated inline using CASE on match_type column —
      // one network round-trip to Neon regardless of rule count.
      const updated = (await sql`
        WITH matched AS (
          SELECT
            bt.id                                              AS tx_id,
            r.gl_account_id,
            r.supplier_id,
            r.client_id,
            r.rule_name,
            r.vat_code,
            ROW_NUMBER() OVER (PARTITION BY bt.id ORDER BY r.priority ASC) AS rn
          FROM bank_transactions bt
          JOIN bank_categorisation_rules r ON (
            r.is_active = true
            AND r.auto_create_entry = false
            AND (
              (r.match_field IN ('description', 'both')
                AND bt.description ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
              OR
              (r.match_field IN ('reference', 'both')
                AND bt.reference ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
            )
          )
          WHERE bt.bank_account_id = ${bankAccountId}::UUID
            AND bt.status IN ('imported', 'allocated')
            AND bt.suggested_gl_account_id IS NULL
            AND bt.suggested_supplier_id IS NULL
            AND bt.suggested_client_id IS NULL
            AND bt.suggested_category IS NULL
        ),
        top_match AS (SELECT * FROM matched WHERE rn = 1)
        UPDATE bank_transactions bt
        SET
          suggested_gl_account_id = tm.gl_account_id,
          suggested_supplier_id   = tm.supplier_id,
          suggested_client_id     = tm.client_id,
          suggested_category      = tm.rule_name,
          suggested_vat_code      = COALESCE(tm.vat_code, 'none')
        FROM top_match tm
        WHERE bt.id = tm.tx_id
        RETURNING bt.id, tm.rule_name
      `) as Record<string, unknown>[];

      for (const row of updated) {
        entries.push({ bankTxId: String(row.id), ruleName: String(row.rule_name), suggestion: true });
      }
      totalApplied += updated.length;

      // Backfill vat_code for already-suggested transactions (suggested before the vat_code column existed)
      await sql`
        UPDATE bank_transactions bt
        SET suggested_vat_code = r.vat_code
        FROM (
          SELECT DISTINCT ON (rule_name) rule_name, vat_code
          FROM bank_categorisation_rules
          WHERE is_active = true AND vat_code != 'none'
          ORDER BY rule_name, priority ASC
        ) r
        WHERE bt.bank_account_id = ${bankAccountId}::UUID
          AND bt.status IN ('imported', 'allocated')
          AND bt.suggested_category = r.rule_name
          AND bt.suggested_vat_code = 'none'
      `;
    }

    // Auto-create JE mode — sequential (each transaction needs its own JE)
    for (const rule of autoCreateRules) {
      const pattern = toSqlPattern(String(rule.match_type), String(rule.match_pattern));
      const field = String(rule.match_field);
      const ruleName = String(rule.rule_name);

      let matchingTxs: Record<string, unknown>[];
      if (field === 'description') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND description ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else if (field === 'reference') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND reference ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      } else {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND (description ILIKE ${pattern} OR reference ILIKE ${pattern})
          ORDER BY transaction_date
        `) as Record<string, unknown>[];
      }

      for (const tx of matchingTxs) {
        const totalAmount = Math.abs(Number(tx.amount));
        const isDeposit = Number(tx.amount) > 0;
        const entryDesc = rule.description_template
          ? String(rule.description_template).replace('{description}', String(tx.description || '')).replace('{amount}', totalAmount.toFixed(2))
          : `Bank: ${tx.description || 'Categorised by rule'}`;

        // VAT splitting — mirrors allocateTransaction logic
        const vatCode = String(rule.vat_code || 'none');
        const hasVat = vatCode === 'standard';
        const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
        const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
        const vatAccountKey = isDeposit ? 'vat_output' as const : 'vat_input' as const;
        const mapVatType = vatCode === 'standard' ? 'standard' as const
          : vatCode === 'zero_rated' ? 'zero_rated' as const
          : vatCode === 'exempt' ? 'exempt' as const
          : undefined;

        let lines: JournalLineInput[];
        if (isDeposit) {
          lines = [
            { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
            { glAccountId: String(rule.gl_account_id), debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ 15%`, vatType: 'standard' });
          }
        } else {
          lines = [
            { glAccountId: String(rule.gl_account_id), debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
            { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ 15%`, vatType: 'standard' });
          }
        }

        const je = await createJournalEntry(companyId, {
          entryDate: tx.transaction_date instanceof Date
            ? tx.transaction_date.toISOString().split('T')[0]!
            : String(tx.transaction_date).split('T')[0]!,
          description: entryDesc,
          source: 'auto_bank_recon',
          lines,
        }, userId);
        await postJournalEntry('', je.id, userId);

        const bankLineRows = (await sql`
          SELECT id FROM gl_journal_lines
          WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID
          LIMIT 1
        `) as Record<string, unknown>[];

        if (bankLineRows[0]) {
          await sql`
            UPDATE bank_transactions
            SET status = 'allocated', matched_journal_line_id = ${bankLineRows[0].id}::UUID,
                allocation_type = 'account',
                allocated_entity_name = ${ruleName},
                updated_at = NOW()
            WHERE id = ${tx.id}::UUID
          `;
        }

        entries.push({ bankTxId: String(tx.id), ruleName, journalEntryId: je.id });
        totalApplied++;
      }
    }

    // Count remaining unmatched for the skipped total
    const remaining = (await sql`
      SELECT COUNT(*) AS cnt FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status IN ('imported', 'allocated')
        AND suggested_gl_account_id IS NULL
        AND matched_journal_line_id IS NULL
    `) as Record<string, unknown>[];
    const skipped = Number(remaining[0]?.cnt ?? 0);

    log.info('Applied bank rules', { bankAccountId, applied: totalApplied, skipped }, 'accounting');
    return { applied: totalApplied, skipped, entries };
  } catch (err) {
    log.error('Failed to apply bank rules', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapRuleRow(row: Record<string, unknown>): BankCategorisationRule {
  return {
    id: String(row.id),
    ruleName: String(row.rule_name),
    matchField: String(row.match_field) as BankCategorisationRule['matchField'],
    matchType: String(row.match_type) as BankCategorisationRule['matchType'],
    matchPattern: String(row.match_pattern ?? row.match_value ?? ''),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    clientId: row.client_id ? String(row.client_id) : undefined,
    descriptionTemplate: row.description_template ? String(row.description_template) : undefined,
    priority: Number(row.priority),
    isActive: Boolean(row.is_active),
    autoCreateEntry: Boolean(row.auto_create_entry),
    vatCode: (row.vat_code || 'none') as BankCategorisationRule['vatCode'],
    createdBy: row.created_by ? String(row.created_by) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
    glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

