/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 * Uses useAdminPrefix hook for subdomain-aware navigation.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
} from 'lucide-react';

interface NavDef {
  label: string;
  /** Relative path without /admin prefix, e.g. '' for dashboard, '/companies' etc. */
  path: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Navigation definitions with relative paths — full hrefs built dynamically via useAdminHref */
const NAV_DEFS: NavDef[] = [
  { label: 'Dashboard',   path: '',                          icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies',                icon: Building2 },
  { label: 'Users',       path: '/users',                    icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',   path: '/analytics',  icon: BarChart2 },
  { label: 'Components',  path: '/components', icon: Palette },
  { label: 'Settings',    path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const buildHref = useAdminHref();

  const isActive = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    if (adminPath === '') return router.asPath === href;
    return router.asPath.startsWith(href);
  };

  const isSectionOpen = (adminPath: string) => {
    const href = buildHref(`/admin${adminPath}`);
    return router.asPath.startsWith(href);
  };

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {NAV_DEFS.map(item => {
          const Icon = item.icon;
          const href = buildHref(`/admin${item.path}`);

          if (item.disabled) {
            return (
              <div
                key={item.path}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.path);
            return (
              <div key={item.path}>
                <Link
                  href={href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.path) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.path) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childHref = buildHref(`/admin${child.path}`);
                      const childActive = router.asPath === childHref;
                      return (
                        <Link
                          key={child.path}
                          href={childHref}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.path);
          return (
            <Link
              key={item.path}
              href={href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

/**
 * Purchase Order DB Service
 * All SQL for supplier_purchase_orders and supplier_purchase_order_items.
 * Pure business logic (validation, calculations) stays in procurementService.ts.
 */

import sql, { withTransaction, TxSql } from '@/lib/neon';

export interface PurchaseOrderItem {
  description: string;
  quantity: number;
  unit_price: number;
  tax_rate: number;
}

export interface CreatePurchaseOrderInput {
  companyId: string;
  userId: string;
  supplier_id: string;
  order_date: string;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items: PurchaseOrderItem[];
}

export interface UpdatePurchaseOrderInput {
  id: string;
  companyId: string;
  supplier_id?: string | null;
  order_date?: string | null;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items?: PurchaseOrderItem[];
}

export interface ListPurchaseOrdersInput {
  companyId: string;
  status?: string | null;
  search?: string | null;
  limit?: number;
  offset?: number;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function calcTotals(items: PurchaseOrderItem[]) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    subtotal += lineTotal;
    taxAmount += lineTax;
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

async function insertLineItems(
  purchaseOrderId: string,
  items: PurchaseOrderItem[],
  tx?: TxSql,
) {
  const exec = tx ?? sql;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    await exec`
      INSERT INTO supplier_purchase_order_items (
        purchase_order_id, description, quantity, unit_price, tax_rate,
        line_total, tax_amount
      ) VALUES (
        ${purchaseOrderId}::UUID,
        ${item.description},
        ${item.quantity},
        ${item.unit_price},
        ${item.tax_rate},
        ${Math.round(lineTotal * 100) / 100},
        ${Math.round(lineTax * 100) / 100}
      )
    `;
  }
}

async function fetchItems(purchaseOrderId: string) {
  return sql`
    SELECT * FROM supplier_purchase_order_items
    WHERE purchase_order_id = ${purchaseOrderId}::UUID
    ORDER BY created_at ASC
  `;
}

// ─── Order number ─────────────────────────────────────────────────────────────

export async function generateOrderNumber(companyId: string): Promise<string> {
  const rows = await sql`
    UPDATE company_document_numbers
    SET next_number = next_number + 1
    WHERE company_id = ${companyId}::UUID AND document_type = 'purchase_order'
    RETURNING prefix, next_number - 1 AS current_number, padding
  `;

  if (rows.length === 0) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, 'purchase_order', 'PO', 2, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
    return 'PO-0000001';
  }

  const row = rows[0]!;
  return `${row.prefix}-${String(row.current_number).padStart(row.padding, '0')}`;
}

// ─── Queries ──────────────────────────────────────────────────────────────────

export async function getPurchaseOrder(id: string, companyId: string) {
  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.id = ${id}::UUID AND po.company_id = ${companyId}::UUID
  `;
  if (orders.length === 0) return null;
  const items = await fetchItems(id);
  return { order: orders[0]!, items };
}

export async function listPurchaseOrders(input: ListPurchaseOrdersInput) {
  const { companyId, status, search, limit = 100, offset = 0 } = input;
  const take = Math.min(limit, 500);
  const statusFilter = status ?? null;
  const searchTerm = search ? `%${search}%` : null;

  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
    ORDER BY po.created_at DESC
    LIMIT ${take} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::INT AS total
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
  `;

  return { orders, total: countResult[0]?.total ?? 0 };
}

// ─── Mutations ────────────────────────────────────────────────────────────────

export async function createPurchaseOrder(input: CreatePurchaseOrderInput) {
  const { companyId, userId, items } = input;
  const orderNumber = await generateOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(items);

  const created = await sql`
    INSERT INTO supplier_purchase_orders (
      company_id, supplier_id, order_number, order_date, delivery_date,
      reference, notes, internal_notes, status,
      subtotal, tax_amount, total_amount, created_by
    ) VALUES (
      ${companyId}::UUID,
      ${input.supplier_id}::UUID,
      ${orderNumber},
      ${input.order_date}::DATE,
      ${input.delivery_date ?? null}::DATE,
      ${input.reference ?? null},
      ${input.notes ?? null},
      ${input.internal_notes ?? null},
      'draft',
      ${subtotal},
      ${taxAmount},
      ${totalAmount},
      ${userId}::UUID
    )
    RETURNING *
  `;

  const order = created[0]!;
  await insertLineItems(order.id, items);
  const orderItems = await fetchItems(order.id);
  return { order, items: orderItems };
}

export async function updatePurchaseOrder(input: UpdatePurchaseOrderInput) {
  const { id, companyId, items } = input;

  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  let subtotal: number | null = null;
  let taxAmount: number | null = null;
  let totalAmount: number | null = null;

  if (items && items.length > 0) {
    const totals = calcTotals(items);
    subtotal = totals.subtotal;
    taxAmount = totals.taxAmount;
    totalAmount = totals.totalAmount;
  }

  const { order: updated, items: orderItems } = await withTransaction(async (tx) => {
    const rows = await tx`
      UPDATE supplier_purchase_orders SET
        supplier_id    = COALESCE(${input.supplier_id ?? null}::UUID, supplier_id),
        order_date     = COALESCE(${input.order_date ?? null}::DATE, order_date),
        delivery_date  = COALESCE(${input.delivery_date ?? null}::DATE, delivery_date),
        reference      = COALESCE(${input.reference ?? null}, reference),
        notes          = COALESCE(${input.notes ?? null}, notes),
        internal_notes = COALESCE(${input.internal_notes ?? null}, internal_notes),
        subtotal       = COALESCE(${subtotal}, subtotal),
        tax_amount     = COALESCE(${taxAmount}, tax_amount),
        total_amount   = COALESCE(${totalAmount}, total_amount),
        updated_at     = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
      RETURNING *
    `;

    if (items && items.length > 0) {
      await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
      await insertLineItems(id, items, tx);
    }

    const lineItems = await tx`
      SELECT * FROM supplier_purchase_order_items
      WHERE purchase_order_id = ${id}::UUID
      ORDER BY created_at ASC
    `;

    return { order: rows[0]!, items: lineItems };
  });

  return { order: updated, items: orderItems };
}

export async function deletePurchaseOrder(id: string, companyId: string) {
  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  await withTransaction(async (tx) => {
    await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
    await tx`DELETE FROM supplier_purchase_orders WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID`;
  });

  return { deleted: true };
}

