/**
 * Purchase Order DB Service
 * All SQL for supplier_purchase_orders and supplier_purchase_order_items.
 * Pure business logic (validation, calculations) stays in procurementService.ts.
 */

import sql, { withTransaction, TxSql } from '@/lib/neon';

export interface PurchaseOrderItem {
  description: string;
  quantity: number;
  unit_price: number;
  tax_rate: number;
}

export interface CreatePurchaseOrderInput {
  companyId: string;
  userId: string;
  supplier_id: string;
  order_date: string;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items: PurchaseOrderItem[];
}

export interface UpdatePurchaseOrderInput {
  id: string;
  companyId: string;
  supplier_id?: string | null;
  order_date?: string | null;
  delivery_date?: string | null;
  reference?: string | null;
  notes?: string | null;
  internal_notes?: string | null;
  items?: PurchaseOrderItem[];
}

export interface ListPurchaseOrdersInput {
  companyId: string;
  status?: string | null;
  search?: string | null;
  limit?: number;
  offset?: number;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function calcTotals(items: PurchaseOrderItem[]) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    subtotal += lineTotal;
    taxAmount += lineTax;
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

async function insertLineItems(
  purchaseOrderId: string,
  items: PurchaseOrderItem[],
  tx?: TxSql,
) {
  const exec = tx ?? sql;
  for (const item of items) {
    const lineTotal = item.quantity * item.unit_price;
    const lineTax = lineTotal * (item.tax_rate / 100);
    await exec`
      INSERT INTO supplier_purchase_order_items (
        purchase_order_id, description, quantity, unit_price, tax_rate,
        line_total, tax_amount
      ) VALUES (
        ${purchaseOrderId}::UUID,
        ${item.description},
        ${item.quantity},
        ${item.unit_price},
        ${item.tax_rate},
        ${Math.round(lineTotal * 100) / 100},
        ${Math.round(lineTax * 100) / 100}
      )
    `;
  }
}

async function fetchItems(purchaseOrderId: string) {
  return sql`
    SELECT * FROM supplier_purchase_order_items
    WHERE purchase_order_id = ${purchaseOrderId}::UUID
    ORDER BY created_at ASC
  `;
}

// ─── Order number ─────────────────────────────────────────────────────────────

export async function generateOrderNumber(companyId: string): Promise<string> {
  const rows = await sql`
    UPDATE company_document_numbers
    SET next_number = next_number + 1
    WHERE company_id = ${companyId}::UUID AND document_type = 'purchase_order'
    RETURNING prefix, next_number - 1 AS current_number, padding
  `;

  if (rows.length === 0) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, 'purchase_order', 'PO', 2, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
    return 'PO-0000001';
  }

  const row = rows[0]!;
  return `${row.prefix}-${String(row.current_number).padStart(row.padding, '0')}`;
}

// ─── Queries ──────────────────────────────────────────────────────────────────

export async function getPurchaseOrder(id: string, companyId: string) {
  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.id = ${id}::UUID AND po.company_id = ${companyId}::UUID
  `;
  if (orders.length === 0) return null;
  const items = await fetchItems(id);
  return { order: orders[0]!, items };
}

export async function listPurchaseOrders(input: ListPurchaseOrdersInput) {
  const { companyId, status, search, limit = 100, offset = 0 } = input;
  const take = Math.min(limit, 500);
  const statusFilter = status ?? null;
  const searchTerm = search ? `%${search}%` : null;

  const orders = await sql`
    SELECT po.*, s.name AS supplier_name
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
    ORDER BY po.created_at DESC
    LIMIT ${take} OFFSET ${offset}
  `;

  const countResult = await sql`
    SELECT COUNT(*)::INT AS total
    FROM supplier_purchase_orders po
    LEFT JOIN suppliers s ON s.id = po.supplier_id AND s.company_id = po.company_id
    WHERE po.company_id = ${companyId}::UUID
      AND (${statusFilter}::TEXT IS NULL OR po.status = ${statusFilter})
      AND (
        ${searchTerm}::TEXT IS NULL
        OR po.order_number ILIKE ${searchTerm}
        OR po.reference ILIKE ${searchTerm}
        OR s.name ILIKE ${searchTerm}
      )
  `;

  return { orders, total: countResult[0]?.total ?? 0 };
}

// ─── Mutations ────────────────────────────────────────────────────────────────

export async function createPurchaseOrder(input: CreatePurchaseOrderInput) {
  const { companyId, userId, items } = input;
  const orderNumber = await generateOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(items);

  const created = await sql`
    INSERT INTO supplier_purchase_orders (
      company_id, supplier_id, order_number, order_date, delivery_date,
      reference, notes, internal_notes, status,
      subtotal, tax_amount, total_amount, created_by
    ) VALUES (
      ${companyId}::UUID,
      ${input.supplier_id}::UUID,
      ${orderNumber},
      ${input.order_date}::DATE,
      ${input.delivery_date ?? null}::DATE,
      ${input.reference ?? null},
      ${input.notes ?? null},
      ${input.internal_notes ?? null},
      'draft',
      ${subtotal},
      ${taxAmount},
      ${totalAmount},
      ${userId}::UUID
    )
    RETURNING *
  `;

  const order = created[0]!;
  await insertLineItems(order.id, items);
  const orderItems = await fetchItems(order.id);
  return { order, items: orderItems };
}

export async function updatePurchaseOrder(input: UpdatePurchaseOrderInput) {
  const { id, companyId, items } = input;

  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  let subtotal: number | null = null;
  let taxAmount: number | null = null;
  let totalAmount: number | null = null;

  if (items && items.length > 0) {
    const totals = calcTotals(items);
    subtotal = totals.subtotal;
    taxAmount = totals.taxAmount;
    totalAmount = totals.totalAmount;
  }

  const { order: updated, items: orderItems } = await withTransaction(async (tx) => {
    const rows = await tx`
      UPDATE supplier_purchase_orders SET
        supplier_id    = COALESCE(${input.supplier_id ?? null}::UUID, supplier_id),
        order_date     = COALESCE(${input.order_date ?? null}::DATE, order_date),
        delivery_date  = COALESCE(${input.delivery_date ?? null}::DATE, delivery_date),
        reference      = COALESCE(${input.reference ?? null}, reference),
        notes          = COALESCE(${input.notes ?? null}, notes),
        internal_notes = COALESCE(${input.internal_notes ?? null}, internal_notes),
        subtotal       = COALESCE(${subtotal}, subtotal),
        tax_amount     = COALESCE(${taxAmount}, tax_amount),
        total_amount   = COALESCE(${totalAmount}, total_amount),
        updated_at     = NOW()
      WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
      RETURNING *
    `;

    if (items && items.length > 0) {
      await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
      await insertLineItems(id, items, tx);
    }

    const lineItems = await tx`
      SELECT * FROM supplier_purchase_order_items
      WHERE purchase_order_id = ${id}::UUID
      ORDER BY created_at ASC
    `;

    return { order: rows[0]!, items: lineItems };
  });

  return { order: updated, items: orderItems };
}

export async function deletePurchaseOrder(id: string, companyId: string) {
  const existing = await sql`
    SELECT id, status FROM supplier_purchase_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID
  `;

  if (existing.length === 0) return { error: 'not_found' as const };
  if (existing[0]!.status !== 'draft') return { error: 'not_draft' as const };

  await withTransaction(async (tx) => {
    await tx`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id = ${id}::UUID`;
    await tx`DELETE FROM supplier_purchase_orders WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID`;
  });

  return { deleted: true };
}

/**
 * Customer Quote Service — Sage-parity quotes with convert-to-invoice
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface QuoteLine {
  id: string;
  quoteId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
  accountId: string | null;
}

export interface Quote {
  id: string;
  quoteNumber: string;
  clientId: string | null;
  customerName: string;
  quoteDate: string;
  expiryDate: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  total: number;
  notes: string | null;
  terms: string | null;
  convertedInvoiceId: string | null;
  createdAt: string;
  updatedAt: string;
  lines?: QuoteLine[];
}

interface QuoteFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface QuoteInput {
  customerName: string;
  clientId?: string;
  quoteDate?: string;
  expiryDate?: string;
  notes?: string;
  terms?: string;
  lines: { description: string; quantity: number; unitPrice: number; taxRate?: number; accountId?: string }[];
}

function mapQuote(r: Row): Quote {
  return {
    id: String(r.id), quoteNumber: String(r.quote_number), clientId: r.client_id != null ? String(r.client_id) : null,
    customerName: String(r.customer_name), quoteDate: String(r.quote_date),
    expiryDate: r.expiry_date != null ? String(r.expiry_date) : null, status: String(r.status),
    subtotal: Number(r.subtotal), taxAmount: Number(r.tax_amount),
    total: Number(r.total), notes: r.notes != null ? String(r.notes) : null, terms: r.terms != null ? String(r.terms) : null,
    convertedInvoiceId: r.converted_invoice_id != null ? String(r.converted_invoice_id) : null,
    createdAt: String(r.created_at), updatedAt: String(r.updated_at),
  };
}

function mapLine(r: Row): QuoteLine {
  return {
    id: String(r.id), quoteId: String(r.quote_id), lineNumber: Number(r.line_number),
    description: String(r.description), quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price), taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total), accountId: r.account_id != null ? String(r.account_id) : null,
  };
}

async function nextQuoteNumber(): Promise<string> {
  const rows = (await sql`
    SELECT quote_number FROM customer_quotes ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  if (rows.length === 0) return 'QUO-00001';
  const last = String(rows[0]!.quote_number);
  const num = parseInt(last.replace('QUO-', ''), 10) || 0;
  return `QUO-${String(num + 1).padStart(5, '0')}`;
}

function calcTotals(lines: QuoteInput['lines']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const l of lines) {
    const lt = l.quantity * l.unitPrice;
    subtotal += lt;
    taxAmount += lt * ((l.taxRate ?? 15) / 100);
  }
  return { subtotal: Math.round(subtotal * 100) / 100, taxAmount: Math.round(taxAmount * 100) / 100, total: Math.round((subtotal + taxAmount) * 100) / 100 };
}

export async function getQuotes(companyId: string, filters?: QuoteFilters): Promise<{ quotes: Quote[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT * FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes
      WHERE company_id = ${companyId}
        AND (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE company_id = ${companyId} ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_quotes WHERE company_id = ${companyId}`) as Row[];
  }
  return { quotes: rows.map(mapQuote), total: Number(countRows[0]?.cnt || 0) };
}

export async function getQuote(companyId: string, id: string): Promise<Quote | null> {
  // companyId may be empty string for internal calls — skip company filter in that case
  const rows = companyId
    ? (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId}`) as Row[]
    : (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID`) as Row[];
  if (rows.length === 0) return null;
  const quote = mapQuote(rows[0]!);
  const lineRows = (await sql`
    SELECT * FROM customer_quote_lines WHERE quote_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  quote.lines = lineRows.map(mapLine);
  return quote;
}

export async function createQuote(companyId: string, input: QuoteInput, userId?: string): Promise<Quote> {
  const quoteNumber = await nextQuoteNumber();
  const { subtotal, taxAmount, total } = calcTotals(input.lines);
  const qd = input.quoteDate || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_quotes (company_id, quote_number, client_id, customer_name, quote_date, expiry_date,
      subtotal, tax_amount, total, notes, terms, created_by)
    VALUES (${companyId}, ${quoteNumber}, ${input.clientId || null}, ${input.customerName}, ${qd},
      ${input.expiryDate || null}, ${subtotal}, ${taxAmount}, ${total},
      ${input.notes || null}, ${input.terms || null}, ${userId || null})
    RETURNING *
  `) as Row[];

  const quote = mapQuote(rows[0]!);
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${quote.id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote created', { quoteNumber, total });
  return (await getQuote('', quote.id))!;
}

export async function updateQuote(companyId: string, id: string, input: QuoteInput): Promise<Quote | null> {
  const existing = await getQuote('', id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, total } = calcTotals(input.lines);

  await sql`
    UPDATE customer_quotes SET customer_name = ${input.customerName}, client_id = ${input.clientId || null},
      quote_date = ${input.quoteDate || existing.quoteDate}, expiry_date = ${input.expiryDate || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total = ${total},
      notes = ${input.notes || null}, terms = ${input.terms || null}, updated_at = NOW()
    WHERE id = ${id}::UUID AND status = 'draft'
  `;
  await sql`DELETE FROM customer_quote_lines WHERE quote_id = ${id}::UUID`;
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote updated', { id });
  return getQuote('', id);
}

export async function deleteQuote(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`DELETE FROM customer_quotes WHERE id = ${id}::UUID AND company_id = ${companyId} AND status = 'draft' RETURNING id`) as Row[];
  return rows.length > 0;
}

export async function updateQuoteStatus(companyId: string, id: string, status: string): Promise<Quote | null> {
  await sql`UPDATE customer_quotes SET status = ${status}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Quote status changed', { id, status });
  return getQuote('', id);
}

export async function convertToInvoice(companyId: string, id: string, userId?: string): Promise<{ quote: Quote; invoiceId: string } | null> {
  const quote = await getQuote(companyId, id);
  if (!quote || quote.status !== 'accepted') return null;

  const invoiceId = await withTransaction(async (tx) => {
    // Create invoice from quote
    const invRows = (await tx`
      INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date, subtotal, tax_amount, total, notes, status, created_by)
      VALUES (${companyId}, ${quote.clientId}, ${quote.quoteDate}, ${quote.expiryDate || quote.quoteDate}, ${quote.subtotal},
        ${quote.taxAmount}, ${quote.total}, ${'Converted from ' + quote.quoteNumber}, 'draft', ${userId || null})
      RETURNING id
    `) as Row[];
    const newInvoiceId = String(invRows[0]!.id);

    // Copy lines
    for (const line of quote.lines || []) {
      await tx`
        INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, tax_rate, line_total, account_id)
        VALUES (${newInvoiceId}::UUID, ${line.description}, ${line.quantity}, ${line.unitPrice}, ${line.taxRate}, ${line.lineTotal}, ${line.accountId})
      `;
    }

    await tx`UPDATE customer_quotes SET status = 'converted', converted_invoice_id = ${newInvoiceId}::UUID, updated_at = NOW() WHERE id = ${id}::UUID`;
    return newInvoiceId;
  });

  log.info('Quote converted to invoice', { quoteId: id, invoiceId });
  return { quote: (await getQuote('', id))!, invoiceId };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Import Service — statement import and persistence
 */

import { transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  detectBankFormat,
  parseFNBStatement,
  parseStandardBankStatement,
  parseNedbankStatement,
  parseABSAStatement,
  parseCapitecStatement,
} from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import type { BankFormat, BankCsvParseResult } from '../types/bank.types';

export async function importBankStatement(
  companyId: string,
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    await transaction((txSql) =>
      parseResult.transactions.map(tx => txSql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `)
    );

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import bank statement', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * Persist an already-parsed set of transactions (e.g. from a PDF import).
 * Reuses the same INSERT logic as importBankStatement so behaviour is identical.
 */
export async function importParsedTransactions(
  companyId: string,
  parseResult: BankCsvParseResult,
  bankAccountId: string,
  statementDate: string,
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    await transaction((txSql) =>
      parseResult.transactions.map(tx => txSql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `)
    );

    log.info('Imported parsed bank statement', {
      batchId,
      format: parseResult.bankFormat,
      count: parseResult.transactions.length,
      statementDate,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import parsed bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

/**
