  orderNumber: string;
  customerId: string | null;
  customerName: string;
  orderDate: string;
  deliveryDate: string | null;
  reference: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  notes: string | null;
  internalNotes: string | null;
