const REQUIRED_VARS = ['DATABASE_URL', 'JWT_SECRET'] as const;
const RECOMMENDED_VARS = ['ENCRYPTION_KEY', 'SMTP_HOST', 'SMTP_USER', 'SMTP_PASS'] as const;

export function validateEnv(): void {
  const missing = REQUIRED_VARS.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  const missingRecommended = RECOMMENDED_VARS.filter(v => !process.env[v]);
  if (missingRecommended.length > 0) {
    console.warn(`[env] Missing recommended variables: ${missingRecommended.join(', ')}`);
  }
}

/**
 * POST /api/auth/login
 * Authenticates a user with email + password.
 * On success: signs a JWT, creates a DB session, sets an HttpOnly cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword } from '@/lib/auth/password';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
import { get2FAStatus, isTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password, deviceFingerprint } = req.body as {
    email?: string;
    password?: string;
    deviceFingerprint?: string;
  };

  if (!email || !password) {
    return apiResponse.badRequest(res, 'Email and password are required');
  }

  try {
    // Look up user by email
    const rows = (await sql`
      SELECT id, email, password_hash, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed,
             failed_login_attempts, locked_until
      FROM users
      WHERE email = ${email.toLowerCase().trim()}
      LIMIT 1
    `) as Row[];

    const user = rows[0];

    if (!user) {
      // Constant-time failure — avoid timing attacks
      await verifyPassword(password, '$2a$12$placeholder.hash.to.prevent.timing.attacks');
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    if (!user.is_active) {
      return res.status(403).json({
        success: false,
        error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
      });
    }

    // Check account lockout
    if (user.locked_until) {
      const lockedUntil = user.locked_until instanceof Date ? user.locked_until : new Date(user.locked_until as string);
      if (lockedUntil > new Date()) {
        const minutesRemaining = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
        return res.status(403).json({
          success: false,
          error: {
            code: 'ACCOUNT_LOCKED',
            message: `Account locked due to too many failed attempts. Try again in ${minutesRemaining} minute(s).`,
          },
        });
      }
    }

    // Verify password
    const passwordValid = await verifyPassword(password, user.password_hash as string);
    if (!passwordValid) {
      // Increment failed attempts; lock after 10 failures
      const attempts = ((user.failed_login_attempts as number) ?? 0) + 1;
      if (attempts >= 10) {
        await sql`
          UPDATE users
          SET failed_login_attempts = ${attempts},
              locked_until = NOW() + INTERVAL '30 minutes'
          WHERE id = ${user.id as string}
        `;
        log.warn('Account locked after failed attempts', { userId: user.id, attempts }, 'auth/login');
      } else {
        await sql`
          UPDATE users SET failed_login_attempts = ${attempts} WHERE id = ${user.id as string}
        `;
      }
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    // Check 2FA before creating a full session
    const twoFAStatus = await get2FAStatus(String(user.id));
    if (twoFAStatus.enabled) {
      // Check if device is already trusted
      const trusted = deviceFingerprint
        ? await isTrustedDevice(String(user.id), deviceFingerprint)
        : false;

      if (!trusted) {
        // Issue a short-lived temp token (5 min) — no DB session yet
        const tempAuthUser = {
          id: String(user.id),
          userId: String(user.id),
          email: user.email as string,
          firstName: (user.first_name as string) || '',
          lastName: (user.last_name as string) || '',
          name: '',
          role: user.role as AuthRole,
          permissions: [],
          isActive: true,
        };
        const tempToken = await signToken(tempAuthUser, '2fa-pending', '5m');
        log.info('2FA required — temp token issued', { userId: user.id }, 'auth/login');
        return res.status(200).json({
          success: true,
          data: { requiresTwoFactor: true, tempToken },
        });
      }
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Sign JWT and create DB session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    // Reset failed login attempts on successful password verification
    await sql`
      UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE id = ${authUser.id}
    `;

    // Create session first, then sign token with the real sessionId
    // We pass a temporary token to createSession, then update the hash
    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);

    // Re-sign token with the real sessionId
    const finalToken = await signToken(authUser, session.id);

    // Update session with the hash of the final token
    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Set HttpOnly cookie — 8h session, always secure
    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    // Auto-accept any pending company invitations for this email
    let invitationsAccepted = 0;
    let onboardingCompleted = !!user.onboarding_completed;

    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${authUser.email})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${authUser.id}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
      `;
      invitationsAccepted++;
    }

    if (invitationsAccepted > 0 && !onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
      onboardingCompleted = true;
      log.info('Onboarding skipped via invitation acceptance', { userId: authUser.id, invitationsAccepted }, 'auth/login');
    }

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('User logged in', { userId: authUser.id, email: authUser.email }, 'auth/login');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
      invitationsAccepted,
    }, 'Login successful');
  } catch (err) {
    log.error('Login error', err instanceof Error ? { message: err.message } : { err }, 'auth/login');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * AES-256-GCM encryption utilities for sensitive data at rest.
 * Requires ENCRYPTION_KEY env var (min 32 chars).
 */

import crypto from 'crypto';
import { log } from '@/lib/logger';

const ALGORITHM = 'aes-256-gcm';

function getEncryptionKey(): Buffer {
  const key = process.env.ENCRYPTION_KEY;
  if (!key || key.length < 32) {
    throw new Error('ENCRYPTION_KEY must be set (min 32 chars)');
  }
  return Buffer.from(key.slice(0, 32), 'utf-8');
}

export function isEncryptionAvailable(): boolean {
  const key = process.env.ENCRYPTION_KEY;
  return !!(key && key.length >= 32);
}

export function encrypt(plaintext: string): string {
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return `${iv.toString('hex')}:${tag}:${encrypted}`;
}

export function decrypt(ciphertext: string): string {
  const key = getEncryptionKey();
  const [ivHex, tagHex, encryptedHex] = ciphertext.split(':');
  if (!ivHex || !tagHex || !encryptedHex) {
    throw new Error('Invalid encrypted format');
  }
  const iv = Buffer.from(ivHex, 'hex');
  const tag = Buffer.from(tagHex, 'hex');
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

/** Encrypt token if key is available, otherwise warn and return plaintext. */
export function encryptToken(plaintext: string): string {
  if (!isEncryptionAvailable()) {
    log.warn('ENCRYPTION_KEY not set — storing token as plaintext', {}, 'encryption');
    return plaintext;
  }
  return encrypt(plaintext);
}

/** Decrypt token if it looks encrypted, otherwise return as-is (plaintext fallback). */
export function decryptToken(value: string): string {
  if (!value) return value;
  // Encrypted format: hex:hex:hex (iv:tag:ciphertext)
  const parts = value.split(':');
  if (parts.length !== 3) {
    // Stored as plaintext — likely pre-encryption-key migration
    return value;
  }
  try {
    return decrypt(value);
  } catch {
    log.warn('Failed to decrypt token — returning as-is', {}, 'encryption');
    return value;
  }
}

/**
 * Password Utilities
 * Secure password hashing and verification using bcryptjs
 */

import * as bcrypt from 'bcryptjs';
import { randomBytes, randomInt, createHash } from 'crypto';

// Cost factor for bcrypt (10-12 is recommended for production)
const SALT_ROUNDS = 12;

/**
 * Hash a password
 */
export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, SALT_ROUNDS);
}

/**
 * Verify a password against a hash
 */
export async function verifyPassword(
  password: string,
  hash: string
): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

/**
 * Check password strength
 * Returns an object with strength score and issues
 */
export function checkPasswordStrength(password: string): {
  score: number; // 0-4 (0 = very weak, 4 = very strong)
  issues: string[];
  isValid: boolean;
} {
  const issues: string[] = [];
  let score = 0;

  // Minimum length check
  if (password.length < 8) {
    issues.push('Password must be at least 8 characters');
  } else {
    score++;
    if (password.length >= 12) score++;
  }

  // Uppercase check
  if (!/[A-Z]/.test(password)) {
    issues.push('Password should contain at least one uppercase letter');
  } else {
    score++;
  }

  // Lowercase check
  if (!/[a-z]/.test(password)) {
    issues.push('Password should contain at least one lowercase letter');
  }

  // Number check
  if (!/[0-9]/.test(password)) {
    issues.push('Password should contain at least one number');
  } else {
    score++;
  }

  // Special character check
  if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
    issues.push('Password should contain at least one special character');
  }

  return {
    score: Math.min(score, 4),
    issues,
    isValid: score >= 3 && issues.length === 0,
  };
}

/**
 * Generate a cryptographically secure random password
 */
export function generateRandomPassword(length: number = 16): string {
  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const numbers = '0123456789';
  const special = '!@#$%^&*';
  const all = uppercase + lowercase + numbers + special;

  const chars: string[] = [];

  // Ensure at least one of each type using crypto.randomInt
  chars.push(uppercase[randomInt(uppercase.length)]!);
  chars.push(lowercase[randomInt(lowercase.length)]!);
  chars.push(numbers[randomInt(numbers.length)]!);
  chars.push(special[randomInt(special.length)]!);

  // Fill the rest
  for (let i = 4; i < length; i++) {
    chars.push(all[randomInt(all.length)]!);
  }

  // Fisher-Yates shuffle using crypto.randomInt
  for (let i = chars.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    [chars[i], chars[j]] = [chars[j]!, chars[i]!];
  }

  return chars.join('');
}

/**
 * Generate a secure password reset token
 * Returns both the plain token (to send to user) and hashed token (to store in DB)
 */
export function generateResetToken(): {
  token: string;
  hashedToken: string;
  expiresAt: Date;
} {
  // Generate 32 random bytes = 64 hex characters
  const token = randomBytes(32).toString('hex');

  // Hash the token for storage (so even if DB is compromised, tokens can't be used)
  const hashedToken = createHash('sha256').update(token).digest('hex');

  // Token expires in 1 hour
  const expiresAt = new Date(Date.now() + 60 * 60 * 1000);

  return { token, hashedToken, expiresAt };
}

/**
 * Hash a reset token for comparison
 */
export function hashResetToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}

/**
 * Check if a reset token has expired
 */
export function isResetTokenExpired(expiresAt: Date | string): boolean {
  const expiry = typeof expiresAt === 'string' ? new Date(expiresAt) : expiresAt;
  return expiry < new Date();
}

/**
 * POST /api/auth/register
 * Creates a new user account with email + password.
 * Does NOT set an auth cookie — user must log in after registering.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 3 registrations per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 3 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { firstName, lastName, email, password, confirmPassword, inviteToken } = req.body as {
    firstName?: string;
    lastName?: string;
    email?: string;
    password?: string;
    confirmPassword?: string;
    inviteToken?: string;
  };

  // Validate all fields present
  if (!firstName || !lastName || !email || !password || !confirmPassword) {
    return apiResponse.badRequest(res, 'All fields are required');
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return apiResponse.badRequest(res, 'Please enter a valid email address');
  }

  // Validate passwords match
  if (password !== confirmPassword) {
    return apiResponse.badRequest(res, 'Passwords do not match');
  }

  // Check password strength
  const strength = checkPasswordStrength(password);
  if (!strength.isValid) {
    return apiResponse.badRequest(res, `Password too weak: ${strength.issues[0] || 'Please choose a stronger password'}`);
  }

  try {
    // Check email uniqueness
    const existing = (await sql`
      SELECT id FROM users WHERE LOWER(email) = LOWER(${email.trim()}) LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      return apiResponse.badRequest(res, 'An account with this email already exists');
    }

    // Hash password
    const hash = await hashPassword(password);

    // Insert user
    const rows = (await sql`
      INSERT INTO users (email, password_hash, first_name, last_name, role, permissions, is_active, onboarding_completed)
      VALUES (${email.toLowerCase().trim()}, ${hash}, ${firstName.trim()}, ${lastName.trim()}, 'viewer', '[]', true, false)
      RETURNING id, email
    `) as Row[];

    const user = rows[0]!;
    const userId = String(user.id);
    const normalizedEmail = (email as string).toLowerCase().trim();

    // Auto-accept pending invitations: by token (if provided) + by email match
    let invitationsAccepted = 0;

    // 1. Accept the specific invite by token (from invite link flow)
    if (inviteToken && typeof inviteToken === 'string') {
      const tokenInvites = (await sql`
        SELECT id, company_id, role
        FROM company_invitations
        WHERE token = ${inviteToken}
          AND accepted_at IS NULL
          AND expires_at > NOW()
        LIMIT 1
      `) as Row[];

      if (tokenInvites.length > 0) {
        await transaction((txSql) =>
          tokenInvites.flatMap((inv) => [
            txSql`
              INSERT INTO company_users (company_id, user_id, role, is_default)
              VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
              ON CONFLICT (company_id, user_id) DO NOTHING
            `,
            txSql`
              UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
            `,
          ])
        );
        invitationsAccepted += tokenInvites.length;
      }
    }

    // 2. Also accept any other pending invitations matching by email
    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${normalizedEmail})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    if (pendingInvitations.length > 0) {
      await transaction((txSql) =>
        pendingInvitations.flatMap((inv) => [
          txSql`
            INSERT INTO company_users (company_id, user_id, role, is_default)
            VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
            ON CONFLICT (company_id, user_id) DO NOTHING
          `,
          txSql`
            UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
          `,
        ])
      );
      invitationsAccepted += pendingInvitations.length;
    }

    const onboardingCompleted = invitationsAccepted > 0;
    if (onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${userId}`;
      log.info('Onboarding skipped via invitation acceptance at registration', { userId, invitationsAccepted }, 'auth/register');
    }

    log.info('User registered', { userId, email: user.email as string, invitationsAccepted }, 'auth/register');

    // Auto-login: create session and set auth cookie
    const authUser = {
      id: userId,
      userId,
      email: normalizedEmail,
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      name: `${firstName.trim()} ${lastName.trim()}`.trim(),
      role: 'viewer' as AuthRole,
      permissions: [] as string[],
      isActive: true,
    };

    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);
    const finalToken = await signToken(authUser, session.id);

    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    const isProd = process.env.NODE_ENV === 'production';
    const cookies = [
      serialize(AUTH_COOKIE_NAME, finalToken, {
        httpOnly: true,
        secure: true,
        sameSite: 'lax',
        path: '/',
        maxAge: 8 * 60 * 60,
        ...(isProd ? { domain: '.isaflow.co.za' } : {}),
      }),
    ];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    return apiResponse.created(res, {
      userId,
      email: normalizedEmail,
      invitationsAccepted,
      autoLoggedIn: true,
    });
  } catch (err) {
    log.error('Registration error', err instanceof Error ? { message: err.message } : { err }, 'auth/register');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * Admin User Service
 * Cross-company user management for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { generateRandomPassword, hashPassword } from '@/lib/auth';
import type {
  AdminUserListItem,
  AdminUserDetail,
  AdminUserCompany,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  email: 'u.email',
  first_name: 'u.first_name',
  last_name: 'u.last_name',
  created_at: 'u.created_at',
  last_login: 'u.last_login',
  role: 'u.role',
};

export async function listUsers(
  filters: AdminListFilters & { role?: string; company_id?: string } = {}
): Promise<PaginatedResult<AdminUserListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'u.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT u.id) AS total
    FROM users u
    LEFT JOIN company_users cu ON cu.user_id = u.id
    WHERE (${searchPattern}::text IS NULL
           OR u.email ILIKE ${searchPattern}
           OR u.first_name ILIKE ${searchPattern}
           OR u.last_name ILIKE ${searchPattern})
      AND (${filters.role ?? null}::text IS NULL OR u.role = ${filters.role ?? null})
      AND (${filters.company_id ?? null}::uuid IS NULL OR cu.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR (${filters.status ?? null} = 'active'    AND u.is_active = true)
           OR (${filters.status ?? null} = 'suspended' AND u.is_active = false))
  `;

/**
 * Custom Report Runner — WS-7.1
 * Dynamic SQL builder using whitelisted field expressions only.
 * All user-supplied values go through parameterized query bindings.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  getAvailableFields,
  getFieldDef,
  getBaseQuery,
  getCompanyAlias,
  type FieldDef,
} from './customReportFieldDefs';
import type { ReportConfig, RunResult } from './customReportService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export async function runReport(companyId: string, config: ReportConfig): Promise<RunResult> {
  const { dataSource, columns, filters = [], sortBy = [], limit = 500, offset = 0 } = config;

  const fields = getAvailableFields(dataSource);
  if (!fields.length) throw new Error(`Unknown data source: ${dataSource}`);

  // Validate & resolve selected columns against whitelist — no user input touches SQL strings
  const selectedFields = columns
    .map(c => getFieldDef(dataSource, c.field))
    .filter((f): f is FieldDef => f !== undefined);

  if (!selectedFields.length) throw new Error('No valid columns selected');

  const alias = getCompanyAlias(dataSource);
  const baseQuery = getBaseQuery(dataSource);

  // SELECT from whitelisted sqlExpr values only
  const selectParts = selectedFields.map(f => `${f.sqlExpr} AS "${f.field}"`).join(', ');

  // Parameterized WHERE clause — values bound as $N, never interpolated
  const params: (string | number | null)[] = [companyId];
  let paramIdx = 2;
  const whereParts: string[] = [`${alias}.company_id = $1`];

  for (const filter of filters) {
    const fd = getFieldDef(dataSource, filter.field);
    if (!fd || !fd.filterable) continue;

    const expr = fd.sqlExpr; // from whitelist only
    switch (filter.operator) {
      case 'equals':
        whereParts.push(`${expr} = $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'not_equals':
        whereParts.push(`${expr} != $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'contains':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`%${filter.value ?? ''}%`);
        break;
      case 'starts_with':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`${filter.value ?? ''}%`);
        break;
      case 'greater_than':
        whereParts.push(`${expr} > $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'less_than':
        whereParts.push(`${expr} < $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'between':
        whereParts.push(`${expr} BETWEEN $${paramIdx} AND $${paramIdx + 1}`);
        paramIdx += 2;
        params.push(filter.value ?? null, filter.value2 ?? null);
        break;
      case 'in': {
        const vals = String(filter.value ?? '').split(',').map(v => v.trim()).filter(Boolean);
        if (vals.length) {
          const placeholders = vals.map(() => `$${paramIdx++}`).join(', ');
          whereParts.push(`${expr} IN (${placeholders})`);
          params.push(...vals);
        }
        break;
      }
      case 'is_null':
        whereParts.push(`${expr} IS NULL`);
        break;
      case 'is_not_null':
        whereParts.push(`${expr} IS NOT NULL`);
        break;
    }
  }

  const whereClause = whereParts.join(' AND ');

  // ORDER BY from whitelisted fields only
  const orderParts = sortBy
    .map(s => {
      const fd = getFieldDef(dataSource, s.field);
      if (!fd || !fd.sortable) return null;
      return `${fd.sqlExpr} ${s.direction === 'desc' ? 'DESC' : 'ASC'}`;
    })
    .filter((x): x is string => x !== null);
  const orderClause = orderParts.length ? `ORDER BY ${orderParts.join(', ')}` : '';

  const limitVal = Math.min(Math.max(1, Number(limit) || 500), 10000);
  const offsetVal = Math.max(0, Number(offset) || 0);

  // Final SQL — structure comes from whitelisted exprs, values from $N bindings
  const querySql = `
    SELECT ${selectParts}
    ${baseQuery}
    WHERE ${whereClause}
    ${orderClause}
    LIMIT ${limitVal} OFFSET ${offsetVal}
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    ${baseQuery}
    WHERE ${whereClause}
  `;

  // sql.query() sends parameterized queries to Neon
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [dataRows, countRows] = await Promise.all([
    (sql as any).query(querySql, params),
    (sql as any).query(countSql, params),
  ]);

  const rows = (dataRows.rows ?? dataRows) as Row[];
  const rowCount = Number((countRows.rows ?? countRows)[0]?.total ?? rows.length);

  // Aggregate totals for totalable fields
  const totals: Record<string, number> = {};
  for (const f of selectedFields) {
    if (f.totalable) {
      totals[f.field] = rows.reduce((sum, r) => sum + (Number(r[f.field]) || 0), 0);
    }
  }

  const resultColumns = selectedFields.map(f => ({
    field: f.field,
    label: columns.find(c => c.field === f.field)?.label ?? f.label,
    type: f.type,
  }));

/**
 * POST /api/auth/2fa-verify
 * Verify TOTP code during login using a short-lived temp token.
 * Returns full auth token on success (mirrors login response).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken, signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { verifyTOTPCode, addTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';
import type { AuthRole } from '@/lib/auth/types';
import { createHash } from 'crypto';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const {
    tempToken,
    code,
    trustDevice,
    deviceFingerprint,
    deviceName,
  } = req.body as {
    tempToken?: string;
    code?: string;
    trustDevice?: boolean;
    deviceFingerprint?: string;
    deviceName?: string;
  };

  if (!tempToken || !code) {
    return apiResponse.badRequest(res, 'tempToken and code are required');
  }

  try {
    // Verify the temp token
    const payload = await verifyToken(tempToken);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired temp token' },
      });
    }

    // Temp tokens use sessionId = '2fa-pending'
    if (payload.sessionId !== '2fa-pending') {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Token is not a 2FA temp token' },
      });
    }

    const userId = payload.sub;

    // Look up the user
    const rows = (await sql`
      SELECT id, email, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed
      FROM users
      WHERE id = ${userId} AND is_active = true
      LIMIT 1
    `) as Row[];

    const user = rows[0];
    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'USER_NOT_FOUND', message: 'User not found' },
      });
    }

    // Verify TOTP code
    const codeValid = await verifyTOTPCode(userId, code.trim());
    if (!codeValid) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_2FA_CODE', message: 'Invalid authentication code' },
      });
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Create full session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const pendingToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, pendingToken, ipAddress, userAgent);

    const finalToken = await signToken(authUser, session.id);
    const finalHash = createHash('sha256').update(finalToken).digest('hex');

    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Optionally trust device
    if (trustDevice && deviceFingerprint) {
      await addTrustedDevice(userId, deviceFingerprint, deviceName ?? 'Unknown Device');
    }

    const onboardingCompleted = !!user.onboarding_completed;

    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('2FA verified — full session created', { userId }, 'api/auth/2fa-verify');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
    }, 'Two-factor authentication verified');
  } catch (err) {
    log.error('2fa-verify error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-verify');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: serve /admin/* pages with super_admin auth verification
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects /admin/* on non-admin hosts to admin.isaflow.co.za
 * - Redirects unauthenticated /accounting/* and /payroll/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const getJWTSecret = (): Uint8Array =>
  new TextEncoder().encode(process.env.JWT_SECRET ?? '');

const PUBLIC_PATHS = [
  '/login',
  '/register',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/register',
  '/onboarding',
  '/api/onboarding',
  '/invite',
  '/api/invite',
];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the /admin platform */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths that bypass auth checks on the admin subdomain */
const ADMIN_PASSTHROUGH = [
  '/_next',
  '/api/',
  '/login',
  '/register',
  '/favicon.ico',
  '/icons',
  '/manifest.json',
  '/sw.js',
];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(token: string): Promise<boolean> {
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin';
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  const isAdminHost = ADMIN_HOSTS.includes(host);

  // ── Admin subdomain handling ─────────────────────────────────────────────────
  if (isAdminHost) {
    // Always passthrough for static assets, API routes, and login
    if (ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p))) {
      return NextResponse.next();
    }

    // Verify super_admin auth for all other paths
    const adminToken = request.cookies.get(AUTH_COOKIE_NAME)?.value;
    if (!adminToken) {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    const isAdmin = await verifyAdmin(adminToken);
    if (!isAdmin) {
      return NextResponse.redirect(new URL('/login', request.url));
    }

    // Rewrite path: / → /admin, /companies → /admin/companies, etc.
    if (!pathname.startsWith('/admin')) {
      const rewrittenUrl = request.nextUrl.clone();
      rewrittenUrl.pathname = pathname === '/' ? '/admin' : `/admin${pathname}`;
      return NextResponse.rewrite(rewrittenUrl);
    }

    return NextResponse.next();
  }

  // ── Non-admin hosts: redirect /admin/* to admin subdomain ───────────────────
  if (pathname.startsWith('/admin')) {
    const adminPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(`${ADMIN_URL}${adminPath}`);
  }

  // Allow public paths, static files, and API routes on main domains
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

