  name: string;
  role: AuthRole;
  permissions: string[];
  isActive: boolean;
  profilePicture?: string;
  department?: string;
}

export type AuthRole = 'super_admin' | 'admin' | 'manager' | 'storeman' | 'technician' | 'viewer' | 'system';

export interface JWTPayload {
  sub: string; // user id
  email: string;
  role: AuthRole;
  /** @deprecated Permissions no longer stored in JWT — fetched from DB via middleware */
  permissions: string[];
  sessionId: string;
  iat: number;
  exp: number;
}

export interface Session {
  id: string;
  userId: string;
  tokenHash: string;
  expiresAt: Date;
  createdAt: Date;
  ipAddress?: string;
  userAgent?: string;
}

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface LoginResponse {
  success: boolean;
  user?: AuthUser;
  error?: string;
}

export interface AuthenticatedRequest {
  user: AuthUser;
  sessionId: string;
