/**
 * Intercompany Transactions API
 * GET  — list transactions / reconciliation report
 * POST — create transaction / match transactions
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import {
  listIntercompanyTransactions,
  createIntercompanyTransaction,
  matchIntercompanyTransactions,
  getIntercompanyReconciliation,
} from '@/modules/accounting/services/groupCompanyService';

async function verifyGroupAccess(groupId: string, userId: string): Promise<boolean> {
  const rows = (await sql`
    SELECT 1 FROM company_group_members cgm
    JOIN company_users cu ON cu.company_id = cgm.company_id
    WHERE cgm.group_id = ${groupId}::UUID AND cu.user_id = ${userId}::UUID
    LIMIT 1
  `) as Record<string, unknown>[];
  return rows.length > 0;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;
  const groupId = req.query.group_id as string;

  if (req.method === 'GET') {
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');
    if (!(await verifyGroupAccess(groupId, userId))) return apiResponse.forbidden(res, 'Access denied to this group');

    if (action === 'reconciliation') {
      const periodStart = req.query.period_start as string;
      const periodEnd = req.query.period_end as string;
      if (!periodStart || !periodEnd) return apiResponse.badRequest(res, 'period_start and period_end required');
      const report = await getIntercompanyReconciliation(groupId, periodStart, periodEnd);
      return apiResponse.success(res, report);
    }

    const filters = {
      dateFrom: req.query.period_start as string | undefined,
      dateTo: req.query.period_end as string | undefined,
      matchStatus: req.query.status as string | undefined,
      sourceCompanyId: req.query.company_id as string | undefined,
    };
    const transactions = await listIntercompanyTransactions(groupId, filters);
    return apiResponse.success(res, { items: transactions });
  }

  if (req.method === 'POST') {
    if (action === 'match') {
      const { sourceId, targetId, groupId: matchGroupId } = req.body;
      if (!sourceId || !targetId) return apiResponse.badRequest(res, 'sourceId and targetId required');
      if (!matchGroupId) return apiResponse.badRequest(res, 'groupId required');
      if (!(await verifyGroupAccess(matchGroupId as string, userId))) return apiResponse.forbidden(res, 'Access denied to this group');
      await matchIntercompanyTransactions(sourceId, targetId);
      return apiResponse.success(res, { matched: true });
    }

    // Create transaction
    const { groupId: gId, sourceCompanyId, targetCompanyId, transactionType, amount, currency, description, transactionDate, sourceJournalEntryId, targetJournalEntryId } = req.body;
    if (!gId || !sourceCompanyId || !targetCompanyId || !transactionType || !amount || !transactionDate) {
      return apiResponse.badRequest(res, 'groupId, sourceCompanyId, targetCompanyId, transactionType, amount, transactionDate required');
    }
    if (!(await verifyGroupAccess(gId as string, userId))) return apiResponse.forbidden(res, 'Access denied to this group');
    const tx = await createIntercompanyTransaction({
      groupId: gId,
      sourceCompanyId,
      targetCompanyId,
      transactionType,
      amount,
      currency,
      description,
      transactionDate,
      sourceJournalEntryId,
      targetJournalEntryId,
    });
    return apiResponse.success(res, tx);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

    leftDate: r.left_date != null ? String(r.left_date) : null,
    createdAt: String(r.created_at),
  };
}

// ── Group CRUD ───────────────────────────────────────────────────────────────

export async function listGroups(): Promise<CompanyGroup[]> {
  const rows = (await sql`
    SELECT cg.*,
           COUNT(cgm.id) FILTER (WHERE cgm.left_date IS NULL) AS member_count
    FROM company_groups cg
    LEFT JOIN company_group_members cgm ON cgm.group_id = cg.id
    WHERE cg.is_active = true
    GROUP BY cg.id
    ORDER BY cg.name
  `) as Row[];
  return rows.map((r: Row) => ({ ...mapGroup(r), memberCount: Number(r.member_count) }));
}

export async function getGroup(groupId: string): Promise<CompanyGroup | null> {
  const rows = (await sql`
    SELECT cg.*,
           COUNT(cgm.id) FILTER (WHERE cgm.left_date IS NULL) AS member_count
    FROM company_groups cg
    LEFT JOIN company_group_members cgm ON cgm.group_id = cg.id
    WHERE cg.id = ${groupId}::UUID
    GROUP BY cg.id
  `) as Row[];
  if (!rows[0]) return null;

// ── Status Mutations ──────────────────────────────────────────────────────────

export async function matchTransaction(
  companyId: string, bankTxId: string, journalLineId: string, reconciliationId?: string
): Promise<BankTransaction> {
  try {
    let rows: Row[];
    if (reconciliationId) {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched', matched_journal_line_id = ${journalLineId}::UUID,
            reconciliation_id = ${reconciliationId}::UUID
        WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    } else {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched', matched_journal_line_id = ${journalLineId}::UUID
        WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    }
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Matched bank transaction', { bankTxId, journalLineId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to match bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function unmatchTransaction(companyId: string, bankTxId: string): Promise<BankTransaction> {
  try {
    const rows = (await sql`
      UPDATE bank_transactions
      SET status = 'imported', matched_journal_line_id = NULL,
          allocation_type = NULL, allocated_entity_name = NULL
      WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Unmatched bank transaction', { bankTxId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to unmatch bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function excludeTransaction(
  companyId: string, bankTxId: string, reason?: string
): Promise<BankTransaction> {
  try {
    const rows = (await sql`
      UPDATE bank_transactions SET status = 'excluded', exclude_reason = ${reason || null}
      WHERE id = ${bankTxId}::UUID AND company_id = ${companyId}::UUID RETURNING *`) as Row[];
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Excluded bank transaction', { bankTxId, reason }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to exclude bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

/** Delete bank transactions — only imported (unallocated) transactions can be deleted. */
export async function deleteTransactions(companyId: string, bankTxIds: string[]): Promise<number> {
  if (bankTxIds.length === 0) return 0;
  try {
    const result = (await sql`
      DELETE FROM bank_transactions
      WHERE id = ANY(${bankTxIds}::UUID[]) AND status = 'imported'
        AND company_id = ${companyId}::UUID`) as Row[];
    const deleted = result.length ?? bankTxIds.length;
    log.info('Deleted bank transactions', { count: deleted, ids: bankTxIds }, 'accounting');
    return deleted;
  } catch (err) {
    log.error('Failed to delete bank transactions', { bankTxIds, error: err }, 'accounting');
    throw err;
  }
}

/** Mark a batch of imported/allocated transactions as matched without creating journal entries. */
export async function bulkAcceptTransactions(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  try {
    const result = (await sql`
      UPDATE bank_transactions SET status = 'matched', updated_at = NOW()
      WHERE id = ANY(${ids}::UUID[]) AND status IN ('imported', 'allocated')
        AND company_id = ${companyId}::UUID`) as Row[];
    const count = (result as unknown as { count?: number }).count ?? ids.length;
    log.info('Bulk accepted bank transactions', { count, ids }, 'accounting');
    return count;
  } catch (err) {
    log.error('Failed to bulk accept bank transactions', { ids, error: err }, 'accounting');
    throw err;
  }
}

export async function deleteBudget(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM accounting_budgets WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID`;
}

export async function copyBudgets(companyId: string, fromYear: number, toYear: number, userId: string): Promise<number> {
  const existing = (await sql`
    SELECT gl_account_id, annual_amount,
           jan, feb, mar, apr, may, jun, jul, aug, sep, oct, nov, "dec", notes
    FROM accounting_budgets WHERE fiscal_year = ${fromYear} AND company_id = ${companyId}::UUID
  `) as Row[];

  let count = 0;
  for (const row of existing) {
    await sql`
      INSERT INTO accounting_budgets (
        company_id, gl_account_id, fiscal_year, annual_amount,
        jan, feb, mar, apr, may, jun, jul, aug, sep, oct, nov, "dec",
        notes, created_by
      ) VALUES (
        ${companyId}::UUID, ${row.gl_account_id}::UUID, ${toYear}, ${row.annual_amount},
        ${row.jan}, ${row.feb}, ${row.mar}, ${row.apr},
        ${row.may}, ${row.jun}, ${row.jul}, ${row.aug},
        ${row.sep}, ${row.oct}, ${row.nov}, ${row.dec},
        ${row.notes || null}, ${userId}::UUID
      )
      ON CONFLICT (gl_account_id, fiscal_year) DO NOTHING
    `;
    count++;
  }
  log.info('Copied budgets', { fromYear, toYear, count }, 'accounting');
  return count;
}

function distributeEvenly(annual: number): number[] {
  const monthly = Math.round((annual / 12) * 100) / 100;
  const arr = Array(12).fill(monthly) as number[];
  // Adjust last month for rounding
  const sum = arr.slice(0, 11).reduce((s, v) => s + v, 0);
  arr[11] = Math.round((annual - sum) * 100) / 100;

/**
 * Invoice Service
 * Admin invoice lifecycle for the ISAFlow Admin Platform.
 * Subscription operations are in billingService.ts.
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { InvoiceListItem, PaginatedResult } from '../types/admin.types';
type Row = Record<string, unknown>;


function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT: Record<string, string> = {
  created_at: 'i.created_at',
  due_date: 'i.due_date',
  status: 'i.status',
  total_cents: 'i.total_cents',
  company_name: 'c.name',
  invoice_number: 'i.invoice_number',
};

export async function listInvoices(filters: {
  company_id?: string;
  status?: string;
  from_date?: string;
  to_date?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<InvoiceListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT[filters.sort_by ?? ''] ?? 'i.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      i.id, i.company_id, c.name AS company_name,
      i.invoice_number, i.status,
      i.subtotal_cents, i.tax_cents, i.total_cents, i.currency,
      i.due_date, i.paid_at, i.payment_method,
      i.created_at
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listInvoices: ${rows.length} rows (page ${page})`, {}, 'InvoiceService');

  return {
    items: (rows as Row[]).map((r: Row) => ({
      id: r.id as string,
      company_id: r.company_id as string,
      company_name: r.company_name as string,
      invoice_number: r.invoice_number as string,
      status: r.status as string,
      subtotal_cents: r.subtotal_cents as number,
      tax_cents: r.tax_cents as number,
      total_cents: r.total_cents as number,
      currency: r.currency as string,
      due_date: toIso(r.due_date),
      paid_at: toIso(r.paid_at),
      payment_method: r.payment_method as string | null,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function createInvoice(data: {
  company_id: string;
  subscription_id?: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_date?: string;
  line_items?: unknown[];
  notes?: string;
}): Promise<string> {
  const {
    company_id,
    subscription_id = null,
    subtotal_cents,
    tax_cents,
    total_cents,
    due_date = null,
    line_items = [],
    notes = null,
  } = data;

  // Sequential invoice number: INV-YYYYMM-XXXX
  // Wrapped in a transaction to prevent race conditions on sequence generation.
  const id = await withTransaction(async (tx) => {
    const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
    const prefix = `INV-${yyyymm}-`;

    const seqRows = (await tx`
      SELECT COUNT(*) AS count FROM admin_invoices
      WHERE invoice_number LIKE ${prefix + '%'}
    `) as Row[];
    const seq = parseInt((seqRows[0] as Row).count as string, 10) + 1;
    const invoice_number = `${prefix}${String(seq).padStart(4, '0')}`;

    const rows = (await tx`
      INSERT INTO admin_invoices (
        company_id, subscription_id, invoice_number, status,
        subtotal_cents, tax_cents, total_cents, currency,
        due_date, line_items, notes, created_at
      ) VALUES (
        ${company_id}::uuid,
        ${subscription_id}::uuid,
        ${invoice_number}, 'draft',
        ${subtotal_cents}, ${tax_cents}, ${total_cents}, 'ZAR',
        ${due_date}::date,
        ${JSON.stringify(line_items)}::jsonb,
        ${notes},
        NOW()
      )
      RETURNING id
    `) as Row[];

    log.info('createInvoice', { id: (rows[0] as Row).id, invoice_number, company_id }, 'InvoiceService');
    return (rows[0] as Row).id as string;
  });

  return id;
}

export async function markInvoicePaid(
  invoiceId: string,
  paymentMethod: string
): Promise<boolean> {
  const rows = await sql`
    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
      AND status IN ('sent', 'overdue')
    RETURNING id
  `;
  const updated = rows.length > 0;
  log.info('markInvoicePaid', { invoiceId, paymentMethod, updated }, 'InvoiceService');
  return updated;
}

export async function sendInvoice(invoiceId: string): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status = 'sent'
    WHERE id   = ${invoiceId}
      AND status = 'draft'
  `;
  log.info('sendInvoice', { invoiceId }, 'InvoiceService');
}

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

type Row = Record<string, unknown>;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

