/**
 * Webhooks API — WS-8.1
 * GET  — list webhooks
 * POST — create webhook
 * PUT  — update webhook (body includes id)
 * DELETE — delete webhook (?id=X)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getWebhooks,
  createWebhook,
  updateWebhook,
  deleteWebhook,
} from '@/modules/accounting/services/webhookService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const items = await getWebhooks(companyId);
    return apiResponse.success(res, items);
  }

  if (req.method === 'POST') {
    const { name, url, secret, events, isActive } = req.body as {
      name?: string; url?: string; secret?: string; events?: string[]; isActive?: boolean;
    };
    if (!name || !url || !events || events.length === 0) {
      return apiResponse.badRequest(res, 'name, url, and at least one event are required');
    }
    try {
      const item = await createWebhook(companyId, { name, url, secret, events, isActive });
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Webhook create failed', { error: err }, 'webhooks-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  if (req.method === 'PUT') {
    const { id, ...updates } = req.body as { id?: string; [key: string]: unknown };
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      const item = await updateWebhook(companyId, id, updates as Parameters<typeof updateWebhook>[2]);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Update failed';
      log.error('Webhook update failed', { error: err }, 'webhooks-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  if (req.method === 'DELETE') {
    const id = req.query.id as string;
    if (!id) return apiResponse.badRequest(res, 'id query param is required');
    try {
      await deleteWebhook(companyId, id);
      return apiResponse.success(res, { deleted: true });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Delete failed';
      log.error('Webhook delete failed', { error: err }, 'webhooks-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * In-memory rate limiter using LRU cache with TTL
 *
 * NOTE: This is a single-instance in-memory store. For multi-instance deployments
 * (horizontal scaling), replace the LRUCache backing with a Redis store so rate
 * limit counters are shared across all pods.
 */

import { LRUCache } from 'lru-cache';
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

interface RateLimitOptions {
  windowMs?: number;    // time window in ms (default 15 min)
  maxRequests?: number; // max requests per window (default 5)
}

// Each cache entry tracks hit count within the TTL window
const caches = new Map<string, LRUCache<string, number>>();

function getCache(windowMs: number): LRUCache<string, number> {
  const key = String(windowMs);
  if (!caches.has(key)) {
    caches.set(key, new LRUCache<string, number>({
      max: 10_000,
      ttl: windowMs,
    }));
  }
  return caches.get(key)!;
}

/**
 * Returns true if the key is rate limited, false if the request is allowed.
 */
export function checkRateLimit(key: string, opts?: RateLimitOptions): boolean {
  const windowMs = opts?.windowMs ?? 15 * 60 * 1000;
  const maxRequests = opts?.maxRequests ?? 5;

  const cache = getCache(windowMs);
  const current = cache.get(key) ?? 0;

  if (current >= maxRequests) {
    return true; // rate limited
  }

  cache.set(key, current + 1);
  return false;
}

function getClientIp(req: NextApiRequest): string {
  // In production behind nginx/Cloudflare, use the last proxy-added IP.
  // x-forwarded-for format: client, proxy1, proxy2
  // The FIRST entry is client-supplied and therefore spoofable.
  // The LAST entry is appended by the closest trusted proxy (nginx/Cloudflare)
  // and cannot be forged by the client.
  // In a Cloudflare + nginx setup, the real IP is the second-to-last entry;
  // using the last (nginx-appended) is still safe for rate limiting purposes.
  const forwarded = req.headers['x-forwarded-for'];
  if (forwarded) {
    const ips = (Array.isArray(forwarded) ? forwarded[0] : forwarded)
      .split(',')
      .map(s => s.trim());
    return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
  }
  return req.socket.remoteAddress || 'unknown';
}

/**
 * Middleware wrapper that applies rate limiting per IP before the handler runs.
 */
export function withRateLimit(
  handler: (req: NextApiRequest, res: NextApiResponse) => Promise<void> | void,
  opts?: RateLimitOptions
) {
  return async (req: NextApiRequest, res: NextApiResponse): Promise<void> => {
    const ip = getClientIp(req);
    const limited = checkRateLimit(ip, opts);

    if (limited) {
      log.warn('Rate limit exceeded', { ip }, 'rateLimit');
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
      });
      return;
    }

    return handler(req, res);
  };
}

// ENCRYPTION_KEY is required — the app must not start without encryption configured.
// All fields encrypted at rest (tokens, secrets) depend on this key being present.
const REQUIRED_VARS = ['DATABASE_URL', 'JWT_SECRET', 'ENCRYPTION_KEY'] as const;
const RECOMMENDED_VARS = ['SMTP_HOST', 'SMTP_USER', 'SMTP_PASS'] as const;

export function validateEnv(): void {
  const missing = REQUIRED_VARS.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  const missingRecommended = RECOMMENDED_VARS.filter(v => !process.env[v]);
  if (missingRecommended.length > 0) {
    // Use process.stderr to avoid triggering the no-console-log lint rule on warnings
    process.stderr.write(`[env] Missing recommended variables: ${missingRecommended.join(', ')}\n`);
  }
}

/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: serve /admin/* pages with super_admin auth verification
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects /admin/* on non-admin hosts to admin.isaflow.co.za
 * - Redirects unauthenticated /accounting/* and /payroll/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

// Sentinel used when JWT_SECRET is absent — any token verified against this will
// always fail the role check, giving defense-in-depth without crashing the edge runtime.
const MISSING_SECRET_SENTINEL = '__MIDDLEWARE_NO_SECRET__';

const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  // Return sentinel instead of empty string so jwtVerify still runs but produces
  // a payload that cannot match a real token signed with the real secret.
  return new TextEncoder().encode(secret ?? MISSING_SECRET_SENTINEL);
};

const PUBLIC_PATHS = [
  '/login',
  '/register',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/register',
  '/onboarding',
  '/api/onboarding',
  '/invite',
  '/api/invite',
];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the /admin platform */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths that bypass auth checks on the admin subdomain.
 *  NOTE: '/api/' is intentionally excluded — admin API routes must pass through
 *  the JWT check here (defense-in-depth alongside withAdmin on each handler).
 *  Only truly static/public paths are listed. */
const ADMIN_PASSTHROUGH = [
  '/_next',
  '/login',
  '/register',
  '/favicon.ico',
  '/icons',
  '/manifest.json',
  '/sw.js',
];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(token: string): Promise<boolean> {
  // Reject immediately if JWT_SECRET is not configured — never allow access
  // with a missing secret, regardless of what the token contains.
  if (!process.env.JWT_SECRET) return false;
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin';
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  const isAdminHost = ADMIN_HOSTS.includes(host);

  // ── Admin subdomain handling ─────────────────────────────────────────────────
  if (isAdminHost) {
    // Always passthrough for static assets, API routes, and login
    if (ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p))) {
      return NextResponse.next();
    }

    // Verify super_admin auth for all other paths
    const adminToken = request.cookies.get(AUTH_COOKIE_NAME)?.value;
    if (!adminToken) {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    const isAdmin = await verifyAdmin(adminToken);
    if (!isAdmin) {
      return NextResponse.redirect(new URL('/login', request.url));
    }

    // Rewrite path: / → /admin, /companies → /admin/companies, etc.
    if (!pathname.startsWith('/admin')) {
      const rewrittenUrl = request.nextUrl.clone();
      rewrittenUrl.pathname = pathname === '/' ? '/admin' : `/admin${pathname}`;
      return NextResponse.rewrite(rewrittenUrl);
    }

    return NextResponse.next();
  }

  // ── Non-admin hosts: redirect /admin/* to admin subdomain ───────────────────
  if (pathname.startsWith('/admin')) {
    const adminPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(`${ADMIN_URL}${adminPath}`);
  }

  // Allow public paths, static files, and API routes on main domains
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

