try {
  const { status, limit: limitParam = '50', offset = '0', q } = req.query;
  const limit = Math.min(Number(limitParam), 200);
  const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

  let invoices;
  if (status && status !== 'all') {
    invoices = await sql`
