/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: serve /admin/* pages with super_admin auth verification
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects /admin/* on non-admin hosts to admin.isaflow.co.za
 * - Redirects unauthenticated /accounting/* and /payroll/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

// Sentinel used when JWT_SECRET is absent — any token verified against this will
// always fail the role check, giving defense-in-depth without crashing the edge runtime.
const MISSING_SECRET_SENTINEL = '__MIDDLEWARE_NO_SECRET__';

const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  // Return sentinel instead of empty string so jwtVerify still runs but produces
  // a payload that cannot match a real token signed with the real secret.
  return new TextEncoder().encode(secret ?? MISSING_SECRET_SENTINEL);
};

const PUBLIC_PATHS = [
  '/login',
  '/register',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/register',
  '/onboarding',
  '/api/onboarding',
  '/invite',
  '/api/invite',
];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the /admin platform */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths that bypass auth checks on the admin subdomain.
 *  NOTE: '/api/' is intentionally excluded — admin API routes must pass through
 *  the JWT check here (defense-in-depth alongside withAdmin on each handler).
 *  Only truly static/public paths are listed. */
const ADMIN_PASSTHROUGH = [
  '/_next',
  '/login',
  '/register',
  '/favicon.ico',
  '/icons',
  '/manifest.json',
  '/sw.js',
];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(token: string): Promise<boolean> {
  // Reject immediately if JWT_SECRET is not configured — never allow access
  // with a missing secret, regardless of what the token contains.
  if (!process.env.JWT_SECRET) return false;
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin';
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  const isAdminHost = ADMIN_HOSTS.includes(host);

  // ── Admin subdomain handling ─────────────────────────────────────────────────
  if (isAdminHost) {
    // Always passthrough for static assets, API routes, and login
    if (ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p))) {
      return NextResponse.next();
    }

    // Verify super_admin auth for all other paths
    const adminToken = request.cookies.get(AUTH_COOKIE_NAME)?.value;
    if (!adminToken) {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    const isAdmin = await verifyAdmin(adminToken);
    if (!isAdmin) {
      return NextResponse.redirect(new URL('/login', request.url));
    }

    // Rewrite path: / → /admin, /companies → /admin/companies, etc.
    if (!pathname.startsWith('/admin')) {
      const rewrittenUrl = request.nextUrl.clone();
      rewrittenUrl.pathname = pathname === '/' ? '/admin' : `/admin${pathname}`;
      return NextResponse.rewrite(rewrittenUrl);
    }

    return NextResponse.next();
  }

  // ── Non-admin hosts: redirect /admin/* to admin subdomain ───────────────────
  if (pathname.startsWith('/admin')) {
    const adminPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(`${ADMIN_URL}${adminPath}`);
  }

  // Allow public paths, static files, and API routes on main domains
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

/**
 * GET  /api/invite/[token] — Validate an invitation token (public)
 * POST /api/invite/[token] — Accept an invitation (requires auth)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { serialize } from 'cookie';
type Row = Record<string, unknown>;


function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!local || !domain) return '***@***';
  return `${local[0]}***@${domain}`;
}

// ── GET: public token validation ──────────────────────────────────────────────

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  const rows = (await sql`
    SELECT
      ci.email,
      ci.role,
      c.name AS company_name,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS invited_by_name
    FROM company_invitations ci
    JOIN companies c ON c.id = ci.company_id
    LEFT JOIN users u ON u.id = ci.invited_by
    WHERE ci.token = ${token}
      AND ci.accepted_at IS NULL
      AND ci.expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const row = rows[0]!;

  return apiResponse.success(res, {
    email: maskEmail(row.email as string),
    companyName: row.company_name as string,
    role: row.role as string,
    invitedBy: (row.invited_by_name as string) || 'Someone',
  });
}

// ── POST: accept invitation (auth required) ───────────────────────────────────

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  // Look up the invitation
  const rows = (await sql`
    SELECT id, company_id, email, role
    FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const inv = rows[0]!;
  const userId = authReq.user.id;

  // Verify invited email matches the logged-in user's email
  if ((inv.email as string).toLowerCase() !== authReq.user.email.toLowerCase()) {
    return apiResponse.forbidden(res, 'This invitation was sent to a different email address');
  }

  // Insert into company_users
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  // Mark invitation accepted
  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  // Mark onboarding completed for this user (they're joining an existing company)
  await sql`
    UPDATE users SET onboarding_completed = true WHERE id = ${userId}
  `;

  log.info('Invitation accepted via token page', { token, userId, companyId: inv.company_id }, 'invite');

  // Set the onboarding-done cookie so middleware stops redirecting
  const cookieStr = serialize('ff_onboarding_done', '1', {
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 30 * 24 * 60 * 60,
  });
  res.setHeader('Set-Cookie', cookieStr);

  return apiResponse.success(res, { companyId: inv.company_id as string }, 'Invitation accepted');
}

// ── Router ────────────────────────────────────────────────────────────────────

const postHandler = withAuth(handlePost);

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    if (req.method === 'GET') {
      return await handleGet(req, res);
    }
    if (req.method === 'POST') {
      return await postHandler(req, res);
    }
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'POST']);
  } catch (err) {
    log.error('Invite token handler error', err instanceof Error ? { message: err.message } : { err }, 'invite');
    return apiResponse.internalError(res, err);
  }
}

/**
 * POST /api/auth/login
 * Authenticates a user with email + password.
 * On success: signs a JWT, creates a DB session, sets an HttpOnly cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword } from '@/lib/auth/password';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
import { get2FAStatus, isTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  // Use the last x-forwarded-for entry (proxy-appended) to prevent client IP spoofing.
  const ip: string = (() => {
    const forwarded = req.headers['x-forwarded-for'];
    if (forwarded) {
      const raw = Array.isArray(forwarded) ? forwarded[0] ?? '' : forwarded;
      const ips = raw.split(',').map((s: string) => s.trim());
      return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
    }
    return req.socket.remoteAddress || 'unknown';
  })();
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password, deviceFingerprint } = req.body as {
    email?: string;
    password?: string;
    deviceFingerprint?: string;
  };

  if (!email || !password) {
    return apiResponse.badRequest(res, 'Email and password are required');
  }

  try {
    // Look up user by email
    const rows = (await sql`
      SELECT id, email, password_hash, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed,
             failed_login_attempts, locked_until
      FROM users
      WHERE email = ${email.toLowerCase().trim()}
      LIMIT 1
    `) as Row[];

    const user = rows[0];

    if (!user) {
      // Constant-time failure — avoid timing attacks
      await verifyPassword(password, '$2a$12$placeholder.hash.to.prevent.timing.attacks');
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    if (!user.is_active) {
      return res.status(403).json({
        success: false,
        error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
      });
    }

    // Check account lockout
    if (user.locked_until) {
      const lockedUntil = user.locked_until instanceof Date ? user.locked_until : new Date(user.locked_until as string);
      if (lockedUntil > new Date()) {
        const minutesRemaining = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
        return res.status(403).json({
          success: false,
          error: {
            code: 'ACCOUNT_LOCKED',
            message: `Account locked due to too many failed attempts. Try again in ${minutesRemaining} minute(s).`,
          },
        });
      }
    }

    // Verify password
    const passwordValid = await verifyPassword(password, user.password_hash as string);
    if (!passwordValid) {
      // Increment failed attempts; lock after 10 failures
      const attempts = ((user.failed_login_attempts as number) ?? 0) + 1;
      if (attempts >= 10) {
        await sql`
          UPDATE users
          SET failed_login_attempts = ${attempts},
              locked_until = NOW() + INTERVAL '30 minutes'
          WHERE id = ${user.id as string}
        `;
        log.warn('Account locked after failed attempts', { userId: user.id, attempts }, 'auth/login');
      } else {
        await sql`
          UPDATE users SET failed_login_attempts = ${attempts} WHERE id = ${user.id as string}
        `;
      }
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    // Check 2FA before creating a full session
    const twoFAStatus = await get2FAStatus(String(user.id));
    if (twoFAStatus.enabled) {
      // Check if device is already trusted
      const trusted = deviceFingerprint
        ? await isTrustedDevice(String(user.id), deviceFingerprint)
        : false;

      if (!trusted) {
        // Issue a short-lived temp token (5 min) — no DB session yet
        const tempAuthUser = {
          id: String(user.id),
          userId: String(user.id),
          email: user.email as string,
          firstName: (user.first_name as string) || '',
          lastName: (user.last_name as string) || '',
          name: '',
          role: user.role as AuthRole,
          permissions: [],
          isActive: true,
        };
        const tempToken = await signToken(tempAuthUser, '2fa-pending', '5m');
        log.info('2FA required — temp token issued', { userId: user.id }, 'auth/login');
        return res.status(200).json({
          success: true,
          data: { requiresTwoFactor: true, tempToken },
        });
      }
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Sign JWT and create DB session — reuse the already-resolved safe IP
    const ipAddress = ip;
    const userAgent = req.headers['user-agent'];

    // Reset failed login attempts on successful password verification
    await sql`
      UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE id = ${authUser.id}
    `;

    // Create session first, then sign token with the real sessionId
    // We pass a temporary token to createSession, then update the hash
    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);

    // Re-sign token with the real sessionId
    const finalToken = await signToken(authUser, session.id);

    // Update session with the hash of the final token
    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Set HttpOnly cookie — 8h session, always secure
    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    // Auto-accept any pending company invitations for this email
    let invitationsAccepted = 0;
    let onboardingCompleted = !!user.onboarding_completed;

    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${authUser.email})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${authUser.id}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
      `;
      invitationsAccepted++;
    }

    if (invitationsAccepted > 0 && !onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
      onboardingCompleted = true;
      log.info('Onboarding skipped via invitation acceptance', { userId: authUser.id, invitationsAccepted }, 'auth/login');
    }

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('User logged in', { userId: authUser.id, email: authUser.email }, 'auth/login');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
      invitationsAccepted,
    }, 'Login successful');
  } catch (err) {
    log.error('Login error', err instanceof Error ? { message: err.message } : { err }, 'auth/login');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * POST /api/auth/change-password
 * Allows the authenticated user to change their password.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword, hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
type Row = Record<string, unknown>;


async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.socket.remoteAddress || 'unknown';
  if (checkRateLimit(`change-password:${ip}`, { maxRequests: 5, windowMs: 15 * 60 * 1000 })) {
    return res.status(429).json({ success: false, error: 'Too many attempts. Try again later.' });
  }

  const authReq = req as AuthenticatedNextApiRequest;
  const userId = authReq.user.id;

  const { oldPassword, newPassword, confirmPassword } = req.body as {
    oldPassword?: string;
    newPassword?: string;
    confirmPassword?: string;
  };

  if (!oldPassword || !newPassword || !confirmPassword) {
    return apiResponse.badRequest(res, 'All password fields are required');
  }

  if (newPassword !== confirmPassword) {
    return apiResponse.badRequest(res, 'New passwords do not match');
  }

  const strength = checkPasswordStrength(newPassword);
  if (strength.score < 2) {
    return apiResponse.badRequest(
      res,
      `Password too weak: ${strength.issues[0] ?? 'Please choose a stronger password'}`
    );
  }

  // Fetch current password hash
  const rows = (await sql`
    SELECT password_hash FROM users WHERE id = ${userId} LIMIT 1
  `) as Row[];

  if (!rows.length) {
    return apiResponse.notFound(res, 'User');
  }

  const currentHash: string = String(rows[0]!.password_hash);
  const valid = await verifyPassword(oldPassword, currentHash);

  if (!valid) {
    return apiResponse.badRequest(res, 'Current password is incorrect');
  }

  const newHash = await hashPassword(newPassword);

  await sql`
    UPDATE users SET password_hash = ${newHash} WHERE id = ${userId}
  `;

  log.info('Password changed', { userId }, 'auth/change-password');

  return apiResponse.success(res, null, 'Password changed successfully');
}

export default withAuth(withErrorHandler(handler) as any);

/**
 * User Access Service
 * Manages company users and invitations — mirrors Sage's "Control User Access".
 */

import crypto from 'crypto';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

const VALID_ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
type CompanyRole = (typeof VALID_ROLES)[number];

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CompanyUserRecord {
  userId: string;
  name: string;
  email: string;
  role: string;
  joinedAt: string;
}

export interface PendingInvitation {
  id: string;
  companyId: string;
  email: string;
  role: string;
  invitedBy: string;
  token: string;
  expiresAt: string;
  createdAt: string;
  emailSentAt: string | null;
  emailError: string | null;
}

export interface InvitationResult {
  autoAdded: boolean;
  invitation?: PendingInvitation;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function isValidRole(role: string): role is CompanyRole {
  return (VALID_ROLES as readonly string[]).includes(role);
}

async function countOwners(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COUNT(*) AS cnt FROM company_users
    WHERE company_id = ${companyId}::UUID AND role = 'owner'
  `) as Row[];
  return parseInt(String(rows[0]?.cnt ?? '0'), 10);
}

function toIso(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString();
  return val;
}

// ── Company Users ─────────────────────────────────────────────────────────────

export async function listCompanyUsers(companyId: string): Promise<CompanyUserRecord[]> {
  const rows = (await sql`
    SELECT
      cu.user_id,
      u.first_name,
      u.last_name,
      u.email,
      cu.role,
      cu.created_at
    FROM company_users cu
    JOIN users u ON u.id = cu.user_id::VARCHAR
    WHERE cu.company_id = ${companyId}::UUID
    ORDER BY cu.created_at ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    userId: r.user_id as string,
    name: `${(r.first_name as string) ?? ''} ${(r.last_name as string) ?? ''}`.trim() || (r.email as string),
    email: r.email as string,
    role: r.role as string,
    joinedAt: toIso(r.created_at as string | Date | null) ?? '',
  }));
}

export async function updateCompanyUserRole(
  companyId: string,
  userId: string,
  newRole: string,
): Promise<void> {
  if (!isValidRole(newRole)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Prevent stripping last owner
  const currentRows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  const currentRole = currentRows[0]?.role as string | undefined;
  if (currentRole === 'owner' && newRole !== 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot change role: this is the last owner of the company.');
    }
  }

  await sql`
    UPDATE company_users
    SET role = ${newRole}
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user role updated', { companyId, userId, newRole }, 'accounting');
}

export async function removeCompanyUser(companyId: string, userId: string): Promise<void> {
  // Prevent removing last owner
  const rows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  if ((rows[0]?.role as string | undefined) === 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot remove the last owner of the company.');
    }
  }

  await sql`
    DELETE FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user removed', { companyId, userId }, 'accounting');
}

// ── Invitations ───────────────────────────────────────────────────────────────

export async function createInvitation(
  companyId: string,
  email: string,
  role: string,
  invitedBy: string,
): Promise<InvitationResult> {
  if (!isValidRole(role)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Check if a user with this email already exists
  const existing = (await sql`
    SELECT id FROM users WHERE email = ${email} LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    const existingUserId = existing[0]!.id as string;

    // Check if already in company
    const alreadyMember = (await sql`
      SELECT 1 FROM company_users
      WHERE company_id = ${companyId}::UUID AND user_id = ${existingUserId}::UUID
    `) as Row[];

    if (alreadyMember.length > 0) {
      throw new Error('This user is already a member of the company.');
    }

    // Auto-add directly
    await sql`
      INSERT INTO company_users (company_id, user_id, role)
      VALUES (${companyId}::UUID, ${existingUserId}::UUID, ${role})
      ON CONFLICT (company_id, user_id) DO NOTHING
    `;
    log.info('User auto-added to company', { companyId, email, role }, 'accounting');
    return { autoAdded: true };
  }

  // Create invitation row — upsert on (company_id, email) to allow re-invite
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  const rows = (await sql`
    INSERT INTO company_invitations (company_id, email, role, invited_by, token, expires_at)
    VALUES (${companyId}::UUID, ${email}, ${role}, ${invitedBy}, ${token}, ${expiresAt}::TIMESTAMPTZ)
    ON CONFLICT (company_id, email) DO UPDATE SET
      role = EXCLUDED.role,
      invited_by = EXCLUDED.invited_by,
      token = EXCLUDED.token,
      expires_at = EXCLUDED.expires_at,
      accepted_at = NULL,
      created_at = NOW()
    RETURNING *
  `) as Row[];

  const inv = rows[0]!;
  log.info('Invitation created', { companyId, email, role }, 'accounting');
  return {
    autoAdded: false,
    invitation: mapInvitation(inv),
  };
}

export async function listPendingInvitations(companyId: string): Promise<PendingInvitation[]> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE company_id = ${companyId}::UUID
      AND accepted_at IS NULL
      AND expires_at > NOW()
    ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapInvitation);
}

export async function markInvitationEmailSent(invitationId: string): Promise<void> {
  await sql`
    UPDATE company_invitations
    SET email_sent_at = NOW(), email_error = NULL
    WHERE id = ${invitationId}::UUID
  `;
}

export async function markInvitationEmailFailed(invitationId: string, error: string): Promise<void> {
  await sql`
    UPDATE company_invitations
    SET email_error = ${error}
    WHERE id = ${invitationId}::UUID
  `;
}

export async function cancelInvitation(invitationId: string, companyId: string): Promise<void> {
  await sql`
    DELETE FROM company_invitations
    WHERE id = ${invitationId}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Invitation cancelled', { invitationId, companyId }, 'accounting');
}

export async function acceptInvitation(token: string, userId: string): Promise<void> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    throw new Error('Invitation not found or has expired.');
  }

  const inv = rows[0]!;

  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
  `;

  log.info('Invitation accepted', { token, userId, companyId: inv.company_id }, 'accounting');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

function mapInvitation(r: Row): PendingInvitation {
  return {
    id: r.id as string,
    companyId: r.company_id as string,
    email: r.email as string,
    role: r.role as string,
    invitedBy: r.invited_by as string,
    token: r.token as string,
    expiresAt: toIso(r.expires_at as string | Date | null) ?? '',
    createdAt: toIso(r.created_at as string | Date | null) ?? '',
    emailSentAt: r.email_sent_at ? (toIso(r.email_sent_at as string | Date | null) ?? null) : null,
    emailError: (r.email_error as string | null) ?? null,
  };
}

