/**
 * KPI Dashboard API
 * GET /api/accounting/kpi-dashboard
 *   ?from=YYYY-MM-DD   - period start (defaults to start of current month)
 *   ?to=YYYY-MM-DD     - period end (defaults to today)
 *   ?months=N           - chart lookback months (default 6)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDashboardKPIs,
  getRevenueChart,
  getCashFlowChart,
  getAgingBreakdown,
  getTopCustomers,
  getTopExpenseCategories,
} from '@/modules/accounting/services/kpiService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;

    // Default to start of financial year (12 months back from current month-end)
    const fyStart = new Date(year, month - 13, 1); // ~12 months ago
    const from = req.query.from
      ? String(req.query.from)
      : fyStart.toISOString().slice(0, 10);
    const to = req.query.to
      ? String(req.query.to)
      : now.toISOString().slice(0, 10);
    const months = req.query.months ? Number(req.query.months) : 6;

    const [kpis, revenueChart, cashFlowChart, arAging, apAging, topCustomers, topExpenses] =
      await Promise.all([
        getDashboardKPIs(companyId, from, to),
        getRevenueChart(companyId, months),
        getCashFlowChart(companyId, months),
        getAgingBreakdown(companyId, 'ar'),
        getAgingBreakdown(companyId, 'ap'),
        getTopCustomers(companyId, 5),
        getTopExpenseCategories(companyId, 5),
      ]);

    return apiResponse.success(res, {
      kpis,
      revenueChart,
      cashFlowChart,
      arAging,
      apAging,
      topCustomers,
      topExpenses,
    });
  } catch (err) {
    log.error('Failed to load KPI dashboard', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to load KPI dashboard');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Cash Flow Forecast API
 * GET — generate cash flow forecast for the next N months
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { generateForecast, getHistoricalForChart } from '@/modules/accounting/services/cashFlowForecastService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const months = Math.min(Number(req.query.months) || 6, 24);
  const threshold = Number(req.query.threshold) || 0;
  const includeHistory = req.query.history !== 'false';

  try {
    const [forecast, historical] = await Promise.all([
      generateForecast(companyId, months, threshold),
      includeHistory ? getHistoricalForChart(companyId, 6) : Promise.resolve([]),
    ]);

    return apiResponse.success(res, {
      ...forecast,
      historical,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Cash flow forecast failed';
    return apiResponse.internalError(res, err, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Webhook Deliveries API — WS-8.1
 * GET — delivery log (?webhook_id=X&limit=50)
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getDeliveries } from '@/modules/accounting/services/webhookService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }
  const { companyId } = req as CompanyApiRequest;
  const webhookId = req.query.webhook_id as string;
  const limit = req.query.limit ? Number(req.query.limit) : 50;

  if (!webhookId) return apiResponse.badRequest(res, 'webhook_id query param is required');

  try {
    const deliveries = await getDeliveries(companyId, webhookId, limit);
    return apiResponse.success(res, deliveries);
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Fetch failed';
    log.error('Webhook deliveries fetch failed', { webhookId, error: err }, 'webhook-deliveries-api');
    return apiResponse.badRequest(res, msg);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * SARS VAT201 API
 * GET  ?from=YYYY-MM-DD&to=YYYY-MM-DD — generate VAT201 data for period
 * POST { periodStart, periodEnd }     — save as draft submission
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { isValidDate } from '@/lib/validation';
import {
  generateVAT201,
  saveDraftSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const from = req.query.from as string;
    const to = req.query.to as string;

    if (!from || !to) {
      return apiResponse.badRequest(res, 'from and to query parameters are required (YYYY-MM-DD)');
    }
    if (!isValidDate(from) || !isValidDate(to)) {
      return apiResponse.badRequest(res, 'from and to must be valid dates in YYYY-MM-DD format');
    }

    try {
      const vat201 = await generateVAT201(companyId, from, to);
      return apiResponse.success(res, vat201);
    } catch (err) {
      log.error('Failed to generate VAT201', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to generate VAT201');
    }
  }

  if (req.method === 'POST') {
    const { periodStart, periodEnd } = req.body;

    if (!periodStart || !periodEnd) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd are required');
    }
    if (!isValidDate(periodStart) || !isValidDate(periodEnd)) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd must be valid dates in YYYY-MM-DD format');
    }

    try {
      const vat201 = await generateVAT201(companyId, periodStart, periodEnd);
      const submission = await saveDraftSubmission(
        companyId,
        'VAT201',
        periodStart,
        periodEnd,
        vat201 as unknown as Record<string, unknown>,
        userId
      );
      return apiResponse.created(res, submission, 'VAT201 draft saved');
    } catch (err) {
      log.error('Failed to save VAT201 draft', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to save draft');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * SARS EMP201 API
 * GET  ?from=YYYY-MM-DD&to=YYYY-MM-DD — generate EMP201 data for period
 * POST { periodStart, periodEnd }     — save as draft submission
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { isValidDate } from '@/lib/validation';
import {
  generateEMP201,
  saveDraftSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const from = req.query.from as string;
    const to = req.query.to as string;

    if (!from || !to) {
      return apiResponse.badRequest(res, 'from and to query parameters are required (YYYY-MM-DD)');
    }
    if (!isValidDate(from) || !isValidDate(to)) {
      return apiResponse.badRequest(res, 'from and to must be valid dates in YYYY-MM-DD format');
    }

    try {
      const emp201 = await generateEMP201(companyId, from, to);
      return apiResponse.success(res, emp201);
    } catch (err) {
      log.error('Failed to generate EMP201', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to generate EMP201');
    }
  }

  if (req.method === 'POST') {
    const { periodStart, periodEnd } = req.body;

    if (!periodStart || !periodEnd) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd are required');
    }
    if (!isValidDate(periodStart) || !isValidDate(periodEnd)) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd must be valid dates in YYYY-MM-DD format');
    }

    try {
      const emp201 = await generateEMP201(companyId, periodStart, periodEnd);
      const submission = await saveDraftSubmission(
        companyId,
        'EMP201',
        periodStart,
        periodEnd,
        emp201 as unknown as Record<string, unknown>,
        userId
      );
      return apiResponse.created(res, submission, 'EMP201 draft saved');
    } catch (err) {
      log.error('Failed to save EMP201 draft', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to save draft');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

