      );
    }

    return apiResponse.created(res, { id: docId });
  }

  // ── DELETE (soft) ──
  if (req.method === 'DELETE') {
    const docId = req.query.id as string;
    if (!docId) return apiResponse.badRequest(res, 'id is required');

