interface PagedResponse {
  items: AuditEntry[];
  total: number;
  page: number;
  limit: number;
}

function getDefaultDates() {
  const now   = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  return {
    from: start.toISOString().split('T')[0] as string,
    to:   now.toISOString().split('T')[0] as string,
  };
}

