-- Migration 267: Audit Trail
-- Creates the audit_log table for comprehensive field-level change history

CREATE TABLE IF NOT EXISTS audit_log (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  user_id VARCHAR(255) NOT NULL REFERENCES users(id),
  user_email VARCHAR(255),
  action VARCHAR(20) NOT NULL CHECK (action IN (
    'create', 'update', 'delete', 'post', 'reverse', 'approve', 'reject', 'login', 'export'
  )),
  entity_type VARCHAR(50) NOT NULL,
  entity_id UUID NOT NULL,
  entity_ref VARCHAR(100),
  changes JSONB,
  ip_address VARCHAR(45),
  user_agent TEXT,
  session_id UUID,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for common query patterns
CREATE INDEX IF NOT EXISTS idx_audit_log_company ON audit_log(company_id);
CREATE INDEX IF NOT EXISTS idx_audit_log_entity ON audit_log(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_log_user ON audit_log(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_log_date ON audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_log_action ON audit_log(action);
CREATE INDEX IF NOT EXISTS idx_audit_log_company_date ON audit_log(company_id, created_at DESC);

-- GIN index for JSONB changes queries
CREATE INDEX IF NOT EXISTS idx_audit_log_changes ON audit_log USING GIN (changes);

/**
 * Admin Audit Log API
 * GET /api/admin/audit — Retrieve paginated admin audit log
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getAuditLog } from '@/modules/admin/services/auditService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const {
        admin_user_id,
        target_type,
        target_id,
        action,
        from_date,
        to_date,
        page,
        limit,
      } = req.query;

      const result = await getAuditLog({
        admin_user_id: admin_user_id as string | undefined,
        target_type: target_type as string | undefined,
        target_id: target_id as string | undefined,
        action: action as string | undefined,
        from_date: from_date as string | undefined,
        to_date: to_date as string | undefined,
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get audit log', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get audit log');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

export default withAdmin(handler);

/**
 * Audit Service
 * Admin action logging for ISAFlow Admin Platform
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { AuditLogEntry, PaginatedResult } from '../types/admin.types';

export interface AuditLogFilters {
  admin_user_id?: string;
  target_type?: string;
  target_id?: string;
  action?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

export async function logAdminAction(
  adminUserId: string,
  action: string,
  targetType: string,
  targetId: string | null,
  details: Record<string, unknown> | null,
  ipAddress: string | null
): Promise<void> {
  try {
    await sql`
      INSERT INTO admin_audit_log (
        admin_user_id,
        action,
        target_type,
        target_id,
        details,
        ip_address,
        created_at
      ) VALUES (
        ${adminUserId},
        ${action},
        ${targetType},
        ${targetId},
        ${details ? JSON.stringify(details) : null},
        ${ipAddress},
        NOW()
      )
    `;
  } catch (err) {
    // Audit logging must not break the calling flow — log and swallow
    log.error('logAdminAction failed', { adminUserId, action, error: err }, 'auditService');
  }
}

export async function getAuditLog(
  filters: AuditLogFilters = {}
): Promise<PaginatedResult<AuditLogEntry>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        al.id,
        al.admin_user_id,
        COALESCE(u.first_name || ' ' || u.last_name, u.email, 'Unknown') AS admin_name,
        al.action,
        al.target_type,
        al.target_id,
        al.details,
        al.ip_address,
        al.created_at
      FROM admin_audit_log al
      LEFT JOIN users u ON u.id = al.admin_user_id::text
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
      ORDER BY al.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(*)::int AS total
      FROM admin_audit_log al
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const toIso = (v: unknown) =>
      v instanceof Date ? v.toISOString() : (v as string);

    const total = countRow?.total ?? 0;

    return {
      items: rows.map((r) => ({
        id: r.id as string,
        admin_user_id: r.admin_user_id as string,
        admin_name: r.admin_name as string,
        action: r.action as string,
        target_type: r.target_type as string,
        target_id: r.target_id as string | null,
        details: (r.details ?? {}) as Record<string, unknown>,
        ip_address: r.ip_address as string | null,
        created_at: toIso(r.created_at),
      })),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('getAuditLog failed', { error: err }, 'auditService');
    throw err;
  }
}

/**
 * Audit Trail Service
 * Field-level change history for all accounting entities.
 * logAudit is fire-and-forget — never throws.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export type AuditAction =
  | 'create'
  | 'update'
  | 'delete'
  | 'post'
  | 'reverse'
  | 'approve'
  | 'reject'
  | 'login'
  | 'export';

export interface AuditFieldChange {
  field: string;
  old: string | null;
  new: string | null;
  label: string;
}

export interface AuditChanges {
  fields: AuditFieldChange[];
  metadata?: Record<string, string>;
}

export interface AuditLogItem {
  id: string;
  companyId: string;
  userId: string;
  userEmail: string | null;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef: string | null;
  changes: AuditChanges | null;
  ipAddress: string | null;
  userAgent: string | null;
  sessionId: string | null;
  createdAt: string;
}

export interface LogAuditParams {
  companyId: string;
  userId: string;
  userEmail?: string;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef?: string;
  changes?: AuditChanges;
  ip?: string;
  userAgent?: string;
  sessionId?: string;
}

export interface AuditLogFilters {
  entityType?: string;
  entityId?: string;
  userId?: string;
  action?: string;
  dateFrom?: string;
  dateTo?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

/**
 * Fire-and-forget audit log writer. Never throws — errors are swallowed
 * so audit failures never break the calling transaction.
 */
export async function logAudit(params: LogAuditParams): Promise<void> {
  try {
    const changesJson = params.changes ? JSON.stringify(params.changes) : null;
    await sql`
      INSERT INTO audit_log (
        company_id, user_id, user_email, action,
        entity_type, entity_id, entity_ref,
        changes, ip_address, user_agent, session_id
      ) VALUES (
        ${params.companyId}::UUID,
        ${params.userId},
        ${params.userEmail ?? null},
        ${params.action},
        ${params.entityType},
        ${params.entityId}::UUID,
        ${params.entityRef ?? null},
        ${changesJson}::JSONB,
        ${params.ip ?? null},
        ${params.userAgent ?? null},
        ${params.sessionId ? params.sessionId + '::UUID' : null}
      )
    `;
  } catch (err) {
    // Never surface audit errors to callers
    log.warn('Audit log write failed', { error: err, params }, 'audit-trail');
  }
}

export async function getAuditLog(
  companyId: string,
  filters: AuditLogFilters,
): Promise<{ items: AuditLogItem[]; total: number }> {
  try {
    const limit = filters.limit ?? 50;
    const offset = filters.offset ?? 0;

    // Build conditional clauses using separate queries per filter combination
    // to avoid dynamic SQL string concatenation
    const entityType = filters.entityType ?? null;
    const entityId = filters.entityId ?? null;
    const userId = filters.userId ?? null;
    const action = filters.action ?? null;
    const dateFrom = filters.dateFrom ?? null;
    const dateTo = filters.dateTo ?? null;
    const search = filters.search ? `%${filters.search}%` : null;

    const [rows, countRows] = await Promise.all([
      sql`
        SELECT *
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
        ORDER BY created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      ` as Promise<Record<string, unknown>[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
      ` as Promise<Record<string, unknown>[]>,
    ]);

    return {
      items: rows.map(mapAuditRow),
      total: Number(countRows[0]?.cnt ?? 0),
    };
  } catch (err) {
    log.error('Failed to get audit log', { companyId, filters, error: err }, 'audit-trail');
    throw err;
  }
}

export async function getEntityHistory(
  companyId: string,
  entityType: string,
  entityId: string,
): Promise<AuditLogItem[]> {
  try {
    const rows = (await sql`
      SELECT *
      FROM audit_log
      WHERE company_id = ${companyId}::UUID
        AND entity_type = ${entityType}
        AND entity_id = ${entityId}::UUID
      ORDER BY created_at DESC
      LIMIT 500
    `) as Record<string, unknown>[];
    return rows.map(mapAuditRow);
  } catch (err) {
    log.error('Failed to get entity history', { companyId, entityType, entityId, error: err }, 'audit-trail');
    throw err;
  }
}

/**
 * Diffs two objects and returns an array of field changes.
 * Only includes fields that actually changed.
 */
export function diffObjects(
  oldObj: Record<string, unknown>,
  newObj: Record<string, unknown>,
  fieldLabels: Record<string, string>,
): AuditFieldChange[] {
  const allKeys = new Set([...Object.keys(oldObj), ...Object.keys(newObj)]);
  const changes: AuditFieldChange[] = [];

  for (const key of allKeys) {
    const oldVal = oldObj[key];
    const newVal = newObj[key];
    const oldStr = oldVal == null ? null : String(oldVal);
    const newStr = newVal == null ? null : String(newVal);
    if (oldStr !== newStr) {
      changes.push({
        field: key,
        old: oldStr,
        new: newStr,
        label: fieldLabels[key] ?? key,
      });
    }
  }

  return changes;
}

function mapAuditRow(row: Record<string, unknown>): AuditLogItem {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    userId: String(row.user_id),
    userEmail: row.user_email ? String(row.user_email) : null,
    action: String(row.action) as AuditAction,
    entityType: String(row.entity_type),
    entityId: String(row.entity_id),
    entityRef: row.entity_ref ? String(row.entity_ref) : null,
    changes: row.changes != null ? (row.changes as AuditChanges) : null,
    ipAddress: row.ip_address ? String(row.ip_address) : null,
    userAgent: row.user_agent ? String(row.user_agent) : null,
    sessionId: row.session_id ? String(row.session_id) : null,
    createdAt: row.created_at instanceof Date
      ? row.created_at.toISOString()
      : String(row.created_at),
  };
}

/**
 * Audit Log API
 * GET /api/accounting/audit-log — List audit entries with filters and pagination
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAuditLog } from '@/modules/accounting/services/auditTrailService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const {
        entity_type,
        entity_id,
        user_id,
        action,
        date_from,
        date_to,
        search,
        limit,
        offset,
      } = req.query;

      const result = await getAuditLog(companyId, {
        entityType: entity_type as string | undefined,
        entityId: entity_id as string | undefined,
        userId: user_id as string | undefined,
        action: action as string | undefined,
        dateFrom: date_from as string | undefined,
        dateTo: date_to as string | undefined,
        search: search as string | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get audit log', { error: err }, 'audit-log-api');
      return apiResponse.internalError(res, err, 'Failed to get audit log');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

