async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const {
        source,
        company_id,
        user_id,
        action,
        entity_type,
        search,
        from_date,
        to_date,
        page,
        limit,
      } = req.query;

      const filters: UnifiedAuditFilters = {
        source:      source      as UnifiedAuditFilters['source'],
