/**
 * GET  /api/invite/[token] — Validate an invitation token (public)
 * POST /api/invite/[token] — Accept an invitation (requires auth)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { createHash } from 'crypto';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { serialize } from 'cookie';
type Row = Record<string, unknown>;

function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}


function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!local || !domain) return '***@***';
  return `${local[0]}***@${domain}`;
}

// ── GET: public token validation ──────────────────────────────────────────────

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  const tokenHash = hashToken(token);

  const rows = (await sql`
    SELECT
      ci.email,
      ci.role,
      c.name AS company_name,
      COALESCE(u.first_name || ' ' || u.last_name, u.email) AS invited_by_name
    FROM company_invitations ci
    JOIN companies c ON c.id = ci.company_id
    LEFT JOIN users u ON u.id = ci.invited_by
    WHERE ci.token = ${tokenHash}
      AND ci.accepted_at IS NULL
      AND ci.expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const row = rows[0]!;

  return apiResponse.success(res, {
    email: maskEmail(row.email as string),
    companyName: row.company_name as string,
    role: row.role as string,
    invitedBy: (row.invited_by_name as string) || 'Someone',
  });
}

// ── POST: accept invitation (auth required) ───────────────────────────────────

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  // Look up the invitation using the hashed token
  const tokenHash = hashToken(token);
  const rows = (await sql`
    SELECT id, company_id, email, role
    FROM company_invitations
    WHERE token = ${tokenHash}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const inv = rows[0]!;
  const userId = authReq.user.id;

  // Verify invited email matches the logged-in user's email
  if ((inv.email as string).toLowerCase() !== authReq.user.email.toLowerCase()) {
    return apiResponse.forbidden(res, 'This invitation was sent to a different email address');
  }

  // Insert into company_users
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  // Mark invitation accepted
  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  // Mark onboarding completed for this user (they're joining an existing company)
  await sql`
    UPDATE users SET onboarding_completed = true WHERE id = ${userId}
  `;

  log.info('Invitation accepted via token page', { token, userId, companyId: inv.company_id }, 'invite');

  // Set the onboarding-done cookie so middleware stops redirecting
  const cookieStr = serialize('ff_onboarding_done', '1', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 30 * 24 * 60 * 60,
  });
  res.setHeader('Set-Cookie', cookieStr);

  return apiResponse.success(res, { companyId: inv.company_id as string }, 'Invitation accepted');
}

// ── Router ────────────────────────────────────────────────────────────────────

const postHandler = withAuth(handlePost);

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    if (req.method === 'GET') {
      return await handleGet(req, res);
    }
    if (req.method === 'POST') {
      return await postHandler(req, res);
    }
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'POST']);
  } catch (err) {
    log.error('Invite token handler error', err instanceof Error ? { message: err.message } : { err }, 'invite');
    return apiResponse.internalError(res, err);
  }
}

/**
 * Bank Feeds — OAuth Callback
 * Handles the redirect from Stitch after user authorizes bank access.
 * Exchanges code for tokens, fetches accounts, creates connection.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  exchangeCode, fetchStitchAccounts, createConnection,
} from '@/modules/accounting/services/bankFeedService';
import cookie from 'cookie';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { code, state, error } = req.query;

  if (error) {
    // User cancelled or Stitch returned error
    return res.redirect('/accounting/bank-accounts?feed_error=' + encodeURIComponent(String(error)));
  }

  if (!code || !state) {
    return apiResponse.badRequest(res, 'Missing code or state parameter');
  }

  // Retrieve stored state + code verifier from cookie
  const cookies = cookie.parse(req.headers.cookie || '');
  const rawState = cookies.stitch_oauth_state;
  if (!rawState) {
    return apiResponse.badRequest(res, 'OAuth state cookie missing. Please try connecting again.');
  }

  let storedState: { state: string; codeVerifier: string };
  try {
    storedState = JSON.parse(decodeURIComponent(rawState));
  } catch {
    return apiResponse.badRequest(res, 'Invalid OAuth state');
  }

  if (storedState.state !== state) {
    return apiResponse.badRequest(res, 'OAuth state mismatch — possible CSRF attack');
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // Exchange code for tokens
  const tokens = await exchangeCode(String(code), storedState.codeVerifier);

  // Fetch linked bank accounts
  const accounts = await fetchStitchAccounts(tokens.accessToken);

  // Clear the state cookie
  res.setHeader('Set-Cookie', `stitch_oauth_state=; Path=/; HttpOnly; Max-Age=0${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);

  // Store accounts info and redirect to bank accounts page with success
  // In a real flow, user would select which account to link.
  // For now, store the first account or return the list for selection.

  if (accounts.length === 0) {
    return res.redirect('/accounting/bank-accounts?feed_error=no_accounts');
  }

  // Return accounts for the user to select which to link
  // Store tokens temporarily in the session
  const bankAccountId = req.query.bankAccountId as string;
  if (bankAccountId) {
    // Direct link — create connection immediately
    const account = accounts[0]!;
    await createConnection({
      bankAccountId,
      externalAccountId: account.id,
      bankName: account.bankId,
      accountNumberMasked: account.accountNumber,
      branchCode: account.branchCode,
      accountType: account.accountType,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresIn: tokens.expiresIn,
      createdBy: userId,
    });
    return res.redirect('/accounting/bank-accounts?feed_connected=true');
  }

  // Return accounts for selection — tokens are NOT returned to the client
  return apiResponse.success(res, { accounts });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

/**
 * Bank Feeds — Initiate Connection
 * GET — returns Stitch OAuth authorization URL
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { getAuthorizationUrl, isConfigured } from '@/modules/accounting/services/bankFeedService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  if (!isConfigured()) {
    return apiResponse.badRequest(res, 'Bank feed integration not configured. Set STITCH_CLIENT_ID, STITCH_CLIENT_SECRET, and STITCH_REDIRECT_URI in environment.');
  }

  const { url, state, nonce, codeVerifier } = getAuthorizationUrl();

  // Store state + verifier in a secure cookie for the callback
  const stateData = JSON.stringify({ state, nonce, codeVerifier });
  res.setHeader('Set-Cookie', `stitch_oauth_state=${encodeURIComponent(stateData)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=600${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);

  return apiResponse.success(res, { url });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

